{
  "name": "AgroCalculadora Orgánica",
  "description": "Una herramienta profesional para agricultores que calcula dosis precisas de fertilizantes orgánicos por árbol, optimizada con IA para recomendaciones sostenibles.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum TreeType {
  CITRUS = 'Cítricos (Limón, Naranja)',
  AVOCADO = 'Aguacate',
  MANGO = 'Mango',
  COFFEE = 'Café',
  CACAO = 'Cacao',
  FRUIT_GENERAL = 'Frutales Caducifolios (Manzano, Durazno)',
  FOREST = 'Forestales / Ornamentales'
}

export enum OrganicProduct {
  COMPOST = 'Compost Madurado',
  BOKASHI = 'Bokashi',
  HUMUS = 'Humus de Lombriz',
  BIOFERTILIZER = 'Biofertilizante Líquido (Biol)',
  PURINE = 'Purín de Ortiga/Consuelda'
}

export interface CalculationInput {
  treeType: TreeType;
  treeAge: number;
  numTrees: number;
  product: OrganicProduct;
  healthStatus: 'bueno' | 'regular' | 'deficiente';
}

export interface CalculationResult {
  perTreeAmount: number; // in kg or liters
  unit: 'kg' | 'L';
  totalAmount: number;
  frequency: string;
  notes: string;
}

export interface AIAdvice {
  tips: string[];
  seasonalAdvice: string;
  sustainabilityScore: number;
}

import React from 'react';
import { TreeType, OrganicProduct } from './types';

export const TREE_TYPE_ICONS: Record<TreeType, React.ReactNode> = {
  [TreeType.CITRUS]: <i className="fas fa-lemon text-yellow-500"></i>,
  [TreeType.AVOCADO]: <i className="fas fa-seedling text-green-700"></i>,
  [TreeType.MANGO]: <i className="fas fa-sun text-orange-400"></i>,
  [TreeType.COFFEE]: <i className="fas fa-mug-hot text-brown-600"></i>,
  [TreeType.CACAO]: <i className="fas fa-cookie text-amber-800"></i>,
  [TreeType.FRUIT_GENERAL]: <i className="fas fa-apple-whole text-red-500"></i>,
  [TreeType.FOREST]: <i className="fas fa-tree text-emerald-800"></i>,
};

// Base rates (kg or L per year of age)
export const BASE_RATES: Record<OrganicProduct, number> = {
  [OrganicProduct.COMPOST]: 1.5, // 1.5kg por año de edad
  [OrganicProduct.BOKASHI]: 1.0, 
  [OrganicProduct.HUMUS]: 0.8,
  [OrganicProduct.BIOFERTILIZER]: 2.0, // Litros (dilución)
  [OrganicProduct.PURINE]: 1.5,  // Litros (dilución)
};

export const PRODUCT_UNITS: Record<OrganicProduct, 'kg' | 'L'> = {
  [OrganicProduct.COMPOST]: 'kg',
  [OrganicProduct.BOKASHI]: 'kg',
  [OrganicProduct.HUMUS]: 'kg',
  [OrganicProduct.BIOFERTILIZER]: 'L',
  [OrganicProduct.PURINE]: 'L',
};

import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Actúa como un agrónomo experto en agricultura orgánica. Proporciona consejos específicos para un cultivo de ${input.treeType} de ${input.treeAge} años usando ${input.product}. El estado de salud actual es ${input.healthStatus}.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "3 consejos prácticos de aplicación.",
            },
            seasonalAdvice: {
              type: Type.STRING,
              description: "Recomendación basada en la fenología del cultivo.",
            },
            sustainabilityScore: {
              type: Type.NUMBER,
              description: "Puntuación de 1 a 10 del impacto ambiental.",
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore"],
        },
      },
    });

    if (response.text) {
      return JSON.parse(response.text.trim());
    }
    return null;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { TreeType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice } from './types';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS } from './constants';
import { getAgriculturalAdvice } from './services/geminiService';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    treeAge: 1,
    numTrees: 1,
    product: OrganicProduct.COMPOST,
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);

  const calculateDose = useCallback(() => {
    const baseRate = BASE_RATES[input.product];
    const unit = PRODUCT_UNITS[input.product];

    // Adjust based on health
    let healthModifier = 1.0;
    if (input.healthStatus === 'regular') healthModifier = 1.25;
    if (input.healthStatus === 'deficiente') healthModifier = 1.5;

    // Dose = Age * BaseRate * HealthModifier
    // Limit max dose per tree to avoid saturation
    const rawPerTree = input.treeAge * baseRate * healthModifier;
    const perTreeAmount = unit === 'kg' ? Math.min(rawPerTree, 20) : Math.min(rawPerTree, 30);

    const totalAmount = perTreeAmount * input.numTrees;

    setResult({
      perTreeAmount: parseFloat(perTreeAmount.toFixed(2)),
      unit,
      totalAmount: parseFloat(totalAmount.toFixed(2)),
      frequency: input.product.includes('Líquido') ? 'Cada 15-20 días' : 'Cada 3-4 meses',
      notes: `Basado en un árbol de ${input.treeAge} años. Aplique en la zona de goteo (proyección de la copa).`
    });
  }, [input]);

  const handleFetchAI = async () => {
    setLoading(true);
    const advice = await getAgriculturalAdvice(input);
    setAiAdvice(advice);
    setLoading(false);
  };

  useEffect(() => {
    calculateDose();
  }, [calculateDose]);

  return (
    <div className="min-h-screen bg-emerald-50 text-slate-800 pb-12">
      {/* Navbar */}
      <nav className="bg-emerald-800 text-white p-4 shadow-lg sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <i className="fas fa-leaf text-2xl text-emerald-400"></i>
            <h1 className="text-xl font-bold tracking-tight">AgroCalculadora <span className="text-emerald-300">Orgánica</span></h1>
          </div>
          <div className="hidden md:block text-sm opacity-80">
            Optimizando el campo con IA
          </div>
        </div>
      </nav>

      <main className="max-w-6xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Input Section */}
        <section className="lg:col-span-5 bg-white rounded-3xl shadow-xl p-6 md:p-8 border border-emerald-100 h-fit">
          <h2 className="text-2xl font-bold mb-6 text-emerald-900 flex items-center gap-2">
            <i className="fas fa-sliders-h text-emerald-600"></i>
            Configuración del Cultivo
          </h2>

          <div className="space-y-6">
            <div>
              <label className="block text-sm font-semibold text-slate-600 mb-2 uppercase tracking-wider">Tipo de Árbol</label>
              <div className="grid grid-cols-2 gap-2">
                {Object.values(TreeType).map((type) => (
                  <button
                    key={type}
                    onClick={() => setInput({ ...input, treeType: type })}
                    className={`flex items-center gap-2 p-3 rounded-xl border-2 transition-all text-sm ${
                      input.treeType === type 
                      ? 'border-emerald-600 bg-emerald-50 text-emerald-900 shadow-sm' 
                      : 'border-slate-100 hover:border-emerald-200 bg-slate-50'
                    }`}
                  >
                    {TREE_TYPE_ICONS[type]}
                    <span className="truncate">{type}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-600 mb-2 uppercase tracking-wider">Edad (Años)</label>
                <input 
                  type="number" 
                  min="1" 
                  max="50"
                  value={input.treeAge}
                  onChange={(e) => setInput({ ...input, treeAge: parseInt(e.target.value) || 1 })}
                  className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-medium text-lg"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-600 mb-2 uppercase tracking-wider">Nº Árboles</label>
                <input 
                  type="number" 
                  min="1"
                  value={input.numTrees}
                  onChange={(e) => setInput({ ...input, numTrees: parseInt(e.target.value) || 1 })}
                  className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-medium text-lg"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-600 mb-2 uppercase tracking-wider">Producto Orgánico</label>
              <select 
                value={input.product}
                onChange={(e) => setInput({ ...input, product: e.target.value as OrganicProduct })}
                className="w-full p-4 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-medium appearance-none cursor-pointer"
              >
                {Object.values(OrganicProduct).map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-600 mb-2 uppercase tracking-wider">Estado de Salud</label>
              <div className="flex bg-slate-100 rounded-xl p-1">
                {(['bueno', 'regular', 'deficiente'] as const).map((status) => (
                  <button
                    key={status}
                    onClick={() => setInput({ ...input, healthStatus: status })}
                    className={`flex-1 py-2 px-3 rounded-lg capitalize text-sm font-semibold transition-all ${
                      input.healthStatus === status 
                      ? 'bg-white text-emerald-800 shadow-md' 
                      : 'text-slate-500 hover:text-slate-700'
                    }`}
                  >
                    {status}
                  </button>
                ))}
              </div>
            </div>

            <button 
              onClick={handleFetchAI}
              disabled={loading}
              className="w-full bg-emerald-700 hover:bg-emerald-800 text-white font-bold py-4 rounded-2xl shadow-lg transform active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
            >
              {loading ? (
                <div className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full"></div>
              ) : (
                <i className="fas fa-wand-magic-sparkles"></i>
              )}
              {loading ? 'Consultando Experto...' : 'Obtener Recomendación IA'}
            </button>
          </div>
        </section>

        {/* Results Section */}
        <section className="lg:col-span-7 space-y-6">

          {/* Main Result Card */}
          {result && (
            <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-emerald-100">
              <div className="bg-emerald-600 p-6 text-white">
                <h3 className="text-xl font-bold flex items-center gap-2">
                  <i className="fas fa-calculator"></i>
                  Resultados del Cálculo
                </h3>
              </div>
              <div className="p-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100 flex flex-col items-center justify-center text-center">
                    <span className="text-emerald-700 font-bold uppercase text-xs tracking-widest mb-1">Dosis por Árbol</span>
                    <div className="flex items-baseline gap-1">
                      <span className="text-5xl font-black text-emerald-900">{result.perTreeAmount}</span>
                      <span className="text-xl font-bold text-emerald-700">{result.unit}</span>
                    </div>
                  </div>
                  <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100 flex flex-col items-center justify-center text-center">
                    <span className="text-slate-500 font-bold uppercase text-xs tracking-widest mb-1">Total para {input.numTrees} árboles</span>
                    <div className="flex items-baseline gap-1">
                      <span className="text-5xl font-black text-slate-800">{result.totalAmount}</span>
                      <span className="text-xl font-bold text-slate-500">{result.unit}</span>
                    </div>
                  </div>
                </div>

                <div className="mt-8 space-y-4">
                  <div className="flex items-start gap-4 p-4 bg-yellow-50 rounded-xl border border-yellow-100">
                    <i className="fas fa-calendar-alt text-yellow-600 mt-1"></i>
                    <div>
                      <h4 className="font-bold text-yellow-800">Frecuencia de Aplicación</h4>
                      <p className="text-yellow-700 text-sm">{result.frequency}</p>
                    </div>
                  </div>
                  <div className="flex items-start gap-4 p-4 bg-blue-50 rounded-xl border border-blue-100">
                    <i className="fas fa-info-circle text-blue-600 mt-1"></i>
                    <div>
                      <h4 className="font-bold text-blue-800">Notas de Aplicación</h4>
                      <p className="text-blue-700 text-sm">{result.notes}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* AI Expert Section */}
          <div className={`bg-gradient-to-br from-emerald-900 to-teal-950 rounded-3xl shadow-2xl p-8 text-white transition-all duration-500 ${!aiAdvice && 'opacity-50 grayscale'}`}>
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-2xl font-bold flex items-center gap-3">
                <i className="fas fa-robot text-emerald-400"></i>
                Recomendación del Agrónomo IA
              </h3>
              {aiAdvice && (
                <div className="flex flex-col items-end">
                  <span className="text-xs uppercase opacity-60 font-bold">Índice Sostenible</span>
                  <div className="flex items-center gap-2">
                    <div className="h-2 w-24 bg-white/20 rounded-full overflow-hidden">
                      <div className="h-full bg-emerald-400" style={{ width: `${aiAdvice.sustainabilityScore * 10}%` }}></div>
                    </div>
                    <span className="font-black text-emerald-400">{aiAdvice.sustainabilityScore}/10</span>
                  </div>
                </div>
              )}
            </div>

            {!aiAdvice ? (
              <div className="text-center py-12 border-2 border-dashed border-white/20 rounded-2xl">
                <i className="fas fa-microchip text-4xl mb-4 opacity-30"></i>
                <p className="text-white/60">Haz clic en el botón para generar consejos personalizados con Inteligencia Artificial.</p>
              </div>
            ) : (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="bg-white/10 p-6 rounded-2xl backdrop-blur-sm border border-white/10">
                  <h4 className="text-emerald-400 font-bold mb-4 flex items-center gap-2">
                    <i className="fas fa-lightbulb"></i> Tips de Aplicación
                  </h4>
                  <ul className="space-y-4">
                    {aiAdvice.tips.map((tip, idx) => (
                      <li key={idx} className="flex items-start gap-3">
                        <span className="bg-emerald-500/20 text-emerald-400 rounded-full h-6 w-6 flex items-center justify-center flex-shrink-0 text-xs font-bold border border-emerald-500/30">
                          {idx + 1}
                        </span>
                        <p className="text-white/90 leading-relaxed text-sm md:text-base">{tip}</p>
                      </li>
                    ))}
                  </ul>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="p-6 rounded-2xl bg-white/5 border border-white/10">
                    <h4 className="text-emerald-400 font-bold mb-2 flex items-center gap-2">
                      <i className="fas fa-cloud-sun"></i> Fenología y Clima
                    </h4>
                    <p className="text-white/80 text-sm leading-relaxed">
                      {aiAdvice.seasonalAdvice}
                    </p>
                  </div>
                  <div className="p-6 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-center">
                    <div>
                      <i className="fas fa-seedling text-3xl text-emerald-400 mb-3"></i>
                      <p className="text-emerald-200 text-xs font-medium uppercase tracking-widest">Compromiso Orgánico</p>
                      <p className="text-white font-bold text-sm mt-1 italic">"Nutriendo el suelo, no solo la planta"</p>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </section>
      </main>

      {/* Footer */}
      <footer className="max-w-6xl mx-auto px-4 mt-12 text-center text-slate-400 text-sm">
        <p>© 2024 AgroCalculadora Orgánica Profesional. Todos los derechos reservados.</p>
        <p className="mt-1">Recuerde realizar un análisis de suelo para resultados más exactos.</p>
      </footer>
    </div>
  );
};

export default App;

export enum TreeType {
  CITRUS = 'Cítricos (Limón, Naranja)',
  AVOCADO = 'Aguacate',
  MANGO = 'Mango',
  COFFEE = 'Café',
  CACAO = 'Cacao',
  FRUIT_GENERAL = 'Frutales Caducifolios (Manzano, Durazno)',
  FOREST = 'Forestales / Ornamentales'
}

export enum OrganicProduct {
  COMPOST = 'Compost Madurado',
  BOKASHI = 'Bokashi',
  HUMUS = 'Humus de Lombriz',
  BIOFERTILIZER = 'Biofertilizante Líquido (Biol)',
  PURINE = 'Purín de Ortiga/Consuelda',
  ROCK_DUST = 'Harina de Rocas',
  BORON = 'Boro (Mineral)',
  ZINC = 'Zinc (Mineral)',
  COPPER = 'Cobre (Mineral)',
  MAGNESIUM = 'Magnesio (Mineral)',
  EM = 'EM (Microorganismos Eficaces)',
  SEA_SALT = 'Sal Marina'
}

export interface CalculationInput {
  treeType: TreeType;
  treeAge: number;
  numTrees: number;
  product: OrganicProduct;
  healthStatus: 'bueno' | 'regular' | 'deficiente';
}

export interface CalculationResult {
  perTreeAmount: number; // in kg, liters or grams
  unit: 'kg' | 'L' | 'g';
  totalAmount: number;
  frequency: string;
  notes: string;
}

export interface AIAdvice {
  tips: string[];
  seasonalAdvice: string;
  sustainabilityScore: number;
}

import React from 'react';
import { TreeType, OrganicProduct } from './types';

export const TREE_TYPE_ICONS: Record<TreeType, React.ReactNode> = {
  [TreeType.CITRUS]: <i className="fas fa-lemon text-yellow-500"></i>,
  [TreeType.AVOCADO]: <i className="fas fa-seedling text-green-700"></i>,
  [TreeType.MANGO]: <i className="fas fa-sun text-orange-400"></i>,
  [TreeType.COFFEE]: <i className="fas fa-mug-hot text-brown-600"></i>,
  [TreeType.CACAO]: <i className="fas fa-cookie text-amber-800"></i>,
  [TreeType.FRUIT_GENERAL]: <i className="fas fa-apple-whole text-red-500"></i>,
  [TreeType.FOREST]: <i className="fas fa-tree text-emerald-800"></i>,
};

// Tasas base (kg, L o g por año de edad)
export const BASE_RATES: Record<OrganicProduct, number> = {
  [OrganicProduct.COMPOST]: 1.5, // kg
  [OrganicProduct.BOKASHI]: 1.0, // kg
  [OrganicProduct.HUMUS]: 0.8,   // kg
  [OrganicProduct.BIOFERTILIZER]: 2.0, // L
  [OrganicProduct.PURINE]: 1.5,  // L
  [OrganicProduct.ROCK_DUST]: 0.3, // kg
  [OrganicProduct.BORON]: 5,     // g
  [OrganicProduct.ZINC]: 5,      // g
  [OrganicProduct.COPPER]: 3,    // g
  [OrganicProduct.MAGNESIUM]: 15, // g
  [OrganicProduct.EM]: 0.2,      // L
  [OrganicProduct.SEA_SALT]: 10,  // g
};

export const PRODUCT_UNITS: Record<OrganicProduct, 'kg' | 'L' | 'g'> = {
  [OrganicProduct.COMPOST]: 'kg',
  [OrganicProduct.BOKASHI]: 'kg',
  [OrganicProduct.HUMUS]: 'kg',
  [OrganicProduct.BIOFERTILIZER]: 'L',
  [OrganicProduct.PURINE]: 'L',
  [OrganicProduct.ROCK_DUST]: 'kg',
  [OrganicProduct.BORON]: 'g',
  [OrganicProduct.ZINC]: 'g',
  [OrganicProduct.COPPER]: 'g',
  [OrganicProduct.MAGNESIUM]: 'g',
  [OrganicProduct.EM]: 'L',
  [OrganicProduct.SEA_SALT]: 'g',
};

import React, { useState, useEffect, useCallback } from 'react';
import { TreeType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice } from './types';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS } from './constants';
import { getAgriculturalAdvice } from './services/geminiService';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    treeAge: 1,
    numTrees: 1,
    product: OrganicProduct.COMPOST,
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);

  const calculateDose = useCallback(() => {
    const baseRate = BASE_RATES[input.product];
    const unit = PRODUCT_UNITS[input.product];

    // Adjust based on health
    let healthModifier = 1.0;
    if (input.healthStatus === 'regular') healthModifier = 1.25;
    if (input.healthStatus === 'deficiente') healthModifier = 1.5;

    // Dose = Age * BaseRate * HealthModifier
    const rawPerTree = input.treeAge * baseRate * healthModifier;

    // Define reasonable limits per tree to avoid toxicity or waste
    let perTreeAmount = rawPerTree;
    if (unit === 'kg') perTreeAmount = Math.min(rawPerTree, 20);
    else if (unit === 'L') perTreeAmount = Math.min(rawPerTree, 30);
    else if (unit === 'g') perTreeAmount = Math.min(rawPerTree, 500); // Max 500g for micronutrients per tree

    const totalAmount = perTreeAmount * input.numTrees;

    // Frequency logic based on product type
    let frequency = 'Cada 3-4 meses';
    if (input.product === OrganicProduct.BIOFERTILIZER || input.product === OrganicProduct.PURINE) {
      frequency = 'Cada 15-20 días (Vía foliar o drench)';
    } else if (input.product === OrganicProduct.EM) {
      frequency = 'Cada 30 días';
    } else if (['Boro (Mineral)', 'Zinc (Mineral)', 'Cobre (Mineral)', 'Magnesio (Mineral)', 'Sal Marina'].includes(input.product)) {
      frequency = 'Cada 6 meses o según deficiencia';
    }

    setResult({
      perTreeAmount: parseFloat(perTreeAmount.toFixed(2)),
      unit,
      totalAmount: parseFloat(totalAmount.toFixed(2)),
      frequency,
      notes: `Basado en un árbol de ${input.treeAge} años. Para minerales sólidos, distribuya uniformemente en la zona de goteo. Para EM o Bioles, diluya según indicación del fabricante.`
    });
  }, [input]);

  const handleFetchAI = async () => {
    setLoading(true);
    const advice = await getAgriculturalAdvice(input);
    setAiAdvice(advice);
    setLoading(false);
  };

  useEffect(() => {
    calculateDose();
  }, [calculateDose]);

  return (
    <div className="min-h-screen bg-emerald-50 text-slate-800 pb-12">
      {/* Navbar */}
