            <div>
              <label className="block text-sm font-semibold text-slate-600 mb-2 uppercase tracking-wider">Vigor / Salud del Árbol</label>
              <div className="flex bg-slate-100 rounded-xl p-1">
                {(['bueno', 'regular', 'deficiente'] as const).map((status) => (
                  <button
                    key={status}
                    onClick={() => setInput({ ...input, healthStatus: status })}
                    className={`flex-1 py-2 px-3 rounded-lg capitalize text-sm font-semibold transition-all ${
                      input.healthStatus === status 
                      ? 'bg-white text-emerald-800 shadow-md' 
