            >
              {loading ? (
                <div className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full"></div>
              ) : (
                <i className="fas fa-wand-magic-sparkles"></i>
              )}
              {loading ? 'Consultando Experto...' : 'Obtener Recomendación IA'}
            </button>
          </div>
        </section>

        {/* Results Section */}
        <section className="lg:col-span-7 space-y-6">

          {/* Main Result Card */}
          {result && (
            <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-emerald-100">
              <div className="bg-emerald-600 p-6 text-white flex justify-between items-center">
                <h3 className="text-xl font-bold flex items-center gap-2">
                  <i className="fas fa-microscope"></i>
                  Prescripción Técnica
                </h3>
                <span className="bg-white/20 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-widest">Calculado</span>
              </div>
              <div className="p-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100 flex flex-col items-center justify-center text-center">
                    <span className="text-emerald-700 font-bold uppercase text-xs tracking-widest mb-1">Por Árbol</span>
                    <div className="flex items-baseline gap-1">
                      <span className="text-5xl font-black text-emerald-900">{result.perTreeAmount}</span>
                      <span className="text-xl font-bold text-emerald-700">{result.unit}</span>
                    </div>
                  </div>
                  <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100 flex flex-col items-center justify-center text-center">
                    <span className="text-slate-500 font-bold uppercase text-xs tracking-widest mb-1">Total Proyecto</span>
                    <div className="flex items-baseline gap-1">
                      <span className="text-5xl font-black text-slate-800">{result.totalAmount}</span>
                      <span className="text-xl font-bold text-slate-500">{result.unit}</span>
                    </div>
                  </div>
                </div>

                <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="flex items-start gap-4 p-4 bg-yellow-50 rounded-xl border border-yellow-100">
                    <i className="fas fa-calendar-alt text-yellow-600 mt-1"></i>
                    <div>
                      <h4 className="font-bold text-yellow-800 text-sm">Frecuencia</h4>
                      <p className="text-yellow-700 text-xs">{result.frequency}</p>
                    </div>
                  </div>
                  <div className="flex items-start gap-4 p-4 bg-blue-50 rounded-xl border border-blue-100">
                    <i className="fas fa-info-circle text-blue-600 mt-1"></i>
                    <div>
                      <h4 className="font-bold text-blue-800 text-sm">Técnica</h4>
                      <p className="text-blue-700 text-xs">{result.notes}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* AI Expert Section */}
          <div className={`bg-gradient-to-br from-emerald-900 to-teal-950 rounded-3xl shadow-2xl p-8 text-white transition-all duration-500 ${!aiAdvice && 'opacity-50 grayscale'}`}>
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-2xl font-bold flex items-center gap-3">
                <i className="fas fa-robot text-emerald-400"></i>
                Análisis del Agrónomo IA
              </h3>
              {aiAdvice && (
                <div className="flex flex-col items-end">
                  <span className="text-xs uppercase opacity-60 font-bold">Bio-Regeneración</span>
                  <div className="flex items-center gap-2">
                    <div className="h-2 w-24 bg-white/20 rounded-full overflow-hidden">
                      <div className="h-full bg-emerald-400" style={{ width: `${aiAdvice.sustainabilityScore * 10}%` }}></div>
                    </div>
                    <span className="font-black text-emerald-400">{aiAdvice.sustainabilityScore}/10</span>
                  </div>
                </div>
              )}
            </div>

            {!aiAdvice ? (
              <div className="text-center py-12 border-2 border-dashed border-white/20 rounded-2xl bg-white/5">
                <i className="fas fa-atom text-4xl mb-4 opacity-30 animate-pulse"></i>
                <p className="text-white/60">Pulsa el botón "Obtener Recomendación IA" para analizar la sinergia de {input.product} con tu cultivo.</p>
              </div>
            ) : (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="bg-white/10 p-6 rounded-2xl backdrop-blur-sm border border-white/10">
                  <h4 className="text-emerald-400 font-bold mb-4 flex items-center gap-2 uppercase tracking-widest text-sm">
                    <i className="fas fa-check-double"></i> Protocolo Sugerido
                  </h4>
                  <ul className="space-y-4">
                    {aiAdvice.tips.map((tip, idx) => (
                      <li key={idx} className="flex items-start gap-4 group">
                        <span className="bg-emerald-500/20 text-emerald-400 rounded-lg h-8 w-8 flex items-center justify-center flex-shrink-0 text-sm font-bold border border-emerald-500/30 group-hover:bg-emerald-500 group-hover:text-white transition-all">
                          {idx + 1}
                        </span>
                        <p className="text-white/90 leading-relaxed text-sm md:text-base">{tip}</p>
                      </li>
                    ))}
                  </ul>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="p-6 rounded-2xl bg-white/5 border border-white/10 flex flex-col justify-between">
                    <div>
                      <h4 className="text-emerald-400 font-bold mb-3 flex items-center gap-2 uppercase tracking-widest text-xs">
                        <i className="fas fa-mountain"></i> Observaciones del Suelo
                      </h4>
                      <p className="text-white/80 text-sm leading-relaxed italic">
                        "{aiAdvice.seasonalAdvice}"
                      </p>
                    </div>
                    <div className="mt-4 pt-4 border-t border-white/10 flex items-center justify-between text-[10px] uppercase font-bold opacity-50">
                      <span>Ref: Agricultura Orgánica</span>
                      <i className="fas fa-certificate"></i>
                    </div>
                  </div>
                  <div className="p-6 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex flex-col items-center justify-center text-center">
                    <i className="fas fa-hand-holding-heart text-3xl text-emerald-400 mb-3"></i>
                    <p className="text-emerald-200 text-xs font-medium uppercase tracking-widest">Impacto Ambiental</p>
                    <p className="text-white font-bold text-sm mt-1">Este manejo favorece la microbiología nativa y la captura de carbono.</p>
                  </div>
                </div>
              </div>
            )}
          </div>
        </section>
      </main>

      {/* Footer */}
      <footer className="max-w-6xl mx-auto px-4 mt-12 pt-8 border-t border-emerald-200 text-center text-slate-400 text-xs md:text-sm">
        <div className="flex justify-center gap-6 mb-4">
          <i className="fas fa-vial hover:text-emerald-600 cursor-help" title="Soporte Mineral"></i>
          <i className="fas fa-bacteria hover:text-emerald-600 cursor-help" title="Microbiología"></i>
          <i className="fas fa-globe-americas hover:text-emerald-600 cursor-help" title="Ecología"></i>
        </div>
        <p>© 2024 AgroCalculadora Orgánica Profesional. Desarrollado para una agricultura más limpia y eficiente.</p>
        <p className="mt-1 font-medium text-emerald-600/60 italic">"Regenerando la vida en cada aplicación"</p>
      </footer>
    </div>
  );
};

export default App;

export enum TreeType {
  CITRUS = 'Cítricos (Limón, Naranja)',
  AVOCADO = 'Aguacate',
  MANGO = 'Mango',
  COFFEE = 'Café',
  CACAO = 'Cacao',
  FRUIT_GENERAL = 'Frutales Caducifolios (Manzano, Durazno)',
  FOREST = 'Forestales / Ornamentales'
}

export enum OrganicProduct {
  COMPOST = 'Compost Madurado',
  BOKASHI = 'Bokashi',
  HUMUS = 'Humus de Lombriz',
  BIOFERTILIZER = 'Biofertilizante Líquido (Biol)',
  PURINE = 'Purín de Ortiga/Consuelda',
  ROCK_DUST = 'Harina de Rocas',
  BORON = 'Boro (Mineral)',
  ZINC = 'Zinc (Mineral)',
  COPPER = 'Cobre (Mineral)',
  MAGNESIUM = 'Magnesio (Mineral)',
  EM = 'EM (Microorganismos Eficaces)',
  SEA_SALT = 'Sal Marina'
}

export interface CalculationInput {
  treeType: TreeType;
  treeAge: number;
  numTrees: number;
  selectedProducts: OrganicProduct[];
  productPrices: Record<string, number>; // Price per unit (kg, L, or g)
  healthStatus: 'bueno' | 'regular' | 'deficiente';
}

export interface ProductResult {
  product: OrganicProduct;
  amount: number;
  unit: 'kg' | 'L' | 'g';
  costPerTree: number;
  totalCost: number;
}

export interface CalculationResult {
  products: ProductResult[];
  totalCostPerTree: number;
  totalProjectCost: number;
  frequency: string;
  notes: string;
}

export interface AIAdvice {
  tips: string[];
  seasonalAdvice: string;
  sustainabilityScore: number;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { TreeType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult } from './types';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS } from './constants';
import { getAgriculturalAdvice } from './services/geminiService';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    treeAge: 1,
    numTrees: 1,
    selectedProducts: [OrganicProduct.COMPOST],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);

  const calculateDose = useCallback(() => {
    let healthModifier = 1.0;
    if (input.healthStatus === 'regular') healthModifier = 1.25;
    if (input.healthStatus === 'deficiente') healthModifier = 1.5;

    const productResults: ProductResult[] = input.selectedProducts.map(product => {
      const baseRate = BASE_RATES[product];
      const unit = PRODUCT_UNITS[product];
      const pricePerUnit = input.productPrices[product] || 0;

      const rawPerTree = input.treeAge * baseRate * healthModifier;

      let perTreeAmount = rawPerTree;
      if (unit === 'kg') perTreeAmount = Math.min(rawPerTree, 20);
      else if (unit === 'L') perTreeAmount = Math.min(rawPerTree, 30);
      else if (unit === 'g') perTreeAmount = Math.min(rawPerTree, 500);

      const costPerTree = perTreeAmount * pricePerUnit;
      const totalCost = costPerTree * input.numTrees;

      return {
        product,
        amount: parseFloat(perTreeAmount.toFixed(2)),
        unit,
        costPerTree: parseFloat(costPerTree.toFixed(2)),
        totalCost: parseFloat(totalCost.toFixed(2))
      };
    });

    const totalCostPerTree = productResults.reduce((acc, curr) => acc + curr.costPerTree, 0);
    const totalProjectCost = totalCostPerTree * input.numTrees;

    setResult({
      products: productResults,
      totalCostPerTree: parseFloat(totalCostPerTree.toFixed(2)),
      totalProjectCost: parseFloat(totalProjectCost.toFixed(2)),
      frequency: "Variable según producto (ver detalles)",
      notes: `Mezcla sugerida para árboles de ${input.treeAge} años. Aplique en la zona radicular activa.`
    });
  }, [input]);

  const handleFetchAI = async () => {
    if (input.selectedProducts.length === 0) return;
    setLoading(true);
    // Passing the first product for context, though service could be updated for all
    const advice = await getAgriculturalAdvice({
      ...input,
      product: input.selectedProducts[0] 
    } as any);
    setAiAdvice(advice);
    setLoading(false);
  };

  const toggleProduct = (product: OrganicProduct) => {
    setInput(prev => {
      const isSelected = prev.selectedProducts.includes(product);
      return {
        ...prev,
        selectedProducts: isSelected 
          ? prev.selectedProducts.filter(p => p !== product)
          : [...prev.selectedProducts, product]
      };
    });
  };

  const handlePriceChange = (product: OrganicProduct, price: number) => {
    setInput(prev => ({
      ...prev,
      productPrices: { ...prev.productPrices, [product]: price }
    }));
  };

  useEffect(() => {
    calculateDose();
  }, [calculateDose]);

  return (
    <div className="min-h-screen bg-emerald-50 text-slate-800 pb-12">
      <nav className="bg-emerald-800 text-white p-4 shadow-lg sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <i className="fas fa-leaf text-2xl text-emerald-400"></i>
            <h1 className="text-xl font-bold tracking-tight">AgroCalculadora <span className="text-emerald-300">Pro</span></h1>
          </div>
          <div className="hidden md:block text-xs opacity-80 uppercase tracking-widest font-bold">
            Gestión de Costos y Nutrición
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Input Section */}
        <section className="lg:col-span-5 space-y-6">
          <div className="bg-white rounded-3xl shadow-xl p-6 border border-emerald-100">
            <h2 className="text-xl font-bold mb-6 text-emerald-900 flex items-center gap-2">
              <i className="fas fa-cog text-emerald-600"></i> Parámetros del Cultivo
            </h2>

            <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Cultivo</label>
                <div className="grid grid-cols-2 gap-2">
                  {Object.values(TreeType).map((type) => (
                    <button
                      key={type}
                      onClick={() => setInput({ ...input, treeType: type })}
                      className={`flex items-center gap-2 p-3 rounded-xl border transition-all text-xs font-medium ${
                        input.treeType === type 
                        ? 'border-emerald-600 bg-emerald-50 text-emerald-900 shadow-sm' 
                        : 'border-slate-100 bg-slate-50 hover:border-emerald-200'
                      }`}
                    >
                      {TREE_TYPE_ICONS[type]}
                      <span className="truncate">{type}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Edad (años)</label>
                  <input type="number" min="1" value={input.treeAge} onChange={e => setInput({...input, treeAge: parseInt(e.target.value) || 1})} className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none" />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Cantidad Árboles</label>
                  <input type="number" min="1" value={input.numTrees} onChange={e => setInput({...input, numTrees: parseInt(e.target.value) || 1})} className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none" />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Salud del Lote</label>
                <div className="flex bg-slate-100 rounded-xl p-1">
                  {(['bueno', 'regular', 'deficiente'] as const).map(status => (
                    <button key={status} onClick={() => setInput({...input, healthStatus: status})} className={`flex-1 py-2 rounded-lg text-xs font-bold capitalize transition-all ${input.healthStatus === status ? 'bg-white text-emerald-800 shadow-md' : 'text-slate-500'}`}>{status}</button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-3xl shadow-xl p-6 border border-emerald-100">
            <h2 className="text-xl font-bold mb-4 text-emerald-900 flex items-center gap-2">
              <i className="fas fa-vial text-emerald-600"></i> Selección de Insumos y Precios
            </h2>
            <p className="text-xs text-slate-500 mb-4 italic">Selecciona los productos e ingresa el precio por unidad (Kg, L o Gramo).</p>

            <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
              {Object.values(OrganicProduct).map(product => {
                const isSelected = input.selectedProducts.includes(product);
                const unit = PRODUCT_UNITS[product];
                return (
                  <div key={product} className={`p-3 rounded-2xl border transition-all ${isSelected ? 'border-emerald-200 bg-emerald-50' : 'border-slate-100 bg-slate-50'}`}>
                    <div className="flex items-center justify-between gap-3 mb-2">
                      <div className="flex items-center gap-3">
                        <input type="checkbox" checked={isSelected} onChange={() => toggleProduct(product)} className="w-5 h-5 accent-emerald-600 cursor-pointer" />
                        <span className={`text-sm font-semibold ${isSelected ? 'text-emerald-900' : 'text-slate-600'}`}>{product}</span>
                      </div>
                      <span className="text-[10px] font-bold bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full uppercase">{unit}</span>
                    </div>
                    {isSelected && (
                      <div className="flex items-center gap-2 pl-8 animate-in fade-in duration-300">
                        <span className="text-xs text-emerald-700 font-bold">$</span>
                        <input 
                          type="number" 
                          placeholder={`Precio x ${unit}`}
                          value={input.productPrices[product]} 
                          onChange={e => handlePriceChange(product, parseFloat(e.target.value) || 0)}
                          className="flex-1 p-2 rounded-lg bg-white border border-emerald-200 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                        />
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            <button onClick={handleFetchAI} disabled={loading || input.selectedProducts.length === 0} className="w-full mt-6 bg-emerald-700 hover:bg-emerald-800 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-3 disabled:opacity-50 transition-all">
              {loading ? <div className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full"></div> : <i className="fas fa-brain"></i>}
              {loading ? 'Consultando...' : 'Analizar Mezcla con IA'}
            </button>
          </div>
        </section>

        {/* Results Section */}
        <section className="lg:col-span-7 space-y-6">
          {result && result.products.length > 0 ? (
            <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-emerald-100">
              <div className="bg-emerald-600 p-6 text-white flex justify-between items-center">
                <h3 className="text-xl font-bold flex items-center gap-2">
                  <i className="fas fa-receipt"></i> Desglose Técnico-Económico
                </h3>
                <div className="text-right">
                  <span className="text-[10px] uppercase font-bold opacity-80 block tracking-wider">Costo Total Proyecto</span>
                  <span className="text-2xl font-black">${result.totalProjectCost.toLocaleString()}</span>
                </div>
              </div>

              <div className="p-6 overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
