  SEA_SALT = 'Sal Marina'
}

export type UnitType = 'kg' | 'L' | 'g';

export interface CalculationInput {
  treeType: TreeType;
  treeAge: number;
  numTrees: number;
  selectedProducts: OrganicProduct[];
  productPrices: Record<string, number>; // Price per selected unit
  manualAmounts: Record<string, number | undefined>; // Manual override for dose per tree
  selectedUnits: Record<string, UnitType>; // User chosen unit for each product
  healthStatus: 'bueno' | 'regular' | 'deficiente';
}

export interface ProductResult {
  product: OrganicProduct;
  amount: number;
  unit: UnitType;
  costPerTree: number;
  totalCost: number;
}

export interface CalculationResult {
  products: ProductResult[];
  totalCostPerTree: number;
  totalProjectCost: number;
  frequency: string;
  notes: string;
}

export interface AIAdvice {
  tips: string[];
  seasonalAdvice: string;
  sustainabilityScore: number;
}

import React, { useState, useEffect, useCallback } from 'react';
import { TreeType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType } from './types';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS } from './constants';
import { getAgriculturalAdvice } from './services/geminiService';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    treeAge: 1,
    numTrees: 1,
    selectedProducts: [OrganicProduct.COMPOST],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);

  const calculateDose = useCallback(() => {
    let healthModifier = 1.0;
    if (input.healthStatus === 'regular') healthModifier = 1.25;
    if (input.healthStatus === 'deficiente') healthModifier = 1.5;

    const productResults: ProductResult[] = input.selectedProducts.map(product => {
      const baseRate = BASE_RATES[product];
      const defaultUnit = PRODUCT_UNITS[product];
      const selectedUnit = input.selectedUnits[product] || defaultUnit;
      const pricePerUnit = input.productPrices[product] || 0;
      const manualAmount = input.manualAmounts[product];

      let perTreeAmount: number;

      if (manualAmount !== undefined) {
        perTreeAmount = manualAmount;
      } else {
        const rawPerTree = input.treeAge * baseRate * healthModifier;
        // If the user changed the unit from the default, we still use the numeric baseRate 
        // logic but label it with the new unit for simplified manual adjustments.
        if (selectedUnit === 'kg') perTreeAmount = Math.min(rawPerTree, 20);
        else if (selectedUnit === 'L') perTreeAmount = Math.min(rawPerTree, 30);
        else perTreeAmount = Math.min(rawPerTree, 1000); // grams limit higher if manual
      }

      const costPerTree = perTreeAmount * pricePerUnit;
      const totalCost = costPerTree * input.numTrees;

      return {
        product,
        amount: parseFloat(perTreeAmount.toFixed(2)),
        unit: selectedUnit,
        costPerTree: parseFloat(costPerTree.toFixed(2)),
        totalCost: parseFloat(totalCost.toFixed(2))
      };
    });

    const totalCostPerTree = productResults.reduce((acc, curr) => acc + curr.costPerTree, 0);
    const totalProjectCost = totalCostPerTree * input.numTrees;

    setResult({
      products: productResults,
      totalCostPerTree: parseFloat(totalCostPerTree.toFixed(2)),
      totalProjectCost: parseFloat(totalProjectCost.toFixed(2)),
      frequency: "Variable según producto",
      notes: `Plan nutricional personalizado para ${input.numTrees} árboles.`
    });
  }, [input]);

  const handleFetchAI = async () => {
    if (input.selectedProducts.length === 0) return;
    setLoading(true);
    const advice = await getAgriculturalAdvice(input);
    setAiAdvice(advice);
    setLoading(false);
  };

  const toggleProduct = (product: OrganicProduct) => {
    setInput(prev => {
      const isSelected = prev.selectedProducts.includes(product);
      return {
        ...prev,
        selectedProducts: isSelected 
          ? prev.selectedProducts.filter(p => p !== product)
          : [...prev.selectedProducts, product]
      };
    });
  };

  const handlePriceChange = (product: OrganicProduct, price: number) => {
    setInput(prev => ({
      ...prev,
      productPrices: { ...prev.productPrices, [product]: price }
    }));
  };

  const handleManualAmountChange = (product: OrganicProduct, amount: number | undefined) => {
    setInput(prev => ({
      ...prev,
      manualAmounts: { ...prev.manualAmounts, [product]: amount }
    }));
  };

  const handleUnitChange = (product: OrganicProduct, unit: UnitType) => {
    setInput(prev => ({
      ...prev,
      selectedUnits: { ...prev.selectedUnits, [product]: unit }
    }));
  };

  useEffect(() => {
    calculateDose();
  }, [calculateDose]);

  return (
    <div className="min-h-screen bg-emerald-50 text-slate-800 pb-12">
      <nav className="bg-emerald-800 text-white p-4 shadow-lg sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <i className="fas fa-leaf text-2xl text-emerald-400"></i>
            <h1 className="text-xl font-bold tracking-tight">AgroCalculadora <span className="text-emerald-300">Pro</span></h1>
          </div>
          <div className="hidden md:block text-xs opacity-80 uppercase tracking-widest font-bold">
            Configuración Personalizada
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Input Section */}
        <section className="lg:col-span-5 space-y-6">
          <div className="bg-white rounded-3xl shadow-xl p-6 border border-emerald-100">
            <h2 className="text-xl font-bold mb-6 text-emerald-900 flex items-center gap-2">
              <i className="fas fa-cog text-emerald-600"></i> Parámetros de Campo
            </h2>

            <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Cultivo</label>
                <div className="grid grid-cols-2 gap-2">
                  {Object.values(TreeType).map((type) => (
                    <button
                      key={type}
                      onClick={() => setInput({ ...input, treeType: type })}
                      className={`flex items-center gap-2 p-3 rounded-xl border transition-all text-xs font-medium ${
                        input.treeType === type 
                        ? 'border-emerald-600 bg-emerald-50 text-emerald-900 shadow-sm' 
                        : 'border-slate-100 bg-slate-50 hover:border-emerald-200'
                      }`}
                    >
                      {TREE_TYPE_ICONS[type]}
                      <span className="truncate">{type}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Edad (años)</label>
                  <input type="number" min="1" value={input.treeAge} onChange={e => setInput({...input, treeAge: parseInt(e.target.value) || 1})} className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none" />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Cantidad Árboles</label>
                  <input type="number" min="1" value={input.numTrees} onChange={e => setInput({...input, numTrees: parseInt(e.target.value) || 1})} className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none" />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Vigor del Árbol</label>
                <div className="flex bg-slate-100 rounded-xl p-1">
                  {(['bueno', 'regular', 'deficiente'] as const).map(status => (
                    <button key={status} onClick={() => setInput({...input, healthStatus: status})} className={`flex-1 py-2 rounded-lg text-xs font-bold capitalize transition-all ${input.healthStatus === status ? 'bg-white text-emerald-800 shadow-md' : 'text-slate-500'}`}>{status}</button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-3xl shadow-xl p-6 border border-emerald-100">
            <h2 className="text-xl font-bold mb-4 text-emerald-900 flex items-center gap-2">
              <i className="fas fa-edit text-emerald-600"></i> Insumos y Unidades
            </h2>
            <p className="text-[11px] text-slate-500 mb-4 leading-relaxed">Configura la unidad de medida, dosis y precio. Los valores se recalculan automáticamente si dejas la dosis vacía.</p>

            <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
              {Object.values(OrganicProduct).map(product => {
                const isSelected = input.selectedProducts.includes(product);
                const currentUnit = input.selectedUnits[product];
                return (
                  <div key={product} className={`p-4 rounded-2xl border transition-all ${isSelected ? 'border-emerald-200 bg-emerald-50 shadow-sm' : 'border-slate-100 bg-slate-50'}`}>
                    <div className="flex items-center justify-between gap-3 mb-3">
                      <div className="flex items-center gap-3">
                        <input type="checkbox" checked={isSelected} onChange={() => toggleProduct(product)} className="w-5 h-5 accent-emerald-600 cursor-pointer" />
                        <span className={`text-sm font-bold ${isSelected ? 'text-emerald-900' : 'text-slate-400'}`}>{product}</span>
                      </div>

                      {isSelected && (
                        <select 
                          value={currentUnit} 
                          onChange={(e) => handleUnitChange(product, e.target.value as UnitType)}
                          className="text-[10px] font-bold bg-white border border-slate-200 text-emerald-700 px-2 py-1 rounded-md uppercase outline-none focus:ring-1 focus:ring-emerald-500 cursor-pointer"
                        >
                          <option value="kg">kg</option>
                          <option value="L">L</option>
                          <option value="g">g</option>
                        </select>
                      )}
                    </div>
                    {isSelected && (
                      <div className="grid grid-cols-2 gap-3 pl-8 animate-in fade-in duration-300">
                        <div>
                          <label className="text-[10px] font-bold text-emerald-700 uppercase mb-1 block">Dosis ({currentUnit})</label>
                          <input 
                            type="number" 
                            placeholder="Auto"
                            value={input.manualAmounts[product] ?? ''} 
                            onChange={e => handleManualAmountChange(product, e.target.value === '' ? undefined : parseFloat(e.target.value))}
                            className="w-full p-2 rounded-lg bg-white border border-emerald-200 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                          />
                        </div>
                        <div>
                          <label className="text-[10px] font-bold text-emerald-700 uppercase mb-1 block">Precio x {currentUnit}</label>
                          <div className="relative">
                            <span className="absolute left-2 top-1/2 -translate-y-1/2 text-emerald-400 text-xs">$</span>
                            <input 
                              type="number" 
                              value={input.productPrices[product]} 
                              onChange={e => handlePriceChange(product, parseFloat(e.target.value) || 0)}
                              className="w-full p-2 pl-5 rounded-lg bg-white border border-emerald-200 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                            />
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            <button onClick={handleFetchAI} disabled={loading || input.selectedProducts.length === 0} className="w-full mt-6 bg-emerald-700 hover:bg-emerald-800 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-3 disabled:opacity-50 transition-all">
              {loading ? <div className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full"></div> : <i className="fas fa-robot"></i>}
              {loading ? 'Analizando Mezcla...' : 'Consultar Recomendación IA'}
            </button>
          </div>
        </section>

        {/* Results Section */}
        <section className="lg:col-span-7 space-y-6">
          {result && result.products.length > 0 ? (
            <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-emerald-100">
              <div className="bg-emerald-600 p-6 text-white flex justify-between items-center">
                <div>
                  <h3 className="text-xl font-bold flex items-center gap-2">
                    <i className="fas fa-file-invoice-dollar"></i> Presupuesto de Nutrición
                  </h3>
                  <p className="text-xs text-white/70">Resumen detallado para {input.numTrees} árboles</p>
                </div>
                <div className="text-right">
                  <span className="text-[10px] uppercase font-bold opacity-80 block tracking-wider">Inversión Total</span>
                  <span className="text-3xl font-black">${result.totalProjectCost.toLocaleString()}</span>
                </div>
              </div>

              <div className="p-6 overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="text-slate-400 text-[10px] uppercase font-bold tracking-widest border-b border-slate-100">
                      <th className="pb-4">Insumo Seleccionado</th>
                      <th className="pb-4 text-center">Cant/Planta</th>
                      <th className="pb-4 text-right">Costo/Planta</th>
                      <th className="pb-4 text-right">Costo Lote</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {result.products.map(item => (
                      <tr key={item.product} className="group hover:bg-slate-50 transition-all">
                        <td className="py-4">
                          <span className="text-sm font-bold text-slate-700 block">{item.product}</span>
                        </td>
                        <td className="py-4 text-center">
                          <span className="text-sm font-black text-emerald-600">{item.amount}</span>
                          <span className="text-[10px] ml-1 font-bold text-slate-400 uppercase">{item.unit}</span>
                        </td>
                        <td className="py-4 text-right">
                          <span className="text-sm font-semibold text-slate-600">${item.costPerTree.toLocaleString()}</span>
                        </td>
                        <td className="py-4 text-right">
                          <span className="text-sm font-bold text-emerald-700">${item.totalCost.toLocaleString()}</span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="bg-emerald-50/50">
                      <td colSpan={2} className="py-4 px-2 text-right text-xs font-black text-slate-500 uppercase tracking-widest">Totales Unitarios</td>
                      <td className="py-4 text-right">
                        <span className="text-xl font-black text-emerald-900">${result.totalCostPerTree.toLocaleString()}</span>
                      </td>
                      <td className="py-4 text-right px-2">
                        <span className="text-[10px] font-bold text-slate-400">/ ÁRBOL</span>
                      </td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-3xl p-16 text-center border-2 border-dashed border-emerald-100 flex flex-col items-center justify-center">
              <div className="bg-emerald-50 h-20 w-20 rounded-full flex items-center justify-center mb-6">
                <i className="fas fa-shopping-basket text-3xl text-emerald-200"></i>
              </div>
              <h3 className="text-slate-400 font-bold text-lg mb-2">Calculadora en Espera</h3>
              <p className="text-slate-400 text-sm max-w-xs">Selecciona y configura los productos a la izquierda para ver el desglose económico.</p>
            </div>
          )}

          {/* AI Feedback */}
          {aiAdvice && (
            <div className="bg-gradient-to-br from-emerald-900 to-slate-900 rounded-3xl shadow-2xl p-8 text-white animate-in zoom-in duration-500">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="text-2xl font-bold flex items-center gap-3">
                    <i className="fas fa-microscope text-emerald-400"></i> Análisis de Sinergia
                  </h3>
                  <p className="text-emerald-400/60 text-xs mt-1">Interpretación técnica de tu mezcla personalizada</p>
                </div>
                <div className="bg-white/10 px-4 py-2 rounded-2xl border border-white/10 text-center">
                  <span className="text-[10px] uppercase font-bold text-white/40 block">Puntaje Eco</span>
                  <span className="text-2xl font-black text-emerald-400">{aiAdvice.sustainabilityScore}/10</span>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <h4 className="text-[10px] uppercase font-bold tracking-widest text-emerald-400 border-b border-emerald-400/20 pb-2">Instrucciones de Campo</h4>
                  {aiAdvice.tips.map((tip, idx) => (
                    <div key={idx} className="flex gap-4 p-4 bg-white/5 rounded-2xl border border-white/10 hover:bg-white/10 transition-all group">
                      <span className="text-emerald-400 font-black opacity-30 group-hover:opacity-100 transition-opacity">{idx+1}</span>
                      <p className="text-sm text-white/80 leading-relaxed">{tip}</p>
                    </div>
                  ))}
                </div>
                <div className="space-y-6">
                  <div className="p-6 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
                    <h4 className="text-[10px] uppercase font-bold tracking-widest text-emerald-400 mb-3">Recomendación Fenológica</h4>
                    <p className="text-sm italic text-white/90 leading-relaxed">"{aiAdvice.seasonalAdvice}"</p>
                  </div>
                  <div className="p-6 bg-blue-500/5 rounded-2xl border border-blue-500/10 flex items-center gap-4">
                    <i className="fas fa-info-circle text-blue-400 text-2xl"></i>
                    <p className="text-xs text-blue-100/60">Recuerda que estas dosis son sugerencias técnicas. La observación directa en campo es fundamental.</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="max-w-6xl mx-auto px-4 mt-12 text-center text-slate-400 text-xs flex flex-col items-center gap-2">
        <p>© 2024 AgroCalculadora Pro - Nutrición Vegetal Sostenible</p>
        <div className="flex gap-4 text-emerald-600/30">
          <i className="fas fa-mountain"></i>
          <i className="fas fa-seedling"></i>
          <i className="fas fa-hand-holding-water"></i>
        </div>
      </footer>
    </div>
  );
};

