import React from 'react';
import { TreeType, OrganicProduct, UnitType } from './types';

export const TREE_TYPE_ICONS: Record<TreeType, React.ReactNode> = {
  [TreeType.CITRUS]: <i className="fas fa-lemon text-yellow-500"></i>,
  [TreeType.AVOCADO]: <i className="fas fa-seedling text-green-700"></i>,
  [TreeType.MANGO]: <i className="fas fa-sun text-orange-400"></i>,
  [TreeType.COFFEE]: <i className="fas fa-mug-hot text-brown-600"></i>,
  [TreeType.CACAO]: <i className="fas fa-cookie text-amber-800"></i>,
  [TreeType.FRUIT_GENERAL]: <i className="fas fa-apple-whole text-red-500"></i>,
  [TreeType.FOREST]: <i className="fas fa-tree text-emerald-800"></i>,
};

// Tasas base (relativas, se adaptarán según la unidad seleccionada o se usarán como kg/L/g base)
export const BASE_RATES: Record<OrganicProduct, number> = {
  [OrganicProduct.COMPOST]: 1.5,
  [OrganicProduct.BOKASHI]: 1.0,
  [OrganicProduct.HUMUS]: 0.8,
  [OrganicProduct.BIOFERTILIZER]: 2.0,
  [OrganicProduct.PURINE]: 1.5,
  [OrganicProduct.ROCK_DUST]: 0.3,
  [OrganicProduct.BORON]: 5,
  [OrganicProduct.ZINC]: 5,
  [OrganicProduct.COPPER]: 3,
  [OrganicProduct.MAGNESIUM]: 15,
  [OrganicProduct.EM]: 0.2,
  [OrganicProduct.SEA_SALT]: 10,
};

export const PRODUCT_UNITS: Record<OrganicProduct, UnitType> = {
  [OrganicProduct.COMPOST]: 'kg',
  [OrganicProduct.BOKASHI]: 'kg',
  [OrganicProduct.HUMUS]: 'kg',
  [OrganicProduct.BIOFERTILIZER]: 'L',
  [OrganicProduct.PURINE]: 'L',
  [OrganicProduct.ROCK_DUST]: 'kg',
  [OrganicProduct.BORON]: 'g',
  [OrganicProduct.ZINC]: 'g',
  [OrganicProduct.COPPER]: 'g',
  [OrganicProduct.MAGNESIUM]: 'g',
  [OrganicProduct.EM]: 'L',
  [OrganicProduct.SEA_SALT]: 'g',
};

import React, { useState, useEffect, useCallback } from 'react';
import { TreeType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType } from './types';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS } from './constants';
import { getAgriculturalAdvice } from './services/geminiService';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    treeAge: 1,
    numTrees: 1,
    selectedProducts: [OrganicProduct.COMPOST],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);

  const calculateDose = useCallback(() => {
    let healthModifier = 1.0;
    if (input.healthStatus === 'regular') healthModifier = 1.25;
    if (input.healthStatus === 'deficiente') healthModifier = 1.5;

    const productResults: ProductResult[] = input.selectedProducts.map(product => {
      const baseRate = BASE_RATES[product];
      const defaultUnit = PRODUCT_UNITS[product];
      const selectedUnit = input.selectedUnits[product] || defaultUnit;
      const pricePerUnit = input.productPrices[product] || 0;
      const manualAmount = input.manualAmounts[product];

      let perTreeAmount: number;

      if (manualAmount !== undefined) {
        perTreeAmount = manualAmount;
      } else {
        const rawPerTree = input.treeAge * baseRate * healthModifier;
        // Lógica de topes base según tipo de unidad
        if (selectedUnit === 'kg' || selectedUnit === 'L') {
          perTreeAmount = Math.min(rawPerTree, 25);
        } else if (selectedUnit === 'g' || selectedUnit === 'cc' || selectedUnit === 'ml') {
          // Si la tasa base era para kg y ahora es g, multiplicamos (estimación simple)
          // pero si el producto ya venía en g, lo dejamos.
          if (defaultUnit === 'kg' || defaultUnit === 'L') {
             perTreeAmount = Math.min(rawPerTree * 1000, 5000); 
          } else {
             perTreeAmount = Math.min(rawPerTree, 1000);
          }
        } else {
          perTreeAmount = rawPerTree;
        }
      }

      const costPerTree = perTreeAmount * pricePerUnit;
      const totalCost = costPerTree * input.numTrees;

      return {
        product,
        amount: parseFloat(perTreeAmount.toFixed(2)),
        unit: selectedUnit,
        costPerTree: parseFloat(costPerTree.toFixed(2)),
        totalCost: parseFloat(totalCost.toFixed(2))
      };
    });

    const totalCostPerTree = productResults.reduce((acc, curr) => acc + curr.costPerTree, 0);
    const totalProjectCost = totalCostPerTree * input.numTrees;

    setResult({
      products: productResults,
      totalCostPerTree: parseFloat(totalCostPerTree.toFixed(2)),
      totalProjectCost: parseFloat(totalProjectCost.toFixed(2)),
      frequency: "Variable según producto",
      notes: `Mezcla para ${input.numTrees} árboles. Verifique diluciones si usa unidades pequeñas (cc/ml/g).`
    });
  }, [input]);

  const handleFetchAI = async () => {
    if (input.selectedProducts.length === 0) return;
    setLoading(true);
    const advice = await getAgriculturalAdvice(input);
    setAiAdvice(advice);
    setLoading(false);
  };

  const toggleProduct = (product: OrganicProduct) => {
    setInput(prev => {
      const isSelected = prev.selectedProducts.includes(product);
      return {
        ...prev,
        selectedProducts: isSelected 
          ? prev.selectedProducts.filter(p => p !== product)
          : [...prev.selectedProducts, product]
      };
    });
  };

  const handlePriceChange = (product: OrganicProduct, price: number) => {
    setInput(prev => ({
      ...prev,
      productPrices: { ...prev.productPrices, [product]: price }
    }));
  };

  const handleManualAmountChange = (product: OrganicProduct, amount: number | undefined) => {
    setInput(prev => ({
      ...prev,
      manualAmounts: { ...prev.manualAmounts, [product]: amount }
    }));
  };

  const handleUnitChange = (product: OrganicProduct, unit: UnitType) => {
    setInput(prev => ({
      ...prev,
      selectedUnits: { ...prev.selectedUnits, [product]: unit }
    }));
  };

  useEffect(() => {
    calculateDose();
  }, [calculateDose]);

  return (
    <div className="min-h-screen bg-emerald-50 text-slate-800 pb-12">
      <nav className="bg-emerald-800 text-white p-4 shadow-lg sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <i className="fas fa-leaf text-2xl text-emerald-400"></i>
            <h1 className="text-xl font-bold tracking-tight">AgroCalculadora <span className="text-emerald-300">Pro</span></h1>
          </div>
          <div className="hidden md:block text-xs opacity-80 uppercase tracking-widest font-bold">
            Métricas de Precisión
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Input Section */}
        <section className="lg:col-span-5 space-y-6">
          <div className="bg-white rounded-3xl shadow-xl p-6 border border-emerald-100">
            <h2 className="text-xl font-bold mb-6 text-emerald-900 flex items-center gap-2">
              <i className="fas fa-cog text-emerald-600"></i> Parámetros de Campo
            </h2>

            <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Cultivo</label>
                <div className="grid grid-cols-2 gap-2">
                  {Object.values(TreeType).map((type) => (
                    <button
                      key={type}
                      onClick={() => setInput({ ...input, treeType: type })}
                      className={`flex items-center gap-2 p-3 rounded-xl border transition-all text-xs font-medium ${
                        input.treeType === type 
                        ? 'border-emerald-600 bg-emerald-50 text-emerald-900 shadow-sm' 
                        : 'border-slate-100 bg-slate-50 hover:border-emerald-200'
                      }`}
                    >
                      {TREE_TYPE_ICONS[type]}
                      <span className="truncate">{type}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Edad (años)</label>
                  <input type="number" min="1" value={input.treeAge} onChange={e => setInput({...input, treeAge: parseInt(e.target.value) || 1})} className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none" />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Cantidad Árboles</label>
                  <input type="number" min="1" value={input.numTrees} onChange={e => setInput({...input, numTrees: parseInt(e.target.value) || 1})} className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none" />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Vigor del Árbol</label>
                <div className="flex bg-slate-100 rounded-xl p-1">
                  {(['bueno', 'regular', 'deficiente'] as const).map(status => (
                    <button key={status} onClick={() => setInput({...input, healthStatus: status})} className={`flex-1 py-2 rounded-lg text-xs font-bold capitalize transition-all ${input.healthStatus === status ? 'bg-white text-emerald-800 shadow-md' : 'text-slate-500'}`}>{status}</button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-3xl shadow-xl p-6 border border-emerald-100">
            <h2 className="text-xl font-bold mb-4 text-emerald-900 flex items-center gap-2">
              <i className="fas fa-balance-scale text-emerald-600"></i> Insumos y Unidades
            </h2>
            <p className="text-[11px] text-slate-500 mb-4 leading-relaxed">Elige entre gramos, kilogramos, cc, ml o litros. Ajusta el precio y dosis según la unidad elegida.</p>

            <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
              {Object.values(OrganicProduct).map(product => {
                const isSelected = input.selectedProducts.includes(product);
                const currentUnit = input.selectedUnits[product];
                return (
                  <div key={product} className={`p-4 rounded-2xl border transition-all ${isSelected ? 'border-emerald-200 bg-emerald-50 shadow-sm' : 'border-slate-100 bg-slate-50'}`}>
                    <div className="flex items-center justify-between gap-3 mb-3">
                      <div className="flex items-center gap-3">
                        <input type="checkbox" checked={isSelected} onChange={() => toggleProduct(product)} className="w-5 h-5 accent-emerald-600 cursor-pointer" />
                        <span className={`text-sm font-bold ${isSelected ? 'text-emerald-900' : 'text-slate-400'}`}>{product}</span>
                      </div>

                      {isSelected && (
                        <div className="flex items-center gap-1">
                          <i className="fas fa-tag text-[9px] text-emerald-600"></i>
                          <select 
                            value={currentUnit} 
                            onChange={(e) => handleUnitChange(product, e.target.value as UnitType)}
                            className="text-[10px] font-bold bg-white border border-slate-200 text-emerald-700 px-2 py-1 rounded-md uppercase outline-none focus:ring-1 focus:ring-emerald-500 cursor-pointer"
                          >
                            <option value="g">gramos</option>
                            <option value="kg">kilogramos</option>
                            <option value="cc">cc</option>
                            <option value="ml">ml</option>
                            <option value="L">litros</option>
                          </select>
                        </div>
                      )}
                    </div>
                    {isSelected && (
                      <div className="grid grid-cols-2 gap-3 pl-8 animate-in fade-in duration-300">
                        <div>
                          <label className="text-[10px] font-bold text-emerald-700 uppercase mb-1 block">Dosis ({currentUnit})</label>
                          <input 
                            type="number" 
                            placeholder="Auto"
                            value={input.manualAmounts[product] ?? ''} 
                            onChange={e => handleManualAmountChange(product, e.target.value === '' ? undefined : parseFloat(e.target.value))}
                            className="w-full p-2 rounded-lg bg-white border border-emerald-200 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                          />
                        </div>
                        <div>
                          <label className="text-[10px] font-bold text-emerald-700 uppercase mb-1 block">Precio x {currentUnit}</label>
                          <div className="relative">
                            <span className="absolute left-2 top-1/2 -translate-y-1/2 text-emerald-400 text-xs">$</span>
                            <input 
                              type="number" 
                              value={input.productPrices[product]} 
                              onChange={e => handlePriceChange(product, parseFloat(e.target.value) || 0)}
                              className="w-full p-2 pl-5 rounded-lg bg-white border border-emerald-200 text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
                            />
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            <button onClick={handleFetchAI} disabled={loading || input.selectedProducts.length === 0} className="w-full mt-6 bg-emerald-700 hover:bg-emerald-800 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-3 disabled:opacity-50 transition-all">
              {loading ? <div className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full"></div> : <i className="fas fa-robot"></i>}
              {loading ? 'Analizando Mezcla...' : 'Consultar Recomendación IA'}
            </button>
          </div>
        </section>

        {/* Results Section */}
        <section className="lg:col-span-7 space-y-6">
          {result && result.products.length > 0 ? (
            <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-emerald-100">
              <div className="bg-emerald-600 p-6 text-white flex justify-between items-center">
                <div>
                  <h3 className="text-xl font-bold flex items-center gap-2">
                    <i className="fas fa-file-invoice-dollar"></i> Presupuesto de Nutrición
                  </h3>
                  <p className="text-xs text-white/70">Resumen para {input.numTrees} árboles</p>
                </div>
                <div className="text-right">
                  <span className="text-[10px] uppercase font-bold opacity-80 block tracking-wider">Inversión Total</span>
                  <span className="text-3xl font-black">${result.totalProjectCost.toLocaleString()}</span>
                </div>
              </div>

              <div className="p-6 overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="text-slate-400 text-[10px] uppercase font-bold tracking-widest border-b border-slate-100">
                      <th className="pb-4">Insumo</th>
                      <th className="pb-4 text-center">Cant/Planta</th>
                      <th className="pb-4 text-right">Costo/Planta</th>
                      <th className="pb-4 text-right">Costo Lote</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {result.products.map(item => (
                      <tr key={item.product} className="group hover:bg-slate-50 transition-all">
                        <td className="py-4">
                          <span className="text-sm font-bold text-slate-700 block">{item.product}</span>
                        </td>
                        <td className="py-4 text-center">
                          <span className="text-sm font-black text-emerald-600">{item.amount}</span>
                          <span className="text-[10px] ml-1 font-bold text-slate-400 uppercase">{item.unit}</span>
                        </td>
                        <td className="py-4 text-right">
                          <span className="text-sm font-semibold text-slate-600">${item.costPerTree.toLocaleString()}</span>
                        </td>
                        <td className="py-4 text-right">
                          <span className="text-sm font-bold text-emerald-700">${item.totalCost.toLocaleString()}</span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="bg-emerald-50/50">
                      <td colSpan={2} className="py-4 px-2 text-right text-xs font-black text-slate-500 uppercase tracking-widest">Totales Unitarios</td>
                      <td className="py-4 text-right">
                        <span className="text-xl font-black text-emerald-900">${result.totalCostPerTree.toLocaleString()}</span>
                      </td>
                      <td className="py-4 text-right px-2">
                        <span className="text-[10px] font-bold text-slate-400">/ ÁRBOL</span>
                      </td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-3xl p-16 text-center border-2 border-dashed border-emerald-100 flex flex-col items-center justify-center">
              <div className="bg-emerald-50 h-20 w-20 rounded-full flex items-center justify-center mb-6 shadow-inner">
                <i className="fas fa-flask text-3xl text-emerald-200"></i>
              </div>
              <h3 className="text-slate-400 font-bold text-lg mb-2">Calculadora en Espera</h3>
              <p className="text-slate-400 text-sm max-w-xs leading-relaxed">Configura los insumos a la izquierda para ver el desglose económico y nutricional.</p>
            </div>
          )}

          {/* AI Feedback */}
          {aiAdvice && (
            <div className="bg-gradient-to-br from-emerald-900 to-slate-900 rounded-3xl shadow-2xl p-8 text-white animate-in zoom-in duration-500 border border-white/5">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="text-2xl font-bold flex items-center gap-3">
                    <i className="fas fa-vial text-emerald-400"></i> Análisis de Sinergia
                  </h3>
                  <p className="text-emerald-400/60 text-xs mt-1">Sugerencias técnicas basadas en las unidades seleccionadas</p>
                </div>
                <div className="bg-white/10 px-4 py-2 rounded-2xl border border-white/10 text-center backdrop-blur-md">
                  <span className="text-[10px] uppercase font-bold text-white/40 block">Puntaje Eco</span>
                  <span className="text-2xl font-black text-emerald-400">{aiAdvice.sustainabilityScore}/10</span>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <h4 className="text-[10px] uppercase font-bold tracking-widest text-emerald-400 border-b border-emerald-400/20 pb-2">Protocolo de Aplicación</h4>
                  {aiAdvice.tips.map((tip, idx) => (
                    <div key={idx} className="flex gap-4 p-4 bg-white/5 rounded-2xl border border-white/10 hover:bg-white/10 transition-all group">
                      <div className="h-8 w-8 rounded-full bg-emerald-500/20 flex items-center justify-center border border-emerald-500/30 group-hover:bg-emerald-500 group-hover:text-white transition-all">
                        <span className="text-xs font-black">{idx+1}</span>
                      </div>
                      <p className="text-sm text-white/80 leading-relaxed">{tip}</p>
                    </div>
                  ))}
                </div>
                <div className="space-y-6">
                  <div className="p-6 bg-emerald-500/10 rounded-2xl border border-emerald-500/20 backdrop-blur-sm">
                    <h4 className="text-[10px] uppercase font-bold tracking-widest text-emerald-400 mb-3 flex items-center gap-2">
                      <i className="fas fa-history"></i> Momento Ideal
                    </h4>
                    <p className="text-sm italic text-white/90 leading-relaxed">"{aiAdvice.seasonalAdvice}"</p>
                  </div>
                  <div className="p-6 bg-blue-500/5 rounded-2xl border border-blue-500/10 flex items-center gap-4">
                    <i className="fas fa-info-circle text-blue-400 text-2xl"></i>
                    <p className="text-[11px] text-blue-100/60 leading-tight">Las unidades de volumen (cc/ml) suelen requerir pre-dilución antes de la aplicación en drench o foliar.</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="max-w-6xl mx-auto px-4 mt-12 text-center text-slate-400 text-xs flex flex-col items-center gap-2">
        <div className="h-px w-32 bg-emerald-200/20 mb-4"></div>
        <p>© 2024 AgroCalculadora Pro - Nutrición de Precisión</p>
        <div className="flex gap-6 text-emerald-600/20 mt-2">
          <i className="fas fa-weight-hanging" title="Gramos / Kilogramos"></i>
          <i className="fas fa-prescription-bottle" title="cc / ml / Litros"></i>
          <i className="fas fa-seedling" title="Crecimiento Sostenible"></i>
        </div>
      </footer>
    </div>
  );
};

export default App;

export enum TreeType {
  CITRUS = 'Cítricos (Limón, Naranja)',
  AVOCADO = 'Aguacate',
  MANGO = 'Mango',
  COFFEE = 'Café',
  CACAO = 'Cacao',
  FRUIT_GENERAL = 'Frutales Caducifolios (Manzano, Durazno)',
  FOREST = 'Forestales / Ornamentales'
}

export enum OrganicProduct {
  // Líquidos
  POTASSIUM_SOAP = 'Jabón Potásico',
  LIQUID_HUMUS = 'Humus Líquido',
  LIQUID_IRON_OXIDE = 'Óxido de Hierro Líquido',
  EM = 'EM (Microorganismos Eficaces)',
  MOLASSES = 'Melaza',
  SULFUR_FUNGICIDE = 'Fungicida de Azufre',
  NEEM_EXTRACT = 'Extracto de Neem',

  // Sólidos
  BORON = 'Boro',
  ZINC = 'Zinc',
  COPPER = 'Cobre',
  COMPOST_TERRABONO = 'Compost (Terrabono)',
  SEA_SALT = 'Sal Marina',
  ROCK_DUST = 'Harina de Roca',
  PHOSPHATE_ROCK = 'Roca Fosfórica',
  CALCIUM_CARBONATE = 'Carbonato de Calcio',
  LEONARDITE = 'Leonardita',
  DIATOMACEOUS_EARTH = 'Tierra de Diatomea',
  MAGNESITE = 'Magnesita'
}

export type UnitType = 'g' | 'kg' | 'cc' | 'ml' | 'L';

export interface CalculationInput {
  treeType: TreeType;
  treeAge: number;
  numTrees: number;
  selectedProducts: OrganicProduct[];
  productPrices: Record<string, number>; // Precio en COP
  manualAmounts: Record<string, number | undefined>; // Dosis por árbol
  selectedUnits: Record<string, UnitType>; // Unidad elegida
  healthStatus: 'bueno' | 'regular' | 'deficiente';
}

export interface ProductResult {
  product: OrganicProduct;
  amount: number;
  unit: UnitType;
  costPerTree: number;
  totalCost: number;
}

export interface CalculationResult {
  products: ProductResult[];
  totalCostPerTree: number;
  totalProjectCost: number;
  frequency: string;
  notes: string;
}

export interface AIAdvice {
  tips: string[];
  seasonalAdvice: string;
  sustainabilityScore: number;
}

import React, { useState, useEffect, useCallback } from 'react';
import { TreeType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType } from './types';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES } from './constants';
import { getAgriculturalAdvice } from './services/geminiService';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    treeAge: 1,
    numTrees: 1,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);

  const calculateDose = useCallback(() => {
    let healthModifier = 1.0;
    if (input.healthStatus === 'regular') healthModifier = 1.25;
    if (input.healthStatus === 'deficiente') healthModifier = 1.5;

    const productResults: ProductResult[] = input.selectedProducts.map(product => {
      const baseRate = BASE_RATES[product];
      const defaultUnit = PRODUCT_UNITS[product];
      const selectedUnit = input.selectedUnits[product] || defaultUnit;
      const pricePerUnit = input.productPrices[product] || 0;
      const manualAmount = input.manualAmounts[product];

      let perTreeAmount: number;

      if (manualAmount !== undefined) {
        perTreeAmount = manualAmount;
      } else {
        const rawPerTree = input.treeAge * baseRate * healthModifier;
        // Ajuste de topes por unidad
        if (selectedUnit === 'kg' || selectedUnit === 'L') {
          perTreeAmount = Math.min(rawPerTree, 30);
        } else {
          perTreeAmount = rawPerTree;
        }
      }

      const costPerTree = perTreeAmount * pricePerUnit;
      const totalCost = costPerTree * input.numTrees;

      return {
        product,
        amount: parseFloat(perTreeAmount.toFixed(2)),
        unit: selectedUnit,
        costPerTree: parseFloat(costPerTree.toFixed(2)),
        totalCost: parseFloat(totalCost.toFixed(2))
      };
    });

    const totalCostPerTree = productResults.reduce((acc, curr) => acc + curr.costPerTree, 0);
    const totalProjectCost = totalCostPerTree * input.numTrees;

    setResult({
      products: productResults,
      totalCostPerTree: parseFloat(totalCostPerTree.toFixed(2)),
      totalProjectCost: parseFloat(totalProjectCost.toFixed(2)),
      frequency: "Variable según producto",
      notes: `Mezcla para ${input.numTrees} árboles. Precios en Pesos Colombianos (COP).`
    });
  }, [input]);

  const handleFetchAI = async () => {
    if (input.selectedProducts.length === 0) return;
    setLoading(true);
    const advice = await getAgriculturalAdvice(input);
    setAiAdvice(advice);
    setLoading(false);
  };

  const toggleProduct = (product: OrganicProduct) => {
    setInput(prev => {
      const isSelected = prev.selectedProducts.includes(product);
      return {
        ...prev,
        selectedProducts: isSelected 
          ? prev.selectedProducts.filter(p => p !== product)
          : [...prev.selectedProducts, product]
      };
    });
  };

  const handlePriceChange = (product: OrganicProduct, price: number) => {
    setInput(prev => ({
      ...prev,
      productPrices: { ...prev.productPrices, [product]: price }
    }));
  };

  const handleManualAmountChange = (product: OrganicProduct, amount: number | undefined) => {
    setInput(prev => ({
      ...prev,
      manualAmounts: { ...prev.manualAmounts, [product]: amount }
    }));
  };

  const handleUnitChange = (product: OrganicProduct, unit: UnitType) => {
    setInput(prev => ({
      ...prev,
      selectedUnits: { ...prev.selectedUnits, [product]: unit }
    }));
  };

  useEffect(() => {
    calculateDose();
  }, [calculateDose]);

  const renderProductGroup = (title: string, products: OrganicProduct[], icon: string) => (
    <div className="mb-6">
      <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
        <i className={`fas ${icon} text-emerald-500`}></i> {title}
      </h3>
      <div className="space-y-3">
        {products.map(product => {
          const isSelected = input.selectedProducts.includes(product);
          const currentUnit = input.selectedUnits[product];
          return (
            <div key={product} className={`p-4 rounded-2xl border transition-all ${isSelected ? 'border-emerald-200 bg-emerald-50 shadow-sm' : 'border-slate-100 bg-slate-50 opacity-70 hover:opacity-100'}`}>
              <div className="flex items-center justify-between gap-3 mb-2">
                <div className="flex items-center gap-3">
                  <input type="checkbox" checked={isSelected} onChange={() => toggleProduct(product)} className="w-5 h-5 accent-emerald-600 cursor-pointer" />
                  <span className={`text-sm font-bold ${isSelected ? 'text-emerald-900' : 'text-slate-600'}`}>{product}</span>
                </div>
                {isSelected && (
                  <select 
                    value={currentUnit} 
                    onChange={(e) => handleUnitChange(product, e.target.value as UnitType)}
                    className="text-[10px] font-bold bg-white border border-slate-200 text-emerald-700 px-2 py-1 rounded-md uppercase"
                  >
                    <option value="g">gramos</option>
                    <option value="kg">kilogramos</option>
                    <option value="cc">cc</option>
                    <option value="ml">ml</option>
                    <option value="L">litros</option>
                  </select>
                )}
              </div>
              {isSelected && (
                <div className="grid grid-cols-2 gap-3 pl-8 animate-in fade-in duration-300">
                  <div>
                    <label className="text-[9px] font-bold text-emerald-700 uppercase mb-1 block">Dosis ({currentUnit})</label>
                    <input type="number" placeholder="Auto" value={input.manualAmounts[product] ?? ''} onChange={e => handleManualAmountChange(product, e.target.value === '' ? undefined : parseFloat(e.target.value))} className="w-full p-2 rounded-lg bg-white border border-emerald-100 text-sm focus:ring-1 focus:ring-emerald-500 outline-none" />
                  </div>
                  <div>
                    <label className="text-[9px] font-bold text-emerald-700 uppercase mb-1 block">Precio ({currentUnit})</label>
                    <div className="relative">
                      <span className="absolute left-2 top-1/2 -translate-y-1/2 text-emerald-400 text-xs">$</span>
                      <input type="number" value={input.productPrices[product]} onChange={e => handlePriceChange(product, parseFloat(e.target.value) || 0)} className="w-full p-2 pl-5 rounded-lg bg-white border border-emerald-100 text-sm focus:ring-1 focus:ring-emerald-500 outline-none" />
                    </div>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 pb-12 font-sans">
      <nav className="bg-emerald-900 text-white p-5 shadow-xl sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="bg-emerald-500 p-2 rounded-lg shadow-lg">
              <i className="fas fa-seedling text-white text-xl"></i>
            </div>
            <div>
              <h1 className="text-xl font-black tracking-tighter">AgroCalculadora <span className="text-emerald-400">CO</span></h1>
              <p className="text-[10px] text-emerald-400/60 uppercase font-bold tracking-widest">Precisión Colombiana</p>
            </div>
          </div>
          <div className="text-right">
            <span className="text-xs font-black bg-emerald-800 px-3 py-1 rounded-full border border-emerald-700">MODO: REGENERATIVO</span>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Panel Izquierdo: Configuración */}
        <section className="lg:col-span-5 space-y-6">
          <div className="bg-white rounded-[2rem] shadow-sm p-8 border border-slate-200/60">
            <h2 className="text-lg font-black mb-6 text-slate-800 flex items-center gap-2">
              <i className="fas fa-map-marker-alt text-emerald-600"></i> Lote y Cultivo
            </h2>

            <div className="space-y-5">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-3 block tracking-widest">Tipo de Árbol</label>
                <div className="grid grid-cols-2 gap-2">
                  {Object.values(TreeType).map((type) => (
                    <button
                      key={type}
                      onClick={() => setInput({ ...input, treeType: type })}
                      className={`flex items-center gap-3 p-3 rounded-2xl border-2 transition-all text-xs font-bold ${
                        input.treeType === type 
                        ? 'border-emerald-600 bg-emerald-50 text-emerald-900 shadow-sm' 
                        : 'border-slate-100 bg-slate-50 text-slate-400 hover:border-emerald-200'
                      }`}
                    >
                      {TREE_TYPE_ICONS[type]}
                      <span className="truncate">{type}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Edad Árbol</label>
                  <input type="number" min="1" value={input.treeAge} onChange={e => setInput({...input, treeAge: parseInt(e.target.value) || 1})} className="w-full p-4 rounded-2xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none font-black text-lg" />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Nº de Árboles</label>
                  <input type="number" min="1" value={input.numTrees} onChange={e => setInput({...input, numTrees: parseInt(e.target.value) || 1})} className="w-full p-4 rounded-2xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none font-black text-lg" />
                </div>
              </div>

              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Vigor General</label>
                <div className="flex bg-slate-100 rounded-2xl p-1.5">
                  {(['bueno', 'regular', 'deficiente'] as const).map(status => (
                    <button key={status} onClick={() => setInput({...input, healthStatus: status})} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${input.healthStatus === status ? 'bg-white text-emerald-900 shadow-sm' : 'text-slate-400'}`}>{status}</button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-[2rem] shadow-sm p-8 border border-slate-200/60">
            <h2 className="text-lg font-black mb-2 text-slate-800 flex items-center gap-2">
              <i className="fas fa-layer-group text-emerald-600"></i> Portafolio de Insumos
            </h2>
            <p className="text-[10px] text-slate-400 uppercase font-bold mb-6 tracking-tight">Separados por estado físico</p>

            <div className="max-h-[600px] overflow-y-auto pr-3 custom-scrollbar">
              {renderProductGroup("Insumos Líquidos", PRODUCT_CATEGORIES.LIQUIDS, "fa-tint")}
              <div className="h-px bg-slate-100 my-8"></div>
              {renderProductGroup("Enmiendas Sólidas", PRODUCT_CATEGORIES.SOLIDS, "fa-mountain")}
            </div>

            <button onClick={handleFetchAI} disabled={loading || input.selectedProducts.length === 0} className="w-full mt-8 bg-emerald-600 hover:bg-emerald-700 text-white font-black py-5 rounded-2xl shadow-lg flex items-center justify-center gap-3 disabled:opacity-50 transition-all uppercase tracking-widest text-xs">
              {loading ? <div className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full"></div> : <i className="fas fa-brain"></i>}
              {loading ? 'Analizando...' : 'Consultar Agrónomo IA'}
            </button>
          </div>
        </section>

        {/* Panel Derecho: Resultados */}
        <section className="lg:col-span-7 space-y-6">
          {result && result.products.length > 0 ? (
            <div className="bg-white rounded-[2.5rem] shadow-xl overflow-hidden border border-slate-200/50">
              <div className="bg-gradient-to-r from-emerald-900 to-emerald-800 p-10 text-white flex justify-between items-center relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-10">
                  <i className="fas fa-file-invoice-dollar text-9xl"></i>
                </div>
                <div className="relative z-10">
                  <h3 className="text-2xl font-black mb-2 flex items-center gap-3">
                    Presupuesto Técnico
                  </h3>
                  <div className="bg-emerald-500/20 inline-block px-3 py-1 rounded-lg border border-emerald-500/30">
                    <p className="text-[10px] uppercase font-bold text-emerald-400 tracking-widest">Plan para {input.numTrees} árboles</p>
                  </div>
                </div>
                <div className="text-right relative z-10">
                  <p className="text-[10px] uppercase font-black text-emerald-400/60 block mb-1">Inversión Total (COP)</p>
                  <span className="text-4xl font-black tabular-nums">${result.totalProjectCost.toLocaleString('es-CO')}</span>
                </div>
              </div>

              <div className="p-10">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="text-slate-400 text-[10px] uppercase font-black tracking-widest border-b border-slate-100">
                        <th className="pb-6">Insumo Nutricional</th>
                        <th className="pb-6 text-center">Dosis</th>
                        <th className="pb-6 text-right">Vr. Árbol</th>
                        <th className="pb-6 text-right">Subtotal</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {result.products.map(item => (
                        <tr key={item.product} className="group hover:bg-slate-50/50 transition-all">
                          <td className="py-6">
                            <span className="text-sm font-black text-slate-800 block">{item.product}</span>
                            <span className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">
                              {PRODUCT_CATEGORIES.LIQUIDS.includes(item.product) ? 'Estado Líquido' : 'Estado Sólido'}
                            </span>
                          </td>
                          <td className="py-6 text-center">
                            <span className="text-lg font-black text-emerald-600 tabular-nums">{item.amount}</span>
                            <span className="text-[10px] ml-1.5 font-bold text-slate-400 uppercase">{item.unit}</span>
                          </td>
                          <td className="py-6 text-right">
                            <span className="text-sm font-bold text-slate-600 tabular-nums">${item.costPerTree.toLocaleString('es-CO')}</span>
                          </td>
                          <td className="py-6 text-right">
                            <span className="text-sm font-black text-emerald-900 tabular-nums">${item.totalCost.toLocaleString('es-CO')}</span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot>
                      <tr className="bg-slate-50/80">
                        <td colSpan={2} className="py-6 px-6 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Costo Unitario por Árbol</td>
                        <td className="py-6 text-right px-10" colSpan={2}>
                          <span className="text-3xl font-black text-emerald-900 tabular-nums">${result.totalCostPerTree.toLocaleString('es-CO')}</span>
                          <span className="text-[10px] font-black text-emerald-600/60 ml-2">COP</span>
                        </td>
                      </tr>
                    </tfoot>
                  </table>
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[3rem] p-24 text-center border-2 border-dashed border-slate-200 flex flex-col items-center justify-center space-y-6">
              <div className="bg-slate-50 h-32 w-32 rounded-full flex items-center justify-center shadow-inner">
                <i className="fas fa-calculator text-5xl text-slate-200"></i>
              </div>
              <div className="max-w-xs">
                <h3 className="text-slate-400 font-black text-xl mb-3">Calculadora Lista</h3>
                <p className="text-slate-400 text-sm font-medium leading-relaxed">Selecciona tus insumos orgánicos y configura los precios en Pesos Colombianos para iniciar el plan.</p>
              </div>
            </div>
          )}

          {/* AI Feedback */}
          {aiAdvice && (
            <div className="bg-slate-900 rounded-[2.5rem] shadow-2xl p-12 text-white animate-in zoom-in duration-700 relative overflow-hidden border border-white/5">
              <div className="absolute top-0 right-0 -mr-20 -mt-20 h-64 w-64 bg-emerald-500/10 rounded-full blur-[100px]"></div>

              <div className="flex items-center justify-between mb-12 relative z-10">
                <div>
                  <h3 className="text-3xl font-black flex items-center gap-4">
                    <i className="fas fa-microscope text-emerald-400"></i> Inteligencia Agrícola
                  </h3>
                  <p className="text-emerald-400/40 text-xs font-bold uppercase tracking-[0.2em] mt-2">Recomendación Regenerativa</p>
                </div>
                <div className="bg-white/5 px-6 py-3 rounded-3xl border border-white/10 text-center backdrop-blur-xl">
                  <span className="text-[10px] uppercase font-black text-white/30 block mb-1">Eco-Sinergia</span>
                  <span className="text-3xl font-black text-emerald-400">{aiAdvice.sustainabilityScore}<span className="text-sm text-white/20">/10</span></span>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-10 relative z-10">
                <div className="space-y-6">
                  <h4 className="text-[10px] uppercase font-black tracking-[0.3em] text-emerald-400 border-b border-emerald-400/20 pb-4">Protocolo de Aplicación</h4>
                  {aiAdvice.tips.map((tip, idx) => (
                    <div key={idx} className="flex gap-6 p-6 bg-white/5 rounded-[2rem] border border-white/10 hover:bg-white/10 transition-all group">
                      <div className="h-10 w-10 rounded-2xl bg-emerald-500/20 flex items-center justify-center border border-emerald-500/30 flex-shrink-0 group-hover:scale-110 transition-transform">
                        <span className="text-emerald-400 font-black text-sm">{idx+1}</span>
                      </div>
                      <p className="text-sm text-white/70 leading-relaxed font-medium">{tip}</p>
                    </div>
                  ))}
                </div>
                <div className="space-y-8">
                  <div className="p-8 bg-emerald-500/10 rounded-[2.5rem] border border-emerald-500/20 backdrop-blur-md">
                    <h4 className="text-[10px] uppercase font-black tracking-widest text-emerald-400 mb-5 flex items-center gap-3">
                      <i className="fas fa-clock"></i> Momento Sugerido
                    </h4>
                    <p className="text-base italic text-emerald-50 leading-relaxed font-light">"{aiAdvice.seasonalAdvice}"</p>
                  </div>
                  <div className="p-8 bg-blue-500/10 rounded-[2.5rem] border border-blue-500/20 flex items-center gap-6">
                    <div className="bg-blue-400/20 p-4 rounded-2xl">
                      <i className="fas fa-info-circle text-blue-400 text-2xl"></i>
                    </div>
                    <p className="text-xs text-blue-100/60 font-bold leading-relaxed uppercase tracking-wider">Asegura la calidad del agua antes de mezclar insumos líquidos como el jabón potásico y EM.</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="max-w-7xl mx-auto px-4 mt-20 text-center text-slate-300 text-[10px] font-black uppercase tracking-[0.4em] pb-10">
        <p>© 2024 AgroCalculadora PRO - Optimización Orgánica Colombiana</p>
        <div className="flex justify-center gap-8 mt-6 opacity-20">
          <i className="fas fa-leaf text-2xl"></i>
          <i className="fas fa-water text-2xl"></i>
          <i className="fas fa-sun text-2xl"></i>
        </div>
      </footer>
    </div>
  );
};

export default App;

export enum TreeType {
  CITRUS = 'Cítricos',
  PLANTAIN = 'Plátano',
  BANANA = 'Banano',
  CASSAVA = 'Yuca',
  AVOCADO = 'Aguacate',
  COFFEE = 'Café',
  CACAO = 'Cacao',
  GARDEN = 'Plantas de Jardín',
  GRASS = 'Césped',
  FOREST = 'Forestales / Ornamentales'
}

export enum OrganicProduct {
  // Líquidos
  POTASSIUM_SOAP = 'Jabón Potásico',
  LIQUID_HUMUS = 'Humus Líquido',
  LIQUID_IRON_OXIDE = 'Óxido de Hierro Líquido',
  EM = 'EM (Microorganismos Eficaces)',
  MOLASSES = 'Melaza',
  SULFUR_FUNGICIDE = 'Fungicida de Azufre',
  NEEM_EXTRACT = 'Extracto de Neem',

  // Sólidos
  BORON = 'Boro',
  ZINC = 'Zinc',
  COPPER = 'Cobre',
  COMPOST_TERRABONO = 'Compost (Terrabono)',
  SEA_SALT = 'Sal Marina',
  ROCK_DUST = 'Harina de Roca',
  PHOSPHATE_ROCK = 'Roca Fosfórica',
  CALCIUM_CARBONATE = 'Carbonato de Calcio',
  LEONARDITE = 'Leonardita',
  DIATOMACEOUS_EARTH = 'Tierra de Diatomea',
  MAGNESITE = 'Magnesita'
}

export type UnitType = 'g' | 'kg' | 'cc' | 'ml' | 'L';

export interface CalculationInput {
  treeType: TreeType;
  treeAge: number;
  numTrees: number;
  selectedProducts: OrganicProduct[];
  productPrices: Record<string, number>; // Precio en COP
  manualAmounts: Record<string, number | undefined>; // Dosis por árbol
  selectedUnits: Record<string, UnitType>; // Unidad elegida
  healthStatus: 'bueno' | 'regular' | 'deficiente';
}

export interface ProductResult {
  product: OrganicProduct;
  amount: number;
  unit: UnitType;
  costPerTree: number;
  totalCost: number;
}

export interface CalculationResult {
  products: ProductResult[];
  totalCostPerTree: number;
  totalProjectCost: number;
  frequency: string;
  notes: string;
}

export interface AIAdvice {
  tips: string[];
  seasonalAdvice: string;
  sustainabilityScore: number;
}

import React, { useState, useEffect, useCallback } from 'react';
import { TreeType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType } from './types';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES } from './constants';
import { getAgriculturalAdvice } from './services/geminiService';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    treeAge: 1,
    numTrees: 1,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);

  const calculateDose = useCallback(() => {
    let healthModifier = 1.0;
    if (input.healthStatus === 'regular') healthModifier = 1.25;
    if (input.healthStatus === 'deficiente') healthModifier = 1.5;

    const productResults: ProductResult[] = input.selectedProducts.map(product => {
      const baseRate = BASE_RATES[product];
      const defaultUnit = PRODUCT_UNITS[product];
      const selectedUnit = input.selectedUnits[product] || defaultUnit;
      const pricePerUnit = input.productPrices[product] || 0;
      const manualAmount = input.manualAmounts[product];

      let perTreeAmount: number;

      if (manualAmount !== undefined) {
        perTreeAmount = manualAmount;
      } else {
        const rawPerTree = input.treeAge * baseRate * healthModifier;
        // Ajuste de topes por unidad
        if (selectedUnit === 'kg' || selectedUnit === 'L') {
          perTreeAmount = Math.min(rawPerTree, 30);
        } else {
          perTreeAmount = rawPerTree;
        }
      }

      const costPerTree = perTreeAmount * pricePerUnit;
      const totalCost = costPerTree * input.numTrees;

      return {
        product,
        amount: parseFloat(perTreeAmount.toFixed(2)),
        unit: selectedUnit,
        costPerTree: parseFloat(costPerTree.toFixed(2)),
        totalCost: parseFloat(totalCost.toFixed(2))
      };
    });

    const totalCostPerTree = productResults.reduce((acc, curr) => acc + curr.costPerTree, 0);
    const totalProjectCost = totalCostPerTree * input.numTrees;

    setResult({
      products: productResults,
      totalCostPerTree: parseFloat(totalCostPerTree.toFixed(2)),
      totalProjectCost: parseFloat(totalProjectCost.toFixed(2)),
      frequency: "Variable según producto",
      notes: `Mezcla para ${input.numTrees} plantas/árboles. Precios en Pesos Colombianos (COP).`
    });
  }, [input]);

  const handleFetchAI = async () => {
    if (input.selectedProducts.length === 0) return;
    setLoading(true);
    const advice = await getAgriculturalAdvice(input);
    setAiAdvice(advice);
    setLoading(false);
  };

  const toggleProduct = (product: OrganicProduct) => {
    setInput(prev => {
      const isSelected = prev.selectedProducts.includes(product);
      return {
        ...prev,
        selectedProducts: isSelected 
          ? prev.selectedProducts.filter(p => p !== product)
          : [...prev.selectedProducts, product]
      };
    });
  };

  const handlePriceChange = (product: OrganicProduct, price: number) => {
    setInput(prev => ({
      ...prev,
      productPrices: { ...prev.productPrices, [product]: price }
    }));
  };

  const handleManualAmountChange = (product: OrganicProduct, amount: number | undefined) => {
    setInput(prev => ({
      ...prev,
      manualAmounts: { ...prev.manualAmounts, [product]: amount }
    }));
  };

  const handleUnitChange = (product: OrganicProduct, unit: UnitType) => {
    setInput(prev => ({
      ...prev,
      selectedUnits: { ...prev.selectedUnits, [product]: unit }
    }));
  };

  useEffect(() => {
    calculateDose();
  }, [calculateDose]);

  const renderProductGroup = (title: string, products: OrganicProduct[], icon: string) => (
    <div className="mb-6">
      <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
        <i className={`fas ${icon} text-emerald-500`}></i> {title}
      </h3>
      <div className="space-y-3">
        {products.map(product => {
          const isSelected = input.selectedProducts.includes(product);
          const currentUnit = input.selectedUnits[product];
          return (
            <div key={product} className={`p-4 rounded-2xl border transition-all ${isSelected ? 'border-emerald-200 bg-emerald-50 shadow-sm' : 'border-slate-100 bg-slate-50 opacity-70 hover:opacity-100'}`}>
              <div className="flex items-center justify-between gap-3 mb-2">
                <div className="flex items-center gap-3">
                  <input type="checkbox" checked={isSelected} onChange={() => toggleProduct(product)} className="w-5 h-5 accent-emerald-600 cursor-pointer" />
                  <span className={`text-sm font-bold ${isSelected ? 'text-emerald-900' : 'text-slate-600'}`}>{product}</span>
                </div>
                {isSelected && (
                  <select 
                    value={currentUnit} 
                    onChange={(e) => handleUnitChange(product, e.target.value as UnitType)}
