                  suggestedAmount: {
                    type: Type.NUMBER,
                    description: "Dosis por planta."
                  },
                  totalAmount: {
                    type: Type.NUMBER,
                    description: "Total para todo el lote de siembra."
                  },
                  unit: {
                    type: Type.STRING,
                    description: "Unidad (g, kg, cc, ml, L)."
                  },
                  reason: {
                    type: Type.STRING,
                    description: "Razón biológica."
                  }
                },
                required: ["product", "suggestedAmount", "totalAmount", "unit", "reason"]
