      p.product,
      `${p.amount} ${p.unit}`,
      `$ ${p.costPerTree.toLocaleString('es-CO')}`,
      `$ ${p.totalCost.toLocaleString('es-CO')}`
    ]);

    autoTable(doc, {
      startY: 90,
      head: [['Producto', 'Dosis / Planta', 'Costo / Planta', 'Subtotal Lote']],
      body: tableData,
      headStyles: { fillColor: [6, 78, 59], textColor: [255, 255, 255], fontStyle: 'bold' },
