      doc.setFont("helvetica", "bold");
      doc.text(`Puntaje de Sostenibilidad: ${aiAdvice.sustainabilityScore}/10`, 15, yPos);
    }

    doc.save(`Reporte_Agro_${input.treeType}_${new Date().toLocaleDateString()}.pdf`);
