  MOLASSES = 'Melaza',
  SULFUR_FUNGICIDE = 'Fungicida de Azufre',
  NEEM_EXTRACT = 'Extracto de Neem',

  // Sólidos
  BORON = 'Boro',
  ZINC = 'Zinc',
  COPPER = 'Cobre',
  COMPOST_TERRABONO = 'Compost (Terrabono)',
  SEA_SALT = 'Sal Marina',
  ROCK_DUST = 'Harina de Roca',
  PHOSPHATE_ROCK = 'Roca Fosfórica',
  CALCIUM_CARBONATE = 'Carbonato de Calcio',
  LEONARDITE = 'Leonardita',
  DIATOMACEOUS_EARTH = 'Tierra de Diatomea',
  MAGNESITE = 'Magnesita'
}

export type UnitType = 'g' | 'kg' | 'cc' | 'ml' | 'L';

export interface CalculationInput {
  treeType: TreeType;
  soilType: SoilType;
  treeAge: number;
  numTrees: number; // Representa plantas, m2 o m lineales según el tipo
  grassMode?: GrassMeasureMode;
  selectedProducts: OrganicProduct[];
  productPrices: Record<string, number>; 
  manualAmounts: Record<string, number | undefined>; 
  selectedUnits: Record<string, UnitType>; 
  healthStatus: 'bueno' | 'regular' | 'deficiente';
}

export interface ProductResult {
  product: OrganicProduct;
  amount: number;
  unit: UnitType;
  costPerUnitArea: number; // Costo por planta, m2 o m lineal
  totalCost: number;
}

export interface CalculationResult {
  products: ProductResult[];
  totalCostPerUnit: number;
  totalProjectCost: number;
  frequency: string;
  notes: string;
}

export interface AIAdvice {
  tips: string[];
  seasonalAdvice: string;
  sustainabilityScore: number;
}

export interface PlantingFormulaItem {
  product: OrganicProduct;
  suggestedAmount: number;
  totalAmount: number;
  unit: UnitType;
  reason: string;
}

export interface PlantingFormulaRecommendation {
  explanation: string;
  items: PlantingFormulaItem[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, PlantingFormulaRecommendation, OrganicProduct } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const productList = input.selectedProducts.join(", ");
    const unitLabel = input.treeType === 'Césped' ? (input.grassMode || 'm2') : 'planta/árbol';

    const prompt = `
      Actúa como un agrónomo experto en agricultura orgánica regenerativa. 
      Analiza una mezcla de los siguientes productos: [${productList}] para un cultivo de ${input.treeType}.
      Datos:
      - Tipo de Suelo: ${input.soilType}.
      - Edad/Etapa: ${input.treeAge} años/meses.
      - Estado actual: ${input.healthStatus}.
      - Medida: Se calcula por ${unitLabel}.

      Proporciona:
      1. 3 consejos de aplicación técnica (considerando si es por cobertura o riego).
      2. Momento ideal de aplicación.
      3. Puntuación de sostenibilidad (1-10).
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore"],
        },
      },
    });

    if (response.text) return JSON.parse(response.text.trim());
    return null;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return null;
  }
};

export const getPlantingFormula = async (treeType: string, soilType: string, quantity: number, grassMode?: string): Promise<PlantingFormulaRecommendation | null> => {
  try {
    const productsEnumValues = Object.values(OrganicProduct).join(", ");
    const measureUnit = treeType === 'Césped' ? (grassMode || 'm2') : 'planta';

    const prompt = `
      Eres un agrónomo experto. Recomienda la mejor fórmula orgánica para SIEMBRA/ESTABLECIMIENTO de: ${treeType} en un suelo ${soilType}.
      Cantidad total: ${quantity} ${measureUnit}.
      Lista permitida: [${productsEnumValues}].

      Para cada producto, indica:
      1. Dosis ideal POR ${measureUnit.toUpperCase()} (suggestedAmount).
      2. Cantidad TOTAL para los ${quantity} ${measureUnit} (totalAmount).
      3. Unidad (g, kg, cc, ml, L).
      4. Razón biológica.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            explanation: { type: Type.STRING },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  product: { type: Type.STRING },
                  suggestedAmount: { type: Type.NUMBER },
                  totalAmount: { type: Type.NUMBER },
                  unit: { type: Type.STRING },
                  reason: { type: Type.STRING }
                },
                required: ["product", "suggestedAmount", "totalAmount", "unit", "reason"]
              }
            }
          },
          required: ["explanation", "items"]
        }
      }
    });

    if (response.text) return JSON.parse(response.text.trim());
    return null;
  } catch (error) {
    console.error("Gemini Formula Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode } from './types';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES } from './constants';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    soilType: SoilType.LOAMY,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingFormula, setLoadingFormula] = useState(false);
  const [formulaRec, setFormulaRec] = useState<PlantingFormulaRecommendation | null>(null);
  const [copiedKey, setCopiedKey] = useState<string | null>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const currentMeasureUnit = isGrass ? input.grassMode : 'planta';

  const calculateDose = useCallback(() => {
    let healthModifier = 1.0;
    if (input.healthStatus === 'regular') healthModifier = 1.25;
    if (input.healthStatus === 'deficiente') healthModifier = 1.5;

    let soilModifier = 1.0;
    if (input.soilType === SoilType.SANDY) soilModifier = 1.15;
    if (input.soilType === SoilType.CLAYEY) soilModifier = 0.90;
    if (input.soilType === SoilType.SILTY) soilModifier = 1.0;
    if (input.soilType === SoilType.LOAMY) soilModifier = 1.0;

    const totalModifier = healthModifier * soilModifier;

    const productResults: ProductResult[] = input.selectedProducts.map(product => {
      const baseRate = BASE_RATES[product];
      const defaultUnit = PRODUCT_UNITS[product];
      const selectedUnit = input.selectedUnits[product] || defaultUnit;
      const pricePerUnit = input.productPrices[product] || 0;
      const manualAmount = input.manualAmounts[product];

      let perUnitAmount: number;

      if (manualAmount !== undefined) {
        perUnitAmount = manualAmount;
      } else {
        const rawPerUnit = input.treeAge * baseRate * totalModifier;
        if (selectedUnit === 'kg' || selectedUnit === 'L') {
          perUnitAmount = Math.min(rawPerUnit, 30);
        } else {
          perUnitAmount = rawPerUnit;
        }
      }

      const costPerUnit = perUnitAmount * pricePerUnit;
      const totalCost = costPerUnit * input.numTrees;

      return {
        product,
        amount: parseFloat(perUnitAmount.toFixed(2)),
        unit: selectedUnit,
        costPerUnitArea: parseFloat(costPerUnit.toFixed(2)),
        totalCost: parseFloat(totalCost.toFixed(2))
      };
    });

    let frequency = "Cada 30-45 días (Mantenimiento)";
    if (isGrass) {
      frequency = "Cada 30 días o después de cada poda";
    }

    const totalCostPerUnit = productResults.reduce((acc, curr) => acc + curr.costPerUnitArea, 0);
    const totalProjectCost = totalCostPerUnit * input.numTrees;

    setResult({
      products: productResults,
      totalCostPerUnit: parseFloat(totalCostPerUnit.toFixed(2)),
      totalProjectCost: parseFloat(totalProjectCost.toFixed(2)),
      frequency: frequency,
      notes: `Plan para ${input.numTrees} ${currentMeasureUnit} de ${input.treeType} en suelo ${input.soilType}.`
    });
  }, [input, isGrass, currentMeasureUnit]);

  const handleFetchAI = async () => {
    if (input.selectedProducts.length === 0) return;
    setLoading(true);
    const advice = await getAgriculturalAdvice(input);
    setAiAdvice(advice);
    setLoading(false);
  };

  const handleGetFormula = async () => {
    setLoadingFormula(true);
    const rec = await getPlantingFormula(input.treeType, input.soilType, input.numTrees, input.grassMode);
    setFormulaRec(rec);
    setLoadingFormula(false);
  };

  const applyFormula = () => {
    if (!formulaRec) return;
    const selectedProducts: OrganicProduct[] = [];
    const manualAmounts: Record<string, number> = {};
    const selectedUnits: Record<string, UnitType> = { ...input.selectedUnits };

    formulaRec.items.forEach(item => {
      selectedProducts.push(item.product);
      manualAmounts[item.product] = item.suggestedAmount;
      selectedUnits[item.product] = item.unit;
    });

    setInput(prev => ({
      ...prev,
      selectedProducts,
      manualAmounts,
      selectedUnits,
      treeAge: 1,
      healthStatus: 'bueno'
    }));
    setFormulaRec(null);
  };

  const generatePDF = () => {
    if (!result) return;
    const doc = new jsPDF();
    doc.setFillColor(6, 78, 59);
    doc.rect(0, 0, 210, 40, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.text('AgroCalculadora PRO CO', 15, 25);
    doc.setFontSize(10);
    doc.text('REPORTE TÉCNICO DE NUTRICIÓN REGENERATIVA', 15, 33);

    doc.setTextColor(50, 50, 50);
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text('Información Técnica', 15, 55);
    doc.setDrawColor(200, 200, 200);
    doc.line(15, 57, 195, 57);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(`Tipo: ${input.treeType}`, 15, 65);
    doc.text(`Suelo: ${input.soilType}`, 15, 72);
    doc.text(`Vigor: ${input.healthStatus.toUpperCase()}`, 15, 79);

    doc.text(`Edad/Etapa: ${input.treeAge} años/meses`, 105, 65);
    doc.text(`Cantidad: ${input.numTrees} ${currentMeasureUnit}`, 105, 72);
    doc.setFont("helvetica", "bold");
    doc.text(`Frecuencia: ${result.frequency}`, 105, 79);

    const tableData = result.products.map(p => [
      p.product,
      `${p.amount} ${p.unit}`,
      `$ ${p.costPerUnitArea.toLocaleString('es-CO')}`,
      `$ ${p.totalCost.toLocaleString('es-CO')}`
    ]);

    autoTable(doc, {
      startY: 90,
      head: [['Producto', `Dosis / ${currentMeasureUnit}`, `Vr. / ${currentMeasureUnit}`, 'Subtotal']],
      body: tableData,
      headStyles: { fillColor: [6, 78, 59], textColor: [255, 255, 255] },
      foot: [['', 'TOTALES', `$ ${result.totalCostPerUnit.toLocaleString('es-CO')}`, `$ ${result.totalProjectCost.toLocaleString('es-CO')}`]],
      footStyles: { fillColor: [240, 253, 244], textColor: [6, 78, 59] },
      theme: 'striped'
    });

    if (aiAdvice) {
      const finalY = (doc as any).lastAutoTable.finalY + 15;
      doc.setFont("helvetica", "bold").setFontSize(12).text('Recomendación IA', 15, finalY);
      doc.setFont("helvetica", "normal").setFontSize(9);
      let yPos = finalY + 10;
      aiAdvice.tips.forEach((tip, i) => {
        const splitTip = doc.splitTextToSize(`${i + 1}. ${tip}`, 170);
        doc.text(splitTip, 15, yPos);
        yPos += (splitTip.length * 5) + 2;
      });
    }
    doc.save(`AgroReporte_${input.treeType}_${Date.now()}.pdf`);
  };

  const copyToClipboard = async (text: string, key: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedKey(key);
      setTimeout(() => setCopiedKey(null), 2000);
    } catch (err) { console.error(err); }
  };

  const toggleProduct = (product: OrganicProduct) => {
    setInput(prev => {
      const isSelected = prev.selectedProducts.includes(product);
      return { ...prev, selectedProducts: isSelected ? prev.selectedProducts.filter(p => p !== product) : [...prev.selectedProducts, product] };
    });
  };

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const renderProductGroup = (title: string, products: OrganicProduct[], icon: string) => (
    <div className="mb-6">
      <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
        <i className={`fas ${icon} text-emerald-500`}></i> {title}
      </h3>
      <div className="space-y-3">
        {products.map(product => {
          const isSelected = input.selectedProducts.includes(product);
          const currentUnit = input.selectedUnits[product];
          return (
            <div key={product} className={`p-4 rounded-2xl border transition-all ${isSelected ? 'border-emerald-200 bg-emerald-50 shadow-sm' : 'border-slate-100 bg-slate-50 opacity-70 hover:opacity-100'}`}>
              <div className="flex items-center justify-between gap-3 mb-2">
                <div className="flex items-center gap-3">
                  <input type="checkbox" checked={isSelected} onChange={() => toggleProduct(product)} className="w-5 h-5 accent-emerald-600 cursor-pointer" />
                  <span className={`text-sm font-bold ${isSelected ? 'text-emerald-900' : 'text-slate-600'}`}>{product}</span>
                </div>
                {isSelected && (
                  <select 
                    value={currentUnit} 
                    onChange={(e) => setInput({...input, selectedUnits: {...input.selectedUnits, [product]: e.target.value as UnitType}})}
                    className="text-[10px] font-bold bg-white border border-slate-200 text-emerald-700 px-2 py-1 rounded-md uppercase"
                  >
                    <option value="g">g</option><option value="kg">kg</option><option value="cc">cc</option><option value="ml">ml</option><option value="L">L</option>
                  </select>
                )}
              </div>
              {isSelected && (
                <div className="grid grid-cols-2 gap-3 pl-8">
                  <div>
                    <label className="text-[9px] font-bold text-emerald-700 uppercase mb-1 block">Dosis ({currentUnit})</label>
                    <input type="number" placeholder="Auto" value={input.manualAmounts[product] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [product]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="w-full p-2 rounded-lg border border-emerald-100 text-sm" />
                  </div>
                  <div>
                    <label className="text-[9px] font-bold text-emerald-700 uppercase mb-1 block">Precio ({currentUnit})</label>
                    <input type="number" value={input.productPrices[product]} onChange={e => setInput({...input, productPrices: {...input.productPrices, [product]: parseFloat(e.target.value) || 0}})} className="w-full p-2 rounded-lg border border-emerald-100 text-sm" />
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-12 font-sans text-slate-800">
      <nav className="bg-emerald-900 p-5 shadow-xl text-white sticky top-0 z-50 no-print">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="bg-emerald-500 p-2 rounded-lg"><i className="fas fa-seedling text-xl"></i></div>
            <h1 className="text-xl font-black tracking-tighter">AgroCalculadora <span className="text-emerald-400">CO</span></h1>
          </div>
          <span className="text-xs font-black bg-emerald-800 px-3 py-1 rounded-full">MODO: REGENERATIVO</span>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <section className="lg:col-span-5 space-y-6 no-print">
          <div className="bg-white rounded-[2rem] p-8 border border-slate-200/60 shadow-sm">
            <h2 className="text-lg font-black mb-6 flex items-center gap-2"><i className="fas fa-map-marker-alt text-emerald-600"></i> Lote y Cultivo</h2>

            <div className="space-y-5">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-3 block tracking-widest">Tipo de Cultivo</label>
                <div className="grid grid-cols-2 gap-2 max-h-64 overflow-y-auto pr-2 custom-scrollbar">
                  {Object.values(TreeType).map(type => (
                    <button key={type} onClick={() => setInput({ ...input, treeType: type })} className={`flex items-center gap-3 p-3 rounded-2xl border-2 transition-all text-xs font-bold ${input.treeType === type ? 'border-emerald-600 bg-emerald-50 text-emerald-900 shadow-sm' : 'border-slate-100 bg-slate-50 text-slate-400 hover:border-emerald-200'}`}>
                      {TREE_TYPE_ICONS[type]} <span className="truncate">{type}</span>
                    </button>
                  ))}
                </div>
              </div>

              {isGrass && (
                <div className="animate-in slide-in-from-left duration-300">
                  <label className="text-[10px] font-black text-slate-400 uppercase mb-3 block tracking-widest">Modo de Medición (Césped)</label>
                  <div className="flex bg-slate-100 rounded-2xl p-1.5">
                    {Object.values(GrassMeasureMode).map(mode => (
                      <button key={mode} onClick={() => setInput({...input, grassMode: mode})} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${input.grassMode === mode ? 'bg-white text-emerald-900 shadow-sm' : 'text-slate-400'}`}>
                        {mode === 'm2' ? <i className="fas fa-th-large mr-2"></i> : <i className="fas fa-arrows-alt-h mr-2"></i>}
                        {mode}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">{isGrass ? 'Etapa (Meses)' : 'Edad (Años)'}</label>
                  <input type="number" min="1" value={input.treeAge} onChange={e => setInput({...input, treeAge: parseInt(e.target.value) || 1})} className="w-full p-4 rounded-2xl bg-slate-50 border border-slate-200 font-black text-lg outline-none" />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">
                    {isGrass ? (input.grassMode === 'm2' ? 'Área Total (m²)' : 'Longitud (m)') : 'Cantidad Plantas'}
                  </label>
                  <input type="number" min="1" value={input.numTrees} onChange={e => setInput({...input, numTrees: parseInt(e.target.value) || 1})} className="w-full p-4 rounded-2xl bg-slate-50 border border-slate-200 font-black text-lg outline-none" />
                </div>
              </div>

              <button onClick={handleGetFormula} disabled={loadingFormula} className="w-full bg-gradient-to-r from-emerald-600 to-teal-600 text-white font-black py-4 rounded-2xl shadow-lg flex items-center justify-center gap-3 transition-all uppercase tracking-widest text-[10px]">
                {loadingFormula ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-wand-magic-sparkles"></i>}
                {loadingFormula ? 'Analizando...' : `Obtener Fórmula para ${input.numTrees} ${currentMeasureUnit}`}
              </button>

              {formulaRec && (
                <div className="bg-slate-900 text-white p-6 rounded-[1.5rem] border border-emerald-500/30 animate-in slide-in-from-top duration-500">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="text-xs font-black text-emerald-400 uppercase tracking-widest">Fórmula de Establecimiento</h3>
                    <button onClick={() => setFormulaRec(null)} className="text-slate-500"><i className="fas fa-times"></i></button>
                  </div>
                  <p className="text-[11px] text-slate-400 mb-4 italic leading-relaxed">"{formulaRec.explanation}"</p>
                  <div className="space-y-3 mb-6">
                    {formulaRec.items.map((item, idx) => (
                      <div key={idx} className="bg-white/5 p-3 rounded-xl">
                        <div className="flex justify-between items-start">
                          <span className="text-[11px] font-bold text-emerald-100">{item.product}</span>
                          <span className="text-[11px] font-black text-emerald-400">{item.totalAmount}{item.unit} Total</span>
                        </div>
                        <span className="text-[9px] text-slate-500 block mt-1">{item.reason}</span>
                      </div>
                    ))}
                  </div>
                  <button onClick={applyFormula} className="w-full bg-emerald-500 hover:bg-emerald-400 text-emerald-950 font-black py-3 rounded-xl text-[10px] uppercase tracking-widest">Aplicar al Presupuesto</button>
                </div>
              )}

              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Vigor General</label>
                <div className="flex bg-slate-100 rounded-2xl p-1.5">
                  {(['bueno', 'regular', 'deficiente'] as const).map(status => (
                    <button key={status} onClick={() => setInput({...input, healthStatus: status})} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${input.healthStatus === status ? 'bg-white text-emerald-900 shadow-sm' : 'text-slate-400'}`}>{status}</button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-[2rem] p-8 border border-slate-200/60 shadow-sm">
            <h2 className="text-lg font-black mb-2 flex items-center gap-2"><i className="fas fa-layer-group text-emerald-600"></i> Insumos</h2>
            <div className="max-h-[600px] overflow-y-auto pr-3 custom-scrollbar">
              {renderProductGroup("Insumos Líquidos", PRODUCT_CATEGORIES.LIQUIDS, "fa-tint")}
              {renderProductGroup("Enmiendas Sólidas", PRODUCT_CATEGORIES.SOLIDS, "fa-mountain")}
            </div>
            <button onClick={handleFetchAI} disabled={loading || input.selectedProducts.length === 0} className="w-full mt-8 bg-emerald-600 hover:bg-emerald-700 text-white font-black py-5 rounded-2xl shadow-lg disabled:opacity-50 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-3">
              {loading ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-brain"></i>}
              {loading ? 'Analizando...' : 'Consultar Agrónomo IA'}
            </button>
          </div>
        </section>

        <section className="lg:col-span-7 space-y-6">
          {result && result.products.length > 0 ? (
            <div className="space-y-6">
              <div className="flex gap-4 no-print">
                <button onClick={generatePDF} className="flex-1 bg-red-600 text-white font-black py-4 rounded-2xl shadow-lg flex items-center justify-center gap-3 uppercase text-[10px]"><i className="fas fa-file-pdf"></i> PDF</button>
                <button onClick={() => window.print()} className="flex-1 bg-slate-800 text-white font-black py-4 rounded-2xl shadow-lg flex items-center justify-center gap-3 uppercase text-[10px]"><i className="fas fa-print"></i> Imprimir</button>
              </div>

              <div id="results-panel" className="bg-white rounded-[2.5rem] shadow-xl overflow-hidden border border-slate-200/50 print:border-none print:shadow-none">
                <div className="bg-gradient-to-r from-emerald-900 to-emerald-800 p-10 text-white flex justify-between items-center relative overflow-hidden">
                  <div className="relative z-10">
                    <h3 className="text-2xl font-black mb-2">Presupuesto Técnico</h3>
                    <div className="bg-emerald-500/20 px-3 py-1 rounded-lg border border-emerald-500/30 w-fit">
                      <p className="text-[10px] uppercase font-bold text-emerald-400 tracking-widest">Para {input.numTrees} {currentMeasureUnit} de {input.treeType}</p>
                    </div>
                  </div>
                  <div className="text-right z-10">
                    <p className="text-[10px] uppercase font-black text-emerald-400/60 mb-1">Inversión Total (COP)</p>
                    <div className="flex items-center gap-3">
                      <span className="text-4xl font-black">${result.totalProjectCost.toLocaleString('es-CO')}</span>
                      <button onClick={() => copyToClipboard(result.totalProjectCost.toString(), 'total')} className="text-white/50 hover:text-white no-print"><i className={`fas ${copiedKey === 'total' ? 'fa-check' : 'fa-copy'}`}></i></button>
                    </div>
                  </div>
                </div>

                <div className="p-10">
                  <div className="overflow-x-auto">
                    <table className="w-full text-left">
                      <thead>
                        <tr className="text-slate-400 text-[10px] uppercase font-black border-b">
                          <th className="pb-6">Insumo</th>
                          <th className="pb-6 text-center">Dosis / {currentMeasureUnit}</th>
                          <th className="pb-6 text-right">Vr. / {currentMeasureUnit}</th>
                          <th className="pb-6 text-right">Subtotal</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {result.products.map(item => (
                          <tr key={item.product} className="hover:bg-slate-50/50 transition-all">
                            <td className="py-6 font-black text-sm">{item.product}</td>
                            <td className="py-6 text-center font-black text-emerald-600">{item.amount} <span className="text-[10px] text-slate-400">{item.unit}</span></td>
                            <td className="py-6 text-right text-slate-600 text-sm">${item.costPerUnitArea.toLocaleString('es-CO')}</td>
                            <td className="py-6 text-right font-black text-emerald-900 text-sm">${item.totalCost.toLocaleString('es-CO')}</td>
                          </tr>
                        ))}
                      </tbody>
                      <tfoot>
                        <tr className="bg-slate-50/80">
                          <td colSpan={2} className="py-6 px-6 text-right text-[10px] font-black uppercase">Costo por {currentMeasureUnit}</td>
                          <td className="py-6 text-right px-10 font-black text-3xl text-emerald-900" colSpan={2}>${result.totalCostPerUnit.toLocaleString('es-CO')}</td>
                        </tr>
                      </tfoot>
                    </table>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[3rem] p-24 text-center border-2 border-dashed flex flex-col items-center justify-center space-y-6 no-print">
              <div className="bg-slate-50 h-32 w-32 rounded-full flex items-center justify-center"><i className="fas fa-calculator text-5xl text-slate-200"></i></div>
              <p className="text-slate-400 text-sm font-medium">Selecciona tus insumos orgánicos para iniciar el plan.</p>
            </div>
          )}

          {aiAdvice && (
            <div className="bg-slate-900 rounded-[2.5rem] p-12 text-white animate-in zoom-in duration-700 relative overflow-hidden border border-white/5 print:bg-white print:text-slate-900 print:shadow-none print:border-slate-200">
              <div className="flex items-center justify-between mb-12 relative z-10">
                <h3 className="text-3xl font-black flex items-center gap-4"><i className="fas fa-microscope text-emerald-400"></i> Inteligencia Agrícola</h3>
                <div className="bg-white/5 px-6 py-3 rounded-3xl text-center"><span className="text-3xl font-black text-emerald-400">{aiAdvice.sustainabilityScore}/10</span></div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10 relative z-10">
                <div className="space-y-6">
                  {aiAdvice.tips.map((tip, idx) => (
                    <div key={idx} className="flex gap-6 p-6 bg-white/5 rounded-[2rem] border border-white/10 print:bg-slate-50 print:border-slate-100">
                      <div className="h-10 w-10 rounded-2xl bg-emerald-500/20 flex items-center justify-center flex-shrink-0"><span className="text-emerald-400 font-black">{idx+1}</span></div>
                      <p className="text-sm text-white/70 leading-relaxed font-medium print:text-slate-700">{tip}</p>
                    </div>
                  ))}
                </div>
                <div className="p-8 bg-emerald-500/10 rounded-[2.5rem] border border-emerald-500/20 print:bg-slate-50 print:border-slate-100">
                  <h4 className="text-[10px] uppercase font-black text-emerald-400 mb-5 flex items-center gap-3"><i className="fas fa-clock"></i> Momento Sugerido</h4>
                  <p className="text-base italic text-emerald-50 leading-relaxed print:text-slate-600">"{aiAdvice.seasonalAdvice}"</p>
                </div>
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="max-w-7xl mx-auto px-4 mt-20 text-center text-slate-300 text-[10px] font-black uppercase tracking-[0.4em] no-print">
        <p>© 2024 AgroCalculadora PRO - Optimización Orgánica Colombiana</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode } from './types';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend, Cell 
} from 'recharts';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    soilType: SoilType.LOAMY,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingFormula, setLoadingFormula] = useState(false);
  const [formulaRec, setFormulaRec] = useState<PlantingFormulaRecommendation | null>(null);
  const [copiedKey, setCopiedKey] = useState<string | null>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const currentMeasureUnit = isGrass ? input.grassMode : 'planta';

  const calculateDose = useCallback(() => {
    let healthModifier = 1.0;
    if (input.healthStatus === 'regular') healthModifier = 1.25;
    if (input.healthStatus === 'deficiente') healthModifier = 1.5;

    let soilModifier = 1.0;
    if (input.soilType === SoilType.SANDY) soilModifier = 1.15;
    if (input.soilType === SoilType.CLAYEY) soilModifier = 0.90;
    if (input.soilType === SoilType.SILTY) soilModifier = 1.0;
    if (input.soilType === SoilType.LOAMY) soilModifier = 1.0;

    const totalModifier = healthModifier * soilModifier;

    const productResults: ProductResult[] = input.selectedProducts.map(product => {
      const baseRate = BASE_RATES[product];
      const defaultUnit = PRODUCT_UNITS[product];
      const selectedUnit = input.selectedUnits[product] || defaultUnit;
      const pricePerUnit = input.productPrices[product] || 0;
      const manualAmount = input.manualAmounts[product];

      let perUnitAmount: number;

      if (manualAmount !== undefined) {
        perUnitAmount = manualAmount;
      } else {
        const rawPerUnit = input.treeAge * baseRate * totalModifier;
        if (selectedUnit === 'kg' || selectedUnit === 'L') {
          perUnitAmount = Math.min(rawPerUnit, 30);
        } else {
          perUnitAmount = rawPerUnit;
        }
      }

      const costPerUnit = perUnitAmount * pricePerUnit;
      const totalCost = costPerUnit * input.numTrees;

      return {
        product,
        amount: parseFloat(perUnitAmount.toFixed(2)),
        unit: selectedUnit,
        costPerUnitArea: parseFloat(costPerUnit.toFixed(2)),
        totalCost: parseFloat(totalCost.toFixed(2))
      };
    });

    let frequency = "Cada 30-45 días (Mantenimiento)";
    if (isGrass) {
      frequency = "Cada 30 días o después de cada poda";
    }

    const totalCostPerUnit = productResults.reduce((acc, curr) => acc + curr.costPerUnitArea, 0);
    const totalProjectCost = totalCostPerUnit * input.numTrees;

    setResult({
      products: productResults,
      totalCostPerUnit: parseFloat(totalCostPerUnit.toFixed(2)),
      totalProjectCost: parseFloat(totalProjectCost.toFixed(2)),
      frequency: frequency,
      notes: `Plan para ${input.numTrees} ${currentMeasureUnit} de ${input.treeType} en suelo ${input.soilType}.`
    });
  }, [input, isGrass, currentMeasureUnit]);

  // Analítica de Nutrientes
  const nutrientAnalytics = useMemo(() => {
    if (!result) return [];

    let totalN = 0, totalP = 0, totalK = 0, totalOM = 0;

    result.products.forEach(p => {
      const nutrients = PRODUCT_NUTRIENTS[p.product];
      // Normalizamos la cantidad a kg o L para el cálculo de impacto
      let factor = 1;
      if (p.unit === 'g' || p.unit === 'ml' || p.unit === 'cc') factor = 0.001;

      const weightedAmount = p.amount * factor;
      totalN += nutrients.N * weightedAmount;
      totalP += nutrients.P * weightedAmount;
      totalK += nutrients.K * weightedAmount;
      totalOM += nutrients.OM * weightedAmount;
    });

    return [
      { subject: 'Nitrógeno', A: totalN, fullMark: 100 },
      { subject: 'Fósforo', A: totalP, fullMark: 100 },
      { subject: 'Potasio', A: totalK, fullMark: 100 },
      { subject: 'Mat. Orgánica', A: totalOM, fullMark: 100 },
    ];
  }, [result]);

  const costAnalytics = useMemo(() => {
    if (!result) return [];
    return result.products.map(p => ({
      name: p.product.substring(0, 10) + '...',
      cost: p.totalCost,
      fullName: p.product
    }));
  }, [result]);

  const handleFetchAI = async () => {
    if (input.selectedProducts.length === 0) return;
    setLoading(true);
    const advice = await getAgriculturalAdvice(input);
    setAiAdvice(advice);
    setLoading(false);
  };

  const handleGetFormula = async () => {
    setLoadingFormula(true);
    const rec = await getPlantingFormula(input.treeType, input.soilType, input.numTrees, input.grassMode);
    setFormulaRec(rec);
    setLoadingFormula(false);
  };

  const applyFormula = () => {
    if (!formulaRec) return;
    const selectedProducts: OrganicProduct[] = [];
    const manualAmounts: Record<string, number> = {};
    const selectedUnits: Record<string, UnitType> = { ...input.selectedUnits };

    formulaRec.items.forEach(item => {
      selectedProducts.push(item.product);
      manualAmounts[item.product] = item.suggestedAmount;
      selectedUnits[item.product] = item.unit;
    });

    setInput(prev => ({
      ...prev,
      selectedProducts,
      manualAmounts,
      selectedUnits,
      treeAge: 1,
      healthStatus: 'bueno'
    }));
    setFormulaRec(null);
  };

  const generatePDF = () => {
    if (!result) return;
    const doc = new jsPDF();
    doc.setFillColor(6, 78, 59);
    doc.rect(0, 0, 210, 40, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.text('AgroCalculadora PRO CO', 15, 25);
    doc.setFontSize(10);
    doc.text('REPORTE TÉCNICO DE NUTRICIÓN REGENERATIVA', 15, 33);

    doc.setTextColor(50, 50, 50);
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text('Información Técnica', 15, 55);
    doc.setDrawColor(200, 200, 200);
    doc.line(15, 57, 195, 57);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(`Tipo: ${input.treeType}`, 15, 65);
    doc.text(`Suelo: ${input.soilType}`, 15, 72);
    doc.text(`Vigor: ${input.healthStatus.toUpperCase()}`, 15, 79);

    doc.text(`Edad/Etapa: ${input.treeAge} años/meses`, 105, 65);
    doc.text(`Cantidad: ${input.numTrees} ${currentMeasureUnit}`, 105, 72);
    doc.setFont("helvetica", "bold");
    doc.text(`Frecuencia: ${result.frequency}`, 105, 79);

    const tableData = result.products.map(p => [
      p.product,
      `${p.amount} ${p.unit}`,
      `$ ${p.costPerUnitArea.toLocaleString('es-CO')}`,
      `$ ${p.totalCost.toLocaleString('es-CO')}`
    ]);

    autoTable(doc, {
      startY: 90,
      head: [['Producto', `Dosis / ${currentMeasureUnit}`, `Vr. / ${currentMeasureUnit}`, 'Subtotal']],
      body: tableData,
      headStyles: { fillColor: [6, 78, 59], textColor: [255, 255, 255] },
      foot: [['', 'TOTALES', `$ ${result.totalCostPerUnit.toLocaleString('es-CO')}`, `$ ${result.totalProjectCost.toLocaleString('es-CO')}`]],
      footStyles: { fillColor: [240, 253, 244], textColor: [6, 78, 59] },
      theme: 'striped'
    });

    if (aiAdvice) {
      const finalY = (doc as any).lastAutoTable.finalY + 15;
      doc.setFont("helvetica", "bold").setFontSize(12).text('Recomendación IA', 15, finalY);
      doc.setFont("helvetica", "normal").setFontSize(9);
      let yPos = finalY + 10;
      aiAdvice.tips.forEach((tip, i) => {
        const splitTip = doc.splitTextToSize(`${i + 1}. ${tip}`, 170);
        doc.text(splitTip, 15, yPos);
        yPos += (splitTip.length * 5) + 2;
      });
    }
    doc.save(`AgroReporte_${input.treeType}_${Date.now()}.pdf`);
  };

  const copyToClipboard = async (text: string, key: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedKey(key);
      setTimeout(() => setCopiedKey(null), 2000);
    } catch (err) { console.error(err); }
  };

  const toggleProduct = (product: OrganicProduct) => {
    setInput(prev => {
      const isSelected = prev.selectedProducts.includes(product);
      return { ...prev, selectedProducts: isSelected ? prev.selectedProducts.filter(p => p !== product) : [...prev.selectedProducts, product] };
    });
  };

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const renderProductGroup = (title: string, products: OrganicProduct[], icon: string) => (
    <div className="mb-6">
      <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
        <i className={`fas ${icon} text-emerald-500`}></i> {title}
      </h3>
      <div className="space-y-3">
        {products.map(product => {
          const isSelected = input.selectedProducts.includes(product);
          const currentUnit = input.selectedUnits[product];
          return (
            <div key={product} className={`p-4 rounded-2xl border transition-all ${isSelected ? 'border-emerald-200 bg-emerald-50 shadow-sm' : 'border-slate-100 bg-slate-50 opacity-70 hover:opacity-100'}`}>
              <div className="flex items-center justify-between gap-3 mb-2">
                <div className="flex items-center gap-3">
                  <input type="checkbox" checked={isSelected} onChange={() => toggleProduct(product)} className="w-5 h-5 accent-emerald-600 cursor-pointer" />
                  <span className={`text-sm font-bold ${isSelected ? 'text-emerald-900' : 'text-slate-600'}`}>{product}</span>
                </div>
                {isSelected && (
                  <select 
                    value={currentUnit} 
                    onChange={(e) => setInput({...input, selectedUnits: {...input.selectedUnits, [product]: e.target.value as UnitType}})}
                    className="text-[10px] font-bold bg-white border border-slate-200 text-emerald-700 px-2 py-1 rounded-md uppercase"
                  >
                    <option value="g">g</option><option value="kg">kg</option><option value="cc">cc</option><option value="ml">ml</option><option value="L">L</option>
                  </select>
                )}
              </div>
              {isSelected && (
                <div className="grid grid-cols-2 gap-3 pl-8">
                  <div>
                    <label className="text-[9px] font-bold text-emerald-700 uppercase mb-1 block">Dosis ({currentUnit})</label>
                    <input type="number" placeholder="Auto" value={input.manualAmounts[product] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [product]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="w-full p-2 rounded-lg border border-emerald-100 text-sm" />
                  </div>
                  <div>
                    <label className="text-[9px] font-bold text-emerald-700 uppercase mb-1 block">Precio ({currentUnit})</label>
                    <input type="number" value={input.productPrices[product]} onChange={e => setInput({...input, productPrices: {...input.productPrices, [product]: parseFloat(e.target.value) || 0}})} className="w-full p-2 rounded-lg border border-emerald-100 text-sm" />
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-12 font-sans text-slate-800">
      <nav className="bg-emerald-900 p-5 shadow-xl text-white sticky top-0 z-50 no-print">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="bg-emerald-500 p-2 rounded-lg"><i className="fas fa-seedling text-xl"></i></div>
            <h1 className="text-xl font-black tracking-tighter">AgroCalculadora <span className="text-emerald-400">CO</span></h1>
          </div>
          <span className="text-xs font-black bg-emerald-800 px-3 py-1 rounded-full">ANÁLITICA PRO</span>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <section className="lg:col-span-5 space-y-6 no-print">
          <div className="bg-white rounded-[2rem] p-8 border border-slate-200/60 shadow-sm">
            <h2 className="text-lg font-black mb-6 flex items-center gap-2"><i className="fas fa-map-marker-alt text-emerald-600"></i> Lote y Cultivo</h2>

            <div className="space-y-5">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase mb-3 block tracking-widest">Tipo de Cultivo</label>
                <div className="grid grid-cols-2 gap-2 max-h-64 overflow-y-auto pr-2 custom-scrollbar">
                  {Object.values(TreeType).map(type => (
                    <button key={type} onClick={() => setInput({ ...input, treeType: type })} className={`flex items-center gap-3 p-3 rounded-2xl border-2 transition-all text-xs font-bold ${input.treeType === type ? 'border-emerald-600 bg-emerald-50 text-emerald-900 shadow-sm' : 'border-slate-100 bg-slate-50 text-slate-400 hover:border-emerald-200'}`}>
                      {TREE_TYPE_ICONS[type]} <span className="truncate">{type}</span>
                    </button>
                  ))}
                </div>
              </div>

