              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 no-print">
                <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm h-80">
                  <h4 className="text-[10px] font-bold text-slate-400 mb-4 uppercase flex items-center gap-2"><i className="fas fa-chart-area"></i> Balance de Nutrientes</h4>
                  <ResponsiveContainer width="100%" height="90%">
                    <RadarChart cx="50%" cy="50%" outerRadius="80%" data={nutrientData}>
                      <PolarGrid stroke="#f1f5f9" />
                      <PolarAngleAxis dataKey="subject" tick={{fontSize: 10, fontWeight: 800, fill: '#64748b'}} />
                      <Radar name="Mix" dataKey="A" stroke="#10b981" fill="#10b981" fillOpacity={0.6} />
                      <Tooltip />
                    </RadarChart>
                  </ResponsiveContainer>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm h-80">
                  <h4 className="text-[10px] font-bold text-slate-400 mb-4 uppercase flex items-center gap-2"><i className="fas fa-chart-bar"></i> Distribución de Costos</h4>
                  <ResponsiveContainer width="100%" height="90%">
                    <BarChart data={result.products}>
                      <XAxis dataKey="product" hide />
                      <YAxis hide />
                      <Tooltip formatter={(v: any) => [`$${v.toLocaleString('es-CO')}`, 'Costo Total']} />
                      <Bar dataKey="totalCost" fill="#10b981" radius={[5,5,0,0]}>
                        {result.products.map((_, i) => <Cell key={i} fill={i%2===0?'#059669':'#34d399'} />)}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-white rounded-[2.5rem] shadow-xl overflow-hidden print-full-width border border-slate-200">
                <div className="bg-emerald-900 p-10 text-white flex justify-between items-center">
                  <div>
                    <h3 className="text-2xl font-black mb-1 tracking-tight">Reporte de Aplicación</h3>
                    <p className="text-[10px] opacity-60 uppercase font-bold tracking-widest">Lote: {input.numTrees} {unitLabel} | Cultivo: {input.treeType}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] opacity-60 mb-1 font-bold uppercase">Inversión Estimada</p>
                    <span className="text-4xl font-black tracking-tighter">${result.totalProjectCost.toLocaleString('es-CO')}</span>
                  </div>
                </div>
                <div className="p-8">
                  <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                      <thead>
                        <tr className="border-b text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                          <th className="pb-4">Producto Insumo</th>
                          <th className="pb-4 text-center">Dosis x {unitLabel}</th>
                          <th className="pb-4 text-right">Subtotal Lote</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {result.products.map(p => (
                          <tr key={p.product} className="hover:bg-slate-50 transition-colors">
                            <td className="py-4 font-bold text-slate-800">{p.product}</td>
                            <td className="py-4 text-center font-bold text-emerald-600">{p.amount}{p.unit}</td>
                            <td className="py-4 text-right font-medium text-slate-600">${p.totalCost.toLocaleString('es-CO')}</td>
                          </tr>
                        ))}
                      </tbody>
                      <tfoot>
                        <tr className="bg-slate-50/80">
                          <td className="p-6 font-bold text-[10px] uppercase text-slate-400" colSpan={2}>Costo unitario por {unitLabel}</td>
                          <td className="p-6 text-right font-black text-emerald-900 text-2xl tracking-tighter">${result.totalCostPerUnit.toLocaleString('es-CO')}</td>
                        </tr>
                      </tfoot>
                    </table>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[3rem] p-24 text-center border-2 border-dashed border-slate-200 flex flex-col items-center justify-center space-y-4 no-print">
              <div className="bg-slate-50 h-20 w-20 rounded-full flex items-center justify-center">
                <i className="fas fa-calculator text-3xl text-slate-200"></i>
              </div>
              <p className="text-slate-400 font-medium">Configura los parámetros del lote y selecciona insumos para generar el análisis.</p>
            </div>
          )}

          {aiAdvice && (
            <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white animate-in zoom-in duration-700 border border-white/5 shadow-2xl no-print">
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-xl font-bold flex items-center gap-3"><i className="fas fa-microscope text-emerald-400"></i> Análisis de Sostenibilidad IA</h3>
                <div className="bg-emerald-500/10 px-4 py-2 rounded-2xl border border-emerald-500/20 text-emerald-400 font-black">Score: {aiAdvice.sustainabilityScore}/10</div>
              </div>
              <div className="grid md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  {aiAdvice.tips.map((t, i) => (
                    <div key={i} className="flex gap-4 items-start bg-white/5 p-4 rounded-2xl border border-white/5">
                      <div className="h-6 w-6 rounded-full bg-emerald-500/20 flex items-center justify-center text-[10px] text-emerald-400 font-bold shrink-0">{i+1}</div>
                      <p className="text-xs text-white/70 leading-relaxed">{t}</p>
                    </div>
                  ))}
                </div>
                <div className="p-6 bg-emerald-400/5 rounded-3xl border border-emerald-400/10 h-fit">
                  <h4 className="text-[10px] font-bold text-emerald-400 uppercase mb-3 flex items-center gap-2"><i className="fas fa-calendar-alt"></i> Momento Ideal</h4>
                  <p className="text-sm italic text-emerald-50/80 leading-relaxed">"{aiAdvice.seasonalAdvice}"</p>
                </div>
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="max-w-7xl mx-auto text-center mt-20 text-[10px] font-bold text-slate-300 uppercase tracking-widest no-print">
        <p>© 2024 AGROCALCULADORA PRO • SISTEMAS DE PRECISIÓN REGENERATIVA</p>
      </footer>
    </div>
  );
};

export default App;

export enum TreeType {
  CITRUS = 'Cítricos',
  PLANTAIN = 'Plátano',
  BANANA = 'Banano',
  CASSAVA = 'Yuca',
  AVOCADO = 'Aguacate',
  COFFEE = 'Café',
  CACAO = 'Cacao',
  GARDEN = 'Plantas de Jardín',
  GRASS = 'Césped',
  FOREST = 'Forestales'
}

export enum SoilType {
  SANDY = 'Arenoso',
  SILTY = 'Limoso',
  CLAYEY = 'Arcilloso',
  LOAMY = 'Franco'
}

export enum GrassMeasureMode {
  AREA = 'm2',
  LINEAR = 'm lineal'
}

export enum OrganicProduct {
  POTASSIUM_SOAP = 'Jabón Potásico',
  LIQUID_HUMUS = 'Humus Líquido',
  LIQUID_IRON_OXIDE = 'Hierro Líquido',
  EM = 'EM (Microorganismos)',
  MOLASSES = 'Melaza',
  SULFUR_FUNGICIDE = 'Azufre Líquido',
  NEEM_EXTRACT = 'Extracto de Neem',
  BORON = 'Boro',
  ZINC = 'Zinc',
  COPPER = 'Cobre',
  COMPOST_TERRABONO = 'Compost Premium',
  SEA_SALT = 'Sal Marina',
  ROCK_DUST = 'Harina de Roca',
  PHOSPHATE_ROCK = 'Roca Fosfórica',
  CALCIUM_CARBONATE = 'Carbonato de Calcio',
  LEONARDITE = 'Leonardita',
  DIATOMACEOUS_EARTH = 'Tierra de Diatomeas',
  MAGNESITE = 'Magnesita'
}

export type UnitType = 'g' | 'kg' | 'cc' | 'ml' | 'L';

export interface CustomProduct {
  name: string;
  category: 'LIQUIDS' | 'SOLIDS';
  unit: UnitType;
  baseRate: number;
}

export interface CalculationInput {
  treeType: TreeType;
  soilType: SoilType;
  treeAge: number;
  numTrees: number;
  grassMode?: GrassMeasureMode;
  selectedProducts: string[]; // Cambiado de OrganicProduct[] a string[] para soportar personalizados
  productPrices: Record<string, number>;
  manualAmounts: Record<string, number | undefined>;
  selectedUnits: Record<string, UnitType>;
  healthStatus: 'bueno' | 'regular' | 'deficiente';
}

export interface ProductResult {
  product: string;
  amount: number;
  unit: UnitType;
  costPerUnit: number;
  totalCost: number;
}

export interface CalculationResult {
  products: ProductResult[];
  totalCostPerUnit: number;
  totalProjectCost: number;
  frequency: string;
}

export interface AIAdvice {
  tips: string[];
  seasonalAdvice: string;
  sustainabilityScore: number;
}

export interface PlantingFormulaItem {
  product: string;
  suggestedAmount: number;
  totalAmount: number;
  unit: UnitType;
  reason: string;
}

export interface PlantingFormulaRecommendation {
  explanation: string;
  items: PlantingFormulaItem[];
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode, CustomProduct } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService.ts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell 
} from 'recharts';

const App: React.FC = () => {
  const [customProducts, setCustomProducts] = useState<CustomProduct[]>([]);
  const [showAddCustom, setShowAddCustom] = useState(false);
  const [newCustom, setNewCustom] = useState<CustomProduct>({
    name: '',
    category: 'SOLIDS',
    unit: 'kg',
    baseRate: 1
  });

  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    soilType: SoilType.LOAMY,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingFormula, setLoadingFormula] = useState(false);
  const [formulaRec, setFormulaRec] = useState<PlantingFormulaRecommendation | null>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      // Buscar base rate en constantes o en personalizados
      let baseRate = BASE_RATES[p as OrganicProduct];
      if (baseRate === undefined) {
        const custom = customProducts.find(cp => cp.name === p);
        baseRate = custom ? custom.baseRate : 1;
      }

      const amount = input.manualAmounts[p] ?? (input.treeAge * baseRate * modifier);
      const unit = input.selectedUnits[p] || (PRODUCT_UNITS[p as OrganicProduct] || 'kg');
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit: unit as UnitType,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass, customProducts]);

  const nutrientData = useMemo(() => {
    if (!result) return [];
    let n=0, p=0, k=0, om=0;
    result.products.forEach(item => {
      const nut = PRODUCT_NUTRIENTS[item.product as OrganicProduct] || { N: 0, P: 0, K: 0, OM: 0 };
      const qty = item.amount * (['g','ml','cc'].includes(item.unit) ? 0.001 : 1);
      n += nut.N * qty; p += nut.P * qty; k += nut.K * qty; om += nut.OM * qty;
    });
    return [
      { subject: 'N', A: Math.min(n, 100) },
      { subject: 'P', A: Math.min(p, 100) },
      { subject: 'K', A: Math.min(k, 100) },
      { subject: 'M.O.', A: Math.min(om, 100) }
    ];
  }, [result]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const addCustomProduct = () => {
    if (!newCustom.name.trim()) return;
    const exists = customProducts.some(p => p.name === newCustom.name) || Object.values(OrganicProduct).includes(newCustom.name as OrganicProduct);
    if (exists) return;

    setCustomProducts([...customProducts, newCustom]);
    setInput(prev => ({
      ...prev,
      selectedUnits: { ...prev.selectedUnits, [newCustom.name]: newCustom.unit },
      productPrices: { ...prev.productPrices, [newCustom.name]: 0 }
    }));
    setNewCustom({ name: '', category: 'SOLIDS', unit: 'kg', baseRate: 1 });
    setShowAddCustom(false);
  };

  const renderProductSelector = (title: string, category: 'LIQUIDS' | 'SOLIDS') => {
    const standardItems = PRODUCT_CATEGORIES[category];
    const customItems = customProducts.filter(cp => cp.category === category).map(cp => cp.name);
    const allItems = [...standardItems, ...customItems];

    return (
      <div className="mb-6">
        <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">{title}</h3>
        <div className="space-y-2">
          {allItems.map(p => {
            const selected = input.selectedProducts.includes(p);
            const isStandard = Object.values(OrganicProduct).includes(p as OrganicProduct);
            return (
              <div key={p} className={`p-3 rounded-xl border transition-all ${selected ? 'bg-emerald-50 border-emerald-200' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                <div className="flex items-center justify-between">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p] }))} className="accent-emerald-600 h-4 w-4" />
                    <span className="text-sm font-bold text-slate-700 flex items-center gap-2">
                      {p} {!isStandard && <i className="fas fa-user-tag text-[10px] text-teal-500" title="Personalizado"></i>}
                    </span>
                  </label>
                  {selected && (
                    <select value={input.selectedUnits[p]} onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})} className="text-[10px] bg-white border px-1 rounded uppercase">
                      <option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="cc">cc</option><option value="L">L</option>
                    </select>
                  )}
                </div>
                {selected && (
                  <div className="grid grid-cols-2 gap-2 mt-2 pl-7">
                    <input type="number" placeholder="Dosis" value={input.manualAmounts[p] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="p-1 text-xs border rounded bg-white" />
                    <input type="number" placeholder="Precio" value={input.productPrices[p] || ''} onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} className="p-1 text-xs border rounded bg-white" />
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen pb-12 bg-slate-50">
      <header className="bg-emerald-900 text-white p-6 shadow-lg sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-2 rounded-lg"><i className="fas fa-seedling text-xl"></i></div>
            <h1 className="text-xl font-extrabold tracking-tight">AgroCalculadora <span className="text-emerald-400">PRO</span></h1>
          </div>
          <span className="text-[10px] font-bold bg-emerald-800 px-3 py-1 rounded-full border border-emerald-700 uppercase">Colombia Regenerativa</span>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <aside className="lg:col-span-4 space-y-6 no-print">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-6 flex items-center gap-2"><i className="fas fa-layer-group text-emerald-600"></i> Parámetros</h2>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-2">
                {Object.values(TreeType).map(t => (
                  <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-2 rounded-xl border text-[11px] font-bold flex flex-col items-center gap-1 transition-all ${input.treeType === t ? 'bg-emerald-50 border-emerald-500 text-emerald-900' : 'bg-slate-50 border-slate-100 hover:border-slate-300'}`}>
                    {TREE_TYPE_ICONS[t]} {t}
                  </button>
                ))}
              </div>
              {isGrass && (
                <div className="flex bg-slate-100 p-1 rounded-xl">
                  {Object.values(GrassMeasureMode).map(m => (
                    <button key={m} onClick={() => setInput({...input, grassMode: m})} className={`flex-1 py-2 text-[10px] font-bold rounded-lg transition-all ${input.grassMode === m ? 'bg-white shadow-sm text-emerald-900' : 'text-slate-400'}`}>{m}</button>
                  ))}
                </div>
              )}
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Edad/Mes</label>
                <input type="number" value={input.treeAge} onChange={e => setInput({...input, treeAge: parseInt(e.target.value) || 1})} className="w-full p-2 bg-slate-50 border rounded-xl" /></div>
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Cant. {unitLabel}</label>
                <input type="number" value={input.numTrees} onChange={e => setInput({...input, numTrees: parseInt(e.target.value) || 1})} className="w-full p-2 bg-slate-50 border rounded-xl" /></div>
              </div>
              <button onClick={async () => { setLoadingFormula(true); const f = await getPlantingFormula(input.treeType, input.soilType, input.numTrees, input.grassMode); setFormulaRec(f); setLoadingFormula(false); }} className="w-full py-3 bg-teal-600 text-white font-bold rounded-xl text-xs shadow-md hover:bg-teal-700 transition-colors">
                {loadingFormula ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-wand-magic mr-2"></i>}
                Generar Fórmula de Siembra IA
              </button>
            </div>
          </div>

          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><i className="fas fa-box text-emerald-600"></i> Insumos Disponibles</h2>
            <div className="max-h-96 overflow-y-auto pr-2 custom-scrollbar">
              {renderProductSelector("Líquidos / Bioinsumos", 'LIQUIDS')}
              {renderProductSelector("Sólidos / Enmiendas", 'SOLIDS')}
            </div>

            <div className="mt-4 pt-4 border-t border-slate-100">
              {!showAddCustom ? (
                <button 
                  onClick={() => setShowAddCustom(true)}
                  className="w-full py-2 border-2 border-dashed border-emerald-200 text-emerald-600 rounded-xl text-[10px] font-bold uppercase hover:bg-emerald-50 transition-colors flex items-center justify-center gap-2"
                >
                  <i className="fas fa-plus"></i> Añadir Insumo Personalizado
                </button>
              ) : (
                <div className="bg-slate-50 p-4 rounded-2xl border border-emerald-100 space-y-3 animate-in fade-in slide-in-from-bottom-2">
                  <div>
                    <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Nombre del Insumo</label>
                    <input type="text" value={newCustom.name} onChange={e => setNewCustom({...newCustom, name: e.target.value})} className="w-full p-2 text-xs border rounded-lg bg-white" placeholder="Ej: Purín de Ortiga" />
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Tipo</label>
                      <select value={newCustom.category} onChange={e => setNewCustom({...newCustom, category: e.target.value as any})} className="w-full p-2 text-[10px] border rounded-lg bg-white">
                        <option value="SOLIDS">Sólido</option>
                        <option value="LIQUIDS">Líquido</option>
                      </select>
                    </div>
                    <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Unidad Base</label>
                      <select value={newCustom.unit} onChange={e => setNewCustom({...newCustom, unit: e.target.value as any})} className="w-full p-2 text-[10px] border rounded-lg bg-white">
                        <option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="cc">cc</option><option value="L">L</option>
                      </select>
                    </div>
                  </div>
                  <div>
                    <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Dosis Base (x año/etapa)</label>
                    <input type="number" value={newCustom.baseRate} onChange={e => setNewCustom({...newCustom, baseRate: parseFloat(e.target.value) || 0})} className="w-full p-2 text-xs border rounded-lg bg-white" />
                  </div>
                  <div className="flex gap-2">
                    <button onClick={addCustomProduct} className="flex-1 py-2 bg-emerald-600 text-white rounded-lg text-[10px] font-bold uppercase">Guardar</button>
                    <button onClick={() => setShowAddCustom(false)} className="px-4 py-2 text-slate-400 text-[10px] font-bold uppercase">Cancelar</button>
                  </div>
                </div>
              )}
            </div>

            <button onClick={async () => { setLoading(true); const a = await getAgriculturalAdvice(input); setAiAdvice(a); setLoading(false); }} className="w-full mt-6 py-4 bg-emerald-600 text-white font-bold rounded-2xl shadow-lg hover:bg-emerald-700 transition-colors">
              {loading ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-brain mr-2"></i>}
              {loading ? 'Analizando...' : 'Consultar Analista IA'}
            </button>
          </div>
        </aside>

        <section className="lg:col-span-8 space-y-6">
          {formulaRec && (
            <div className="bg-slate-900 text-white p-8 rounded-3xl animate-in fade-in slide-in-from-top duration-500 no-print">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-emerald-400 font-bold uppercase text-xs tracking-widest">Protocolo Sugerido de Siembra</h3>
                <button onClick={() => setFormulaRec(null)} className="text-slate-500 hover:text-white transition-colors"><i className="fas fa-times"></i></button>
              </div>
              <div className="grid md:grid-cols-2 gap-4">
                {formulaRec.items.map((it, i) => (
