  try {
    const apiKey = getApiKey();
    if (!apiKey) return null;

    const ai = new GoogleGenAI({ apiKey });
    const productList = input.selectedProducts.join(", ");
    const unitLabel = input.treeType === 'Césped' ? (input.grassMode || 'm2') : 'planta/árbol';

    const prompt = `Actúa como agrónomo experto. Analiza estos productos: [${productList}] para un cultivo de ${input.treeType}. Suelo: ${input.soilType}. Estado: ${input.healthStatus}. Medida por ${unitLabel}. Proporciona: 3 consejos técnicos, momento ideal y puntaje de sostenibilidad (1-10).`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore"],
        },
      },
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Advice Error:", error);
    return null;
  }
};

export const getPlantingFormula = async (treeType: string, soilType: string, quantity: number, grassMode?: string): Promise<PlantingFormulaRecommendation | null> => {
  try {
    const apiKey = getApiKey();
    if (!apiKey) return null;

    const ai = new GoogleGenAI({ apiKey });
    const productsList = Object.values(OrganicProduct).join(", ");
    const measureUnit = treeType === 'Césped' ? (grassMode || 'm2') : 'planta';

    const prompt = `Eres agrónomo. Recomienda fórmula de SIEMBRA para: ${treeType} en suelo ${soilType}. Cantidad: ${quantity} ${measureUnit}. Lista permitida: [${productsList}]. Devuelve para cada item: dosis por ${measureUnit}, total para lote, unidad y razón biológica.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            explanation: { type: Type.STRING },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  product: { type: Type.STRING },
                  suggestedAmount: { type: Type.NUMBER },
                  totalAmount: { type: Type.NUMBER },
                  unit: { type: Type.STRING },
                  reason: { type: Type.STRING }
                },
                required: ["product", "suggestedAmount", "totalAmount", "unit", "reason"]
              }
            }
          },
          required: ["explanation", "items"]
        }
      }
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Formula Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell 
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    soilType: SoilType.LOAMY,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingFormula, setLoadingFormula] = useState(false);
  const [formulaRec, setFormulaRec] = useState<PlantingFormulaRecommendation | null>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const amount = input.manualAmounts[p] ?? (input.treeAge * BASE_RATES[p] * modifier);
      const unit = input.selectedUnits[p];
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass]);

  const nutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return [];
    let n=0, p=0, k=0, om=0;
    result.products.forEach(item => {
      const nut = PRODUCT_NUTRIENTS[item.product] || { N: 0, P: 0, K: 0, OM: 0 };
      const qty = item.amount * (['g','ml','cc'].includes(item.unit) ? 0.001 : 1);
      n += nut.N * qty; p += nut.P * qty; k += nut.K * qty; om += nut.OM * qty;
    });
    return [
      { subject: 'N', A: Math.min(n, 100) },
      { subject: 'P', A: Math.min(p, 100) },
      { subject: 'K', A: Math.min(k, 100) },
      { subject: 'M.O.', A: Math.min(om, 100) }
    ];
  }, [result]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const generatePDF = () => {
    if (!result) return;
    const doc = new jsPDF();

    // Header
    doc.setFillColor(16, 185, 129);
    doc.rect(0, 0, 210, 40, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.text('AgroCalculadora PRO', 15, 25);
    doc.setFontSize(10);
    doc.text(`Reporte de Fertilización - ${new Date().toLocaleDateString()}`, 15, 33);

    // Info
    doc.setTextColor(50, 50, 50);
    doc.setFontSize(12);
    doc.text(`Cultivo: ${input.treeType}`, 15, 50);
    doc.text(`Cantidad: ${input.numTrees} ${unitLabel}`, 15, 57);
    doc.text(`Tipo de Suelo: ${input.soilType}`, 15, 64);

    // Table
    const tableData = result.products.map(p => [
      p.product,
      `${p.amount} ${p.unit}`,
      `$${p.costPerUnit.toLocaleString()}`,
      `$${p.totalCost.toLocaleString()}`
    ]);

    autoTable(doc, {
      startY: 75,
      head: [['Insumo', 'Dosis x ' + unitLabel, 'Costo Unit.', 'Total Lote']],
      body: tableData,
      theme: 'grid',
      headStyles: { fillColor: [16, 185, 129] }
    });

    const finalY = (doc as any).lastAutoTable.finalY || 150;
    doc.setFontSize(14);
    doc.text(`Inversión Total Lote: $${result.totalProjectCost.toLocaleString()}`, 15, finalY + 15);

    if (aiAdvice) {
      doc.addPage();
      doc.setFillColor(15, 23, 42);
      doc.rect(0, 0, 210, 30, 'F');
      doc.setTextColor(255, 255, 255);
      doc.text('Análisis IA de Sostenibilidad', 15, 20);
      doc.setTextColor(50, 50, 50);
      doc.setFontSize(10);
      aiAdvice.tips.forEach((tip, i) => {
        doc.text(`${i+1}. ${tip}`, 15, 45 + (i * 10));
      });
      doc.text(`Momento Ideal: ${aiAdvice.seasonalAdvice}`, 15, 85);
      doc.text(`Puntaje de Sostenibilidad: ${aiAdvice.sustainabilityScore}/10`, 15, 95);
    }

    doc.save(`Reporte_Agro_${input.treeType}.pdf`);
  };

