            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-2">
                {Object.values(TreeType).map(t => (
                  <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-2 rounded-xl border text-[11px] font-bold flex flex-col items-center gap-1 transition-all ${input.treeType === t ? 'bg-emerald-50 border-emerald-500 text-emerald-900' : 'bg-slate-50 border-slate-100 hover:border-slate-300'}`}>
                    {TREE_TYPE_ICONS[t]} {t}
                  </button>
                ))}
              </div>
              {isGrass && (
                <div className="flex bg-slate-100 p-1 rounded-xl">
