                      <div className="h-6 w-6 rounded-full bg-emerald-500/20 flex items-center justify-center text-[10px] text-emerald-400 font-bold shrink-0">{i+1}</div>
                      <p className="text-xs text-white/70 leading-relaxed">{t}</p>
                    </div>
                  ))}
                </div>
                <div className="p-6 bg-emerald-400/5 rounded-3xl border border-emerald-400/10 h-fit">
                  <h4 className="text-[10px] font-bold text-emerald-400 uppercase mb-3 flex items-center gap-2"><i className="fas fa-calendar-alt"></i> Momento Ideal</h4>
                  <p className="text-sm italic text-emerald-50/80 leading-relaxed">"{aiAdvice.seasonalAdvice}"</p>
                </div>
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="max-w-7xl mx-auto text-center mt-20 text-[10px] font-bold text-slate-300 uppercase tracking-widest no-print">
        <p>© 2024 AGROCALCULADORA PRO • SISTEMAS DE PRECISIÓN REGENERATIVA</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell 
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    soilType: SoilType.LOAMY,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingFormula, setLoadingFormula] = useState(false);
  const [formulaRec, setFormulaRec] = useState<PlantingFormulaRecommendation | null>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || 'g';
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass]);

  // ACTIVA: Función de balance de nutrientes (NPK + MO)
  const nutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return [];
    let n=0, p=0, k=0, om=0;
    result.products.forEach(item => {
      const nut = PRODUCT_NUTRIENTS[item.product] || { N: 0, P: 0, K: 0, OM: 0 };
      // Ajuste de escala según unidad (g/ml vs kg/L)
      const qty = item.amount * (['g','ml','cc'].includes(item.unit) ? 0.001 : 1);
      n += nut.N * qty; 
      p += nut.P * qty; 
      k += nut.K * qty; 
      om += nut.OM * qty;
    });

    return [
      { subject: 'Nitrógeno (N)', A: Math.min(n, 100), fullMark: 100 },
      { subject: 'Fósforo (P)', A: Math.min(p, 100), fullMark: 100 },
      { subject: 'Potasio (K)', A: Math.min(k, 100), fullMark: 100 },
      { subject: 'Materia Org.', A: Math.min(om, 100), fullMark: 100 }
    ];
  }, [result]);

  useEffect(() => { 
    calculateDose(); 
  }, [calculateDose]);

  const generatePDF = () => {
    if (!result) return;
    try {
      const doc = new jsPDF();
      doc.setFillColor(16, 185, 129);
      doc.rect(0, 0, 210, 40, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFontSize(22);
      doc.text('AgroCalculadora PRO', 15, 25);
      doc.setFontSize(10);
      doc.text(`Reporte de Fertilización - ${new Date().toLocaleDateString()}`, 15, 33);

      doc.setTextColor(50, 50, 50);
      doc.setFontSize(12);
      doc.text(`Cultivo: ${input.treeType}`, 15, 50);
      doc.text(`Cantidad: ${input.numTrees} ${unitLabel}`, 15, 57);
      doc.text(`Suelo: ${input.soilType}`, 15, 64);

      const tableData = result.products.map(p => [
        p.product,
        `${p.amount} ${p.unit}`,
        `$${p.costPerUnit.toLocaleString()}`,
        `$${p.totalCost.toLocaleString()}`
      ]);

      autoTable(doc, {
        startY: 75,
        head: [['Insumo', `Dosis x ${unitLabel}`, 'Costo Unit.', 'Total Lote']],
        body: tableData,
        theme: 'striped',
        headStyles: { fillColor: [16, 185, 129] }
      });

      const finalY = (doc as any).lastAutoTable.finalY || 150;
      doc.setFontSize(14);
      doc.text(`Inversión Total Lote: $${result.totalProjectCost.toLocaleString()}`, 15, finalY + 15);

      if (aiAdvice) {
        doc.addPage();
        doc.setFillColor(15, 23, 42);
        doc.rect(0, 0, 210, 30, 'F');
        doc.setTextColor(255, 255, 255);
        doc.text('Análisis IA de Sostenibilidad', 15, 20);
        doc.setTextColor(50, 50, 50);
        doc.setFontSize(10);
        aiAdvice.tips.forEach((tip, i) => {
          doc.text(`${i+1}. ${tip}`, 15, 45 + (i * 10));
        });
        doc.text(`Momento Ideal: ${aiAdvice.seasonalAdvice}`, 15, 90);
        doc.text(`Puntaje de Sostenibilidad: ${aiAdvice.sustainabilityScore}/10`, 15, 100);
      }

      doc.save(`Reporte_Agro_${input.treeType}_${new Date().getTime()}.pdf`);
    } catch (e) {
      console.error("Error generating PDF:", e);
    }
  };

  const shareWhatsApp = () => {
    if (!result) return;
    const text = `*Reporte AgroCalculadora PRO*%0A%0A*Cultivo:* ${input.treeType}%0A*Cantidad:* ${input.numTrees} ${unitLabel}%0A%0A*Resumen de Aplicación:*%0A${result.products.map(p => `- ${p.product}: ${p.amount}${p.unit}`).join('%0A')}%0A%0A*Costo Total Lote:* $${result.totalProjectCost.toLocaleString()}%0A%0A_Generado por AgroCalculadora PRO_`;
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  const shareEmail = () => {
    if (!result) return;
    const subject = `Plan de Fertilización - ${input.treeType}`;
    const body = `Resumen de Fertilización para ${input.numTrees} ${unitLabel} de ${input.treeType}.%0A%0AInsumos a aplicar:%0A${result.products.map(p => `- ${p.product}: ${p.amount}${p.unit} (Subtotal: $${p.totalCost})`).join('%0A')}%0A%0AInversión Total Estimada: $${result.totalProjectCost.toLocaleString()}`;
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  };

  const renderProductSelector = (title: string, items: OrganicProduct[]) => (
    <div className="mb-6">
      <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">{title}</h3>
      <div className="space-y-2">
        {items.map(p => {
          const selected = input.selectedProducts.includes(p);
          return (
            <div key={p} className={`p-3 rounded-xl border transition-all ${selected ? 'bg-emerald-50 border-emerald-200' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
              <div className="flex items-center justify-between">
                <label className="flex items-center gap-3 cursor-pointer">
                  <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p] }))} className="accent-emerald-600 h-4 w-4" />
                  <span className="text-sm font-bold text-slate-700">{p}</span>
                </label>
                {selected && (
                  <select value={input.selectedUnits[p]} onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})} className="text-[10px] bg-white border px-1 rounded uppercase">
                    <option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="cc">cc</option><option value="L">L</option>
                  </select>
                )}
              </div>
              {selected && (
                <div className="grid grid-cols-2 gap-2 mt-2 pl-7">
                  <input type="number" placeholder="Dosis" value={input.manualAmounts[p] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="p-1 text-xs border rounded bg-white" />
                  <input type="number" placeholder="Precio" value={input.productPrices[p] || ''} onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} className="p-1 text-xs border rounded bg-white" />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pb-12 bg-slate-50">
      <header className="bg-emerald-900 text-white p-6 shadow-lg sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-2 rounded-lg"><i className="fas fa-seedling text-xl"></i></div>
            <h1 className="text-xl font-extrabold tracking-tight">AgroCalculadora <span className="text-emerald-400">PRO</span></h1>
          </div>
          <div className="flex gap-4">
            {result && result.products.length > 0 && (
              <div className="flex gap-2">
                <button onClick={generatePDF} className="bg-white/10 hover:bg-white/20 px-3 py-1 rounded-lg text-xs font-bold transition-colors"><i className="fas fa-file-pdf mr-1"></i> PDF</button>
                <button onClick={shareWhatsApp} className="bg-emerald-600 hover:bg-emerald-500 px-3 py-1 rounded-lg text-xs font-bold transition-colors"><i className="fab fa-whatsapp mr-1"></i> WA</button>
              </div>
            )}
            <span className="hidden md:block text-[10px] font-bold bg-emerald-800 px-3 py-1 rounded-full border border-emerald-700 uppercase">Tecnología de Precisión</span>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <aside className="lg:col-span-4 space-y-6 no-print">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-6 flex items-center gap-2"><i className="fas fa-layer-group text-emerald-600"></i> Parámetros del Lote</h2>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-2">
                {Object.values(TreeType).map(t => (
                  <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-2 rounded-xl border text-[11px] font-bold flex flex-col items-center gap-1 transition-all ${input.treeType === t ? 'bg-emerald-50 border-emerald-500 text-emerald-900 shadow-sm' : 'bg-slate-50 border-slate-100 hover:border-slate-300'}`}>
                    {TREE_TYPE_ICONS[t]} {t}
                  </button>
                ))}
              </div>
              {isGrass && (
                <div className="flex bg-slate-100 p-1 rounded-xl">
                  {Object.values(GrassMeasureMode).map(m => (
                    <button key={m} onClick={() => setInput({...input, grassMode: m})} className={`flex-1 py-2 text-[10px] font-bold rounded-lg transition-all ${input.grassMode === m ? 'bg-white shadow-sm text-emerald-900' : 'text-slate-400'}`}>{m}</button>
                  ))}
                </div>
              )}
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Edad (Meses)</label>
                <input type="number" min="1" value={input.treeAge} onChange={e => setInput({...input, treeAge: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-2 bg-slate-50 border rounded-xl" /></div>
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Cant. {unitLabel}</label>
                <input type="number" min="1" value={input.numTrees} onChange={e => setInput({...input, numTrees: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-2 bg-slate-50 border rounded-xl" /></div>
              </div>
              <div className="pt-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Tipo de Suelo</label>
                <div className="grid grid-cols-2 gap-2">
                  {Object.values(SoilType).map(s => (
                    <button key={s} onClick={() => setInput({...input, soilType: s})} className={`py-2 rounded-lg border text-[10px] font-bold transition-all ${input.soilType === s ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-slate-50 border-slate-100'}`}>{s}</button>
                  ))}
                </div>
              </div>
              <button onClick={async () => { setLoadingFormula(true); const f = await getPlantingFormula(input.treeType, input.soilType, input.numTrees, input.grassMode); setFormulaRec(f); setLoadingFormula(false); }} className="w-full py-3 bg-teal-600 text-white font-bold rounded-xl text-xs shadow-md hover:bg-teal-700 transition-colors">
                {loadingFormula ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-wand-magic mr-2"></i>}
