          </div>

          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><i className="fas fa-box text-emerald-600"></i> Insumos Disponibles</h2>
            <div className="max-h-[30rem] overflow-y-auto pr-2 custom-scrollbar">
              {renderProductSelector("Líquidos / Bioinsumos", PRODUCT_CATEGORIES.LIQUIDS)}
              {renderProductSelector("Sólidos / Enmiendas", PRODUCT_CATEGORIES.SOLIDS)}
            </div>
            <button onClick={async () => { setLoading(true); const a = await getAgriculturalAdvice(input); setAiAdvice(a); setLoading(false); }} className="w-full mt-6 py-4 bg-emerald-600 text-white font-bold rounded-2xl shadow-lg hover:bg-emerald-700 transition-colors">
              {loading ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-brain mr-2"></i>}
              {loading ? 'Analizando...' : 'Consultar Analista IA'}
            </button>
          </div>
        </aside>

        <section className="lg:col-span-8 space-y-6">
          {formulaRec && (
            <div className="bg-slate-900 text-white p-8 rounded-3xl animate-in fade-in slide-in-from-top duration-500 no-print">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-emerald-400 font-bold uppercase text-xs tracking-widest">Protocolo Sugerido de Siembra</h3>
                <button onClick={() => setFormulaRec(null)} className="text-slate-500 hover:text-white transition-colors"><i className="fas fa-times"></i></button>
              </div>
              <p className="text-xs text-slate-400 mb-6 leading-relaxed">{formulaRec.explanation}</p>
              <div className="grid md:grid-cols-2 gap-4">
                {formulaRec.items.map((it, i) => (
                  <div key={i} className="bg-white/5 p-4 rounded-2xl border border-white/5">
                    <div className="flex justify-between font-bold text-sm mb-1"><span>{it.product}</span><span className="text-emerald-400">{it.totalAmount} {it.unit}</span></div>
                    <p className="text-[10px] text-slate-400 italic leading-relaxed">"{it.reason}"</p>
                  </div>
                ))}
              </div>
