                          name="Suministro" 
                          dataKey="A" 
                          stroke="#10b981" 
                          fill="#10b981" 
                          fillOpacity={0.5} 
                        />
                        <Tooltip />
                      </RadarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm h-80 flex flex-col">
                  <h4 className="text-[10px] font-bold text-slate-400 mb-4 uppercase flex items-center gap-2"><i className="fas fa-chart-bar"></i> Distribución de Costos por Producto</h4>
                  <div className="flex-1 min-h-0">
