          {aiAdvice && (
            <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white animate-in zoom-in duration-700 border border-white/5 shadow-2xl no-print">
              <div className="flex justify-between items-center mb-8">
                <div className="flex items-center gap-4">
