          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><i className="fas fa-leaf text-emerald-600"></i> Insumos</h2>
            <div className="max-h-80 overflow-y-auto pr-2 custom-scrollbar">
              {renderProductSelector("Líquidos", PRODUCT_CATEGORIES.LIQUIDS)}
              {renderProductSelector("Sólidos", PRODUCT_CATEGORIES.SOLIDS)}
