            <button onClick={async () => { setLoading(true); const a = await getAgriculturalAdvice(input); setAiAdvice(a); setLoading(false); }} className="w-full mt-6 py-4 bg-emerald-600 text-white font-bold rounded-2xl shadow-lg hover:bg-emerald-700 transition-colors">
              {loading ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-brain mr-2"></i>}
