import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell 
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    soilType: SoilType.LOAMY,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingFormula, setLoadingFormula] = useState(false);
  const [formulaRec, setFormulaRec] = useState<PlantingFormulaRecommendation | null>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  // Load history on start
  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Error loading history", e);
      }
    }
  }, []);

  // Save history when it changes
  useEffect(() => {
    localStorage.setItem('agro_pro_history', JSON.stringify(history));
  }, [history]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || 'g';
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass]);

  const nutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return [];
    let n=0, p=0, k=0, om=0;
    result.products.forEach(item => {
      const nut = PRODUCT_NUTRIENTS[item.product] || { N: 0, P: 0, K: 0, OM: 0 };
      const qty = item.amount * (['g','ml','cc'].includes(item.unit) ? 0.001 : 1);
      n += nut.N * qty; 
      p += nut.P * qty; 
      k += nut.K * qty; 
      om += nut.OM * qty;
    });

    return [
      { subject: 'N', A: Math.min(n, 100) },
      { subject: 'P', A: Math.min(p, 100) },
      { subject: 'K', A: Math.min(k, 100) },
      { subject: 'M.O.', A: Math.min(om, 100) }
    ];
  }, [result]);

  useEffect(() => { 
    calculateDose(); 
  }, [calculateDose]);

  const saveReportToHistory = () => {
    if (!result) return;
    const newItem: HistoryItem = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      treeType: input.treeType,
      numTrees: input.numTrees,
      unitLabel: unitLabel || 'planta',
      totalCost: result.totalProjectCost,
      result: { ...result }
    };
    setHistory(prev => [newItem, ...prev].slice(0, 20)); // Keep last 20
  };

  const deleteFromHistory = (id: string) => {
    setHistory(prev => prev.filter(item => item.id !== id));
  };

  const clearHistory = () => {
    if (confirm("¿Estás seguro de que deseas vaciar todo el historial?")) {
      setHistory([]);
    }
  };

  const generatePDF = () => {
    if (!result) return;
    try {
      const doc = new jsPDF();
      doc.setFillColor(16, 185, 129);
      doc.rect(0, 0, 210, 40, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFontSize(22);
      doc.text('AgroCalculadora PRO', 15, 25);
      doc.setFontSize(10);
      doc.text(`Reporte Técnico - ${new Date().toLocaleDateString()}`, 15, 33);

      doc.setTextColor(50, 50, 50);
      doc.setFontSize(12);
      doc.text(`Cultivo: ${input.treeType}`, 15, 50);
      doc.text(`Cantidad: ${input.numTrees} ${unitLabel}`, 15, 57);

      const tableData = result.products.map(p => [
        p.product,
        `${p.amount} ${p.unit}`,
        `$${p.totalCost.toLocaleString('es-CO')}`
      ]);

      autoTable(doc, {
        startY: 70,
        head: [['Producto', 'Dosis Total', 'Subtotal']],
        body: tableData,
        headStyles: { fillColor: [16, 185, 129] }
      });

      const finalY = (doc as any).lastAutoTable?.finalY || 150;
      doc.setFontSize(14);
      doc.text(`Inversión Total: $${result.totalProjectCost.toLocaleString('es-CO')}`, 15, finalY + 15);

      doc.save(`AgroReporte_${input.treeType}.pdf`);
    } catch (e) {
      console.error("PDF Error:", e);
    }
  };

  const shareWhatsApp = () => {
    if (!result) return;
    const text = `*AgroCalculadora PRO*%0A*Cultivo:* ${input.treeType}%0A*Cantidad:* ${input.numTrees} ${unitLabel}%0A*Costo:* $${result.totalProjectCost.toLocaleString('es-CO')}`;
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  const renderProductSelector = (title: string, items: OrganicProduct[]) => (
    <div className="mb-6">
      <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">{title}</h3>
      <div className="space-y-2">
        {items.map(p => {
          const selected = input.selectedProducts.includes(p);
          return (
            <div key={p} className={`p-3 rounded-xl border transition-all ${selected ? 'bg-emerald-50 border-emerald-200' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
              <div className="flex items-center justify-between">
                <label className="flex items-center gap-3 cursor-pointer">
                  <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p] }))} className="accent-emerald-600 h-4 w-4" />
                  <span className="text-sm font-bold text-slate-700">{p}</span>
                </label>
                {selected && (
                  <select value={input.selectedUnits[p]} onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})} className="text-[10px] bg-white border px-1 rounded uppercase">
                    <option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="cc">cc</option><option value="L">L</option>
                  </select>
                )}
              </div>
              {selected && (
                <div className="grid grid-cols-2 gap-2 mt-2 pl-7">
                  <input type="number" placeholder="Dosis" value={input.manualAmounts[p] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="p-1 text-xs border rounded bg-white" />
                  <input type="number" placeholder="Precio" value={input.productPrices[p] || ''} onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} className="p-1 text-xs border rounded bg-white" />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pb-12 bg-slate-50">
      <header className="bg-emerald-900 text-white p-6 shadow-lg sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-2 rounded-lg"><i className="fas fa-seedling text-xl"></i></div>
            <h1 className="text-xl font-extrabold tracking-tight">AgroCalculadora <span className="text-emerald-400">PRO</span></h1>
          </div>
          {result && result.products.length > 0 && (
            <div className="flex gap-2">
              <button onClick={saveReportToHistory} title="Guardar en historial" className="bg-emerald-600 hover:bg-emerald-500 px-3 py-1 rounded-lg text-xs font-bold transition-colors"><i className="fas fa-save"></i></button>
              <button onClick={generatePDF} className="bg-white/10 hover:bg-white/20 px-3 py-1 rounded-lg text-xs font-bold transition-colors"><i className="fas fa-file-pdf"></i></button>
              <button onClick={shareWhatsApp} className="bg-emerald-600 hover:bg-emerald-500 px-3 py-1 rounded-lg text-xs font-bold transition-colors"><i className="fab fa-whatsapp"></i></button>
            </div>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <aside className="lg:col-span-4 space-y-6 no-print">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-6 flex items-center gap-2"><i className="fas fa-cog text-emerald-600"></i> Parámetros</h2>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-2">
                {Object.values(TreeType).map(t => (
                  <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-2 rounded-xl border text-[10px] font-bold flex flex-col items-center gap-1 transition-all ${input.treeType === t ? 'bg-emerald-50 border-emerald-500 text-emerald-900 shadow-sm' : 'bg-slate-50 border-slate-100'}`}>
                    {TREE_TYPE_ICONS[t]} {t}
                  </button>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Edad (Mes)</label>
                <input type="number" min="1" value={input.treeAge} onChange={e => setInput({...input, treeAge: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-2 bg-slate-50 border rounded-xl" /></div>
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Cant. {unitLabel}</label>
                <input type="number" min="1" value={input.numTrees} onChange={e => setInput({...input, numTrees: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-2 bg-slate-50 border rounded-xl" /></div>
              </div>
              <button onClick={async () => { setLoadingFormula(true); const f = await getPlantingFormula(input.treeType, input.soilType, input.numTrees, input.grassMode); setFormulaRec(f); setLoadingFormula(false); }} className="w-full py-3 bg-teal-600 text-white font-bold rounded-xl text-xs shadow-md hover:bg-teal-700 transition-colors">
                {loadingFormula ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-wand-magic mr-2"></i>}
                Generar Fórmula Siembra
              </button>
            </div>
          </div>

          {/* Historial Section */}
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-lg font-bold flex items-center gap-2"><i className="fas fa-history text-emerald-600"></i> Historial</h2>
              {history.length > 0 && (
                <button onClick={clearHistory} className="text-[10px] text-red-400 hover:text-red-600 font-bold uppercase">Limpiar</button>
              )}
            </div>
            <div className="max-h-64 overflow-y-auto pr-2 custom-scrollbar space-y-3">
              {history.length === 0 ? (
                <p className="text-[11px] text-slate-400 text-center py-4 italic">No hay reportes guardados.</p>
              ) : (
                history.map(item => (
                  <div key={item.id} className="group relative bg-slate-50 p-3 rounded-xl border border-slate-100 hover:border-emerald-200 transition-all cursor-pointer">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-[10px] font-black text-emerald-700 uppercase">{TREE_TYPE_ICONS[item.treeType]} {item.treeType}</span>
                      <button onClick={(e) => { e.stopPropagation(); deleteFromHistory(item.id); }} className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all">
                        <i className="fas fa-trash-alt text-[10px]"></i>
                      </button>
                    </div>
                    <div className="flex justify-between items-end">
                      <div className="text-[9px] text-slate-400">
                        {new Date(item.timestamp).toLocaleDateString()} • {item.numTrees} {item.unitLabel}
                      </div>
                      <div className="text-[10px] font-bold text-slate-800">
                        ${item.totalCost.toLocaleString('es-CO')}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><i className="fas fa-leaf text-emerald-600"></i> Insumos</h2>
            <div className="max-h-80 overflow-y-auto pr-2 custom-scrollbar">
              {renderProductSelector("Líquidos", PRODUCT_CATEGORIES.LIQUIDS)}
              {renderProductSelector("Sólidos", PRODUCT_CATEGORIES.SOLIDS)}
            </div>
            <button onClick={async () => { setLoading(true); const a = await getAgriculturalAdvice(input); setAiAdvice(a); setLoading(false); }} className="w-full mt-6 py-4 bg-emerald-600 text-white font-bold rounded-2xl shadow-lg hover:bg-emerald-700 transition-colors">
              {loading ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-brain mr-2"></i>}
              Análisis IA
            </button>
          </div>
        </aside>

        <section className="lg:col-span-8 space-y-6">
          {result && result.products.length > 0 ? (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 no-print">
                <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm h-80 flex flex-col">
                  <h4 className="text-[10px] font-bold text-slate-400 mb-4 uppercase flex items-center gap-2"><i className="fas fa-chart-pie"></i> Balance NPK+MO</h4>
                  <div className="flex-1 min-h-0">
                    <ResponsiveContainer width="100%" height="100%">
                      <RadarChart cx="50%" cy="50%" outerRadius="80%" data={nutrientData}>
                        <PolarGrid stroke="#e2e8f0" />
                        <PolarAngleAxis dataKey="subject" tick={{fontSize: 10, fill: '#64748b'}} />
                        <Radar name="Aporte" dataKey="A" stroke="#10b981" fill="#10b981" fillOpacity={0.6} />
                        <Tooltip />
                      </RadarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm h-80 flex flex-col">
                  <h4 className="text-[10px] font-bold text-slate-400 mb-4 uppercase flex items-center gap-2"><i className="fas fa-dollar-sign"></i> Distribución Costos</h4>
                  <div className="flex-1 min-h-0">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={result.products}>
                        <XAxis dataKey="product" hide />
                        <YAxis hide />
                        <Tooltip formatter={(v: any) => `$${v.toLocaleString('es-CO')}`} />
                        <Bar dataKey="totalCost" fill="#10b981" radius={[4, 4, 0, 0]}>
                          {result.products.map((_, i) => <Cell key={i} fill={i % 2 === 0 ? '#059669' : '#34d399'} />)}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-[2rem] shadow-xl overflow-hidden border border-slate-200">
                <div className="bg-emerald-900 p-8 text-white flex justify-between items-center">
                  <div>
                    <h3 className="text-xl font-bold">Reporte de Lote</h3>
                    <p className="text-[10px] opacity-60 uppercase font-bold tracking-widest">{input.numTrees} {unitLabel} de {input.treeType}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] opacity-60 mb-1 font-bold uppercase">Total Estimado</p>
                    <span className="text-3xl font-black">${result.totalProjectCost.toLocaleString('es-CO')}</span>
                  </div>
                </div>
                <div className="p-8 overflow-x-auto">
                  <table className="w-full text-left text-sm">
                    <thead>
                      <tr className="border-b text-[10px] font-bold text-slate-400 uppercase">
                        <th className="pb-4">Insumo</th>
                        <th className="pb-4 text-center">Dosis</th>
                        <th className="pb-4 text-right">Subtotal</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {result.products.map(p => (
                        <tr key={p.product}>
                          <td className="py-4 font-bold text-slate-800">{p.product}</td>
                          <td className="py-4 text-center font-bold text-emerald-600">{p.amount} {p.unit}</td>
                          <td className="py-4 text-right text-slate-600">${p.totalCost.toLocaleString('es-CO')}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  <div className="mt-8 flex gap-3 no-print">
                    <button onClick={saveReportToHistory} className="flex-1 py-3 bg-emerald-600 text-white font-bold rounded-xl text-xs shadow-md hover:bg-emerald-700 transition-all flex items-center justify-center gap-2">
                      <i className="fas fa-save"></i> Guardar en Historial
                    </button>
                    <button onClick={generatePDF} className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-800 font-bold rounded-xl text-xs transition-all flex items-center justify-center gap-2">
                      <i className="fas fa-file-pdf"></i> Descargar PDF
                    </button>
                    <button onClick={shareWhatsApp} className="flex-1 py-3 bg-emerald-50 hover:bg-emerald-100 text-emerald-700 font-bold rounded-xl text-xs transition-all flex items-center justify-center gap-2">
                      <i className="fab fa-whatsapp"></i> WhatsApp
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[2rem] p-20 text-center border-2 border-dashed border-slate-200 flex flex-col items-center">
              <i className="fas fa-seedling text-5xl text-emerald-100 mb-6 animate-pulse"></i>
              <h3 className="text-lg font-bold text-slate-800">Cálculo de Precisión</h3>
              <p className="text-slate-400 text-sm max-w-xs mx-auto mt-2">Configura el lote y selecciona insumos para ver el análisis de costos y nutrientes.</p>
            </div>
          )}

          {aiAdvice && (
            <div className="bg-slate-900 rounded-[2rem] p-10 text-white animate-in zoom-in duration-500 shadow-2xl">
              <div className="flex justify-between items-center mb-8">
                <div className="flex items-center gap-3">
                  <i className="fas fa-brain text-emerald-400 text-2xl"></i>
                  <h3 className="font-bold">Diagnóstico IA</h3>
                </div>
                <div className="text-right">
                  <span className="text-[10px] text-emerald-400 font-bold uppercase block">Sostenibilidad</span>
                  <span className="text-2xl font-black text-emerald-400">{aiAdvice.sustainabilityScore}/10</span>
                </div>
              </div>
              <div className="grid md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  {aiAdvice.tips.map((t, i) => (
                    <div key={i} className="flex gap-4 items-start bg-white/5 p-4 rounded-xl border border-white/5">
                      <span className="text-emerald-400 font-bold text-xs">{i + 1}</span>
                      <p className="text-xs text-slate-300 leading-relaxed">{t}</p>
                    </div>
                  ))}
                </div>
                <div className="p-6 bg-emerald-400/5 rounded-2xl border border-emerald-400/10">
                  <h4 className="text-[10px] font-bold text-emerald-400 uppercase mb-2">Momento Sugerido</h4>
                  <p className="text-sm italic text-slate-200">"{aiAdvice.seasonalAdvice}"</p>
                </div>
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="text-center mt-20 text-[10px] font-bold text-slate-300 uppercase tracking-widest pb-12">
        <p>© 2024 AGROCALCULADORA PRO • COLOMBIA</p>
      </footer>
    </div>
  );
};

export default App;

export enum TreeType {
  CITRUS = 'Cítricos',
  PLANTAIN = 'Plátano',
  BANANA = 'Banano',
  CASSAVA = 'Yuca',
  AVOCADO = 'Aguacate',
  COFFEE = 'Café',
  CACAO = 'Cacao',
  GARDEN = 'Plantas de Jardín',
  GRASS = 'Césped',
  FOREST = 'Forestales'
}

export enum SoilType {
  SANDY = 'Arenoso',
  SILTY = 'Limoso',
  CLAYEY = 'Arcilloso',
  LOAMY = 'Franco'
}

export enum GrassMeasureMode {
  AREA = 'm2',
  LINEAR = 'm lineal'
}

export enum OrganicProduct {
  POTASSIUM_SOAP = 'Jabón Potásico',
  LIQUID_HUMUS = 'Humus Líquido',
  LIQUID_IRON_OXIDE = 'Hierro Líquido',
  EM = 'EM (Microorganismos)',
  MOLASSES = 'Melaza',
  SULFUR_FUNGICIDE = 'Azufre Líquido',
  NEEM_EXTRACT = 'Extracto de Neem',
  BORON = 'Boro',
  ZINC = 'Zinc',
  COPPER = 'Cobre',
  COMPOST_TERRABONO = 'Compost Premium',
  SEA_SALT = 'Sal Marina',
  ROCK_DUST = 'Harina de Roca',
  PHOSPHATE_ROCK = 'Roca Fosfórica',
  CALCIUM_CARBONATE = 'Carbonato de Calcio',
  LEONARDITE = 'Leonardita',
  DIATOMACEOUS_EARTH = 'Tierra de Diatomeas',
  MAGNESITE = 'Magnesita'
}

export type UnitType = 'g' | 'kg' | 'cc' | 'ml' | 'L';

export interface CalculationInput {
  treeType: TreeType;
  soilType: SoilType;
  treeAge: number;
  numTrees: number;
  grassMode?: GrassMeasureMode;
  selectedProducts: OrganicProduct[];
  productPrices: Record<string, number>;
  manualAmounts: Record<string, number | undefined>;
  selectedUnits: Record<string, UnitType>;
  healthStatus: 'bueno' | 'regular' | 'deficiente';
}

export interface ProductResult {
  product: OrganicProduct;
  amount: number;
  unit: UnitType;
  costPerUnit: number;
  totalCost: number;
}

export interface CalculationResult {
  products: ProductResult[];
  totalCostPerUnit: number;
  totalProjectCost: number;
  frequency: string;
}

export interface NutritionStep {
  item: string;
  dosage: string;
  purpose: string;
}

export interface AIAdvice {
  tips: string[];
  seasonalAdvice: string;
  sustainabilityScore: number;
  radicularPlan: NutritionStep[];
  foliarPlan: NutritionStep[];
  soilAnalysis: string;
}

export interface PlantingFormulaItem {
  product: OrganicProduct;
  suggestedAmount: number;
  totalAmount: number;
  unit: UnitType;
  reason: string;
}

export interface PlantingFormulaRecommendation {
  explanation: string;
  items: PlantingFormulaItem[];
}

export interface HistoryItem {
  id: string;
  timestamp: number;
  treeType: TreeType;
  numTrees: number;
  unitLabel: string;
  totalCost: number;
  result: CalculationResult;
}

import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, PlantingFormulaRecommendation, OrganicProduct } from "../types.ts";

const getApiKey = () => {
  try {
    return process.env.API_KEY || "";
  } catch (e) {
    return "";
  }
};

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const apiKey = getApiKey();
    if (!apiKey) return null;

    const ai = new GoogleGenAI({ apiKey });
    const productList = input.selectedProducts.join(", ");
    const unitLabel = input.treeType === 'Césped' ? (input.grassMode || 'm2') : 'planta/árbol';

    const prompt = `Actúa como Ingeniero Agrónomo de Alta Precisión. 
    Analiza este escenario:
    - Cultivo: ${input.treeType}
    - Suelo: ${input.soilType}
    - Estado de Salud: ${input.healthStatus}
    - Insumos disponibles: [${productList}]

    Proporciona una formulación profesional detallada que incluya:
    1. Un "Análisis de Suelo" explicando cómo ese tipo de suelo (${input.soilType}) afecta la absorción.
    2. Un "Plan Radicular" (nutrición al suelo) con pasos específicos usando los insumos.
    3. Un "Plan Foliar" (nutrición a las hojas) para bioestimulación.
    4. 3 Consejos Técnicos.
    5. Puntaje de sostenibilidad.
    6. Momento estacional ideal.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan"],
        },
      },
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Advice Error:", error);
    return null;
  }
};

export const getPlantingFormula = async (treeType: string, soilType: string, quantity: number, grassMode?: string): Promise<PlantingFormulaRecommendation | null> => {
  try {
    const apiKey = getApiKey();
    if (!apiKey) return null;

    const ai = new GoogleGenAI({ apiKey });
    const productsList = Object.values(OrganicProduct).join(", ");
    const measureUnit = treeType === 'Césped' ? (grassMode || 'm2') : 'planta';

    const prompt = `Eres agrónomo experto en establecimiento de cultivos. 
    Diseña la fórmula de SIEMBRA ideal para: ${treeType}. 
    Considerando suelo: ${soilType}. 
    Cantidad: ${quantity} ${measureUnit}.
    Explica detalladamente cómo preparar el hoyo de siembra según el suelo ${soilType} (drenaje, materia orgánica, etc).
    Usa productos de esta lista: [${productsList}].`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            explanation: { type: Type.STRING },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  product: { type: Type.STRING },
                  suggestedAmount: { type: Type.NUMBER },
                  totalAmount: { type: Type.NUMBER },
                  unit: { type: Type.STRING },
                  reason: { type: Type.STRING }
                },
                required: ["product", "suggestedAmount", "totalAmount", "unit", "reason"]
              }
            }
          },
          required: ["explanation", "items"]
        }
      }
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Formula Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode, HistoryItem } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell 
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    soilType: SoilType.LOAMY,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingFormula, setLoadingFormula] = useState(false);
  const [formulaRec, setFormulaRec] = useState<PlantingFormulaRecommendation | null>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history');
    if (saved) {
      try { setHistory(JSON.parse(saved)); } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history', JSON.stringify(history));
  }, [history]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || 'g';
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass]);

  const nutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return [];
    let n=0, p=0, k=0, om=0;
    result.products.forEach(item => {
      const nut = PRODUCT_NUTRIENTS[item.product] || { N: 0, P: 0, K: 0, OM: 0 };
      const qty = item.amount * (['g','ml','cc'].includes(item.unit) ? 0.001 : 1);
      n += nut.N * qty; p += nut.P * qty; k += nut.K * qty; om += nut.OM * qty;
    });
    return [
      { subject: 'N', A: Math.min(n, 100) },
      { subject: 'P', A: Math.min(p, 100) },
      { subject: 'K', A: Math.min(k, 100) },
      { subject: 'M.O.', A: Math.min(om, 100) }
    ];
  }, [result]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const saveReportToHistory = () => {
    if (!result) return;
    const newItem: HistoryItem = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      treeType: input.treeType,
      numTrees: input.numTrees,
      unitLabel: unitLabel || 'planta',
      totalCost: result.totalProjectCost,
      result: { ...result }
    };
    setHistory(prev => [newItem, ...prev].slice(0, 20));
  };

  const generatePDF = () => {
    if (!result) return;
    try {
      const doc = new jsPDF();
      doc.setFillColor(16, 185, 129);
      doc.rect(0, 0, 210, 40, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFontSize(20);
      doc.text('Reporte AgroCalculadora PRO', 15, 25);
      doc.text(`Cultivo: ${input.treeType}`, 15, 33);
      const tableData = result.products.map(p => [p.product, `${p.amount} ${p.unit}`, `$${p.totalCost.toLocaleString('es-CO')}`]);
      autoTable(doc, { startY: 50, head: [['Insumo', 'Dosis', 'Subtotal']], body: tableData });
      doc.save(`Reporte_${input.treeType}.pdf`);
    } catch (e) { console.error(e); }
  };

  const renderProductSelector = (title: string, items: OrganicProduct[]) => (
    <div className="mb-6">
      <h3 className="text-[10px] font-bold text-slate-400 uppercase mb-3">{title}</h3>
      <div className="space-y-2">
        {items.map(p => {
          const selected = input.selectedProducts.includes(p);
          return (
            <div key={p} className={`p-3 rounded-xl border transition-all ${selected ? 'bg-emerald-50 border-emerald-200 shadow-sm' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
              <div className="flex items-center justify-between">
                <label className="flex items-center gap-3 cursor-pointer">
                  <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p] }))} className="accent-emerald-600 h-4 w-4" />
                  <span className="text-sm font-bold text-slate-700">{p}</span>
                </label>
                {selected && (
                  <select value={input.selectedUnits[p]} onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})} className="text-[10px] bg-white border px-1 rounded">
                    <option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="cc">cc</option><option value="L">L</option>
                  </select>
                )}
              </div>
              {selected && (
                <div className="grid grid-cols-2 gap-2 mt-2 pl-7">
                  <input type="number" placeholder="Dosis" value={input.manualAmounts[p] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="p-1 text-xs border rounded bg-white" />
                  <input type="number" placeholder="Precio" value={input.productPrices[p] || ''} onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} className="p-1 text-xs border rounded bg-white" />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pb-12 bg-slate-50">
      <header className="bg-emerald-900 text-white p-6 shadow-lg sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-2 rounded-lg shadow-inner"><i className="fas fa-seedling text-xl"></i></div>
            <h1 className="text-xl font-extrabold tracking-tight">AgroCalculadora <span className="text-emerald-400">PRO</span></h1>
          </div>
          {result && result.products.length > 0 && (
            <div className="flex gap-2">
              <button onClick={saveReportToHistory} title="Guardar" className="bg-emerald-600 hover:bg-emerald-500 px-3 py-1 rounded-lg text-xs font-bold transition-all"><i className="fas fa-save"></i></button>
              <button onClick={generatePDF} className="bg-white/10 hover:bg-white/20 px-3 py-1 rounded-lg text-xs font-bold transition-all"><i className="fas fa-file-pdf"></i></button>
            </div>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <aside className="lg:col-span-4 space-y-6 no-print">
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800"><i className="fas fa-cog text-emerald-600"></i> Parámetros Técnicos</h2>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-2">
                {Object.values(TreeType).map(t => (
                  <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-2 rounded-xl border text-[10px] font-bold flex flex-col items-center gap-1 transition-all ${input.treeType === t ? 'bg-emerald-50 border-emerald-500 text-emerald-900 shadow-sm' : 'bg-slate-50 border-slate-100 hover:border-slate-300'}`}>
                    {TREE_TYPE_ICONS[t]} {t}
                  </button>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-2">
                {Object.values(SoilType).map(s => (
                  <button key={s} onClick={() => setInput({...input, soilType: s})} className={`py-2 rounded-xl border text-[9px] font-bold transition-all ${input.soilType === s ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-slate-50 border-slate-100'}`}>{s}</button>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Edad (Mes)</label>
                <input type="number" min="1" value={input.treeAge} onChange={e => setInput({...input, treeAge: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-2 bg-slate-50 border rounded-xl font-bold" /></div>
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Cant. {unitLabel}</label>
                <input type="number" min="1" value={input.numTrees} onChange={e => setInput({...input, numTrees: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-2 bg-slate-50 border rounded-xl font-bold" /></div>
              </div>
              <button onClick={async () => { setLoadingFormula(true); const f = await getPlantingFormula(input.treeType, input.soilType, input.numTrees, input.grassMode); setFormulaRec(f); setLoadingFormula(false); }} className="w-full py-4 bg-teal-600 text-white font-bold rounded-2xl text-xs shadow-lg hover:bg-teal-700 transition-all flex items-center justify-center gap-2">
