import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, PlantingFormulaRecommendation, OrganicProduct } from "../types.ts";

const getApiKey = () => {
  try {
    return process.env.API_KEY || "";
  } catch (e) {
    return "";
  }
};

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const apiKey = getApiKey();
    if (!apiKey) return null;

    const ai = new GoogleGenAI({ apiKey });
    const productList = input.selectedProducts.join(", ");

    const prompt = `Actúa como Ingeniero Agrónomo de Alta Precisión y Fisiólogo Vegetal. 
    Analiza este escenario técnico:
    - Cultivo Específico: ${input.treeType} (Edad: ${input.treeAge} meses)
    - Entorno de Suelo: ${input.soilType}
    - Condición de Salud actual: ${input.healthStatus}
    - Insumos para la mezcla: [${productList}]

    Proporciona una FORMULACIÓN PRECISA DE ELEMENTOS que incluya:
    1. Un "Análisis de Suelo" profesional sobre la interacción físico-química con el cultivo.
    2. "Formulación Elemental": Identifica los 5 elementos químicos (N, P, K, Ca, Mg, S o micros como B, Zn) más críticos para este cultivo en este momento, su relevancia fisiológica y su prioridad.
    3. "Plan Radicular": Dosificación exacta por planta/área basada en los insumos seleccionados.
    4. "Plan Foliar": Aplicación técnica para corrección rápida de carencias.
    5. Consejos de manejo agronómico.
    6. Puntaje de sostenibilidad y recomendación estacional.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING, description: "Nombre del elemento (ej. Nitrógeno (N))" },
                  relevance: { type: Type.STRING, description: "Por qué es vital para esta planta" },
                  priority: { type: Type.STRING, enum: ["Alta", "Media", "Baja"] }
                },
                required: ["element", "relevance", "priority"]
              }
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "elementalFormulation"],
        },
      },
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Advice Error:", error);
    return null;
  }
};

export const getPlantingFormula = async (treeType: string, soilType: string, quantity: number, grassMode?: string): Promise<PlantingFormulaRecommendation | null> => {
  try {
    const apiKey = getApiKey();
    if (!apiKey) return null;

    const ai = new GoogleGenAI({ apiKey });
    const productsList = Object.values(OrganicProduct).join(", ");
    const measureUnit = treeType === 'Césped' ? (grassMode || 'm2') : 'planta';

    const prompt = `Eres agrónomo experto en establecimiento de cultivos. 
    Diseña la fórmula de SIEMBRA ideal para: ${treeType}. 
    Considerando suelo: ${soilType}. 
    Cantidad: ${quantity} ${measureUnit}.
    Explica detalladamente cómo preparar el hoyo de siembra según el suelo ${soilType} (drenaje, materia orgánica, etc).
    Usa productos de esta lista: [${productsList}].`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            explanation: { type: Type.STRING },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  product: { type: Type.STRING },
                  suggestedAmount: { type: Type.NUMBER },
                  totalAmount: { type: Type.NUMBER },
                  unit: { type: Type.STRING },
                  reason: { type: Type.STRING }
                },
                required: ["product", "suggestedAmount", "totalAmount", "unit", "reason"]
              }
            }
          },
          required: ["explanation", "items"]
        }
      }
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Formula Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode, HistoryItem } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell 
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    soilType: SoilType.LOAMY,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingFormula, setLoadingFormula] = useState(false);
  const [formulaRec, setFormulaRec] = useState<PlantingFormulaRecommendation | null>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history');
    if (saved) {
      try { setHistory(JSON.parse(saved)); } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history', JSON.stringify(history));
  }, [history]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || 'g';
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass]);

  const nutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return [];
    let n=0, p=0, k=0, om=0;
    result.products.forEach(item => {
      const nut = PRODUCT_NUTRIENTS[item.product] || { N: 0, P: 0, K: 0, OM: 0 };
      const qty = item.amount * (['g','ml','cc'].includes(item.unit) ? 0.001 : 1);
      n += nut.N * qty; p += nut.P * qty; k += nut.K * qty; om += nut.OM * qty;
    });
    return [
      { subject: 'N', A: Math.min(n, 100) },
      { subject: 'P', A: Math.min(p, 100) },
      { subject: 'K', A: Math.min(k, 100) },
      { subject: 'M.O.', A: Math.min(om, 100) }
    ];
  }, [result]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const saveReportToHistory = () => {
    if (!result) return;
    const newItem: HistoryItem = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      treeType: input.treeType,
      numTrees: input.numTrees,
      unitLabel: unitLabel || 'planta',
      totalCost: result.totalProjectCost,
      result: { ...result }
    };
    setHistory(prev => [newItem, ...prev].slice(0, 20));
  };

  const generatePDF = () => {
    if (!result) return;
    try {
      const doc = new jsPDF();
      doc.setFillColor(16, 185, 129);
      doc.rect(0, 0, 210, 40, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFontSize(20);
      doc.text('Reporte AgroCalculadora PRO', 15, 25);
      doc.text(`Cultivo: ${input.treeType}`, 15, 33);
      const tableData = result.products.map(p => [p.product, `${p.amount} ${p.unit}`, `$${p.totalCost.toLocaleString('es-CO')}`]);
      autoTable(doc, { startY: 50, head: [['Insumo', 'Dosis', 'Subtotal']], body: tableData });
      doc.save(`Reporte_${input.treeType}.pdf`);
    } catch (e) { console.error(e); }
  };

  const renderProductSelector = (title: string, items: OrganicProduct[]) => (
    <div className="mb-6">
      <h3 className="text-[10px] font-bold text-slate-400 uppercase mb-3">{title}</h3>
      <div className="space-y-2">
        {items.map(p => {
          const selected = input.selectedProducts.includes(p);
          return (
            <div key={p} className={`p-3 rounded-xl border transition-all ${selected ? 'bg-emerald-50 border-emerald-200 shadow-sm' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
              <div className="flex items-center justify-between">
                <label className="flex items-center gap-3 cursor-pointer">
                  <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p] }))} className="accent-emerald-600 h-4 w-4" />
                  <span className="text-sm font-bold text-slate-700">{p}</span>
                </label>
                {selected && (
                  <select value={input.selectedUnits[p]} onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})} className="text-[10px] bg-white border px-1 rounded">
                    <option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="cc">cc</option><option value="L">L</option>
                  </select>
                )}
              </div>
              {selected && (
                <div className="grid grid-cols-2 gap-2 mt-2 pl-7">
                  <input type="number" placeholder="Dosis" value={input.manualAmounts[p] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="p-1 text-xs border rounded bg-white" />
                  <input type="number" placeholder="Precio" value={input.productPrices[p] || ''} onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} className="p-1 text-xs border rounded bg-white" />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pb-12 bg-slate-50">
      <header className="bg-emerald-900 text-white p-6 shadow-lg sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-2 rounded-lg shadow-inner"><i className="fas fa-seedling text-xl"></i></div>
            <h1 className="text-xl font-extrabold tracking-tight">AgroCalculadora <span className="text-emerald-400">PRO</span></h1>
          </div>
          {result && result.products.length > 0 && (
            <div className="flex gap-2">
              <button onClick={saveReportToHistory} title="Guardar" className="bg-emerald-600 hover:bg-emerald-500 px-3 py-1 rounded-lg text-xs font-bold transition-all"><i className="fas fa-save"></i></button>
              <button onClick={generatePDF} className="bg-white/10 hover:bg-white/20 px-3 py-1 rounded-lg text-xs font-bold transition-all"><i className="fas fa-file-pdf"></i></button>
            </div>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <aside className="lg:col-span-4 space-y-6 no-print">
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800"><i className="fas fa-cog text-emerald-600"></i> Parámetros Técnicos</h2>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-2">
                {Object.values(TreeType).map(t => (
                  <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-2 rounded-xl border text-[10px] font-bold flex flex-col items-center gap-1 transition-all ${input.treeType === t ? 'bg-emerald-50 border-emerald-500 text-emerald-900 shadow-sm' : 'bg-slate-50 border-slate-100 hover:border-slate-300'}`}>
                    {TREE_TYPE_ICONS[t]} {t}
                  </button>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-2">
                {Object.values(SoilType).map(s => (
                  <button key={s} onClick={() => setInput({...input, soilType: s})} className={`py-2 rounded-xl border text-[9px] font-bold transition-all ${input.soilType === s ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-slate-50 border-slate-100'}`}>{s}</button>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Edad (Mes)</label>
                <input type="number" min="1" value={input.treeAge} onChange={e => setInput({...input, treeAge: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-2 bg-slate-50 border rounded-xl font-bold" /></div>
                <div><label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Cant. {unitLabel}</label>
                <input type="number" min="1" value={input.numTrees} onChange={e => setInput({...input, numTrees: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-2 bg-slate-50 border rounded-xl font-bold" /></div>
              </div>
              <button onClick={async () => { setLoadingFormula(true); const f = await getPlantingFormula(input.treeType, input.soilType, input.numTrees, input.grassMode); setFormulaRec(f); setLoadingFormula(false); }} className="w-full py-4 bg-teal-600 text-white font-bold rounded-2xl text-xs shadow-lg hover:bg-teal-700 transition-all flex items-center justify-center gap-2">
                {loadingFormula ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-seedling"></i>}
                Formulación de Siembra IA
              </button>
            </div>
          </div>

          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2 text-slate-800"><i className="fas fa-history text-emerald-600"></i> Historial</h2>
            <div className="max-h-48 overflow-y-auto pr-2 custom-scrollbar space-y-2">
              {history.length === 0 ? <p className="text-[10px] text-slate-400 italic text-center py-4">Sin registros.</p> : history.map(h => (
