import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, PlantingFormulaRecommendation, OrganicProduct } from "../types.ts";

const getApiKey = () => {
  try {
    return process.env.API_KEY || "";
  } catch (e) {
    return "";
  }
};

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const apiKey = getApiKey();
    if (!apiKey) return null;

    const ai = new GoogleGenAI({ apiKey });
    const productList = input.selectedProducts.join(", ");
    const isGrass = input.treeType === 'Césped';
    const specificType = isGrass ? `Césped variedad ${input.grassVariety}` : input.treeType;
    const measureUnit = isGrass ? input.grassMode : 'planta/árbol';

    const prompt = `Actúa como Ingeniero Agrónomo experto en el campo colombiano y fisiólogo vegetal. 
    Analiza este escenario técnico:
    - Cultivo Específico: ${specificType} (Edad/Tiempo: ${input.treeAge} meses)
    - Cantidad: ${input.numTrees} ${measureUnit}
    - Entorno de Suelo: ${input.soilType}
    - Condición de Salud actual: ${input.healthStatus}
    - Insumos para la mezcla: [${productList}]

    Proporciona una FORMULACIÓN DE ALTO RENDIMIENTO que incluya:
    1. Un "Análisis de Suelo" profesional (enfocado en ${input.soilType} y su impacto en ${specificType}).
    2. "Formulación Elemental": Identifica los 5 elementos más críticos para la salud, densidad y color de este cultivo. Asigna un nivel de requerimiento de 0 a 100.
    3. "Plan Radicular": Mezcla exacta para el suelo para fortalecer raíces y estolones.
    4. "Plan Foliar": Aplicación para brillo, resistencia al pisoteo y fotosíntesis rápida.
    5. Consejos de manejo agronómico (frecuencia de riego, altura de corte si aplica, etc).
    6. Puntaje de sostenibilidad y recomendación según el clima colombiano predominante.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING, enum: ["Alta", "Media", "Baja"] },
                  requirementLevel: { type: Type.NUMBER }
                },
                required: ["element", "relevance", "priority", "requirementLevel"]
              }
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "elementalFormulation"],
        },
      },
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Advice Error:", error);
    return null;
  }
};

