                </div>

                <div className="mt-8 grid md:grid-cols-2 gap-4">
                   <div className="p-6 bg-emerald-400/5 rounded-3xl border border-emerald-400/10">
                    <h4 className="text-[10px] font-black text-emerald-400 uppercase mb-3">{isGrass ? 'Manejo de Pradera' : 'Consejos de Ingeniería'}</h4>
                    <ul className="space-y-2">
                      {aiAdvice.tips.map((t, i) => (
