              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="text-center mt-20 text-[10px] font-bold text-slate-300 uppercase tracking-widest pb-12">
        <p>© 2024 AGROCALCULADORA PRO • INGENIERÍA AGRÓNOMA DIGITAL • COLOMBIA</p>
      </footer>
    </div>
  );
};

export default App;

export enum TreeType {
  CITRUS = 'Cítricos',
  PLANTAIN = 'Plátano',
  BANANA = 'Banano',
  CASSAVA = 'Yuca',
  AVOCADO = 'Aguacate',
  COFFEE = 'Café',
  CACAO = 'Cacao',
  GARDEN = 'Plantas de Jardín',
  GRASS = 'Césped',
  FOREST = 'Forestales'
}

export enum GrassVariety {
  KIKUYO = 'Kikuyo',
  SAN_AGUSTIN = 'San Agustín',
