  BERMUDA_419 = 'Bermuda 419',
  TRENZA = 'Trenza',
  MACANA = 'Macana / Dulce',
  MANI_FORRAJERO = 'Maní Forrajero',
  JAPONESA = 'Japonesa',
  GATEADORA = 'Gateadora',
  ESMERALDA = 'Esmeralda'
}

export enum SoilType {
  SANDY = 'Arenoso',
  SILTY = 'Limoso',
  CLAYEY = 'Arcilloso',
  LOAMY = 'Franco'
}

export enum GrassMeasureMode {
