                          </BarChart>
                        </ResponsiveContainer>
                      </div>
                   </div>

                   <div className="lg:col-span-5 flex flex-col gap-3 overflow-y-auto custom-scrollbar max-h-[350px]">
                      {aiAdvice.elementalFormulation?.map((el, i) => (
                        <div key={i} className="bg-white/5 p-4 rounded-2xl border border-white/10 hover:bg-white/10 transition-all group">
                          <div className="flex justify-between items-start mb-2">
                            <span className="text-[10px] font-black text-emerald-400 px-2 py-0.5 bg-emerald-400/10 rounded-md uppercase tracking-wider">{el.element}</span>
                            <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded uppercase ${el.priority === 'Alta' ? 'bg-red-500/20 text-red-400' : 'bg-yellow-500/20 text-yellow-400'}`}>
                              {el.priority}
