                          </div>
                          <div className="w-full bg-white/5 h-1 rounded-full mb-2 overflow-hidden">
                             <div className="bg-emerald-500 h-full transition-all duration-1000" style={{ width: `${el.requirementLevel}%` }}></div>
                          </div>
                          <p className="text-[10px] text-slate-400 leading-snug font-medium line-clamp-2 group-hover:line-clamp-none">"{el.relevance}"</p>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                  <div className="space-y-4">
                    <h4 className="text-xs font-black text-emerald-400 uppercase tracking-widest flex items-center gap-2">
                      <i className="fas fa-arrow-down"></i> Nutrición Radicular (Suelo)
                    </h4>
                    {aiAdvice.radicularPlan.map((step, i) => (
                      <div key={i} className="bg-white/5 p-4 rounded-2xl border border-white/5 hover:bg-white/10 transition-all">
                        <div className="flex justify-between items-center mb-2">
                          <span className="text-xs font-black text-white">{step.item}</span>
                          <span className="text-[10px] bg-emerald-500/20 text-emerald-400 px-2 py-0.5 rounded-full font-bold">{step.dosage}</span>
                        </div>
                        <p className="text-[10px] text-slate-400 leading-relaxed font-medium">{step.purpose}</p>
                      </div>
                    ))}
                  </div>
                  <div className="space-y-4">
                    <h4 className="text-xs font-black text-teal-400 uppercase tracking-widest flex items-center gap-2">
                      <i className="fas fa-spray-can"></i> Nutrición Foliar (Hojas)
                    </h4>
                    {aiAdvice.foliarPlan.map((step, i) => (
                      <div key={i} className="bg-white/5 p-4 rounded-2xl border border-white/5 hover:bg-white/10 transition-all">
                        <div className="flex justify-between items-center mb-2">
                          <span className="text-xs font-black text-white">{step.item}</span>
                          <span className="text-[10px] bg-teal-500/20 text-teal-400 px-2 py-0.5 rounded-full font-bold">{step.dosage}</span>
                        </div>
                        <p className="text-[10px] text-slate-400 leading-relaxed font-medium">{step.purpose}</p>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="mt-8 grid md:grid-cols-2 gap-4">
                   <div className="p-6 bg-emerald-400/5 rounded-3xl border border-emerald-400/10">
                    <h4 className="text-[10px] font-black text-emerald-400 uppercase mb-3">{isGrass ? 'Manejo de Pradera' : 'Consejos de Ingeniería'}</h4>
                    <ul className="space-y-2">
                      {aiAdvice.tips.map((t, i) => (
                        <li key={i} className="text-[10px] text-slate-300 flex items-start gap-2">
                          <i className="fas fa-check text-emerald-500 mt-0.5"></i> {t}
                        </li>
                      ))}
                    </ul>
                  </div>
                  <div className="p-6 bg-white/5 rounded-3xl border border-white/10 flex flex-col justify-center items-center text-center">
                    <p className="text-[10px] text-slate-500 font-black uppercase mb-2">Ventana Estacional</p>
                    <p className="text-lg font-black text-white">{aiAdvice.seasonalAdvice}</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </section>
      </main>

      <footer className="text-center mt-20 text-[10px] font-bold text-slate-300 uppercase tracking-widest pb-12">
        <p>© 2024 AGROCALCULADORA PRO • INGENIERÍA AGRÓNOMA DIGITAL • COLOMBIA</p>
      </footer>
    </div>
  );
};

