      const finalY = (doc as any).lastAutoTable.finalY + 10;
      doc.setTextColor(0, 0, 0);
      doc.setFontSize(14);
      doc.text(`Inversión Total Proyecto: $${result.totalProjectCost.toLocaleString('es-CO')}`, 15, finalY);

      if (aiAdvice) {
        doc.setFontSize(16);
        doc.text('Estrategia de Nutrición IA', 15, finalY + 15);

        // Pest Analysis in PDF
        if (aiAdvice.pestAnalysis) {
          doc.setFillColor(244, 63, 94); // Rose 500
          doc.rect(15, finalY + 20, 180, 25, 'F');
          doc.setTextColor(255, 255, 255);
          doc.setFontSize(12);
          doc.text(`ALERTA DE PLAGA: ${aiAdvice.pestAnalysis.identifiedPest}`, 20, finalY + 28);
          doc.setFontSize(9);
          doc.text(`Tratamiento: ${aiAdvice.pestAnalysis.organicTreatment} | Ciclo: ${aiAdvice.pestAnalysis.controlCycle}`, 20, finalY + 35);
          doc.text(`Severidad: ${aiAdvice.pestAnalysis.severity}`, 20, finalY + 40);
        }

        doc.setTextColor(0, 0, 0);
        let currentY = finalY + (aiAdvice.pestAnalysis ? 55 : 25);

        // Radicular Plan
        doc.setFontSize(12);
        doc.setTextColor(16, 185, 129);
        doc.text('Plan Radicular:', 15, currentY);
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);
        currentY += 7;
        aiAdvice.radicularPlan.forEach(step => {
          if (currentY > 270) { doc.addPage(); currentY = 20; }
          doc.text(`• ${step.item}: ${step.dosage} - ${step.purpose}`, 20, currentY, { maxWidth: 170 });
          currentY += 8;
        });

        // Foliar Plan
        currentY += 5;
        if (currentY > 270) { doc.addPage(); currentY = 20; }
        doc.setFontSize(12);
        doc.setTextColor(14, 165, 233);
        doc.text('Plan Foliar:', 15, currentY);
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);
        currentY += 7;
        aiAdvice.foliarPlan.forEach(step => {
          if (currentY > 270) { doc.addPage(); currentY = 20; }
          doc.text(`• ${step.item}: ${step.dosage} - ${step.purpose}`, 20, currentY, { maxWidth: 170 });
          currentY += 8;
        });
      }
    }
    return { doc, title };
  };

  const generatePDF = () => {
    const { doc, title } = createPDFDoc();
    doc.save(`${title}.pdf`);
  };

  const shareReport = async (method: 'whatsapp' | 'email') => {
    if (!result) return;
    const { doc, title } = createPDFDoc();
    const pdfBlob = doc.output('blob');
    const pdfFile = new File([pdfBlob], `${title}.pdf`, { type: 'application/pdf' });

    const summaryText = `*REPORTE AGROCALCULADORA VISION PRO*\n\n` +
      `Cultivo: ${isGrass ? `Césped ${input.grassVariety}` : input.treeType}\n` +
      `Suelo: ${input.soilType}\n` +
      `Inversión Total: $${result.totalProjectCost.toLocaleString('es-CO')}\n` +
      (aiAdvice?.pestAnalysis ? `🚨 PLAGA DETECTADA: ${aiAdvice.pestAnalysis.identifiedPest}\n` : '') +
      `Estrategia IA disponible en el PDF adjunto.`;

    if (navigator.share && navigator.canShare && navigator.canShare({ files: [pdfFile] })) {
      try {
        await navigator.share({
