import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode, HistoryItem, GrassVariety, ClimateType } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell,
  CartesianGrid, AreaChart, Area
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingFormula, setLoadingFormula] = useState(false);
  const [formulaRec, setFormulaRec] = useState<PlantingFormulaRecommendation | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history');
    if (saved) {
      try { setHistory(JSON.parse(saved)); } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history', JSON.stringify(history));
  }, [history]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;
    if (input.climate === ClimateType.RAINY) modifier *= 1.1; 

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || 'g';
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass]);

  const nutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return [];
    let n=0, p=0, k=0, om=0;
    result.products.forEach(item => {
      const nut = PRODUCT_NUTRIENTS[item.product] || { N: 0, P: 0, K: 0, OM: 0 };
      const qty = item.amount * (['g','ml','cc'].includes(item.unit) ? 0.001 : 1);
      n += nut.N * qty; p += nut.P * qty; k += nut.K * qty; om += nut.OM * qty;
    });
    return [
      { subject: 'N', A: Math.min(n, 100) },
      { subject: 'P', A: Math.min(p, 100) },
      { subject: 'K', A: Math.min(k, 100) },
      { subject: 'M.O.', A: Math.min(om, 100) }
    ];
  }, [result]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const saveReportToHistory = () => {
    if (!result) return;
    const newItem: HistoryItem = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      treeType: input.treeType,
      grassVariety: input.grassVariety,
      numTrees: input.numTrees,
      unitLabel: unitLabel || 'planta',
      totalCost: result.totalProjectCost,
      result: { ...result }
    };
    setHistory(prev => [newItem, ...prev].slice(0, 20));
  };

  const createPDFDoc = () => {
    const doc = new jsPDF();
    const title = `Reporte_${isGrass ? `Cesped_${input.grassVariety}` : input.treeType.replace(' ', '_')}`;

    doc.setFillColor(6, 78, 59);
    doc.rect(0, 0, 210, 45, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.text('AGROCALCULADORA VISION PRO', 15, 20);
    doc.setFontSize(10);
    doc.text(`Generado el: ${new Date().toLocaleString()}`, 15, 28);
    doc.text(`Cultivo: ${isGrass ? `Césped ${input.grassVariety}` : input.treeType}`, 15, 34);
    doc.text(`Suelo: ${input.soilType} | Clima: ${input.climate} | Cantidad: ${input.numTrees} ${unitLabel}`, 15, 40);

    if (result) {
      const tableData = result.products.map(p => [p.product, `${p.amount} ${p.unit}`, `$${p.totalCost.toLocaleString('es-CO')}`]);
      autoTable(doc, { 
        startY: 55, 
        head: [['Producto / Insumo', 'Dosis Sugerida', 'Inversión Total']], 
        body: tableData,
        theme: 'striped',
        headStyles: { fillColor: [16, 185, 129] }
      });

      const finalY = (doc as any).lastAutoTable.finalY + 10;
      doc.setTextColor(0, 0, 0);
      doc.setFontSize(14);
      doc.text(`Inversión Total Proyecto: $${result.totalProjectCost.toLocaleString('es-CO')}`, 15, finalY);

      if (aiAdvice) {
        let currentY = finalY + 15;
        doc.setFontSize(16);
        doc.text('Estrategia de Nutrición e IA', 15, currentY);
        currentY += 10;

        if (aiAdvice.visualDiagnosis) {
          doc.setFontSize(11);
          doc.text('Lectura de Planta:', 15, currentY);
          doc.setFontSize(9);
          doc.text(aiAdvice.visualDiagnosis, 15, currentY + 5, { maxWidth: 180 });
          currentY += 20;
        }

        if (aiAdvice.pestAnalysis) {
          doc.setFillColor(244, 63, 94);
          doc.rect(15, currentY, 180, 25, 'F');
          doc.setTextColor(255, 255, 255);
          doc.setFontSize(12);
          doc.text(`ALERTA DE PLAGA: ${aiAdvice.pestAnalysis.identifiedPest}`, 20, currentY + 8);
          doc.setFontSize(9);
          doc.text(`Tratamiento: ${aiAdvice.pestAnalysis.organicTreatment}`, 20, currentY + 15);
          doc.text(`Ciclo: ${aiAdvice.pestAnalysis.controlCycle} | Severidad: ${aiAdvice.pestAnalysis.severity}`, 20, currentY + 20);
          currentY += 35;
        }

        doc.setTextColor(0, 0, 0);
        doc.setFontSize(12);
        doc.setTextColor(16, 185, 129);
        doc.text('Plan Radicular:', 15, currentY);
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);
        currentY += 7;
        aiAdvice.radicularPlan.forEach(step => {
          if (currentY > 270) { doc.addPage(); currentY = 20; }
          doc.text(`• ${step.item}: ${step.dosage} - ${step.purpose}`, 20, currentY, { maxWidth: 170 });
          currentY += 8;
        });
      }
    }
    return { doc, title };
  };

  const generatePDF = () => {
    const { doc, title } = createPDFDoc();
    doc.save(`${title}.pdf`);
  };

  const shareReport = async (method: 'whatsapp' | 'email') => {
    if (!result) return;
    const { doc, title } = createPDFDoc();
    const pdfBlob = doc.output('blob');
    const pdfFile = new File([pdfBlob], `${title}.pdf`, { type: 'application/pdf' });

    const summaryText = `*REPORTE AGROCALCULADORA VISION PRO*\n\n` +
      `Cultivo: ${isGrass ? `Césped ${input.grassVariety}` : input.treeType}\n` +
      `Lote: ${input.numTrees} ${unitLabel}\n` +
      (aiAdvice?.pestAnalysis ? `🚨 PLAGA DETECTADA: ${aiAdvice.pestAnalysis.identifiedPest}\n` : '') +
      `Estrategia Completa en el PDF adjunto.`;

    if (navigator.share && navigator.canShare && navigator.canShare({ files: [pdfFile] })) {
      try {
