export interface HistoryItem {
  id: string;
  timestamp: number;
  treeType: TreeType;
  grassVariety?: GrassVariety;
  numTrees: number;
  unitLabel: string;
  totalCost: number;
  result: CalculationResult;
  aiAdvice: AIAdvice | null;
  location?: {
    lat: number;
    lng: number;
  };
}

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode, HistoryItem, GrassVariety, ClimateType } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell,
  CartesianGrid, AreaChart, Area
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'history'>('calculator');
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingLocation, setSavingLocation] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history_v2');
    if (saved) {
      try { setHistory(JSON.parse(saved)); } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history_v2', JSON.stringify(history));
  }, [history]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;
    if (input.climate === ClimateType.RAINY) modifier *= 1.1; 

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || 'g';
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass]);

  const nutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return [];
    let n=0, p=0, k=0, om=0;
    result.products.forEach(item => {
      const nut = PRODUCT_NUTRIENTS[item.product] || { N: 0, P: 0, K: 0, OM: 0 };
      const qty = item.amount * (['g','ml','cc'].includes(item.unit) ? 0.001 : 1);
      n += nut.N * qty; p += nut.P * qty; k += nut.K * qty; om += nut.OM * qty;
    });
    return [
      { subject: 'N', A: Math.min(n, 100) },
      { subject: 'P', A: Math.min(p, 100) },
      { subject: 'K', A: Math.min(k, 100) },
      { subject: 'M.O.', A: Math.min(om, 100) }
    ];
  }, [result]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const saveReportToHistory = () => {
    if (!result) return;
    setSavingLocation(true);

    const performSave = (location?: { lat: number; lng: number }) => {
      const newItem: HistoryItem = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        treeType: input.treeType,
        grassVariety: input.grassVariety,
        numTrees: input.numTrees,
        unitLabel: unitLabel || 'planta',
        totalCost: result.totalProjectCost,
        result: { ...result },
        aiAdvice: aiAdvice ? { ...aiAdvice } : null,
        location
      };
      setHistory(prev => [newItem, ...prev].slice(0, 50));
      setSavingLocation(false);
      alert("Reporte guardado exitosamente con ubicación.");
    };

    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          performSave({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        },
        (error) => {
          console.warn("Error obteniendo ubicación:", error);
          performSave();
        },
        { timeout: 10000 }
      );
    } else {
      performSave();
    }
  };

  const loadFromHistory = (item: HistoryItem) => {
    setResult(item.result);
    setAiAdvice(item.aiAdvice);
    setInput(prev => ({
      ...prev,
      treeType: item.treeType,
      grassVariety: item.grassVariety,
      numTrees: item.numTrees
    }));
    setActiveTab('calculator');
  };

  const deleteFromHistory = (id: string) => {
    setHistory(prev => prev.filter(h => h.id !== id));
  };

  const createPDFDoc = () => {
    const doc = new jsPDF();
    const title = `Reporte_${isGrass ? `Cesped_${input.grassVariety}` : input.treeType.replace(' ', '_')}`;

    doc.setFillColor(6, 78, 59);
    doc.rect(0, 0, 210, 45, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.text('AGROCALCULADORA VISION PRO', 15, 20);
    doc.setFontSize(10);
    doc.text(`Generado el: ${new Date().toLocaleString()}`, 15, 28);
    doc.text(`Cultivo: ${isGrass ? `Césped ${input.grassVariety}` : input.treeType}`, 15, 34);
    doc.text(`Suelo: ${input.soilType} | Clima: ${input.climate} | Cantidad: ${input.numTrees} ${unitLabel}`, 15, 40);

    if (result) {
      const tableData = result.products.map(p => [p.product, `${p.amount} ${p.unit}`, `$${p.totalCost.toLocaleString('es-CO')}`]);
      autoTable(doc, { 
        startY: 55, 
        head: [['Producto / Insumo', 'Dosis Sugerida', 'Inversión Total']], 
        body: tableData,
        theme: 'striped',
        headStyles: { fillColor: [16, 185, 129] }
      });

      const finalY = (doc as any).lastAutoTable.finalY + 10;
      doc.setTextColor(0, 0, 0);
      doc.setFontSize(14);
      doc.text(`Inversión Total Proyecto: $${result.totalProjectCost.toLocaleString('es-CO')}`, 15, finalY);

      if (aiAdvice) {
        let currentY = finalY + 15;
        doc.setFontSize(16);
        doc.text('Estrategia de Nutrición e IA', 15, currentY);
        currentY += 10;

        if (aiAdvice.visualDiagnosis) {
          doc.setFontSize(11);
          doc.text('Lectura de Planta:', 15, currentY);
          doc.setFontSize(9);
          doc.text(aiAdvice.visualDiagnosis, 15, currentY + 5, { maxWidth: 180 });
          currentY += 20;
        }

        if (aiAdvice.pestAnalysis) {
          doc.setFillColor(244, 63, 94);
          doc.rect(15, currentY, 180, 25, 'F');
          doc.setTextColor(255, 255, 255);
          doc.setFontSize(12);
          doc.text(`ALERTA DE PLAGA: ${aiAdvice.pestAnalysis.identifiedPest}`, 20, currentY + 8);
          doc.setFontSize(9);
          doc.text(`Tratamiento: ${aiAdvice.pestAnalysis.organicTreatment}`, 20, currentY + 15);
          doc.text(`Ciclo: ${aiAdvice.pestAnalysis.controlCycle} | Severidad: ${aiAdvice.pestAnalysis.severity}`, 20, currentY + 20);
          currentY += 35;
        }

        doc.setTextColor(0, 0, 0);
        doc.setFontSize(12);
        doc.setTextColor(16, 185, 129);
        doc.text('Plan Radicular:', 15, currentY);
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);
        currentY += 7;
        aiAdvice.radicularPlan.forEach(step => {
          if (currentY > 270) { doc.addPage(); currentY = 20; }
          doc.text(`• ${step.item}: ${step.dosage} - ${step.purpose}`, 20, currentY, { maxWidth: 170 });
          currentY += 8;
        });
      }
    }
    return { doc, title };
  };

  const generatePDF = () => {
    const { doc, title } = createPDFDoc();
    doc.save(`${title}.pdf`);
  };

  const shareReport = async (method: 'whatsapp' | 'email') => {
    if (!result) return;
    const { doc, title } = createPDFDoc();
    const pdfBlob = doc.output('blob');
    const pdfFile = new File([pdfBlob], `${title}.pdf`, { type: 'application/pdf' });

    const summaryText = `*REPORTE AGROCALCULADORA VISION PRO*\n\n` +
      `Cultivo: ${isGrass ? `Césped ${input.grassVariety}` : input.treeType}\n` +
      `Lote: ${input.numTrees} ${unitLabel}\n` +
      (aiAdvice?.pestAnalysis ? `🚨 PLAGA DETECTADA: ${aiAdvice.pestAnalysis.identifiedPest}\n` : '') +
      `Estrategia Completa en el PDF adjunto.`;

    if (navigator.share && navigator.canShare && navigator.canShare({ files: [pdfFile] })) {
      try {
        await navigator.share({ files: [pdfFile], title: 'Reporte Agronómico', text: summaryText });
      } catch (err) {
        fallbackShare(method, summaryText);
      }
    } else {
      fallbackShare(method, summaryText);
    }
  };

  const fallbackShare = (method: 'whatsapp' | 'email', text: string) => {
    if (method === 'whatsapp') {
      window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
    } else {
      window.location.href = `mailto:?subject=Reporte AgroCalculadora&body=${encodeURIComponent(text)}`;
    }
    alert("Para enviar el reporte con el archivo, por favor descargue el PDF y adjúntelo manualmente.");
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setInput(prev => ({ ...prev, healthPhoto: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const renderProductSelector = (title: string, items: OrganicProduct[]) => (
    <div className="mb-6">
      <h3 className="text-[10px] font-bold text-slate-400 uppercase mb-3">{title}</h3>
      <div className="space-y-2">
        {items.map(p => {
          const selected = input.selectedProducts.includes(p);
          return (
            <div key={p} className={`p-3 rounded-xl border transition-all ${selected ? 'bg-emerald-50 border-emerald-200 shadow-sm' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
              <div className="flex items-center justify-between">
                <label className="flex items-center gap-3 cursor-pointer">
                  <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p] }))} className="accent-emerald-600 h-4 w-4" />
                  <span className="text-sm font-bold text-slate-700">{p}</span>
                </label>
                {selected && (
                  <select value={input.selectedUnits[p]} onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})} className="text-[10px] bg-white border px-1 rounded">
                    <option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="cc">cc</option><option value="L">L</option>
                  </select>
                )}
              </div>
              {selected && (
                <div className="grid grid-cols-2 gap-2 mt-2 pl-7">
                  <input type="number" placeholder="Dosis" value={input.manualAmounts[p] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="p-1 text-xs border rounded bg-white" />
                  <input type="number" placeholder="Precio" value={input.productPrices[p] || ''} onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} className="p-1 text-xs border rounded bg-white" />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pb-12 bg-slate-50">
      <header className="bg-emerald-900 text-white p-6 shadow-lg sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-2 rounded-lg shadow-inner"><i className="fas fa-robot text-xl"></i></div>
            <h1 className="text-xl font-extrabold tracking-tight">AgroCalculadora <span className="text-emerald-400">VISION PRO</span></h1>
          </div>
          <div className="flex gap-4">
            <nav className="flex bg-white/10 rounded-2xl p-1">
              <button onClick={() => setActiveTab('calculator')} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${activeTab === 'calculator' ? 'bg-emerald-500 text-white' : 'text-emerald-100 hover:bg-white/5'}`}>Calculadora</button>
              <button onClick={() => setActiveTab('history')} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${activeTab === 'history' ? 'bg-emerald-500 text-white' : 'text-emerald-100 hover:bg-white/5'}`}>Historial</button>
            </nav>
            {activeTab === 'calculator' && result && (
              <button onClick={saveReportToHistory} disabled={savingLocation} className="bg-emerald-600 hover:bg-emerald-500 px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 shadow-lg disabled:opacity-50">
                {savingLocation ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-map-marker-alt"></i>}
                <span>Guardar Ubicación</span>
              </button>
            )}
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        {activeTab === 'calculator' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <aside className="lg:col-span-4 space-y-6 no-print">
              {/* Parámetros */}
              <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
                <h2 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800"><i className="fas fa-cog text-emerald-600"></i> Parámetros</h2>
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-2">
                    {Object.values(TreeType).map(t => (
                      <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-2 rounded-xl border text-[10px] font-bold flex flex-col items-center gap-1 transition-all ${input.treeType === t ? 'bg-emerald-50 border-emerald-500 text-emerald-900 shadow-sm' : 'bg-slate-50 border-slate-100 hover:border-slate-300'}`}>
                        {TREE_TYPE_ICONS[t]} {t}
                      </button>
                    ))}
                  </div>

