import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, PlantingFormulaRecommendation, OrganicProduct } from "../types.ts";

// Agricultural advice service using Gemini 3
export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    // Initializing Gemini with API key from environment as per guidelines
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const productList = input.selectedProducts.join(", ");
    const isGrass = input.treeType === 'Césped';
    const specificType = isGrass ? `Césped variedad ${input.grassVariety}` : input.treeType;
    const measureUnit = isGrass ? input.grassMode : 'planta/árbol';

    let contents: any;
    const textPrompt = `Actúa como Ingeniero Agrónomo Senior y experto en Entomología y Fitopatología. 
    Analiza este escenario técnico:
    - Cultivo: ${specificType} (Edad: ${input.treeAge} meses)
    - Cantidad: ${input.numTrees} ${measureUnit}
    - Clima: ${input.climate}
    - Suelo: ${input.soilType}
    - Insumos disponibles: [${productList}]

    INSTRUCCIÓN ESPECIAL PARA IMAGEN:
    Si hay una foto, busca específicamente signos de PLAGAS (insectos, ácaros, etc.) o ENFERMEDADES (hongos, bacterias, virus).
    Identifica el agente causal y proporciona un "pestAnalysis" con:
    1. identifiedPest: Nombre común y científico.
    2. symptoms: Qué daño se observa.
    3. organicTreatment: Qué producto orgánico usar (preferir Jabón Potásico, Neem, Azufre o soluciones biológicas).
    4. controlCycle: Periodo de control (ej: cada 3 días por 2 semanas).
    5. severity: Nivel de urgencia.

    Genera una respuesta en JSON con:
    1. soilAnalysis: Contexto del suelo.
    2. visualDiagnosis: Resumen general de lo que ves.
    3. pestAnalysis: El análisis detallado de la plaga (si se detecta).
    4. elementalFormulation: 5 elementos críticos.
    5. radicularPlan & foliarPlan: Nutrición técnica.
    6. waterRequirement: Plan de riego para clima ${input.climate}.
    7. tips, seasonalAdvice, sustainabilityScore.`;

    if (input.healthPhoto) {
      contents = {
        parts: [
          { text: textPrompt },
          { inlineData: { mimeType: 'image/jpeg', data: input.healthPhoto.split(',')[1] } }
        ]
      };
    } else {
      contents = textPrompt;
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: contents,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            visualDiagnosis: { type: Type.STRING },
            pestAnalysis: {
              type: Type.OBJECT,
              properties: {
                identifiedPest: { type: Type.STRING },
                symptoms: { type: Type.STRING },
                organicTreatment: { type: Type.STRING },
                controlCycle: { type: Type.STRING },
                severity: { type: Type.STRING, enum: ["Leve", "Moderada", "Crítica"] }
              },
              required: ["identifiedPest", "symptoms", "organicTreatment", "controlCycle", "severity"]
            },
            waterRequirement: {
              type: Type.OBJECT,
              properties: {
                volume: { type: Type.STRING },
                frequency: { type: Type.STRING },
                technique: { type: Type.STRING }
              },
              required: ["volume", "frequency", "technique"]
            },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING, enum: ["Alta", "Media", "Baja"] },
                  requirementLevel: { type: Type.NUMBER }
                },
                required: ["element", "relevance", "priority", "requirementLevel"]
              }
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "elementalFormulation", "waterRequirement"],
        },
      },
    });

    // Accessing .text property directly as per guidelines
    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Advice Error:", error);
    return null;
  }
};

// Planting formula service using Gemini 3
export const getPlantingFormula = async (input: CalculationInput): Promise<PlantingFormulaRecommendation | null> => {
  try {
    // Initializing Gemini with API key from environment as per guidelines
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const productsList = Object.values(OrganicProduct).join(", ");
    const isGrass = input.treeType === 'Césped';
    const specificType = isGrass ? `Césped ${input.grassVariety}` : input.treeType;
    const measureUnit = isGrass ? input.grassMode : 'planta';

    const prompt = `Eres agrónomo experto en establecimiento de cultivos. 
    Diseña la fórmula de SIEMBRA/INSTALACIÓN ideal para: ${specificType}. 
    Considerando suelo: ${input.soilType}. 
    Cantidad: ${input.numTrees} ${measureUnit}.
    Explica detalladamente cómo preparar el terreno o el hoyo según el suelo ${input.soilType}.
    Para césped, enfócate en nivelación y capa vegetal.
    Usa productos de esta lista: [${productsList}].`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            explanation: { type: Type.STRING },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  product: { type: Type.STRING },
                  suggestedAmount: { type: Type.NUMBER },
                  totalAmount: { type: Type.NUMBER },
                  unit: { type: Type.STRING },
                  reason: { type: Type.STRING }
                },
                required: ["product", "suggestedAmount", "totalAmount", "unit", "reason"]
              }
            }
          },
          required: ["explanation", "items"]
        }
      }
    });

    // Accessing .text property directly as per guidelines
    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Formula Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode, HistoryItem, GrassVariety, ClimateType } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getPlantingFormula } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell,
  CartesianGrid, AreaChart, Area
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'history'>('calculator');
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingLocation, setSavingLocation] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history_v2');
    if (saved) {
      try { setHistory(JSON.parse(saved)); } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history_v2', JSON.stringify(history));
  }, [history]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;
    if (input.climate === ClimateType.RAINY) modifier *= 1.1; 

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || 'g';
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass]);

  const nutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return [];
    let n=0, p=0, k=0, om=0;
    result.products.forEach(item => {
      const nut = PRODUCT_NUTRIENTS[item.product] || { N: 0, P: 0, K: 0, OM: 0 };
      const qty = item.amount * (['g','ml','cc'].includes(item.unit) ? 0.001 : 1);
      n += nut.N * qty; p += nut.P * qty; k += nut.K * qty; om += nut.OM * qty;
    });
    return [
      { subject: 'N', A: Math.min(n, 100) },
      { subject: 'P', A: Math.min(p, 100) },
      { subject: 'K', A: Math.min(k, 100) },
      { subject: 'M.O.', A: Math.min(om, 100) }
    ];
  }, [result]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const saveReportToHistory = () => {
    if (!result) return;
    setSavingLocation(true);

    const performSave = (location?: { lat: number; lng: number }) => {
      const newItem: HistoryItem = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        treeType: input.treeType,
        grassVariety: input.grassVariety,
        numTrees: input.numTrees,
        unitLabel: unitLabel || 'planta',
        totalCost: result.totalProjectCost,
