import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, PlantingFormulaRecommendation, OrganicProduct, VisionReport } from "../types.ts";

// Agricultural advice service using Gemini 3
export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const productList = input.selectedProducts.join(", ");
    const isGrass = input.treeType === 'Césped';
    const specificType = isGrass ? `Césped variedad ${input.grassVariety}` : input.treeType;
    const measureUnit = isGrass ? input.grassMode : 'planta/árbol';

    let contents: any;
    const textPrompt = `Actúa como Ingeniero Agrónomo Senior y experto en Entomología y Fitopatología. 
    Analiza este escenario técnico:
    - Cultivo: ${specificType} (Edad: ${input.treeAge} meses)
    - Cantidad: ${input.numTrees} ${measureUnit}
    - Clima: ${input.climate}
    - Suelo: ${input.soilType}
    - Insumos disponibles: [${productList}]

    INSTRUCCIÓN ESPECIAL PARA IMAGEN:
    Si hay una foto, busca específicamente signos de PLAGAS (insectos, ácaros, etc.) o ENFERMEDADES (hongos, bacterias, virus).
    Identifica el agente causal y proporciona un "pestAnalysis" detallado.

    Genera una respuesta en JSON con:
    1. soilAnalysis: Contexto del suelo.
    2. visualDiagnosis: Resumen general de lo que ves.
    3. pestAnalysis: El análisis detallado de la plaga (si se detecta).
    4. elementalFormulation: 5 elementos críticos.
    5. radicularPlan & foliarPlan: Nutrición técnica.
    6. waterRequirement: Plan de riego para clima ${input.climate}.
    7. tips, seasonalAdvice, sustainabilityScore.`;

    if (input.healthPhoto) {
      contents = {
        parts: [
          { text: textPrompt },
          { inlineData: { mimeType: 'image/jpeg', data: input.healthPhoto.split(',')[1] } }
        ]
      };
    } else {
      contents = textPrompt;
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: contents,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            visualDiagnosis: { type: Type.STRING },
            pestAnalysis: {
              type: Type.OBJECT,
              properties: {
                identifiedPest: { type: Type.STRING },
                scientificName: { type: Type.STRING },
                symptoms: { type: Type.STRING },
                prevention: { type: Type.STRING },
                organicTreatment: { type: Type.STRING },
                controlCycle: { type: Type.STRING },
                severity: { type: Type.STRING, enum: ["Leve", "Moderada", "Crítica"] },
                lifeCycleInfo: { type: Type.STRING }
              },
              required: ["identifiedPest", "scientificName", "symptoms", "prevention", "organicTreatment", "controlCycle", "severity", "lifeCycleInfo"]
            },
            waterRequirement: {
              type: Type.OBJECT,
              properties: {
                volume: { type: Type.STRING },
                frequency: { type: Type.STRING },
                technique: { type: Type.STRING }
              },
              required: ["volume", "frequency", "technique"]
            },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING, enum: ["Alta", "Media", "Baja"] },
                  requirementLevel: { type: Type.NUMBER }
                },
                required: ["element", "relevance", "priority", "requirementLevel"]
              }
            },
