// Independent Vision Diagnosis Service
export const getIndependentVisionDiagnosis = async (imageBase64: string, treeType: string): Promise<VisionReport | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Actúa como un experto mundial en Fitopatología y Entomología Agrícola.
    Analiza esta imagen de un cultivo de ${treeType}.

    Proporciona un informe independiente extremadamente detallado:
    1. Lectura de Planta: Describe el estado fisiológico actual, color de hojas, turgencia y vigor.
    2. Análisis de Plaga/Enfermedad: Identificación precisa, nombre científico, síntomas observados, información sobre su ciclo de vida y nivel de severidad.
    3. Remedio Biológico Maestro: Crea una receta paso a paso para un remedio orgánico específico para esta plaga (ej: purín de ortiga, caldo bordelés, emulsión de neem/jabón, etc.). Incluye ingredientes exactos, preparación y modo de aplicación.
    4. Ciclo de Control: Define exactamente cada cuánto aplicar y por cuánto tiempo.
    5. Recomendaciones de prevención a futuro.

    Formato JSON:
    {
      "plantReading": "...",
      "pestAnalysis": {
        "identifiedPest": "...",
        "scientificName": "...",
        "symptoms": "...",
        "prevention": "...",
        "organicTreatment": "...",
        "controlCycle": "...",
        "severity": "...",
        "lifeCycleInfo": "..."
      },
      "biologicalRemedy": {
        "ingredients": ["...", "..."],
        "preparation": "...",
        "application": "..."
      },
      "recommendations": ["...", "..."]
    }`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] } }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            plantReading: { type: Type.STRING },
            pestAnalysis: {
              type: Type.OBJECT,
              properties: {
                identifiedPest: { type: Type.STRING },
                scientificName: { type: Type.STRING },
                symptoms: { type: Type.STRING },
                prevention: { type: Type.STRING },
                organicTreatment: { type: Type.STRING },
                controlCycle: { type: Type.STRING },
                severity: { type: Type.STRING, enum: ["Leve", "Moderada", "Crítica"] },
                lifeCycleInfo: { type: Type.STRING }
              },
              required: ["identifiedPest", "scientificName", "symptoms", "prevention", "organicTreatment", "controlCycle", "severity", "lifeCycleInfo"]
            },
            biologicalRemedy: {
              type: Type.OBJECT,
              properties: {
                ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                preparation: { type: Type.STRING },
                application: { type: Type.STRING }
              },
              required: ["ingredients", "preparation", "application"]
            },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["plantReading", "pestAnalysis", "biologicalRemedy", "recommendations"]
        }
      }
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Vision Diagnosis Error:", error);
    return null;
  }
};

export const getPlantingFormula = async (input: CalculationInput): Promise<PlantingFormulaRecommendation | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const productsList = Object.values(OrganicProduct).join(", ");
    const isGrass = input.treeType === 'Césped';
    const specificType = isGrass ? `Césped ${input.grassVariety}` : input.treeType;
    const measureUnit = isGrass ? input.grassMode : 'planta';

    const prompt = `Eres agrónomo experto en establecimiento de cultivos. 
    Diseña la fórmula de SIEMBRA/INSTALACIÓN ideal para: ${specificType}. 
    Considerando suelo: ${input.soilType}. 
    Cantidad: ${input.numTrees} ${measureUnit}.
    Explica detalladamente cómo preparar el terreno o el hoyo según el suelo ${input.soilType}.
    Para césped, enfócate en nivelación y capa vegetal.
    Usa productos de esta lista: [${productsList}].`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            explanation: { type: Type.STRING },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  product: { type: Type.STRING },
                  suggestedAmount: { type: Type.NUMBER },
                  totalAmount: { type: Type.NUMBER },
                  unit: { type: Type.STRING },
                  reason: { type: Type.STRING }
                },
                required: ["product", "suggestedAmount", "totalAmount", "unit", "reason"]
              }
            }
          },
          required: ["explanation", "items"]
        }
      }
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Formula Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode, HistoryItem, GrassVariety, ClimateType, VisionReport } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell,
  CartesianGrid, AreaChart, Area
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'vision' | 'history'>('calculator');
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingLocation, setSavingLocation] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const visionFileInputRef = useRef<HTMLInputElement>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history_v3');
    if (saved) {
      try { setHistory(JSON.parse(saved)); } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history_v3', JSON.stringify(history));
  }, [history]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;
    if (input.climate === ClimateType.RAINY) modifier *= 1.1; 

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || 'g';
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const handleVisionDiagnosis = async (image: string) => {
    setLoading(true);
    const report = await getIndependentVisionDiagnosis(image, input.treeType);
    setVisionReport(report);
    setLoading(false);
    if (report) {
      // Auto-save vision reports too
      saveReportToHistory(report, image);
    }
  };

  const saveReportToHistory = (customVisionReport?: VisionReport, customImage?: string) => {
    setSavingLocation(true);

    const performSave = (location?: { lat: number; lng: number }) => {
      const newItem: HistoryItem = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        treeType: input.treeType,
        grassVariety: input.grassVariety,
        numTrees: input.numTrees,
        unitLabel: unitLabel || 'planta',
        totalCost: result?.totalProjectCost || 0,
        result: activeTab === 'calculator' ? (result ? { ...result } : null) : null,
        aiAdvice: activeTab === 'calculator' ? (aiAdvice ? { ...aiAdvice } : null) : null,
        visionReport: customVisionReport || visionReport,
        location,
        imagePreview: customImage || input.healthPhoto
      };
      setHistory(prev => [newItem, ...prev].slice(0, 50));
      setSavingLocation(false);
    };

    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => performSave({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        () => performSave(),
