                              <i className={mode === GrassMeasureMode.AREA ? 'fas fa-th-large' : 'fas fa-ruler-horizontal'}></i>
                              {mode === GrassMeasureMode.AREA ? 'Área (m²)' : 'Lineal (m)'}
                            </button>
                          ))}
                        </div>
                      </div>
