// Agricultural advice service using Gemini 3
export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const productList = input.selectedProducts.join(", ");
    const isGrass = input.treeType === 'Césped';
    const specificType = isGrass ? `Césped variedad ${input.grassVariety}` : input.treeType;
    const measureUnit = isGrass ? input.grassMode : 'planta/árbol';
    const isPlanting = input.applicationMode === 'Siembra / Instalación';

    let contents: any;
    const textPrompt = `Actúa como Ingeniero Agrónomo Senior experto en nutrición vegetal orgánica. 
    Analiza este escenario de ${isPlanting ? 'SIEMBRA' : 'MANTENIMIENTO'}:
    - Cultivo: ${specificType} (${isPlanting ? 'ETAPA DE INICIO' : 'Edad: ' + input.treeAge + ' meses'})
    - Cantidad: ${input.numTrees} ${measureUnit}
    - Clima: ${input.climate}
    - Suelo: ${input.soilType}
    - Insumos disponibles: [${productList}]

    INSTRUCCIÓN CRÍTICA:
    Genera un plan de aplicación foliar y radicular extremadamente detallado. 
    Si es SIEMBRA, enfócate en el abonado del hoyo y el primer riego de establecimiento.
    Si es MANTENIMIENTO, enfócate en la etapa fisiológica actual.

    Genera una respuesta en JSON con:
    1. soilAnalysis: Contexto del suelo ${input.soilType}.
    2. visualDiagnosis: Resumen general.
    3. radicularPlan: Pasos para aplicación al suelo (Nombre, Dosis Exacta, Propósito).
    4. foliarPlan: Pasos para aspersión foliar (Nombre, Dosis Exacta, Propósito).
    5. pestAnalysis: El análisis detallado de la plaga (si se detecta).
    6. elementalFormulation: 5 elementos críticos.
    7. waterRequirement: Plan de riego para clima ${input.climate}.
    8. tips, seasonalAdvice, sustainabilityScore.`;

    if (input.healthPhoto) {
      contents = {
        parts: [
          { text: textPrompt },
          { inlineData: { mimeType: 'image/jpeg', data: input.healthPhoto.split(',')[1] } }
        ]
      };
    } else {
      contents = textPrompt;
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: contents,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            visualDiagnosis: { type: Type.STRING },
            pestAnalysis: {
              type: Type.OBJECT,
              properties: {
                identifiedPest: { type: Type.STRING },
                scientificName: { type: Type.STRING },
                symptoms: { type: Type.STRING },
                prevention: { type: Type.STRING },
                organicTreatment: { type: Type.STRING },
                controlCycle: { type: Type.STRING },
                severity: { type: Type.STRING, enum: ["Leve", "Moderada", "Crítica"] },
                lifeCycleInfo: { type: Type.STRING }
              },
              required: ["identifiedPest", "scientificName", "symptoms", "prevention", "organicTreatment", "controlCycle", "severity", "lifeCycleInfo"]
            },
            waterRequirement: {
              type: Type.OBJECT,
              properties: {
                volume: { type: Type.STRING },
                frequency: { type: Type.STRING },
                technique: { type: Type.STRING }
              },
              required: ["volume", "frequency", "technique"]
            },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING, enum: ["Alta", "Media", "Baja"] },
                  requirementLevel: { type: Type.NUMBER }
                },
                required: ["element", "relevance", "priority", "requirementLevel"]
              }
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "elementalFormulation", "waterRequirement"],
        },
      },
    });

    return response.text ? JSON.parse(response.text.trim()) : null;
  } catch (error) {
    console.error("Gemini Advice Error:", error);
    return null;
  }
};

