            {history.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
                {history.map(item => (
                  <div key={item.id} className="bg-slate-50 border-2 border-slate-200 rounded-[3rem] p-10 hover:shadow-2xl transition-all group relative overflow-hidden">
                    <div className="flex justify-between items-start mb-8">
                      <div className="h-16 w-16 bg-white rounded-3xl flex items-center justify-center shadow-md text-emerald-600 text-3xl">
                        {item.visionReport ? <i className="fas fa-eye text-indigo-500"></i> : TREE_TYPE_ICONS[item.treeType]}
                      </div>
                    </div>
                    <h3 className="text-3xl font-black text-slate-950 mb-2 leading-none">
                      {item.visionReport ? `IA: ${item.visionReport.pestAnalysis.identifiedPest}` : `Lote: ${item.treeType}`}
                    </h3>
                    <p className="text-sm font-black text-slate-400 uppercase mb-8 tracking-widest">{new Date(item.timestamp).toLocaleString()}</p>
                    <div className="flex justify-between items-center pt-8 border-t-2 border-slate-200">
                      <span className="text-2xl font-black text-emerald-700 tracking-tighter">
                        {item.result ? `$${item.result.totalProjectCost.toLocaleString('es-CO')}` : "Análisis Vision"}
                      </span>
                      <button onClick={() => loadFromHistory(item)} className="px-8 py-4 bg-emerald-600 text-white text-sm font-black rounded-2xl hover:bg-emerald-700 shadow-xl uppercase tracking-widest">Ver Detalles</button>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-40 flex flex-col items-center">
                <h4 className="text-4xl font-black text-slate-300 tracking-tighter">Nube Vacía</h4>
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="text-center mt-48 text-sm font-black text-slate-400 uppercase tracking-[0.5em] pb-32">
        <p className="mb-6">© 2024 AGROCALCULADORA VISION PRO • COLOMBIA</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode, HistoryItem, GrassVariety, ClimateType, VisionReport, ApplicationMode } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell,
  CartesianGrid, Legend
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'vision' | 'history'>('calculator');
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    applicationMode: ApplicationMode.MAINTENANCE,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingLocation, setSavingLocation] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const visionFileInputRef = useRef<HTMLInputElement>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const isPlanting = input.applicationMode === ApplicationMode.PLANTING;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history_v3');
    if (saved) {
      try { setHistory(JSON.parse(saved)); } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history_v3', JSON.stringify(history));
  }, [history]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;
    if (input.climate === ClimateType.RAINY) modifier *= 1.1; 

    if (isPlanting) modifier *= 2.0;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || 'g';
      const costPer = amount * (input.productPrices[p] || 0);
      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass, isPlanting]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const detailedNutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return { radar: [], stacked: [] };

    const colors = ['#10b981', '#3b82f6', '#f59e0b', '#8b5cf6', '#ef4444', '#ec4899', '#06b6d4'];
    let nTotal=0, pTotal=0, kTotal=0, omTotal=0;

    const stacked = [
      { name: 'Nitrógeno (N)', key: 'N' },
      { name: 'Fósforo (P)', key: 'P' },
      { name: 'Potasio (K)', key: 'K' },
      { name: 'Mat. Orgánica (MO)', key: 'OM' }
    ].map(nutType => {
      const data: any = { name: nutType.name };
      result.products.forEach((prod, idx) => {
        const nutConfig = PRODUCT_NUTRIENTS[prod.product] || { N:0, P:0, K:0, OM:0 };
        // Factor de peso: si es gramo/ml/cc dividimos por 1000 para obtener Kg/L para el cálculo de masa total
        const weightFactor = ['g','ml','cc'].includes(prod.unit) ? 0.001 : 1;
        const val = (nutConfig[nutType.key as keyof typeof nutConfig] * prod.amount * weightFactor);
        data[prod.product] = parseFloat(val.toFixed(3));

        if(nutType.key === 'N') nTotal += val;
        if(nutType.key === 'P') pTotal += val;
        if(nutType.key === 'K') kTotal += val;
        if(nutType.key === 'OM') omTotal += val;
      });
      return data;
    });

    const radar = [
      { subject: 'N', A: nTotal },
      { subject: 'P', A: pTotal },
      { subject: 'K', A: kTotal },
      { subject: 'MO', A: omTotal }
    ];

    return { radar, stacked, colors };
  }, [result]);

  const handleVisionDiagnosis = async (image: string) => {
    setLoading(true);
    const report = await getIndependentVisionDiagnosis(image, input.treeType);
    setVisionReport(report);
    setLoading(false);
    if (report) {
      saveReportToHistory(report, image);
    }
  };

  const saveReportToHistory = (customVisionReport?: VisionReport, customImage?: string) => {
    setSavingLocation(true);

    const performSave = (location?: { lat: number; lng: number }) => {
      const newItem: HistoryItem = {
        id: Date.now().toString(),
        timestamp: Date.now(),
        treeType: input.treeType,
        grassVariety: input.grassVariety,
        numTrees: input.numTrees,
        unitLabel: unitLabel || 'planta',
        totalCost: result?.totalProjectCost || 0,
        result: activeTab === 'calculator' ? (result ? { ...result } : null) : null,
        aiAdvice: activeTab === 'calculator' ? (aiAdvice ? { ...aiAdvice } : null) : null,
        visionReport: customVisionReport || visionReport,
        location,
        imagePreview: customImage || input.healthPhoto
      };
      setHistory(prev => [newItem, ...prev].slice(0, 50));
      setSavingLocation(false);
    };

    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => performSave({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        () => performSave(),
        { timeout: 10000 }
      );
    } else {
      performSave();
    }
  };

  const loadFromHistory = (item: HistoryItem) => {
    if (item.result) {
      setResult(item.result);
      setAiAdvice(item.aiAdvice);
      setActiveTab('calculator');
    } else if (item.visionReport) {
      setVisionReport(item.visionReport);
      setActiveTab('vision');
    }
    setInput(prev => ({
      ...prev,
      treeType: item.treeType,
      grassVariety: item.grassVariety,
      numTrees: item.numTrees,
      healthPhoto: item.imagePreview,
      grassMode: (item.unitLabel as GrassMeasureMode) || GrassMeasureMode.AREA
    }));
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'calculator' | 'vision') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const image = reader.result as string;
        if (type === 'calculator') {
          setInput(prev => ({ ...prev, healthPhoto: image }));
        } else {
          handleVisionDiagnosis(image);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const renderProductSelector = (title: string, items: OrganicProduct[]) => (
    <div className="mb-8">
      <h3 className="text-sm font-bold text-slate-500 uppercase mb-4 tracking-wider">{title}</h3>
      <div className="space-y-4">
        {items.map(p => {
          const selected = input.selectedProducts.includes(p);
          const currentUnit = input.selectedUnits[p] || PRODUCT_UNITS[p];

          return (
            <div key={p} className={`p-4 rounded-2xl border transition-all ${selected ? 'bg-emerald-50 border-emerald-300 shadow-md' : 'bg-slate-50 border-slate-200 opacity-70'}`}>
              <div className="flex items-center justify-between">
                <label className="flex items-center gap-4 cursor-pointer w-full">
                  <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p] }))} className="accent-emerald-600 h-5 w-5" />
                  <div className="flex flex-col">
                    <span className="text-base font-bold text-slate-800">{p}</span>
                    <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Base Sugerida: {BASE_RATES[p]} {PRODUCT_UNITS[p]}</span>
                  </div>
                </label>
              </div>
              {selected && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mt-4 pl-9">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Dosis</label>
                    <input 
                      type="number" 
                      placeholder="Dosis"
                      value={input.manualAmounts[p] ?? ''} 
                      onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} 
                      className="w-full p-2 text-sm border-2 rounded-xl bg-white focus:border-emerald-500 outline-none font-bold" 
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Unidad</label>
                    <select
                      value={currentUnit}
                      onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})}
                      className="w-full p-2 text-sm border-2 rounded-xl bg-white focus:border-emerald-500 outline-none font-bold cursor-pointer"
                    >
                      <option value="g">g (Gramos)</option>
                      <option value="kg">kg (Kilogramos)</option>
                      <option value="ml">ml (Mililitros)</option>
                      <option value="cc">cc (Centímetros Cúbicos)</option>
                      <option value="L">L (Litros)</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Precio/{currentUnit}</label>
                    <input 
                      type="number" 
                      placeholder="Precio" 
                      value={input.productPrices[p] || ''} 
                      onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} 
                      className="w-full p-2 text-sm border-2 rounded-xl bg-white focus:border-emerald-500 outline-none font-bold" 
                    />
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen pb-12 bg-slate-50 text-slate-900">
      <header className="bg-emerald-900 text-white p-6 shadow-xl sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex items-center gap-5">
            <div className="bg-emerald-500 p-3 rounded-2xl shadow-lg border-2 border-emerald-400/30"><i className="fas fa-microscope text-2xl"></i></div>
            <h1 className="text-2xl font-black tracking-tight leading-none">AgroVision <span className="text-emerald-400">CO PRO</span></h1>
          </div>
          <div className="flex gap-4 items-center">
            <nav className="flex bg-white/10 rounded-[2rem] p-1.5 border border-white/10 shadow-inner">
              <button onClick={() => setActiveTab('calculator')} className={`px-8 py-3 rounded-[1.5rem] text-sm font-black transition-all ${activeTab === 'calculator' ? 'bg-emerald-500 text-white shadow-lg scale-105' : 'text-emerald-100 hover:bg-white/5'}`}>Calculadora</button>
              <button onClick={() => setActiveTab('vision')} className={`px-8 py-3 rounded-[1.5rem] text-sm font-black transition-all ${activeTab === 'vision' ? 'bg-indigo-500 text-white shadow-lg scale-105' : 'text-emerald-100 hover:bg-white/5'}`}>Diagnóstico IA</button>
              <button onClick={() => setActiveTab('history')} className={`px-8 py-3 rounded-[1.5rem] text-sm font-black transition-all ${activeTab === 'history' ? 'bg-emerald-500 text-white shadow-lg scale-105' : 'text-emerald-100 hover:bg-white/5'}`}>Historial</button>
            </nav>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-10">
        {activeTab === 'calculator' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            <aside className="lg:col-span-4 space-y-8 no-print">
              <div className="bg-white p-8 rounded-[2.5rem] shadow-md border border-slate-200">
                <h2 className="text-xl font-black mb-8 flex items-center gap-3 text-slate-800"><i className="fas fa-sliders-h text-emerald-600"></i> Parámetros</h2>
                <div className="space-y-6">
                  <div className="p-1.5 bg-slate-100 rounded-2xl flex gap-2 border border-slate-200">
                    {Object.values(ApplicationMode).map(mode => (
                      <button key={mode} onClick={() => setInput({...input, applicationMode: mode})} className={`flex-1 py-3 px-2 rounded-xl text-[10px] font-black uppercase transition-all ${input.applicationMode === mode ? 'bg-emerald-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-200'}`}>{mode}</button>
                    ))}
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    {Object.values(TreeType).map(t => (
                      <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-4 rounded-2xl border-2 text-xs font-black flex flex-col items-center gap-2 transition-all ${input.treeType === t ? 'bg-emerald-50 border-emerald-500 text-emerald-900 shadow-md' : 'bg-slate-50 border-slate-100 hover:border-slate-300'}`}>
                        <span className="text-2xl">{TREE_TYPE_ICONS[t]}</span> {t}
                      </button>
                    ))}
                  </div>

                  {isGrass && (
                    <div className="bg-emerald-50/50 p-6 rounded-3xl border-2 border-emerald-100 space-y-6">
                      <div>
                        <h3 className="text-xs font-black text-emerald-800 uppercase mb-4 tracking-widest text-center">Variedad de Césped</h3>
                        <div className="grid grid-cols-2 gap-3">
                          {Object.values(GrassVariety).map(v => (
                            <button key={v} onClick={() => setInput({...input, grassVariety: v})} className={`py-2 px-2 rounded-xl border-2 text-[10px] font-black leading-tight transition-all ${input.grassVariety === v ? 'bg-emerald-600 border-emerald-600 text-white shadow-md' : 'bg-white border-slate-200 text-slate-600'}`}>{v}</button>
                          ))}
                        </div>
                      </div>
                      <div className="pt-4 border-t-2 border-emerald-100">
                        <h3 className="text-xs font-black text-emerald-800 uppercase mb-4 tracking-widest text-center">Tipo de Medida</h3>
                        <div className="grid grid-cols-2 gap-3">
                          {Object.values(GrassMeasureMode).map(mode => (
                            <button key={mode} onClick={() => setInput({...input, grassMode: mode})} className={`py-4 rounded-xl border-2 text-xs font-black flex items-center justify-center gap-2 transition-all ${input.grassMode === mode ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-white border-slate-200 text-slate-600'}`}>
                              <i className={mode === GrassMeasureMode.AREA ? 'fas fa-th-large' : 'fas fa-ruler-horizontal'}></i>
                              {mode === GrassMeasureMode.AREA ? 'Área (m²)' : 'Lineal (m)'}
                            </button>
                          ))}
                        </div>
                      </div>
                    </div>
                  )}

                  <div className="grid grid-cols-2 gap-6">
                    {!isPlanting && (
                      <div>
                        <label className="text-xs font-black text-slate-500 uppercase mb-2 block tracking-wider">Edad (Meses)</label>
                        <input type="number" value={input.treeAge} onChange={e => setInput({...input, treeAge: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-4 bg-slate-50 border-2 rounded-2xl font-black text-lg focus:border-emerald-500 outline-none transition-all" />
                      </div>
                    )}
                    <div className={isPlanting ? 'col-span-2' : ''}>
                      <label className="text-xs font-black text-slate-500 uppercase mb-2 block tracking-wider">
                        Cant. ({unitLabel})
                      </label>
                      <input type="number" value={input.numTrees} onChange={e => setInput({...input, numTrees: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-4 bg-slate-50 border-2 rounded-2xl font-black text-lg focus:border-emerald-500 outline-none transition-all" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-white p-8 rounded-[2.5rem] shadow-md border border-slate-200">
                <h2 className="text-xl font-black mb-6 flex items-center gap-3 text-slate-800"><i className="fas fa-leaf text-emerald-600"></i> Insumos Disponibles</h2>
                <div className="max-h-[500px] overflow-y-auto pr-3 custom-scrollbar">
                  {renderProductSelector("Foliares", PRODUCT_CATEGORIES.LIQUIDS)}
                  {renderProductSelector("Radiculares", PRODUCT_CATEGORIES.SOLIDS)}
                </div>
                <button onClick={async () => { setLoading(true); const a = await getAgriculturalAdvice(input); setAiAdvice(a); setLoading(false); }} className="w-full mt-10 py-6 bg-emerald-600 text-white font-black rounded-[2.5rem] shadow-2xl hover:bg-emerald-700 transition-all flex flex-col items-center justify-center border-2 border-emerald-500/30">
                  {loading ? <i className="fas fa-spinner animate-spin text-2xl"></i> : <span className="text-base uppercase tracking-widest">Calcular Nutrición Profesional</span>}
                </button>
              </div>
            </aside>

            <section className="lg:col-span-8 space-y-10">
              {result && result.products.length > 0 && (
                <div className="space-y-12 animate-in fade-in slide-in-from-bottom duration-500">
                  {/* Sección: Analítica de Nutrientes */}
                  <div className="bg-white rounded-[4rem] shadow-2xl border-4 border-emerald-50 p-12">
                    <div className="flex items-center gap-6 mb-12">
                      <div className="h-16 w-16 bg-emerald-600 rounded-2xl flex items-center justify-center text-white text-3xl shadow-lg border-2 border-emerald-400/30">
                        <i className="fas fa-chart-pie"></i>
                      </div>
                      <div>
                        <h3 className="text-4xl font-black tracking-tighter text-slate-900">Análisis de Nutrientes</h3>
                        <p className="text-lg font-bold text-emerald-600 uppercase tracking-widest">Distribución de N-P-K y Materia Orgánica</p>
                      </div>
                    </div>

                    <div className="grid lg:grid-cols-2 gap-12">
                      <div className="bg-slate-50 p-8 rounded-[3rem] border-2 border-slate-100 h-[450px]">
                        <h4 className="text-sm font-black text-slate-400 uppercase mb-6 tracking-widest text-center">Perfil Nutricional del Plan</h4>
                        <ResponsiveContainer width="100%" height="100%">
                          <RadarChart cx="50%" cy="50%" outerRadius="80%" data={detailedNutrientData.radar}>
                            <PolarGrid stroke="#e2e8f0" />
                            <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontWeight: 800, fontSize: 18 }} />
                            <Radar name="Nutrientes" dataKey="A" stroke="#10b981" fill="#10b981" fillOpacity={0.6} />
                            <Tooltip contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
                          </RadarChart>
                        </ResponsiveContainer>
                      </div>

                      <div className="bg-slate-50 p-8 rounded-[3rem] border-2 border-slate-100 h-[450px]">
                        <h4 className="text-sm font-black text-slate-400 uppercase mb-6 tracking-widest text-center">Distribución por Insumo</h4>
                        <ResponsiveContainer width="100%" height="100%">
                          <BarChart data={detailedNutrientData.stacked} layout="vertical" margin={{ top: 20, right: 30, left: 40, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#e2e8f0" />
                            <XAxis type="number" hide />
                            <YAxis dataKey="name" type="category" tick={{ fill: '#1e293b', fontWeight: 800, fontSize: 12 }} width={100} />
                            <Tooltip contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
                            <Legend wrapperStyle={{ paddingTop: '20px' }} />
                            {result.products.map((prod, idx) => (
                              <Bar key={prod.product} dataKey={prod.product} stackId="a" fill={detailedNutrientData.colors[idx % detailedNutrientData.colors.length]} radius={idx === result.products.length - 1 ? [0, 4, 4, 0] : [0, 0, 0, 0]} />
                            ))}
                          </BarChart>
                        </ResponsiveContainer>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mt-12">
                      {detailedNutrientData.radar.map((nut, idx) => (
