import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, PlantingFormulaRecommendation, OrganicProduct, VisionReport } from "../types.ts";

// Agricultural advice service using Gemini 3
export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const productList = input.selectedProducts.map(p => `${p} (Unidad: ${input.selectedUnits[p] || 'unidad'})`).join(", ");
    const isGrass = input.treeType === 'Césped';
    const specificType = isGrass ? `Césped variedad ${input.grassVariety}` : input.treeType;
    const measureUnit = isGrass ? input.grassMode : 'planta/árbol';
    const isPlanting = input.applicationMode === 'Siembra / Instalación';

    const textPrompt = `Actúa como Ingeniero Agrónomo Senior experto en nutrición vegetal orgánica. 
    Analiza este escenario de ${isPlanting ? 'SIEMBRA' : 'MANTENIMIENTO'}:
    - Cultivo: ${specificType} (${isPlanting ? 'ETAPA DE INICIO/ESTABLECIMIENTO' : 'Edad actual: ' + input.treeAge + ' meses'})
    - Cantidad Total: ${input.numTrees} ${measureUnit}
    - Clima: ${input.climate}
    - Tipo de Suelo: ${input.soilType}
    - Insumos disponibles: [${productList}]

    INSTRUCCIÓN CRÍTICA DE DOSIFICACIÓN:
    Toma en cuenta que el usuario seleccionó unidades específicas para cada producto. 
    Genera un plan de aplicación foliar y radicular indicando la DOSIS EXACTA en las unidades que el usuario dispone.

    Genera una respuesta estrictamente en JSON con:
    1. soilAnalysis: Contexto técnico del suelo ${input.soilType}.
    2. visualDiagnosis: Resumen agronómico del estado.
    3. radicularPlan: Lista de pasos para aplicación al suelo (item, dosage, purpose).
    4. foliarPlan: Lista de pasos para aplicación foliar (item, dosage, purpose).
    5. elementalFormulation: 5 elementos minerales clave (element, relevance, priority, requirementLevel).
    6. waterRequirement: Plan de riego (volume, frequency, technique).
    7. tips, seasonalAdvice, sustainabilityScore.`;

    let parts: any[] = [{ text: textPrompt }];
    if (input.healthPhoto) {
      parts.push({ inlineData: { mimeType: 'image/jpeg', data: input.healthPhoto.split(',')[1] } });
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            visualDiagnosis: { type: Type.STRING },
            waterRequirement: {
              type: Type.OBJECT,
              properties: {
                volume: { type: Type.STRING },
                frequency: { type: Type.STRING },
                technique: { type: Type.STRING }
              },
              required: ["volume", "frequency", "technique"]
            },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING },
                  requirementLevel: { type: Type.NUMBER }
                },
                required: ["element", "relevance", "priority", "requirementLevel"]
              }
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "elementalFormulation", "waterRequirement"],
        },
      },
    });

    const result = response.text ? JSON.parse(response.text.trim()) : null;
    return result;
  } catch (error) {
    console.error("Gemini Advice Error:", error);
    throw error;
  }
};

