export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, PlantingFormulaRecommendation, GrassMeasureMode, HistoryItem, GrassVariety, ClimateType, VisionReport, ApplicationMode } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell,
  CartesianGrid, Legend
} from 'recharts';

interface CustomProductDef {
  name: string;
  category: 'LIQUIDS' | 'SOLIDS';
  N: number;
  P: number;
  K: number;
  OM: number;
  baseRate: number;
  unit: UnitType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'vision' | 'history'>('calculator');
  const [customProducts, setCustomProducts] = useState<CustomProductDef[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newProd, setNewProd] = useState<CustomProductDef>({
    name: '', category: 'SOLIDS', N: 0, P: 0, K: 0, OM: 0, baseRate: 1, unit: 'kg'
  });

  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    applicationMode: ApplicationMode.MAINTENANCE,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const resultsRef = useRef<HTMLDivElement>(null);
  const aiSectionRef = useRef<HTMLDivElement>(null);
  const visionFileInputRef = useRef<HTMLInputElement>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const isPlanting = input.applicationMode === ApplicationMode.PLANTING;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history_v3');
    const savedCustom = localStorage.getItem('agro_custom_products');
    if (saved) {
      try { setHistory(JSON.parse(saved)); } catch (e) { console.error(e); }
    }
    if (savedCustom) {
      try { setCustomProducts(JSON.parse(savedCustom)); } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history_v3', JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    localStorage.setItem('agro_custom_products', JSON.stringify(customProducts));
  }, [customProducts]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;
    if (input.climate === ClimateType.RAINY) modifier *= 1.1; 

    if (isPlanting) modifier *= 2.0;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      // Find if it's a custom product
      const custom = customProducts.find(cp => cp.name === p);
      const baseAmount = custom ? custom.baseRate : (BASE_RATES[p as OrganicProduct] || 0);
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || (custom ? custom.unit : PRODUCT_UNITS[p as OrganicProduct]) || 'g';
      const costPer = amount * (input.productPrices[p] || 0);

      return {
        product: p as OrganicProduct,
        amount: parseFloat(amount.toFixed(2)),
        unit: unit as UnitType,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass, isPlanting, customProducts]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const detailedNutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return { radar: [], stacked: [] };
    const colors = ['#10b981', '#3b82f6', '#f59e0b', '#8b5cf6', '#ef4444', '#ec4899', '#06b6d4'];
    let nTotal=0, pTotal=0, kTotal=0, omTotal=0;

    const stacked = [
      { name: 'N', key: 'N' },
      { name: 'P', key: 'P' },
      { name: 'K', key: 'K' },
      { name: 'MO', key: 'OM' }
    ].map(nutType => {
      const data: any = { name: nutType.name };
      result.products.forEach((prod) => {
        const custom = customProducts.find(cp => cp.name === prod.product);
        const nutConfig = custom ? { N: custom.N, P: custom.P, K: custom.K, OM: custom.OM } : (PRODUCT_NUTRIENTS[prod.product as OrganicProduct] || { N:0, P:0, K:0, OM:0 });

        const weightFactor = ['g','ml','cc'].includes(prod.unit) ? 0.001 : 1;
        const val = ((nutConfig[nutType.key as keyof typeof nutConfig] / 100) * prod.amount * weightFactor);
        data[prod.product] = parseFloat(val.toFixed(3));
        if(nutType.key === 'N') nTotal += val;
        if(nutType.key === 'P') pTotal += val;
        if(nutType.key === 'K') kTotal += val;
        if(nutType.key === 'OM') omTotal += val;
      });
      return data;
    });

    const radar = [
      { subject: 'N', A: nTotal }, { subject: 'P', A: pTotal },
      { subject: 'K', A: kTotal }, { subject: 'MO', A: omTotal }
    ];
    return { radar, stacked, colors };
  }, [result, customProducts]);

  const handleFetchProfessionalAdvice = async () => {
    if (input.selectedProducts.length === 0) {
      alert("Por favor seleccione al menos un insumo.");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const advice = await getAgriculturalAdvice(input);
      if (advice) {
        setAiAdvice(advice);
        setTimeout(() => {
          aiSectionRef.current?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      } else {
        setError("La IA no pudo generar un plan. Intente de nuevo.");
      }
    } catch (err) {
      setError("Error de conexión con el servicio agronómico. Verifique su API Key.");
    } finally {
      setLoading(false);
    }
  };

  const handleAddCustomProduct = () => {
    if (!newProd.name) return;
    setCustomProducts([...customProducts, newProd]);
    setNewProd({ name: '', category: 'SOLIDS', N: 0, P: 0, K: 0, OM: 0, baseRate: 1, unit: 'kg' });
    setShowAddModal(false);
  };

  const handleVisionDiagnosis = async (image: string) => {
    setLoading(true);
    const report = await getIndependentVisionDiagnosis(image, input.treeType);
    setVisionReport(report);
    setLoading(false);
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'calculator' | 'vision') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const image = reader.result as string;
        if (type === 'calculator') setInput(prev => ({ ...prev, healthPhoto: image }));
        else handleVisionDiagnosis(image);
      };
      reader.readAsDataURL(file);
    }
  };

  const renderProductSelector = (title: string, items: (OrganicProduct | string)[], category: 'LIQUIDS' | 'SOLIDS') => {
    const customItems = customProducts.filter(cp => cp.category === category).map(cp => cp.name);
    const combinedItems = [...items, ...customItems];

    return (
      <div className="mb-8">
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-4 tracking-wider">{title}</h3>
        <div className="space-y-4">
          {combinedItems.map(p => {
            const selected = input.selectedProducts.includes(p as OrganicProduct);
            const custom = customProducts.find(cp => cp.name === p);
            const defaultUnit = custom ? custom.unit : PRODUCT_UNITS[p as OrganicProduct];
            const currentUnit = input.selectedUnits[p] || defaultUnit;
            const baseRate = custom ? custom.baseRate : BASE_RATES[p as OrganicProduct];

            return (
              <div key={p} className={`p-4 rounded-2xl border transition-all ${selected ? 'bg-emerald-50 border-emerald-300 shadow-md' : 'bg-slate-50 border-slate-200 opacity-70'}`}>
                <div className="flex items-center justify-between">
                  <label className="flex items-center gap-4 cursor-pointer w-full">
                    <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p as OrganicProduct] }))} className="accent-emerald-600 h-5 w-5" />
                    <div className="flex flex-col">
                      <div className="flex items-center gap-2">
                        <span className="text-base font-bold text-slate-800">{p}</span>
                        {custom && <span className="bg-indigo-100 text-indigo-600 text-[10px] font-black px-2 py-0.5 rounded-md uppercase">Propio</span>}
                      </div>
                      <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Base Sugerida: {baseRate} {defaultUnit}</span>
                    </div>
                  </label>
                  {custom && (
                    <button onClick={() => setCustomProducts(customProducts.filter(cp => cp.name !== p))} className="text-slate-400 hover:text-rose-500 transition-colors p-2">
                      <i className="fas fa-trash-alt"></i>
                    </button>
                  )}
                </div>
                {selected && (
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mt-4 pl-9">
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Dosis</label>
                      <input type="number" value={input.manualAmounts[p] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="w-full p-2 text-sm border-2 rounded-xl bg-white focus:border-emerald-500 outline-none font-bold" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Unidad</label>
                      <select value={currentUnit} onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})} className="w-full p-2 text-sm border-2 rounded-xl bg-white focus:border-emerald-500 outline-none font-bold cursor-pointer">
                        <option value="g">g</option><option value="kg">kg</option>
                        <option value="ml">ml</option><option value="cc">cc</option>
                        <option value="L">L</option>
                      </select>
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Precio/{currentUnit}</label>
                      <input type="number" value={input.productPrices[p] || ''} onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} className="w-full p-2 text-sm border-2 rounded-xl bg-white focus:border-emerald-500 outline-none font-bold" />
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
