            <button onClick={() => setActiveTab('vision')} className={`px-8 py-3 rounded-[1.5rem] text-sm font-black transition-all ${activeTab === 'vision' ? 'bg-indigo-500 text-white shadow-lg' : 'text-emerald-100 hover:bg-white/5'}`}>IA Vision</button>
            <button onClick={() => setActiveTab('history')} className={`px-8 py-3 rounded-[1.5rem] text-sm font-black transition-all ${activeTab === 'history' ? 'bg-emerald-500 text-white shadow-lg' : 'text-emerald-100 hover:bg-white/5'}`}>Historial</button>
          </nav>
