              <div className="bg-white p-8 rounded-[2.5rem] shadow-md border border-slate-200">
                <h2 className="text-xl font-black mb-8 flex items-center gap-3 text-slate-800"><i className="fas fa-sliders-h text-emerald-600"></i> Parámetros</h2>
                <div className="space-y-6">
                  <div className="p-1.5 bg-slate-100 rounded-2xl flex gap-2 border border-slate-200">
                    {Object.values(ApplicationMode).map(mode => (
                      <button key={mode} onClick={() => setInput({...input, applicationMode: mode})} className={`flex-1 py-3 px-2 rounded-xl text-[10px] font-black uppercase transition-all ${input.applicationMode === mode ? 'bg-emerald-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-200'}`}>{mode}</button>
                    ))}
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    {Object.values(TreeType).map(t => (
                      <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-4 rounded-2xl border-2 text-xs font-black flex flex-col items-center gap-2 transition-all ${input.treeType === t ? 'bg-emerald-50 border-emerald-500 text-emerald-900 shadow-md' : 'bg-slate-50 border-slate-100 hover:border-slate-300'}`}>
                        <span className="text-2xl">{TREE_TYPE_ICONS[t]}</span> {t}
                      </button>
                    ))}
                  </div>

                  <div className="grid grid-cols-2 gap-6">
                    {!isPlanting && (
                      <div>
                        <label className="text-xs font-black text-slate-500 uppercase mb-2 block tracking-wider">Edad (Meses)</label>
                        <input type="number" value={input.treeAge} onChange={e => setInput({...input, treeAge: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-4 bg-slate-50 border-2 rounded-2xl font-black text-lg focus:border-emerald-500 outline-none" />
                      </div>
                    )}
                    <div className={isPlanting ? 'col-span-2' : ''}>
                      <label className="text-xs font-black text-slate-500 uppercase mb-2 block tracking-wider">Cantidad ({unitLabel})</label>
                      <input type="number" value={input.numTrees} onChange={e => setInput({...input, numTrees: Math.max(1, parseInt(e.target.value) || 1)})} className="w-full p-4 bg-slate-50 border-2 rounded-2xl font-black text-lg focus:border-emerald-500 outline-none" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-white p-8 rounded-[2.5rem] shadow-md border border-slate-200">
                <div className="flex justify-between items-center mb-6">
                  <h2 className="text-xl font-black flex items-center gap-3 text-slate-800"><i className="fas fa-leaf text-emerald-600"></i> Insumos Disponibles</h2>
                  <button onClick={() => setShowAddModal(true)} className="h-10 w-10 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-100 transition-colors shadow-sm flex items-center justify-center border border-indigo-200" title="Agregar Insumo Propio">
                    <i className="fas fa-plus"></i>
