                <div className="max-h-[550px] overflow-y-auto pr-3 custom-scrollbar">
                  {renderProductSelector("Nutrición Foliar / Líquida", PRODUCT_CATEGORIES.LIQUIDS, 'LIQUIDS')}
                  {renderProductSelector("Nutrición Radicular / Sólida", PRODUCT_CATEGORIES.SOLIDS, 'SOLIDS')}
                </div>

                {error && (
                  <div className="mt-6 p-4 bg-rose-50 border-2 border-rose-100 rounded-2xl text-rose-600 text-sm font-bold flex items-center gap-3 animate-pulse">
                    <i className="fas fa-exclamation-triangle"></i>
                    {error}
