                <button onClick={handleFetchProfessionalAdvice} disabled={loading} className="w-full mt-10 py-6 bg-emerald-600 text-white font-black rounded-[2rem] shadow-2xl hover:bg-emerald-700 transition-all flex flex-col items-center justify-center border-2 border-emerald-500/30 disabled:opacity-50">
                  {loading ? (
                    <div className="flex items-center gap-3">
                      <i className="fas fa-spinner animate-spin text-2xl"></i>
                      <span className="text-base uppercase tracking-widest">Generando Protocolo...</span>
                    </div>
                  ) : (
                    <span className="text-base uppercase tracking-widest">Calcular Nutrición Profesional</span>
                  )}
                </button>
              </div>
            </aside>

            <section className="lg:col-span-8 space-y-10" ref={resultsRef}>
              {result && result.products.length > 0 ? (
                <div className="space-y-12 animate-in fade-in slide-in-from-bottom duration-500">
                  {/* Analítica Local */}
                  <div className="bg-white rounded-[4rem] shadow-2xl border-4 border-emerald-50 p-12">
                    <div className="flex items-center gap-6 mb-12">
                      <div className="h-16 w-16 bg-emerald-600 rounded-2xl flex items-center justify-center text-white text-3xl shadow-lg border-2 border-emerald-400/30">
