                    <div className="grid lg:grid-cols-2 gap-12">
                      <div className="bg-slate-50 p-8 rounded-[3rem] border-2 border-slate-100 h-[400px]">
                        <h4 className="text-xs font-black text-slate-400 uppercase mb-6 tracking-widest text-center">Perfil de Nutrientes Maestro</h4>
                        <ResponsiveContainer width="100%" height="100%">
                          <RadarChart data={detailedNutrientData.radar}>
                            <PolarGrid stroke="#e2e8f0" />
                            <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontWeight: 800, fontSize: 14 }} />
                            <Radar dataKey="A" stroke="#10b981" fill="#10b981" fillOpacity={0.5} />
                            <Tooltip contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
                          </RadarChart>
