                      </div>

                      <div className="bg-slate-50 p-8 rounded-[3rem] border-2 border-slate-100 h-[400px]">
                        <h4 className="text-xs font-black text-slate-400 uppercase mb-6 tracking-widest text-center">Aporte por Insumo Seleccionado</h4>
                        <ResponsiveContainer width="100%" height="100%">
