import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, VisionReport } from "../types.ts";

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const productList = input.selectedProducts.map(p => {
      const unit = input.selectedUnits[p] || 'unidad';
      return `${p} (Unidad: ${unit})`;
    }).join(", ");

    const isPlanting = input.applicationMode === 'Siembra / Instalación';
    const treeName = input.treeType === 'Césped' ? `Césped ${input.grassVariety}` : input.treeType;

    const textPrompt = `Actúa como un Ingeniero Agrónomo Senior de Clase Mundial.
    CONTEXTO TÉCNICO:
    - Etapa: ${isPlanting ? 'SIEMBRA E INSTALACIÓN (ESTABLECIMIENTO)' : 'MANTENIMIENTO Y PRODUCCIÓN'}
    - Cultivo: ${treeName}
    - Edad: ${input.treeAge} meses
    - Ubicación Lote: ${input.numTrees} ${input.treeType === 'Césped' ? input.grassMode : 'unidades'}
    - Clima actual: ${input.climate}
    - Suelo predominante: ${input.soilType}
    - Portafolio de Insumos: [${productList}]

    OBJETIVO:
    ${isPlanting 
      ? 'Genera un PROTOCOLO DE ESTABLECIMIENTO. Enfócate en la preparación del hoyo/terreno, desinfección orgánica y abonado de fondo (fósforo y materia orgánica).' 
      : 'Genera un PLAN DE MANTENIMIENTO. Enfócate en productividad, vigor foliar y balance N-P-K para la etapa actual.'}

    REQUISITOS DE RESPUESTA:
    - Las dosis deben estar en las UNIDADES seleccionadas por el usuario.
    - El plan radicular debe ser un paso a paso claro.
    - El plan foliar debe complementar la nutrición base.

    Responde estrictamente en JSON siguiendo el esquema definido.`;

    let parts: any[] = [{ text: textPrompt }];
    if (input.healthPhoto) {
      parts.push({ inlineData: { mimeType: 'image/jpeg', data: input.healthPhoto.split(',')[1] } });
    }

    // Using gemini-3-pro-preview for complex reasoning tasks
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            visualDiagnosis: { type: Type.STRING },
            waterRequirement: {
              type: Type.OBJECT,
              properties: {
                volume: { type: Type.STRING },
                frequency: { type: Type.STRING },
                technique: { type: Type.STRING }
              },
              required: ["volume", "frequency", "technique"]
            },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING },
                  requirementLevel: { type: Type.NUMBER }
                },
                required: ["element", "relevance", "priority", "requirementLevel"]
              }
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                },
                required: ["item", "dosage", "purpose"]
              } 
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "elementalFormulation", "waterRequirement"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("Empty response from AI");
    return JSON.parse(text.trim());
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

export const getIndependentVisionDiagnosis = async (imageBase64: string, treeType: string): Promise<VisionReport | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Analiza esta imagen de ${treeType}. Identifica problemas fitosanitarios. Responde en JSON.`;

    // Using gemini-3-pro-preview for high-quality vision diagnosis
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] } }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            plantReading: { type: Type.STRING },
            pestAnalysis: {
              type: Type.OBJECT,
              properties: {
                identifiedPest: { type: Type.STRING },
                scientificName: { type: Type.STRING },
                symptoms: { type: Type.STRING },
                prevention: { type: Type.STRING },
                organicTreatment: { type: Type.STRING },
                controlCycle: { type: Type.STRING },
                severity: { type: Type.STRING },
                lifeCycleInfo: { type: Type.STRING }
              },
              required: ["identifiedPest", "scientificName", "symptoms", "prevention", "organicTreatment", "controlCycle", "severity", "lifeCycleInfo"]
            },
            biologicalRemedy: {
              type: Type.OBJECT,
              properties: {
                ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                preparation: { type: Type.STRING },
                application: { type: Type.STRING }
              },
              required: ["ingredients", "preparation", "application"]
            },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["plantReading", "pestAnalysis", "biologicalRemedy", "recommendations"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty vision response");
    return JSON.parse(text.trim());
  } catch (error) {
    console.error("Vision Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, GrassMeasureMode, HistoryItem, GrassVariety, ClimateType, VisionReport, ApplicationMode } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell,
  CartesianGrid, Legend
} from 'recharts';

interface CustomProductDef {
  name: string;
  category: 'LIQUIDS' | 'SOLIDS';
  N: number;
  P: number;
  K: number;
  OM: number;
  baseRate: number;
  unit: UnitType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'vision' | 'history'>('calculator');
  const [customProducts, setCustomProducts] = useState<CustomProductDef[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newProd, setNewProd] = useState<CustomProductDef>({
    name: '', category: 'SOLIDS', N: 0, P: 0, K: 0, OM: 0, baseRate: 1, unit: 'kg'
  });

  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    applicationMode: ApplicationMode.MAINTENANCE,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const aiSectionRef = useRef<HTMLDivElement>(null);
  const visionFileInputRef = useRef<HTMLInputElement>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const isPlanting = input.applicationMode === ApplicationMode.PLANTING;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history_v3');
    const savedCustom = localStorage.getItem('agro_custom_products');
    if (saved) try { setHistory(JSON.parse(saved)); } catch (e) {}
    if (savedCustom) try { setCustomProducts(JSON.parse(savedCustom)); } catch (e) {}
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history_v3', JSON.stringify(history));
    localStorage.setItem('agro_custom_products', JSON.stringify(customProducts));
  }, [history, customProducts]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;
    if (input.climate === ClimateType.RAINY) modifier *= 1.1; 
    if (isPlanting) modifier *= 2.0;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const custom = customProducts.find(cp => cp.name === p);
      const baseAmount = custom ? custom.baseRate : (BASE_RATES[p as OrganicProduct] || 0);
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || (custom ? custom.unit : PRODUCT_UNITS[p as OrganicProduct]) || 'g';
      const costPer = amount * (input.productPrices[p] || 0);

      return {
        product: p as OrganicProduct,
        amount: parseFloat(amount.toFixed(2)),
        unit: unit as UnitType,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass, isPlanting, customProducts]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const detailedNutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return { radar: [], stacked: [] };
    const colors = ['#10b981', '#3b82f6', '#f59e0b', '#8b5cf6', '#ef4444', '#ec4899', '#06b6d4'];
    let nTotal=0, pTotal=0, kTotal=0, omTotal=0;

    const stacked = [
      { name: 'N', key: 'N' }, { name: 'P', key: 'P' },
      { name: 'K', key: 'K' }, { name: 'MO', key: 'OM' }
    ].map(nutType => {
      const data: any = { name: nutType.name };
      result.products.forEach((prod) => {
        const custom = customProducts.find(cp => cp.name === prod.product);
        const nutConfig = custom ? { N: custom.N, P: custom.P, K: custom.K, OM: custom.OM } : (PRODUCT_NUTRIENTS[prod.product as OrganicProduct] || { N:0, P:0, K:0, OM:0 });
        const weightFactor = ['g','ml','cc'].includes(prod.unit) ? 0.001 : 1;
        const val = ((nutConfig[nutType.key as keyof typeof nutConfig] / 100) * prod.amount * weightFactor);
        data[prod.product] = parseFloat(val.toFixed(3));
        if(nutType.key === 'N') nTotal += val;
        if(nutType.key === 'P') pTotal += val;
        if(nutType.key === 'K') kTotal += val;
        if(nutType.key === 'OM') omTotal += val;
      });
      return data;
    });

    const radar = [
      { subject: 'N', A: nTotal }, { subject: 'P', A: pTotal },
      { subject: 'K', A: kTotal }, { subject: 'MO', A: omTotal }
    ];
    return { radar, stacked, colors };
  }, [result, customProducts]);

  const handleFetchProfessionalAdvice = async () => {
    if (input.selectedProducts.length === 0) {
      alert("Seleccione al menos un insumo.");
      return;
    }
    setLoading(true);
    setError(null);
    setAiAdvice(null);
    try {
      const advice = await getAgriculturalAdvice(input);
      if (advice) {
        setAiAdvice(advice);
        setTimeout(() => aiSectionRef.current?.scrollIntoView({ behavior: 'smooth' }), 300);
      } else {
        setError("La IA no pudo procesar los datos.");
      }
    } catch (err) {
      setError("Error de comunicación. Intente nuevamente en unos segundos.");
    } finally {
      setLoading(false);
    }
  };

  const handleAddCustomProduct = () => {
    if (!newProd.name) return;
    setCustomProducts([...customProducts, newProd]);
    setNewProd({ name: '', category: 'SOLIDS', N: 0, P: 0, K: 0, OM: 0, baseRate: 1, unit: 'kg' });
    setShowAddModal(false);
