  // Fix: Added handlePhotoUpload to process image inputs for both vision and calculator
  const handlePhotoUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>, mode: 'calculator' | 'vision') => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);

    const reader = new FileReader();
