                <div className="flex items-center justify-between">
                  <label className="flex items-center gap-4 cursor-pointer w-full">
                    <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p as OrganicProduct] }))} className="accent-emerald-600 h-6 w-6" />
                    <div className="flex flex-col">
                      <div className="flex items-center gap-2">
                        <span className="text-lg font-black text-slate-900">{p}</span>
                        {custom && <span className="bg-indigo-600 text-white text-[9px] font-black px-2 py-0.5 rounded-full uppercase">Propio</span>}
                      </div>
                      <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Sugerencia: {baseRate} {defaultUnit}</span>
