            <div className="bg-emerald-900 p-10 text-white">
              <h3 className="text-3xl font-black tracking-tight">Nuevo Insumo</h3>
              <p className="text-emerald-400 font-bold uppercase tracking-widest text-xs mt-1">Perfil Técnico Profesional</p>
