                  <input type="text" value={newProd.name} onChange={e => setNewProd({...newProd, name: e.target.value})} className="w-full p-4 bg-slate-50 border-2 rounded-[1.5rem] font-bold outline-none focus:border-emerald-500" placeholder="Ej: Super Compost" />
