  const handlePhotoUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>, mode: 'calculator' | 'vision') => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      if (mode === 'vision') {
        const report = await getIndependentVisionDiagnosis(base64, input.treeType);
        if (report) setVisionReport(report);
        setLoading(false);
      } else {
