                      <select value={currentUnit} onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})} className="w-full p-3 text-base border-2 rounded-2xl font-black bg-white focus:border-[#1b3022] cursor-pointer">
