                <div className="bg-white rounded-[5rem] p-40 text-center border-4 border-dashed border-slate-200 flex flex-col items-center group">
                  <div className="bg-[#f0f4f1] h-56 w-56 rounded-[5rem] flex items-center justify-center mb-16 shadow-inner group-hover:scale-110 transition-transform duration-500">
                    <i className="fas fa-tractor text-8xl text-[#1b3022]"></i>
                  </div>
                  <h3 className="text-6xl font-black text-[#1b3022] tracking-tighter mb-8 leading-none">Precisión Agrícola</h3>
                  <p className="text-slate-500 text-3xl max-w-2xl mx-auto font-medium leading-relaxed opacity-70">Seleccione sus insumos y ejecute el cálculo profesional para visualizar el protocolo técnico.</p>
                </div>
              )}
            </section>
          </div>
        ) : activeTab === 'vision' ? (
          <div className="space-y-12 animate-in fade-in duration-700 text-center">
             <div className="bg-white p-24 rounded-[5rem] shadow-2xl border border-slate-200 max-w-4xl mx-auto">
                <h2 className="text-6xl font-black text-[#1b3022] tracking-tighter mb-10 leading-none">IA Vision</h2>
                <p className="text-3xl text-slate-500 font-medium mb-16">Diagnóstico inmediato de plagas y enfermedades.</p>
                <input type="file" accept="image/*" ref={visionFileInputRef} onChange={(e) => handlePhotoUpload(e, 'vision')} className="hidden" />
                <button onClick={() => visionFileInputRef.current?.click()} className="group bg-[#1b3022] text-white px-24 py-12 rounded-[4rem] text-4xl font-black shadow-2xl transition-all active:scale-95 flex items-center gap-8 mx-auto border-8 border-[#3d2b1f]/20">
                  <i className="fas fa-camera"></i>
                  Analizar Cultivo
                </button>
             </div>
             {visionReport && (
                <div className="text-left max-w-5xl mx-auto space-y-12 animate-in slide-in-from-bottom duration-700">
                   <div className="bg-[#1b3022] text-white p-16 rounded-[4.5rem] shadow-2xl relative overflow-hidden">
                      <h3 className="text-2xl font-black uppercase tracking-[0.4em] mb-10 text-emerald-400">Lectura Profunda</h3>
                      <p className="text-4xl italic leading-tight font-black opacity-90 leading-relaxed text-white">"{visionReport.plantReading}"</p>
                   </div>
                </div>
             )}
          </div>
        ) : null}
      </main>
      <footer className="mt-40 text-center py-12 border-t border-slate-200 opacity-50">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-[#1b3022]">© AgroVision Pro • Tecnología Orgánica para el Campo</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, GrassMeasureMode, HistoryItem, GrassVariety, ClimateType, VisionReport, ApplicationMode } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell,
  CartesianGrid, Legend, PieChart, Pie
} from 'recharts';

interface CustomProductDef {
  name: string;
  category: 'LIQUIDS' | 'SOLIDS';
  N: number;
  P: number;
  K: number;
  OM: number;
  baseRate: number;
  unit: UnitType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'vision' | 'history'>('calculator');
  const [customProducts, setCustomProducts] = useState<CustomProductDef[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newProd, setNewProd] = useState<CustomProductDef>({
    name: '', category: 'SOLIDS', N: 0, P: 0, K: 0, OM: 0, baseRate: 1, unit: 'kg'
  });

  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    applicationMode: ApplicationMode.MAINTENANCE,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const aiSectionRef = useRef<HTMLDivElement>(null);
  const visionFileInputRef = useRef<HTMLInputElement>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const isPlanting = input.applicationMode === ApplicationMode.PLANTING;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  // Colors: Pine Green (#1b3022) and Earth Brown (#3d2b1f)
  const pineGreen = "#1b3022";
  const earthBrown = "#3d2b1f";
  const softGreen = "#f0f4f1";

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history_v3');
    const savedCustom = localStorage.getItem('agro_custom_products');
    if (saved) try { setHistory(JSON.parse(saved)); } catch (e) {}
    if (savedCustom) try { setCustomProducts(JSON.parse(savedCustom)); } catch (e) {}
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history_v3', JSON.stringify(history));
    localStorage.setItem('agro_custom_products', JSON.stringify(customProducts));
  }, [history, customProducts]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;
    if (input.climate === ClimateType.RAINY) modifier *= 1.1; 
    if (isPlanting) modifier *= 2.0;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const custom = customProducts.find(cp => cp.name === p);
      const baseAmount = custom ? custom.baseRate : (BASE_RATES[p as OrganicProduct] || 0);
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || (custom ? custom.unit : PRODUCT_UNITS[p as OrganicProduct]) || 'g';
      const costPer = amount * (input.productPrices[p] || 0);

      return {
        product: p as OrganicProduct,
        amount: parseFloat(amount.toFixed(2)),
        unit: unit as UnitType,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass, isPlanting, customProducts]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const detailedNutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return { radar: [], stacked: [], costPie: [], colors: [] };
    const palette = [pineGreen, earthBrown, '#4a5d23', '#8b4513', '#2e4d32', '#5d4037', '#1b3022', '#6b8e23', '#a0522d'];
    let nTotal=0, pTotal=0, kTotal=0, omTotal=0;

    const stacked = [
      { name: 'N', key: 'N' }, { name: 'P', key: 'P' },
      { name: 'K', key: 'K' }, { name: 'MO', key: 'OM' }
    ].map(nutType => {
      const data: any = { name: nutType.name };
      result.products.forEach((prod) => {
        const custom = customProducts.find(cp => cp.name === prod.product);
        const nutConfig = custom ? { N: custom.N, P: custom.P, K: custom.K, OM: custom.OM } : (PRODUCT_NUTRIENTS[prod.product as OrganicProduct] || { N:0, P:0, K:0, OM:0 });
        const weightFactor = ['g','ml','cc'].includes(prod.unit) ? 0.001 : 1;
        const val = ((nutConfig[nutType.key as keyof typeof nutConfig] / 100) * prod.amount * weightFactor);
        data[prod.product] = parseFloat(val.toFixed(3));
        if(nutType.key === 'N') nTotal += val;
        if(nutType.key === 'P') pTotal += val;
        if(nutType.key === 'K') kTotal += val;
        if(nutType.key === 'OM') omTotal += val;
      });
      return data;
    });

    const radar = [
      { subject: 'N', A: nTotal }, { subject: 'P', A: pTotal },
      { subject: 'K', A: kTotal }, { subject: 'MO', A: omTotal }
    ];

    const costPie = result.products.map(p => ({
      name: p.product,
      value: p.totalCost
    })).filter(p => p.value > 0);

    return { radar, stacked, costPie, colors: palette };
  }, [result, customProducts]);

  const handleFetchProfessionalAdvice = async () => {
    if (input.selectedProducts.length === 0) {
      alert("Seleccione al menos un insumo.");
      return;
    }
    setLoading(true);
    setError(null);
    setAiAdvice(null);
    try {
      const advice = await getAgriculturalAdvice(input);
      if (advice) {
        setAiAdvice(advice);
        setTimeout(() => aiSectionRef.current?.scrollIntoView({ behavior: 'smooth' }), 300);
      } else {
        setError("Error en el motor de IA. Intente con menos insumos.");
      }
    } catch (err) {
      setError("Falla de conexión agrícola. Reintentando...");
    } finally {
      setLoading(false);
    }
  };

  const handleAddCustomProduct = () => {
    if (!newProd.name) return;
    setCustomProducts([...customProducts, newProd]);
    setNewProd({ name: '', category: 'SOLIDS', N: 0, P: 0, K: 0, OM: 0, baseRate: 1, unit: 'kg' });
    setShowAddModal(false);
  };

  const handlePhotoUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>, mode: 'calculator' | 'vision') => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      if (mode === 'vision') {
        const report = await getIndependentVisionDiagnosis(base64, input.treeType);
        if (report) setVisionReport(report);
        setLoading(false);
      } else {
        setInput(prev => ({ ...prev, healthPhoto: base64 }));
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  }, [input.treeType]);

  const renderProductSelector = (title: string, items: (OrganicProduct | string)[], category: 'LIQUIDS' | 'SOLIDS') => {
    const customItems = customProducts.filter(cp => cp.category === category).map(cp => cp.name);
    const combinedItems = [...items, ...customItems];

    return (
      <div className="mb-8">
        <h3 className="text-sm font-black text-slate-500 uppercase mb-4 tracking-widest">{title}</h3>
        <div className="space-y-4">
          {combinedItems.map(p => {
            const selected = input.selectedProducts.includes(p as OrganicProduct);
            const custom = customProducts.find(cp => cp.name === p);
            const defaultUnit = custom ? custom.unit : PRODUCT_UNITS[p as OrganicProduct];
            const currentUnit = input.selectedUnits[p] || defaultUnit;
            const baseRate = custom ? custom.baseRate : BASE_RATES[p as OrganicProduct];

            return (
              <div key={p} className={`p-5 rounded-[2rem] border-2 transition-all ${selected ? 'bg-[#f0f4f1] border-[#1b3022] shadow-xl' : 'bg-slate-50 border-slate-100 opacity-80'}`}>
                <div className="flex items-center justify-between">
                  <label className="flex items-center gap-4 cursor-pointer w-full">
                    <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p as OrganicProduct] }))} className="accent-[#1b3022] h-6 w-6" />
                    <div className="flex flex-col">
                      <div className="flex items-center gap-2">
                        <span className="text-lg font-black text-[#1b3022]">{p}</span>
                        {custom && <span className="bg-[#3d2b1f] text-white text-[9px] font-black px-2 py-0.5 rounded-full uppercase">Propio</span>}
                      </div>
                      <span className="text-[10px] font-black text-[#1b3022] uppercase tracking-widest opacity-60">Sugerencia: {baseRate} {defaultUnit}</span>
                    </div>
                  </label>
                  {custom && (
                    <button onClick={() => setCustomProducts(customProducts.filter(cp => cp.name !== p))} className="text-rose-400 hover:text-rose-600 p-2"><i className="fas fa-trash"></i></button>
                  )}
                </div>
                {selected && (
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-6 pl-10">
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Dosis</label>
                      <input type="number" value={input.manualAmounts[p] ?? ''} onChange={e => setInput({...input, manualAmounts: {...input.manualAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="w-full p-3 text-base border-2 rounded-2xl font-black bg-white focus:border-[#1b3022] outline-none" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Unidad</label>
                      <select value={currentUnit} onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as UnitType}})} className="w-full p-3 text-base border-2 rounded-2xl font-black bg-white focus:border-[#1b3022] cursor-pointer">
                        <option value="g">g</option><option value="kg">kg</option>
                        <option value="ml">ml</option><option value="cc">cc</option>
                        <option value="L">L</option>
                      </select>
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Precio/${currentUnit}</label>
                      <input type="number" value={input.productPrices[p] || ''} onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} className="w-full p-3 text-base border-2 rounded-2xl font-black bg-white focus:border-[#1b3022]" />
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      {/* Modal Agregar Insumo */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white w-full max-w-xl rounded-[4rem] shadow-2xl overflow-hidden border-4 border-white">
            <div className="bg-[#1b3022] p-10 text-white">
              <h3 className="text-3xl font-black">Nuevo Insumo</h3>
              <p className="text-slate-300 font-bold uppercase tracking-widest text-xs mt-1">Definición Técnica</p>
            </div>
            <div className="p-10 space-y-8">
              <div className="grid grid-cols-2 gap-6">
                <div className="col-span-2">
                  <label className="text-xs font-black text-slate-400 uppercase mb-2 block">Nombre</label>
                  <input type="text" value={newProd.name} onChange={e => setNewProd({...newProd, name: e.target.value})} className="w-full p-4 bg-slate-50 border-2 rounded-[1.5rem] font-bold outline-none focus:border-[#1b3022]" placeholder="Ej: Super Compost" />
                </div>
                <div>
                  <label className="text-xs font-black text-slate-400 uppercase mb-2 block">Categoría</label>
                  <select value={newProd.category} onChange={e => setNewProd({...newProd, category: e.target.value as any})} className="w-full p-4 bg-slate-50 border-2 rounded-[1.5rem] font-bold">
                    <option value="SOLIDS">Sólido</option><option value="LIQUIDS">Líquido</option>
                  </select>
                </div>
                <div>
                  <label className="text-xs font-black text-slate-400 uppercase mb-2 block">Unidad Base</label>
                  <select value={newProd.unit} onChange={e => setNewProd({...newProd, unit: e.target.value as UnitType})} className="w-full p-4 bg-slate-50 border-2 rounded-[1.5rem] font-bold">
                    <option value="g">g</option><option value="kg">kg</option>
                    <option value="ml">ml</option><option value="L">L</option>
                  </select>
                </div>
              </div>
              <button onClick={handleAddCustomProduct} className="w-full py-6 bg-[#1b3022] text-white font-black rounded-[2rem] shadow-xl uppercase tracking-widest">Añadir Insumo</button>
              <button onClick={() => setShowAddModal(false)} className="w-full py-3 text-slate-400 font-black uppercase text-xs">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      <header className="bg-[#1b3022] text-white p-8 shadow-2xl sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-6">
            <div className="bg-[#3d2b1f] h-16 w-16 rounded-[1.5rem] shadow-xl flex items-center justify-center border-4 border-white/20">
              <i className="fas fa-leaf text-3xl"></i>
            </div>
            <div>
              <h1 className="text-3xl font-black tracking-tighter leading-none">AgroVision <span className="text-emerald-400">CO</span></h1>
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] mt-1">Nutrición Orgánica de Precisión</p>
            </div>
          </div>
          <nav className="flex bg-white/10 rounded-[2.5rem] p-2 border border-white/10 backdrop-blur-xl">
            {['calculator', 'vision', 'history'].map((tab) => (
              <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-10 py-4 rounded-[2rem] text-sm font-black transition-all ${activeTab === tab ? 'bg-white text-[#1b3022] shadow-lg' : 'text-slate-100 hover:bg-white/5'}`}>
                {tab === 'calculator' ? 'Calculadora' : tab === 'vision' ? 'IA Vision' : 'Historial'}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-12">
        {activeTab === 'calculator' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            <aside className="lg:col-span-4 space-y-8 no-print">
              <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border border-slate-200">
                <h2 className="text-2xl font-black mb-10 flex items-center gap-4 text-[#1b3022]"><i className="fas fa-sliders-h"></i> Parámetros</h2>
                <div className="space-y-8">
                  <div className="bg-slate-100 p-2 rounded-[2rem] flex gap-2 border border-slate-200">
                    {Object.values(ApplicationMode).map(mode => (
                      <button key={mode} onClick={() => setInput({...input, applicationMode: mode})} className={`flex-1 py-4 px-4 rounded-[1.5rem] text-[11px] font-black uppercase transition-all leading-tight ${input.applicationMode === mode ? 'bg-[#3d2b1f] text-white shadow-xl' : 'text-slate-500 hover:bg-slate-200'}`}>
                        {mode.split(' ')[0]}
                      </button>
                    ))}
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    {Object.values(TreeType).map(t => (
                      <button key={t} onClick={() => setInput({...input, treeType: t})} className={`p-5 rounded-[2rem] border-2 text-xs font-black flex flex-col items-center gap-3 transition-all ${input.treeType === t ? 'bg-[#f0f4f1] border-[#1b3022] text-[#1b3022] shadow-xl scale-105' : 'bg-slate-50 border-slate-100 hover:border-slate-300'}`}>
                        <span className="text-3xl">{TREE_TYPE_ICONS[t]}</span> {t}
                      </button>
                    ))}
                  </div>

                  <div className="grid grid-cols-2 gap-8">
                    {!isPlanting && (
                      <div>
                        <label className="text-[11px] font-black text-slate-400 uppercase mb-3 block tracking-widest">Edad (Meses)</label>
                        <input type="number" value={input.treeAge} onChange={e => setInput({...input, treeAge: Math.max(1, parseInt(e.target.value)||1)})} className="w-full p-5 bg-slate-50 border-2 rounded-[2rem] font-black text-2xl focus:border-[#1b3022] outline-none" />
                      </div>
                    )}
                    <div className={isPlanting ? 'col-span-2' : ''}>
                      <label className="text-[11px] font-black text-slate-400 uppercase mb-3 block tracking-widest">Cantidad ({unitLabel})</label>
                      <input type="number" value={input.numTrees} onChange={e => setInput({...input, numTrees: Math.max(1, parseInt(e.target.value)||1)})} className="w-full p-5 bg-slate-50 border-2 rounded-[2rem] font-black text-2xl focus:border-[#1b3022] outline-none" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border border-slate-200">
                <div className="flex justify-between items-center mb-8">
                  <h2 className="text-2xl font-black flex items-center gap-4 text-[#1b3022]"><i className="fas fa-boxes"></i> Insumos</h2>
                  <button onClick={() => setShowAddModal(true)} className="h-12 w-12 bg-slate-50 text-[#1b3022] rounded-[1.2rem] hover:bg-slate-100 border border-slate-200">
                    <i className="fas fa-plus"></i>
                  </button>
                </div>
                <div className="max-h-[600px] overflow-y-auto pr-2 custom-scrollbar space-y-10">
                  {renderProductSelector(isPlanting ? "Insumos de Fondo" : "Nutrición Radicular", PRODUCT_CATEGORIES.SOLIDS, 'SOLIDS')}
                  {renderProductSelector(isPlanting ? "Insumos de Arranque" : "Nutrición Foliar", PRODUCT_CATEGORIES.LIQUIDS, 'LIQUIDS')}
                </div>

                <button onClick={handleFetchProfessionalAdvice} disabled={loading} className="w-full mt-12 py-8 bg-[#1b3022] text-white font-black rounded-[2.5rem] shadow-2xl hover:bg-[#2e4d32] transition-all flex flex-col items-center justify-center border-4 border-white/10 disabled:opacity-50">
                  {loading ? (
                    <div className="flex items-center gap-4">
                      <i className="fas fa-circle-notch animate-spin text-3xl"></i>
                      <span className="text-lg uppercase tracking-widest">Calculando...</span>
                    </div>
                  ) : (
                    <div className="text-center">
                      <span className="text-lg uppercase tracking-widest font-black">CÁLCULO PROFESIONAL IA</span>
                      <p className="text-[10px] opacity-70 mt-1 uppercase font-black">{isPlanting ? 'Establecimiento Maestro' : 'Protocolo Productivo'}</p>
                    </div>
                  )}
                </button>
              </div>
            </aside>

            {/* PANEL DE RESULTADOS DERECHO */}
            <section className="lg:col-span-8 space-y-16">
              {result && result.products.length > 0 ? (
                <div className="space-y-16 animate-in fade-in slide-in-from-bottom duration-700">

                  {/* SECCIÓN BALANCE NPK+MO */}
                  <div className="bg-white rounded-[4.5rem] shadow-2xl border-4 border-[#f0f4f1] p-12 relative overflow-hidden">
                    <div className="flex items-center gap-8 mb-16">
                      <div className="h-20 w-20 bg-[#1b3022] rounded-[2rem] flex items-center justify-center text-white text-4xl shadow-2xl"><i className="fas fa-vial"></i></div>
                      <div>
                        <h3 className="text-5xl font-black tracking-tighter text-[#1b3022]">Balance NPK+MO</h3>
                        <p className="text-xl font-black text-[#3d2b1f] uppercase tracking-widest mt-2">Diagnóstico de Vigor Orgánico</p>
                      </div>
                    </div>

                    <div className="grid lg:grid-cols-2 gap-16 mb-16">
                      <div className="bg-[#f0f4f1] p-10 rounded-[3.5rem] border-2 border-[#1b3022]/10 h-[450px]">
                        <h4 className="text-sm font-black text-[#1b3022] uppercase mb-8 tracking-widest text-center">Espectro de Nutrientes</h4>
                        <ResponsiveContainer width="100%" height="100%">
                          <RadarChart data={detailedNutrientData.radar}>
                            <PolarGrid stroke="#cbd5e1" strokeWidth={2} />
                            <PolarAngleAxis dataKey="subject" tick={{ fill: '#1b3022', fontWeight: 900, fontSize: 18 }} />
                            <Radar dataKey="A" stroke="#1b3022" strokeWidth={4} fill="#1b3022" fillOpacity={0.6} />
                            <Tooltip contentStyle={{ borderRadius: '25px', border: 'none', fontWeight: 800 }} />
                          </RadarChart>
                        </ResponsiveContainer>
                      </div>

                      <div className="grid grid-cols-2 gap-6 h-fit self-center">
                        {detailedNutrientData.radar.map((nut) => (
                          <div key={nut.subject} className="bg-white p-8 rounded-[2.5rem] border-2 border-slate-100 shadow-sm hover:border-[#1b3022] transition-all text-center">
                            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-3">{nut.subject}</p>
                            <span className="text-4xl font-black text-[#1b3022]">{nut.A.toFixed(2)}</span>
                            <p className="text-[10px] font-bold text-slate-400 mt-2">Kg Totales</p>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>

                  {/* SECCIÓN DISTRIBUCIÓN COSTOS */}
                  <div className="bg-white rounded-[4.5rem] shadow-2xl border-4 border-[#f0f4f1] p-12 relative overflow-hidden">
                    <div className="flex items-center gap-8 mb-16">
                      <div className="h-20 w-20 bg-[#3d2b1f] rounded-[2rem] flex items-center justify-center text-white text-4xl shadow-2xl"><i className="fas fa-coins"></i></div>
                      <div>
                        <h3 className="text-5xl font-black tracking-tighter text-[#3d2b1f]">Distribución de Costos</h3>
                        <p className="text-xl font-black text-[#1b3022] uppercase tracking-widest mt-2">Optimización Presupuestal</p>
                      </div>
                    </div>

                    <div className="grid lg:grid-cols-2 gap-16 items-center">
                      <div className="bg-slate-50 p-10 rounded-[3.5rem] border-2 border-[#3d2b1f]/10 h-[450px] relative">
                        <ResponsiveContainer width="100%" height="100%">
                          <PieChart>
                            <Pie
                              data={detailedNutrientData.costPie}
                              cx="50%"
                              cy="50%"
                              innerRadius={80}
                              outerRadius={140}
                              paddingAngle={5}
                              dataKey="value"
                            >
                              {detailedNutrientData.costPie.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={detailedNutrientData.colors[index % detailedNutrientData.colors.length]} />
                              ))}
                            </Pie>
                            <Tooltip formatter={(value: number) => `$${value.toLocaleString()}`} contentStyle={{ borderRadius: '20px', border: 'none' }} />
                          </PieChart>
                        </ResponsiveContainer>
                        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                          <span className="text-xs font-black text-slate-400 uppercase">Total</span>
                          <span className="text-2xl font-black text-[#3d2b1f]">${result.totalProjectCost.toLocaleString()}</span>
                        </div>
                      </div>

                      <div className="space-y-4">
                        <h4 className="text-sm font-black text-slate-400 uppercase mb-6 tracking-widest">Detalle por Producto</h4>
                        <div className="space-y-3 max-h-[350px] overflow-y-auto pr-4 custom-scrollbar">
                          {result.products.map((p, idx) => (
                            <div key={p.product} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 hover:border-[#3d2b1f]/30 transition-all">
                              <div className="flex items-center gap-3">
                                <div className="h-3 w-3 rounded-full" style={{ backgroundColor: detailedNutrientData.colors[idx % detailedNutrientData.colors.length] }}></div>
                                <span className="font-bold text-[#1b3022] text-sm">{p.product}</span>
                              </div>
                              <span className="font-black text-[#3d2b1f] text-sm">${p.totalCost.toLocaleString()}</span>
                            </div>
                          ))}
                        </div>
                        <div className="pt-6 border-t-2 border-slate-100 flex justify-between items-center">
                          <span className="text-lg font-black text-[#1b3022]">Inversión Total</span>
                          <span className="text-2xl font-black text-[#3d2b1f]">${result.totalProjectCost.toLocaleString()} COP</span>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* PROTOCOLO PROFESIONAL IA */}
                  <div ref={aiSectionRef}>
                    {aiAdvice ? (
                      <div className="space-y-16 animate-in fade-in slide-in-from-bottom duration-1000">
                        <div className={`p-12 rounded-[4.5rem] shadow-2xl flex items-center gap-10 border-8 transition-all ${isPlanting ? 'bg-[#3d2b1f] border-[#1b3022] text-white' : 'bg-[#1b3022] border-[#3d2b1f] text-white'}`}>
                          <div className={`h-24 w-24 rounded-[2.5rem] flex items-center justify-center text-5xl shadow-2xl ${isPlanting ? 'bg-[#5d4037]' : 'bg-[#2e4d32]'}`}>
                            <i className={isPlanting ? 'fas fa-seedling' : 'fas fa-award'}></i>
                          </div>
                          <div>
                            <h3 className="text-5xl font-black tracking-tighter leading-none text-white">
                              {isPlanting ? 'Plan de Establecimiento' : 'Protocolo Maestro'}
                            </h3>
                            <p className="text-xl font-bold opacity-80 mt-2 uppercase tracking-widest text-white">Lote de {input.numTrees} {unitLabel}</p>
                          </div>
                        </div>

                        {/* PLAN RADICULAR */}
                        <div className="bg-white rounded-[4.5rem] shadow-2xl border-4 border-[#f0f4f1] overflow-hidden">
                          <div className="bg-[#3d2b1f] p-12 text-white flex items-center gap-8">
                            <div className="h-16 w-16 bg-white/20 rounded-[1.5rem] flex items-center justify-center border-2 border-white/30 text-3xl"><i className="fas fa-fill-drip"></i></div>
                            <div>
                              <h3 className="text-4xl font-black tracking-tighter text-white">Preparación de Suelo y Radicular</h3>
                              <p className="text-sm font-bold opacity-80 uppercase tracking-widest mt-1 text-white">{isPlanting ? 'Protocolo de Fondo' : 'Mantenimiento de Raíz'}</p>
                            </div>
                          </div>
                          <div className="p-12 space-y-10">
                            {aiAdvice.radicularPlan.map((step, idx) => (
                              <div key={idx} className="flex gap-8 items-start group border-b border-slate-100 pb-10 last:border-0">
                                <div className="h-14 w-14 bg-[#3d2b1f] rounded-2xl flex items-center justify-center font-black text-2xl text-white shadow-sm">{idx + 1}</div>
                                <div className="flex-1">
                                  <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-4">
                                    <h5 className="text-3xl font-black text-[#1b3022] tracking-tight">{step.item}</h5>
                                    <span className="px-8 py-3 bg-[#f0f4f1] text-[#1b3022] rounded-[2rem] font-black text-xl border-2 border-[#1b3022]/20">Dosis: {step.dosage}</span>
                                  </div>
                                  <p className="text-xl text-slate-600 font-medium leading-relaxed">Objetivo: <span className="text-slate-800 font-black">{step.purpose}</span></p>
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>

                        {/* PLAN FOLIAR */}
                        <div className="bg-white rounded-[4.5rem] shadow-2xl border-4 border-[#f0f4f1] overflow-hidden">
                          <div className="bg-[#1b3022] p-12 text-white flex items-center gap-8">
                            <div className="h-16 w-16 bg-white/20 rounded-[1.5rem] flex items-center justify-center border-2 border-white/30 text-3xl"><i className="fas fa-spray-can"></i></div>
                            <div>
                              <h3 className="text-4xl font-black tracking-tighter text-white">Refuerzo Foliar (Maestro)</h3>
                              <p className="text-sm font-bold opacity-80 uppercase tracking-widest mt-1 text-white">Vigor y Sanidad Orgánica</p>
                            </div>
                          </div>
                          <div className="p-12 space-y-10">
                            {aiAdvice.foliarPlan.map((step, idx) => (
                              <div key={idx} className="flex gap-8 items-start group border-b border-slate-100 pb-10 last:border-0">
                                <div className="h-14 w-14 bg-[#1b3022] rounded-2xl flex items-center justify-center font-black text-2xl text-white shadow-sm">{idx + 1}</div>
                                <div className="flex-1">
                                  <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-4">
                                    <h5 className="text-3xl font-black text-[#1b3022] tracking-tight">{step.item}</h5>
                                    <span className="px-8 py-3 bg-[#f0f4f1] text-[#1b3022] rounded-[2rem] font-black text-xl border-2 border-[#1b3022]/20">Dosis: {step.dosage}</span>
                                  </div>
                                  <p className="text-xl text-slate-600 font-medium leading-relaxed">Objetivo: <span className="text-slate-800 font-black">{step.purpose}</span></p>
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      </div>
                    ) : (
                      loading && (
                        <div className="bg-white p-32 rounded-[5rem] shadow-2xl border-4 border-dashed border-[#1b3022] flex flex-col items-center justify-center text-center">
                          <i className="fas fa-circle-notch animate-spin text-8xl text-[#1b3022] mb-12"></i>
                          <h3 className="text-4xl font-black text-[#1b3022] mb-6 tracking-tight uppercase">Sincronizando con Ingeniero IA...</h3>
                          <p className="text-2xl text-slate-500 font-medium max-w-lg mx-auto">Preparando balance nutricional para {isPlanting ? 'Siembra' : 'Mantenimiento'}.</p>
                        </div>
                      )
                    )}
                  </div>
                </div>
              ) : (
                <div className="bg-white rounded-[5rem] p-40 text-center border-4 border-dashed border-slate-200 flex flex-col items-center group">
                  <div className="bg-[#f0f4f1] h-56 w-56 rounded-[5rem] flex items-center justify-center mb-16 shadow-inner group-hover:scale-110 transition-transform duration-500">
                    <i className="fas fa-tractor text-8xl text-[#1b3022]"></i>
                  </div>
                  <h3 className="text-6xl font-black text-[#1b3022] tracking-tighter mb-8 leading-none">Precisión Agrícola</h3>
                  <p className="text-slate-500 text-3xl max-w-2xl mx-auto font-medium leading-relaxed opacity-70">Seleccione sus insumos y ejecute el cálculo profesional para visualizar el protocolo técnico.</p>
                </div>
              )}
            </section>
          </div>
        ) : activeTab === 'vision' ? (
          <div className="space-y-12 animate-in fade-in duration-700 text-center">
             <div className="bg-white p-24 rounded-[5rem] shadow-2xl border border-slate-200 max-w-4xl mx-auto">
                <h2 className="text-6xl font-black text-[#1b3022] tracking-tighter mb-10 leading-none">IA Vision</h2>
                <p className="text-3xl text-slate-500 font-medium mb-16">Diagnóstico inmediato de plagas y enfermedades.</p>
                <input type="file" accept="image/*" ref={visionFileInputRef} onChange={(e) => handlePhotoUpload(e, 'vision')} className="hidden" />
                <button onClick={() => visionFileInputRef.current?.click()} className="group bg-[#1b3022] text-white px-24 py-12 rounded-[4rem] text-4xl font-black shadow-2xl transition-all active:scale-95 flex items-center gap-8 mx-auto border-8 border-[#3d2b1f]/20">
                  <i className="fas fa-camera"></i>
                  Analizar Cultivo
                </button>
             </div>
             {visionReport && (
                <div className="text-left max-w-5xl mx-auto space-y-12 animate-in slide-in-from-bottom duration-700">
                   <div className="bg-[#1b3022] text-white p-16 rounded-[4.5rem] shadow-2xl relative overflow-hidden">
                      <h3 className="text-2xl font-black uppercase tracking-[0.4em] mb-10 text-emerald-400">Lectura Profunda</h3>
                      <p className="text-4xl italic leading-tight font-black opacity-90 leading-relaxed text-white">"{visionReport.plantReading}"</p>
                   </div>
                </div>
             )}
          </div>
        ) : null}
      </main>
      <footer className="mt-40 text-center py-12 border-t border-slate-200 opacity-50">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-[#1b3022]">© AgroVision Pro • Tecnología Orgánica para el Campo</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, GrassMeasureMode, HistoryItem, GrassVariety, ClimateType, VisionReport, ApplicationMode } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES, PRODUCT_NUTRIENTS } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { 
  Radar, RadarChart, PolarGrid, PolarAngleAxis, 
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Cell,
  CartesianGrid, Legend, PieChart, Pie
} from 'recharts';

interface CustomProductDef {
  name: string;
  category: 'LIQUIDS' | 'SOLIDS';
  N: number;
  P: number;
  K: number;
  OM: number;
  baseRate: number;
  unit: UnitType;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'vision' | 'history'>('calculator');
  const [customProducts, setCustomProducts] = useState<CustomProductDef[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newProd, setNewProd] = useState<CustomProductDef>({
    name: '', category: 'SOLIDS', N: 0, P: 0, K: 0, OM: 0, baseRate: 1, unit: 'kg'
  });

  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    applicationMode: ApplicationMode.MAINTENANCE,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: 0 }), {}),
    manualAmounts: {},
    selectedUnits: Object.values(OrganicProduct).reduce((acc, curr) => ({ ...acc, [curr]: PRODUCT_UNITS[curr] }), {}),
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const aiSectionRef = useRef<HTMLDivElement>(null);
  const visionFileInputRef = useRef<HTMLInputElement>(null);

  const isGrass = input.treeType === TreeType.GRASS;
  const isPlanting = input.applicationMode === ApplicationMode.PLANTING;
  const unitLabel = isGrass ? input.grassMode : 'planta';

  // Colors: Pine Green (#1b3022) and Earth Brown (#3d2b1f)
  const pineGreen = "#1b3022";
  const earthBrown = "#3d2b1f";
  const softGreen = "#f0f4f1";

  useEffect(() => {
    const saved = localStorage.getItem('agro_pro_history_v3');
    const savedCustom = localStorage.getItem('agro_custom_products');
    if (saved) try { setHistory(JSON.parse(saved)); } catch (e) {}
    if (savedCustom) try { setCustomProducts(JSON.parse(savedCustom)); } catch (e) {}
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_pro_history_v3', JSON.stringify(history));
    localStorage.setItem('agro_custom_products', JSON.stringify(customProducts));
  }, [history, customProducts]);

  const calculateDose = useCallback(() => {
    let modifier = (input.healthStatus === 'regular' ? 1.25 : input.healthStatus === 'deficiente' ? 1.5 : 1.0);
    if (input.soilType === SoilType.SANDY) modifier *= 1.15;
    if (input.soilType === SoilType.CLAYEY) modifier *= 0.9;
    if (input.climate === ClimateType.RAINY) modifier *= 1.1; 
    if (isPlanting) modifier *= 2.0;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const custom = customProducts.find(cp => cp.name === p);
      const baseAmount = custom ? custom.baseRate : (BASE_RATES[p as OrganicProduct] || 0);
      const amount = input.manualAmounts[p] ?? (input.treeAge * baseAmount * modifier);
      const unit = input.selectedUnits[p] || (custom ? custom.unit : PRODUCT_UNITS[p as OrganicProduct]) || 'g';
      const costPer = amount * (input.productPrices[p] || 0);

      return {
        product: p as OrganicProduct,
        amount: parseFloat(amount.toFixed(2)),
        unit: unit as UnitType,
        costPerUnit: parseFloat(costPer.toFixed(2)),
        totalCost: parseFloat((costPer * input.numTrees).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: products.reduce((a, b) => a + b.costPerUnit, 0),
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: isGrass ? "Mensual" : "Trimestral"
    });
  }, [input, isGrass, isPlanting, customProducts]);

  useEffect(() => { calculateDose(); }, [calculateDose]);

  const detailedNutrientData = useMemo(() => {
    if (!result || result.products.length === 0) return { radar: [], stacked: [], costPie: [], colors: [] };
    const palette = [pineGreen, earthBrown, '#4a5d23', '#8b4513', '#2e4d32', '#5d4037', '#1b3022', '#6b8e23', '#a0522d'];
    let nTotal=0, pTotal=0, kTotal=0, omTotal=0;

    const stacked = [
      { name: 'N', key: 'N' }, { name: 'P', key: 'P' },
      { name: 'K', key: 'K' }, { name: 'MO', key: 'OM' }
    ].map(nutType => {
      const data: any = { name: nutType.name };
      result.products.forEach((prod) => {
        const custom = customProducts.find(cp => cp.name === prod.product);
        const nutConfig = custom ? { N: custom.N, P: custom.P, K: custom.K, OM: custom.OM } : (PRODUCT_NUTRIENTS[prod.product as OrganicProduct] || { N:0, P:0, K:0, OM:0 });
        const weightFactor = ['g','ml','cc'].includes(prod.unit) ? 0.001 : 1;
        const val = ((nutConfig[nutType.key as keyof typeof nutConfig] / 100) * prod.amount * weightFactor);
        data[prod.product] = parseFloat(val.toFixed(3));
        if(nutType.key === 'N') nTotal += val;
        if(nutType.key === 'P') pTotal += val;
        if(nutType.key === 'K') kTotal += val;
        if(nutType.key === 'OM') omTotal += val;
      });
      return data;
    });

    const radar = [
      { subject: 'N', A: nTotal }, { subject: 'P', A: pTotal },
      { subject: 'K', A: kTotal }, { subject: 'MO', A: omTotal }
    ];

    const costPie = result.products.map(p => ({
      name: p.product,
      value: p.totalCost
    })).filter(p => p.value > 0);

    return { radar, stacked, costPie, colors: palette };
  }, [result, customProducts]);

  const handleFetchProfessionalAdvice = async () => {
    if (input.selectedProducts.length === 0) {
      alert("Seleccione al menos un insumo.");
      return;
    }
    setLoading(true);
    setError(null);
    setAiAdvice(null);
    try {
      const advice = await getAgriculturalAdvice(input);
      if (advice) {
        setAiAdvice(advice);
        setTimeout(() => aiSectionRef.current?.scrollIntoView({ behavior: 'smooth' }), 300);
      } else {
        setError("Error en el motor de IA. Intente con menos insumos.");
      }
    } catch (err) {
      setError("Falla de conexión agrícola. Reintentando...");
    } finally {
      setLoading(false);
    }
  };

  const handleAddCustomProduct = () => {
    if (!newProd.name) return;
    setCustomProducts([...customProducts, newProd]);
    setNewProd({ name: '', category: 'SOLIDS', N: 0, P: 0, K: 0, OM: 0, baseRate: 1, unit: 'kg' });
    setShowAddModal(false);
  };

  const handlePhotoUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>, mode: 'calculator' | 'vision') => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      if (mode === 'vision') {
        const report = await getIndependentVisionDiagnosis(base64, input.treeType);
        if (report) setVisionReport(report);
        setLoading(false);
      } else {
        setInput(prev => ({ ...prev, healthPhoto: base64 }));
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  }, [input.treeType]);

  const renderProductSelector = (title: string, items: (OrganicProduct | string)[], category: 'LIQUIDS' | 'SOLIDS') => {
    const customItems = customProducts.filter(cp => cp.category === category).map(cp => cp.name);
    const combinedItems = [...items, ...customItems];

    return (
      <div className="mb-8">
        <h3 className="text-sm font-black text-slate-500 uppercase mb-4 tracking-widest">{title}</h3>
        <div className="space-y-4">
          {combinedItems.map(p => {
            const selected = input.selectedProducts.includes(p as OrganicProduct);
            const custom = customProducts.find(cp => cp.name === p);
            const defaultUnit = custom ? custom.unit : PRODUCT_UNITS[p as OrganicProduct];
            const currentUnit = input.selectedUnits[p] || defaultUnit;
            const baseRate = custom ? custom.baseRate : BASE_RATES[p as OrganicProduct];

            return (
              <div key={p} className={`p-5 rounded-[2rem] border-2 transition-all ${selected ? 'bg-[#f0f4f1] border-[#1b3022] shadow-xl' : 'bg-slate-50 border-slate-100 opacity-80'}`}>
                <div className="flex items-center justify-between">
                  <label className="flex items-center gap-4 cursor-pointer w-full">
                    <input type="checkbox" checked={selected} onChange={() => setInput(prev => ({ ...prev, selectedProducts: selected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p as OrganicProduct] }))} className="accent-[#1b3022] h-6 w-6" />
                    <div className="flex flex-col">
                      <div className="flex items-center gap-2">
                        <span className="text-lg font-black text-[#1b3022]">{p}</span>
                        {custom && <span className="bg-[#3d2b1f] text-white text-[9px] font-black px-2 py-0.5 rounded-full uppercase">Propio</span>}
                      </div>
                      <span className="text-[10px] font-black text-[#1b3022] uppercase tracking-widest opacity-60">Sugerencia: {baseRate} {defaultUnit}</span>
                    </div>
                  </label>
                  {custom && (
                    <button onClick={() => setCustomProducts(customProducts.filter(cp => cp.name !== p))} className="text-rose-400 hover:text-rose-600 p-2"><i className="fas fa-trash"></i></button>
                  )}
                </div>
                {selected && (
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-6 pl-10">
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Dosis</label>
