import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, VisionReport } from "../types.ts";

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const productList = input.selectedProducts.map(p => {
      const unit = input.selectedUnits[p] || 'unidad';
      return `${p} (Unidad: ${unit})`;
    }).join(", ");

    const isPlanting = input.applicationMode === 'Siembra / Instalación';
    const treeName = input.treeType === 'Césped' ? `Césped Variedad: ${input.grassVariety}` : input.treeType;
    const measureUnit = input.treeType === 'Césped' ? input.grassMode : 'unidades';

    const textPrompt = `Actúa como un Doctor en Ciencias Agronómicas experto en suelos colombianos y agricultura orgánica de precisión.

    CONTEXTO DE OPERACIÓN:
    Estás generando un INFORME TÉCNICO MAESTRO para ${isPlanting ? 'ESTABLECIMIENTO DE CULTIVO' : 'MANTENIMIENTO PRODUCTIVO'}.

    DETALLES TÉCNICOS:
    - Especie: ${treeName}
    - Localización/Clima: ${input.climate}
    - Textura de Suelo: ${input.soilType}
    - Magnitud: ${input.numTrees} ${measureUnit}
    - Insumos Orgánicos Disponibles: [${productList}]

    REQUERIMIENTOS DEL INFORME:
    1. Plan Radicular: Detalla la aplicación al suelo para maximizar la estructura y microbiota.
    2. Plan Foliar: Nutrición y protección biológica para vigor y sanidad.
    3. Plan de Riego: Define milímetros o litros, frecuencia horaria y técnica recomendada (goteo, aspersión, manual).
    4. Análisis de Minerales: Explica por qué el N, P, K son vitales para esta especie en este suelo.
    5. Consejos de Comunidad: Recomendaciones para el manejo sostenible y regenerativo.

    RESPONDE EXCLUSIVAMENTE EN JSON cumpliendo el esquema proporcionado. Las dosis deben ser realistas para las unidades seleccionadas.`;

    let parts: any[] = [{ text: textPrompt }];
    if (input.healthPhoto) {
      parts.push({ inlineData: { mimeType: 'image/jpeg', data: input.healthPhoto.split(',')[1] } });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            visualDiagnosis: { type: Type.STRING },
            waterRequirement: {
              type: Type.OBJECT,
              properties: {
                volume: { type: Type.STRING, description: "Cantidad de agua" },
                frequency: { type: Type.STRING, description: "Cada cuánto regar" },
                technique: { type: Type.STRING, description: "Método de riego (Aspersión, Goteo, etc)" }
              },
              required: ["volume", "frequency", "technique"]
            },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING },
                  requirementLevel: { type: Type.NUMBER }
                }
              }
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                }
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                }
              } 
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "elementalFormulation", "waterRequirement"],
        },
      },
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Critical AI Error:", error);
    return null;
  }
};

export const getIndependentVisionDiagnosis = async (imageBase64: string, targetType: string): Promise<VisionReport | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Diagnóstico de alta precisión para: ${targetType}. Identifica plagas, enfermedades o deficiencias nutricionales visibles. Genera un remedio biológico casero efectivo. Responde en JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] } }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            plantReading: { type: Type.STRING },
