import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, VisionReport } from "../types.ts";

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    // Inicialización dinámica para asegurar la clave más reciente
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const productList = input.selectedProducts.map(p => {
      const unit = input.selectedUnits[p] || 'unidad';
      return `${p} (Unidad: ${unit})`;
    }).join(", ");

    const isPlanting = input.applicationMode === 'Siembra / Instalación';
    const treeName = input.treeType === 'Césped' ? `Césped Variedad: ${input.grassVariety}` : input.treeType;
    const measureUnit = input.treeType === 'Césped' ? input.grassMode : 'unidades';

    const textPrompt = `Actúa como un Ph.D. en Agronomía Tropical experto en suelos de Colombia.

    OBJETIVO: Generar un PROTOCOLO DE NUTRICIÓN ORGÁNICA DE PRECISIÓN.

    DATOS DEL CULTIVO:
    - Especie: ${treeName}
    - Modo: ${input.applicationMode}
    - Suelo: ${input.soilType}
    - Clima: ${input.climate}
    - Cantidad: ${input.numTrees} ${measureUnit}
    - Insumos disponibles: [${productList}]

    ESTRUCTURA DEL INFORME (JSON):
    1. radicularPlan: 3 pasos de fertilización al suelo con dosis en ${measureUnit}.
    2. foliarPlan: 2 pasos de nutrición foliar y protección.
    3. waterRequirement: Volumen específico, frecuencia y técnica de riego.
    4. tips: 3 consejos de manejo comunitario.
    5. sustainabilityScore: 0-100.

    REGLA DE ORO: Las dosis deben ser lógicas para agricultura orgánica. Responde SOLO en JSON.`;

    let parts: any[] = [{ text: textPrompt }];
    if (input.healthPhoto) {
      parts.push({ inlineData: { mimeType: 'image/jpeg', data: input.healthPhoto.split(',')[1] } });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            waterRequirement: {
              type: Type.OBJECT,
              properties: {
                volume: { type: Type.STRING },
                frequency: { type: Type.STRING },
                technique: { type: Type.STRING }
              },
              required: ["volume", "frequency", "technique"]
            },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING },
                  requirementLevel: { type: Type.NUMBER }
                }
              }
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                }
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                }
              } 
            },
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "waterRequirement"],
        },
      },
    });

    const result = JSON.parse(response.text.trim());
    return result;
  } catch (error) {
    console.error("AI Generation Failed:", error);
    return null;
  }
};

export const getIndependentVisionDiagnosis = async (imageBase64: string, targetType: string): Promise<VisionReport | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Analiza esta imagen de ${targetType}. Identifica plagas, enfermedades o deficiencias. Genera un remedio biológico casero con ingredientes naturales. Responde en JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] } }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            plantReading: { type: Type.STRING },
            pestAnalysis: {
              type: Type.OBJECT,
              properties: {
                identifiedPest: { type: Type.STRING },
                scientificName: { type: Type.STRING },
                symptoms: { type: Type.STRING },
                severity: { type: Type.STRING }
              }
            },
            biologicalRemedy: {
              type: Type.OBJECT,
              properties: {
                ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                preparation: { type: Type.STRING },
                application: { type: Type.STRING }
              }
            },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    return null;
  }
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
