      [`Estado de Salud:`, input.healthStatus.toUpperCase()],
      [`Inversión Estimada:`, `$${result.totalProjectCost.toLocaleString('es-CO')} COP`]
    ];

    let currentY = 75;
    summaryData.forEach(([label, value]) => {
      doc.setFont('helvetica', 'bold');
      doc.text(label, 15, currentY);
      doc.setFont('helvetica', 'normal');
      doc.text(value, 60, currentY);
      currentY += 8;
    });

    // Plan Radicular (Tabla)
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text('2. PLAN DE NUTRICIÓN RADICULAR (SUELO)', 15, currentY + 10);

    (doc as any).autoTable({
      startY: currentY + 15,
