      body: aiAdvice.radicularPlan.map(p => [p.item, p.dosage, p.purpose]),
      headStyles: { fillColor: [61, 43, 31], textColor: [255, 255, 255], fontStyle: 'bold' },
      styles: { fontSize: 9, cellPadding: 5 },
      theme: 'grid'
    });

    // Plan Foliar (Tabla)
    (doc as any).autoTable({
      startY: (doc as any).lastAutoTable.finalY + 15,
      head: [['Refuerzo Foliar / Protección', 'Dosis Sugerida', 'Propósito']],
      body: aiAdvice.foliarPlan.map(p => [p.item, p.dosage, p.purpose]),
      headStyles: { fillColor: [6, 78, 59], textColor: [255, 255, 255], fontStyle: 'bold' },
      styles: { fontSize: 9, cellPadding: 5 },
