import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, VisionReport } from "../types.ts";

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const productList = input.selectedProducts.map(p => {
      const unit = input.selectedUnits[p] || 'unidad';
      const price = input.productPrices[p] || 0;
      return `- ${p}: $${price} por ${unit}`;
    }).join("\n");

    const isGrass = input.treeType === 'Césped';
    const speciesName = isGrass ? `Grama ${input.grassVariety}` : input.treeType;
    const unitMeasure = isGrass ? input.grassMode : 'plantas';

    const textPrompt = `Actúa como un experto en agronomía orgánica de precisión en Colombia.

    DATOS DEL CULTIVO:
    - Especie: ${speciesName}
    - Objetivo: ${input.applicationMode}
    - Cantidad: ${input.numTrees} ${unitMeasure}
    - Suelo: ${input.soilType}
    - Clima: ${input.climate}
    - Insumos: ${productList}

    TAREA:
    Genera un protocolo de dosificación EXACTO. Debes indicar cuántos gramos/cc de cada producto usar por cada ${isGrass ? 'metro' : 'árbol'} y en total para el lote.

    INSTRUCCIONES JSON:
    1. radicularPlan: Dosis recomendadas por insumo sólido.
    2. foliarPlan: Dosis recomendadas por insumo líquido.
    3. waterRequirement: Plan de riego.
    4. tips: Recomendaciones prácticas.

    Responde solo en JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: { parts: [{ text: textPrompt }] },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            waterRequirement: {
              type: Type.OBJECT,
              properties: {
                volume: { type: Type.STRING },
                frequency: { type: Type.STRING },
                technique: { type: Type.STRING }
              },
              required: ["volume", "frequency", "technique"]
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                }
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                }
              } 
            },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING },
                  requirementLevel: { type: Type.NUMBER }
                }
              }
            }
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "waterRequirement", "elementalFormulation"],
        },
      },
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    return null;
  }
};

export const getIndependentVisionDiagnosis = async (imageBase64: string, targetType: string): Promise<VisionReport | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Analiza esta imagen de ${targetType}. Identifica plagas o deficiencias. Responde en JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] } }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            plantReading: { type: Type.STRING },
            pestAnalysis: {
              type: Type.OBJECT,
              properties: {
                identifiedPest: { type: Type.STRING },
                scientificName: { type: Type.STRING },
                symptoms: { type: Type.STRING },
                severity: { type: Type.STRING }
              }
            },
            biologicalRemedy: {
              type: Type.OBJECT,
              properties: {
                ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                preparation: { type: Type.STRING },
                application: { type: Type.STRING }
              }
            },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    return null;
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, GrassMeasureMode, GrassVariety, ClimateType, VisionReport, ApplicationMode } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_CATEGORIES } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'grass_pro' | 'vision'>('calculator');
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    applicationMode: ApplicationMode.MAINTENANCE,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: {},
    manualAmounts: {},
    selectedUnits: {},
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const aiSectionRef = useRef<HTMLDivElement>(null);
  const visionFileInputRef = useRef<HTMLInputElement>(null);

  const isGrassTab = activeTab === 'grass_pro';
  const currentType = isGrassTab ? TreeType.GRASS : input.treeType;
  const currentUnitLabel = isGrassTab ? input.grassMode : 'plantas';
  const speciesName = isGrassTab ? `Grama ${input.grassVariety}` : input.treeType;

  const calculateLocalData = useCallback(() => {
    let modifier = 1.0;
    if (input.healthStatus === 'regular') modifier *= 1.25;
    if (input.healthStatus === 'deficiente') modifier *= 1.5;
    if (input.soilType === SoilType.SANDY) modifier *= 1.2;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const baseMult = (currentType === TreeType.GRASS) ? input.numTrees : (input.treeAge || 1) * input.numTrees;
      const baseAmount = BASE_RATES[p] || 0;
      const amount = input.manualAmounts[p] ?? (baseMult * baseAmount * modifier);
      const unit = input.selectedUnits[p] || PRODUCT_UNITS[p] || 'g';
      const price = input.productPrices[p] || 0;

      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit: unit as UnitType,
        costPerUnit: price,
        totalCost: parseFloat((amount * price).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: 0,
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: currentType === TreeType.GRASS ? "Mensual" : "Trimestral"
    });
  }, [input, currentType]);

  useEffect(() => { calculateLocalData(); }, [calculateLocalData]);

  const handleFetchProfessionalAdvice = async () => {
    setLoading(true);
    setError(null);
    setAiAdvice(null);

    try {
      const advice = await getAgriculturalAdvice({
        ...input,
        treeType: currentType,
        selectedUnits: { ...PRODUCT_UNITS, ...input.selectedUnits }
      });

      if (advice) {
        setAiAdvice(advice);
        setTimeout(() => aiSectionRef.current?.scrollIntoView({ behavior: 'smooth' }), 400);
      } else {
        setError("El Ingeniero IA no pudo procesar la solicitud. Verifique su conexión.");
      }
    } catch (err) {
      setError("Fallo crítico en el motor de inteligencia artificial.");
    } finally {
      setLoading(false);
    }
  };

  const handlePhotoUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      const report = await getIndependentVisionDiagnosis(base64, isGrassTab ? "Grama/Césped" : input.treeType);
      if (report) setVisionReport(report);
      setLoading(false);
    };
    reader.readAsDataURL(file);
  }, [input.treeType, isGrassTab]);

  const generatePDF = () => {
    if (!result) return;
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();

    // Cabecera Institucional
    doc.setFillColor(6, 78, 59);
    doc.rect(0, 0, pageWidth, 50, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(26);
    doc.setFont('helvetica', 'bold');
    doc.text('REPORTE AGROVISION CO', 15, 25);
    doc.setFontSize(10);
    doc.text('Ingeniería de Precisión y Bio-Insumos', 15, 35);
    doc.text(`ID Reporte: ${Math.random().toString(36).substr(2, 9).toUpperCase()}`, pageWidth - 15, 25, { align: 'right' });

    // Datos del Cliente/Lote
    doc.setTextColor(17, 24, 39);
    doc.setFontSize(16);
    doc.text('I. INFORMACIÓN TÉCNICA DEL LOTE', 15, 65);
    doc.setDrawColor(200);
    doc.line(15, 68, pageWidth - 15, 68);

    doc.setFontSize(11);
    doc.setFont('helvetica', 'normal');
    const meta = [
      [`Cultivo:`, speciesName],
      [`Magnitud:`, `${input.numTrees} ${currentUnitLabel}`],
      [`Ubicación Suelo:`, input.soilType],
      [`Clima Regional:`, input.climate],
      [`Presupuesto Insumos:`, `$${result.totalProjectCost.toLocaleString()} COP`]
    ];

    let y = 80;
    meta.forEach(([l, v]) => {
      doc.setFont('helvetica', 'bold');
      doc.text(l, 15, y);
      doc.setFont('helvetica', 'normal');
      doc.text(v, 65, y);
      y += 8;
    });

    // Tabla de Dosis
    (doc as any).autoTable({
      startY: y + 10,
      head: [['Insumo Sugerido', 'Dosis Total', 'Costo']],
      body: result.products.map(p => [p.product, `${p.amount} ${p.unit}`, `$${p.totalCost.toLocaleString()}`]),
      headStyles: { fillColor: [16, 185, 129] },
      theme: 'grid'
    });

    if (aiAdvice) {
      const finalY = (doc as any).lastAutoTable.finalY + 15;
      doc.setFont('helvetica', 'bold');
      doc.text('II. PROTOCOLO DE APLICACIÓN IA', 15, finalY);
      (doc as any).autoTable({
        startY: finalY + 5,
        head: [['Producto', 'Dosis IA Sugerida', 'Instrucción / Propósito']],
        body: [
          ...aiAdvice.radicularPlan.map(p => [p.item, p.dosage, p.purpose]),
          ...aiAdvice.foliarPlan.map(p => [p.item, p.dosage, p.purpose])
        ],
        headStyles: { fillColor: [6, 78, 59] }
      });
    }

    doc.save(`Reporte_AgroVision_${speciesName}.pdf`);
  };

  const shareWhatsApp = () => {
    if (!result) return;
    let msg = `🚜 *AGROVISION CO - INFORME TÉCNICO*\n\n` +
      `📍 *Cultivo:* ${speciesName}\n` +
      `📦 *Lote:* ${input.numTrees} ${currentUnitLabel}\n` +
      `💰 *Presupuesto:* $${result.totalProjectCost.toLocaleString()} COP\n\n` +
      `*DOSIS RECOMENDADAS:*\n` +
      result.products.map(p => `✅ ${p.product}: *${p.amount} ${p.unit}*`).join('\n') + `\n\n` +
      `_Reporte generado por IA AgroVision Pro_`;

    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const sendEmail = () => {
    if (!result) return;
    const subject = `Reporte Técnico Agrícola - ${speciesName}`;
    const body = `HOLA,\n\nAdjunto el reporte de dosificación para su lote de ${speciesName}.\n\n` +
      `DETALLES DEL LOTE:\n` +
      `- Cantidad: ${input.numTrees} ${currentUnitLabel}\n` +
      `- Suelo: ${input.soilType}\n` +
      `- Clima: ${input.climate}\n\n` +
      `INSUMOS Y DOSIS:\n` +
      result.products.map(p => `- ${p.product}: ${p.amount} ${p.unit} ($${p.totalCost.toLocaleString()})`).join('\n') +
      `\n\nPRESUPUESTO TOTAL: $${result.totalProjectCost.toLocaleString()} COP\n\n` +
      `RECOMENDACIONES IA:\n` +
      (aiAdvice ? aiAdvice.tips.join('\n') : 'Consulte con su agrónomo.') +
      `\n\nSaludos,\nEquipo AgroVision CO`;

    window.location.href = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  };

  return (
    <div className="min-h-screen bg-[#f1f5f9] pb-24 text-[#111827]">
      <header className="bg-[#064e3b] text-white p-6 shadow-2xl sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 h-14 w-14 rounded-2xl flex items-center justify-center text-white text-3xl shadow-xl border-2 border-white/20">
              <i className="fas fa-leaf"></i>
            </div>
            <div>
              <h1 className="text-2xl font-black tracking-tight leading-none uppercase">AgroVision <span className="text-emerald-400">CO</span></h1>
