                  <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border-4 border-emerald-100 relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-8 opacity-10 text-9xl text-emerald-600"><i className="fas fa-file-invoice"></i></div>
                    <div className="relative z-10">
                        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 mb-10">
