                            <div className="flex flex-wrap gap-3">
                                <button onClick={generatePDF} className="bg-slate-900 text-white px-6 py-4 rounded-2xl font-black text-xs uppercase flex items-center gap-3 hover:scale-105 transition-all shadow-xl">
