                                <button onClick={shareWhatsApp} className="bg-[#25D366] text-white px-6 py-4 rounded-2xl font-black text-xs uppercase flex items-center gap-3 hover:scale-105 transition-all shadow-xl">
                                    <i className="fab fa-whatsapp text-xl"></i> WhatsApp
