                                </button>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
                            <div className="bg-emerald-50 p-8 rounded-[2.5rem] border-2 border-emerald-100">
                                <span className="text-[10px] font-black uppercase text-emerald-600 mb-2 block">Costo Total del Lote</span>
                                <span className="text-4xl font-black text-[#064e3b]">$${result.totalProjectCost.toLocaleString()}</span>
                                <span className="text-xs font-bold text-emerald-800 ml-2">COP</span>
