                        </div>

                        <div className="overflow-x-auto rounded-3xl border border-slate-100">
                            <table className="w-full text-left border-collapse">
                                <thead>
                                    <tr className="bg-slate-50 border-b">
                                        <th className="p-5 text-[10px] font-black uppercase text-slate-400">Producto</th>
                                        <th className="p-5 text-[10px] font-black uppercase text-slate-400">Dosis Total Requerida</th>
                                        <th className="p-5 text-[10px] font-black uppercase text-slate-400">Costo Estimado</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {result.products.map((p, idx) => (
                                        <tr key={idx} className="border-b border-slate-50 hover:bg-emerald-50/20 transition-all">
                                            <td className="p-5 font-bold">{p.product}</td>
                                            <td className="p-5"><span className="px-4 py-2 bg-emerald-100 text-emerald-800 rounded-full font-black text-sm">{p.amount.toLocaleString()} ${p.unit}</span></td>
                                            <td className="p-5 font-black text-slate-600">$${p.totalCost.toLocaleString()}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                  </div>

                  {aiAdvice && (
                    <div className="animate-in fade-in slide-in-from-bottom duration-1000 space-y-10">
                        <div className="bg-[#064e3b] p-12 rounded-[4rem] text-white relative overflow-hidden border-8 border-white/5">
                            <h2 className="text-4xl font-black mb-4">Protocolo Agronómico IA</h2>
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-10">
                              <div className="bg-white/10 p-5 rounded-3xl text-center"><span className="text-[9px] block uppercase opacity-60">Suelo</span><span className="text-lg font-black">{input.soilType}</span></div>
                              <div className="bg-white/10 p-5 rounded-3xl text-center"><span className="text-[9px] block uppercase opacity-60">Clima</span><span className="text-lg font-black">{input.climate}</span></div>
                              <div className="bg-white/10 p-5 rounded-3xl text-center"><span className="text-[9px] block uppercase opacity-60">Sostenibilidad</span><span className="text-lg font-black">{aiAdvice.sustainabilityScore}%</span></div>
                              <div className="bg-white/10 p-5 rounded-3xl text-center"><span className="text-[9px] block uppercase opacity-60">Ciclo</span><span className="text-lg font-black">{result.frequency}</span></div>
                            </div>
                        </div>

                        <div className="grid md:grid-cols-2 gap-8">
                            <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border-t-[12px] border-amber-800">
                                <h3 className="text-2xl font-black text-amber-900 mb-8"><i className="fas fa-layer-group"></i> Pasos Radiculares</h3>
                                {aiAdvice.radicularPlan.map((s, i) => (
                                    <div key={i} className="mb-6 pb-6 border-b border-slate-100 last:border-0">
                                        <h4 className="font-black text-[#111827] uppercase text-sm mb-1">{s.item}</h4>
                                        <p className="text-emerald-700 font-black text-xs mb-2">Dosis: {s.dosage}</p>
                                        <p className="text-slate-500 text-sm leading-relaxed italic">"{s.purpose}"</p>
                                    </div>
                                ))}
