              ) : (
                <div className="bg-white rounded-[4rem] p-32 text-center border-4 border-dashed border-slate-200 shadow-inner flex flex-col items-center">
                  <div className="h-44 w-44 bg-slate-50 rounded-full flex items-center justify-center mb-10 text-7xl text-slate-200">
                    <i className="fas fa-seedling"></i>
                  </div>
                  <h3 className="text-5xl font-black text-[#064e3b] mb-4 leading-none uppercase">Estación de Precisión</h3>
                  <p className="text-slate-500 text-xl font-medium max-w-2xl">Configure sus parámetros a la izquierda para generar su Reporte Final exportable.</p>
