              )}
            </section>
          </div>
        ) : (
          <div className="max-w-5xl mx-auto space-y-10 py-10">
             <div className="bg-white p-20 rounded-[4rem] shadow-2xl text-center border">
                <h2 className="text-6xl font-black text-[#111827] mb-6 leading-none tracking-tighter uppercase">IA Vision</h2>
                <button onClick={() => visionFileInputRef.current?.click()} className="bg-[#064e3b] text-white px-20 py-8 rounded-full text-2xl font-black shadow-2xl flex items-center gap-6 border-8 border-emerald-100 mx-auto">
                    <i className="fas fa-camera"></i> Escanear Muestra
                </button>
                <input type="file" accept="image/*" ref={visionFileInputRef} onChange={handlePhotoUpload} className="hidden" />
             </div>
             {visionReport && (
                <div className="bg-[#111827] p-12 rounded-[4.5rem] text-white shadow-2xl">
                   <p className="text-5xl font-black italic tracking-tight">"{visionReport.plantReading}"</p>
