    const nutrientY = (doc as any).lastAutoTable.finalY + 15;
    doc.setFont('helvetica', 'bold');
    doc.text('BALANCE DE NUTRIENTES APLICADOS', 15, nutrientY);
    autoTable(doc, {
      startY: nutrientY + 5,
