import { GoogleGenAI, Type } from "@google/genai";
import { CalculationInput, AIAdvice, VisionReport } from "../types.ts";

export const getAgriculturalAdvice = async (input: CalculationInput): Promise<AIAdvice | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const productList = input.selectedProducts.map(p => {
      const unit = input.selectedUnits[p] || 'unidad';
      const price = input.productPrices[p] || 0;
      return `- ${p}: $${price} por ${unit}`;
    }).join("\n");

    const isGrass = input.treeType === 'Césped';
    const speciesName = isGrass ? `Grama ${input.grassVariety}` : input.treeType;
    const unitMeasure = isGrass ? input.grassMode : 'plantas';

    const textPrompt = `Actúa como un experto en agronomía orgánica de precisión en Colombia.

    UBICACIÓN GEOGRÁFICA:
    - Departamento: ${input.department}

    DATOS DEL CULTIVO:
    - Especie: ${speciesName}
    - Objetivo: ${input.applicationMode}
    - Cantidad: ${input.numTrees} ${unitMeasure}
    - Suelo: ${input.soilType}
    - Clima reportado: ${input.climate}
    - Estado de salud: ${input.healthStatus}
    - Insumos disponibles: ${productList}

    TAREA:
    Genera un protocolo de dosificación EXACTO y profesional adaptado a las condiciones de ${input.department}. 
    Debes indicar cuántos gramos/cc de cada producto usar por cada unidad (${isGrass ? 'metro' : 'árbol'}) y en total para el lote.
    Ten en cuenta las características típicas del suelo y régimen hídrico de esta región colombiana.

    Responde estrictamente en formato JSON siguiendo el esquema proporcionado.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: { parts: [{ text: textPrompt }] },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            seasonalAdvice: { type: Type.STRING },
            sustainabilityScore: { type: Type.NUMBER },
            soilAnalysis: { type: Type.STRING },
            waterRequirement: {
              type: Type.OBJECT,
              properties: {
                volume: { type: Type.STRING },
                frequency: { type: Type.STRING },
                technique: { type: Type.STRING }
              },
              required: ["volume", "frequency", "technique"]
            },
            radicularPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                }
              } 
            },
            foliarPlan: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  dosage: { type: Type.STRING },
                  purpose: { type: Type.STRING }
                }
              } 
            },
            elementalFormulation: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  element: { type: Type.STRING },
                  relevance: { type: Type.STRING },
                  priority: { type: Type.STRING },
                  requirementLevel: { type: Type.NUMBER }
                }
              }
            }
          },
          required: ["tips", "seasonalAdvice", "sustainabilityScore", "soilAnalysis", "radicularPlan", "foliarPlan", "waterRequirement", "elementalFormulation"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("Respuesta vacía de la IA");

    const cleanJson = text.replace(/```json/g, "").replace(/```/g, "").trim();
    return JSON.parse(cleanJson);
  } catch (error) {
    console.error("Error en getAgriculturalAdvice:", error);
    return null;
  }
};

export const getIndependentVisionDiagnosis = async (imageBase64: string, targetType: string): Promise<VisionReport | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Actúa como un Patólogo Vegetal experto en cultivos colombianos. Analiza esta imagen de una muestra de ${targetType}.
    Identifica:
    1. Lectura general de la planta (color, turgencia).
    2. Identificación exacta de la plaga o deficiencia nutricional (incluyendo nombre científico si es posible).
    3. Síntomas observados y nivel de severidad.
    4. Un remedio biológico/orgánico detallado para el control inmediato.
    5. Recomendaciones de manejo cultural preventivo.

    Responde estrictamente en formato JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] } }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            plantReading: { type: Type.STRING },
            pestAnalysis: {
              type: Type.OBJECT,
              properties: {
                identifiedPest: { type: Type.STRING },
                scientificName: { type: Type.STRING },
                symptoms: { type: Type.STRING },
                severity: { type: Type.STRING }
              },
              required: ["identifiedPest", "symptoms", "severity"]
            },
            biologicalRemedy: {
              type: Type.OBJECT,
              properties: {
                ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                preparation: { type: Type.STRING },
                application: { type: Type.STRING }
              },
              required: ["ingredients", "preparation", "application"]
            },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["plantReading", "pestAnalysis", "biologicalRemedy", "recommendations"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Respuesta vacía de IA Vision");
    const cleanJson = text.replace(/```json/g, "").replace(/```/g, "").trim();
    return JSON.parse(cleanJson);
  } catch (error) {
    console.error("Error en IA Vision:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, GrassMeasureMode, GrassVariety, ClimateType, VisionReport, ApplicationMode, FrequencyUnit, Department } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, TREE_TYPE_ICONS, PRODUCT_NUTRIENTS, COLOMBIAN_MARKET_PRICES, PRODUCT_CATEGORIES, DEPARTMENT_CLIMATE_MAP } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'grass_pro' | 'vision'>('calculator');
  const [showPlantPlan, setShowPlantPlan] = useState(false);
  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS,
    department: Department.ANTIOQUIA,
    applicationMode: ApplicationMode.MAINTENANCE,
    grassVariety: GrassVariety.KIKUYO,
    soilType: SoilType.LOAMY,
    climate: ClimateType.MODERATE,
    treeAge: 1,
    numTrees: 1,
    grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: { ...COLOMBIAN_MARKET_PRICES },
    manualAmounts: {},
    manualPlantAmounts: {},
    selectedUnits: {},
    cycleFrequencyValue: 3,
    cycleFrequencyUnit: 'meses',
    healthStatus: 'bueno'
  });

  const [result, setResult] = useState<CalculationResult | null>(null);
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [visionImage, setVisionImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [fetchingLocation, setFetchingLocation] = useState(false);

  const aiSectionRef = useRef<HTMLDivElement>(null);
  const visionFileInputRef = useRef<HTMLInputElement>(null);

  const isGrassTab = activeTab === 'grass_pro';
  const currentType = isGrassTab ? TreeType.GRASS : input.treeType;
  const currentUnitLabel = isGrassTab ? input.grassMode : 'plantas';
  const speciesName = isGrassTab ? `Grama ${input.grassVariety}` : input.treeType;

  const captureLocation = useCallback(() => {
    if (!navigator.geolocation) {
      setError("Tu navegador no soporta geolocalización.");
      return;
    }

    setFetchingLocation(true);
    navigator.geolocation.getCurrentPosition(
      (position) => {
        setInput(prev => ({
          ...prev,
          location: {
            lat: position.coords.latitude,
            lng: position.coords.longitude
          }
        }));
        setFetchingLocation(false);
      },
      (err) => {
        console.warn("Error capturando ubicación:", err);
        setFetchingLocation(false);
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );
  }, []);

  useEffect(() => {
    captureLocation();
  }, [captureLocation]);

  const calculateLocalData = useCallback(() => {
    let modifier = 1.0;
    if (input.healthStatus === 'regular') modifier *= 1.25;
    if (input.healthStatus === 'deficiente') modifier *= 1.5;
    if (input.soilType === SoilType.SANDY) modifier *= 1.2;

    const products: ProductResult[] = input.selectedProducts.map(p => {
      const unit = input.selectedUnits[p] || PRODUCT_UNITS[p] || 'g';
      const price = input.productPrices[p] || 0;

      let amount: number;
      if (input.manualPlantAmounts[p] !== undefined) {
        amount = (input.manualPlantAmounts[p] || 0) * input.numTrees;
      } else if (input.manualAmounts[p] !== undefined) {
        amount = input.manualAmounts[p] || 0;
      } else {
        const baseMult = (currentType === TreeType.GRASS) ? input.numTrees : (input.treeAge || 1) * input.numTrees;
        const baseAmount = BASE_RATES[p] || 0;
        amount = baseMult * baseAmount * modifier;
      }

      return {
        product: p,
        amount: parseFloat(amount.toFixed(2)),
        unit: unit as UnitType,
        costPerUnit: price,
        totalCost: parseFloat((amount * price).toFixed(2))
      };
    });

    setResult({
      products,
      totalCostPerUnit: 0,
      totalProjectCost: products.reduce((a, b) => a + b.totalCost, 0),
      frequency: `Cada ${input.cycleFrequencyValue} ${input.cycleFrequencyUnit}`
    });
  }, [input, currentType]);

  useEffect(() => { calculateLocalData(); }, [calculateLocalData]);

  const nutrientBalance = useMemo(() => {
    if (!result) return [];
    const totals = { N: 0, P: 0, K: 0, MO: 0 };
    result.products.forEach(p => {
      const profile = PRODUCT_NUTRIENTS[p.product];
      totals.N += (p.amount * profile.N) / 100;
      totals.P += (p.amount * profile.P) / 100;
      totals.K += (p.amount * profile.K) / 100;
      totals.MO += (p.amount * profile.OM) / 100;
    });
    return [
      { name: 'Nitrógeno (N)', value: parseFloat(totals.N.toFixed(2)), color: '#10b981' },
      { name: 'Fósforo (P)', value: parseFloat(totals.P.toFixed(2)), color: '#3b82f6' },
      { name: 'Potasio (K)', value: parseFloat(totals.K.toFixed(2)), color: '#f59e0b' },
      { name: 'Mat. Orgánica (MO)', value: parseFloat(totals.MO.toFixed(2)), color: '#78350f' },
    ];
  }, [result]);

  const handleFetchProfessionalAdvice = async () => {
    const hasKey = typeof window !== 'undefined' && (window as any).aistudio?.hasSelectedApiKey;
    if (hasKey && !(await (window as any).aistudio.hasSelectedApiKey())) {
      await (window as any).aistudio.openSelectKey();
    }
    setLoading(true);
    setError(null);
    setAiAdvice(null);
    try {
      const advice = await getAgriculturalAdvice({
        ...input,
        treeType: currentType,
        selectedUnits: { ...PRODUCT_UNITS, ...input.selectedUnits }
      });
      if (advice) {
        setAiAdvice(advice);
        setTimeout(() => {
          aiSectionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 300);
      } else {
        setError("La IA no pudo procesar los datos. Verifique su conexión.");
      }
    } catch (err) {
      setError("Error crítico en el servicio de Inteligencia Artificial.");
    } finally {
      setLoading(false);
    }
  };

  const handlePhotoUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const hasKey = typeof window !== 'undefined' && (window as any).aistudio?.hasSelectedApiKey;
    if (hasKey && !(await (window as any).aistudio.hasSelectedApiKey())) {
      await (window as any).aistudio.openSelectKey();
    }
    setLoading(true);
    setError(null);
    setVisionReport(null);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setVisionImage(base64);
      try {
        const report = await getIndependentVisionDiagnosis(base64, isGrassTab ? "Grama/Césped" : input.treeType);
        if (report) setVisionReport(report);
        else setError("IA Vision no pudo diagnosticar la imagen.");
      } catch (err) {
        setError("Fallo en el servidor de IA Vision.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  }, [input.treeType, isGrassTab]);

  const generatePDF = () => {
    if (!result) return;
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();
    doc.setFillColor(6, 78, 59);
    doc.rect(0, 0, pageWidth, 50, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(26);
    doc.text('REPORTE AGROVISION CO', 15, 25);
    doc.setFontSize(10);
    doc.text('Ingeniería de Precisión y Bio-Insumos', 15, 35);
    doc.setTextColor(0, 0, 0);
    doc.text('I. INFORMACIÓN TÉCNICA', 15, 65);
    const meta = [
      [`Cultivo:`, speciesName],
      [`Ubicación:`, `${input.department} (Colombia)`],
      [`Cantidad:`, `${input.numTrees} ${currentUnitLabel}`],
      [`Frecuencia:`, result.frequency],
      [`Total Inversión:`, `$${result.totalProjectCost.toLocaleString()} COP`]
    ];
    let y = 80;
    meta.forEach(([l, v]) => {
      doc.setFont('helvetica', 'bold');
      doc.text(l, 15, y);
      doc.setFont('helvetica', 'normal');
      doc.text(v, 65, y);
      y += 8;
    });
    autoTable(doc, {
      startY: y + 10,
      head: [['Insumo', 'Dosis Requerida', 'Costo Estimado']],
      body: result.products.map(p => [p.product, `${p.amount} ${p.unit}`, `$${p.totalCost.toLocaleString()}`]),
      headStyles: { fillColor: [16, 185, 129] }
    });
    doc.save(`Reporte_AgroVision_${speciesName.replace(/\s+/g, '_')}.pdf`);
  };

  const shareWhatsApp = () => {
    if (!result) return;
    let msg = `🚜 *AGROVISION CO*\n📍 *Ubicación:* ${input.department}\n📍 *Cultivo:* ${speciesName}\n📦 *Lote:* ${input.numTrees} ${currentUnitLabel}\n⏳ *Ciclo:* ${result.frequency}\n💰 *Presupuesto:* $${result.totalProjectCost.toLocaleString()} COP\n\n*DOSIS:*\n` +
      result.products.map(p => `✅ ${p.product}: *${p.amount} ${p.unit}*`).join('\n');
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const renderProductItem = (p: OrganicProduct) => {
    const selected = input.selectedProducts.includes(p);
    const unit = PRODUCT_UNITS[p];
