              <input type="number" step="0.01" placeholder={defaultPlantRate.toString()} value={input.manualPlantAmounts[p] ?? ''} onChange={e => setInput({...input, manualPlantAmounts: {...input.manualPlantAmounts, [p]: e.target.value === '' ? undefined : parseFloat(e.target.value)}})} className="w-full p-2 text-[10px] border rounded-lg font-black bg-white outline-none focus:border-emerald-600" />
            </div>
            <div className="space-y-1">
              <label className="text-[8px] font-black uppercase text-slate-500">Precio/{unit}</label>
              <input type="number" value={input.productPrices[p] || ''} onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})} className="w-full p-2 text-[10px] border rounded-lg font-black bg-white outline-none focus:border-emerald-600" />
            </div>
          </div>
        )}
      </div>
    );
  };

