        ['Textura Identificada', input.soilType]
      ],
      theme: 'striped',
      headStyles: { fillColor: [51, 65, 85] }
    });

    const nextY = (doc as any).lastAutoTable.finalY + 10;
    autoTable(doc, {
      startY: nextY,
      head: [['Insumo', `Dosis / Unidad`, 'Total', 'Subtotal']],
      body: result.products.map(p => [
        p.product,
