    doc.save(`Reporte_BioGenesis_${clientData.lastName || 'Export'}.pdf`);
  };

  const shareWhatsApp = () => {
    if (!result) return;
    const clientName = `${clientData.firstName} ${clientData.lastName}`.trim() || 'Cliente';
    let text = `*BioGenesis PRO - Reporte Técnico*%0A%0A`;
