  const [history, setHistory] = useState<HistoryRecord[]>([]);

  // Porcentaje adicional editable (Utilidad/Margen)
  const [additionalPercent, setAdditionalPercent] = useState<number>(0);

  const [clientData, setClientData] = useState<ClientData>({
    firstName: '', lastName: '', location: '', contact: '', email: ''
  });

  const [input, setInput] = useState<CalculationInput>({
    treeType: TreeType.CITRUS, department: Department.ANTIOQUIA, applicationMode: ApplicationMode.MAINTENANCE,
    soilType: SoilType.FRANCO, climate: ClimateType.MODERATE, treeAge: 1, numTrees: 1, 
    grassVariety: GrassVariety.KIKUYO, grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: { ...COLOMBIAN_MARKET_PRICES }, manualPlantAmounts: {}, selectedUnits: {},
    cycleFrequencyValue: 3, cycleFrequencyUnit: 'meses', healthStatus: 'bueno',
    manualAmounts: {}
  });

  const [result, setResult] = useState<CalculationResult | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('biogenesis_history_v7');
    if (saved) setHistory(JSON.parse(saved));
  }, []);

  // Función de cálculo unificada para evitar los 182M
  const calculateProductRow = useCallback((p: OrganicProduct) => {
    const totalUnits = Math.max(1, input.numTrees || 1);

    // Dosis unitaria (ya sea sugerida por salud/edad o manual)
    let dosePerUnit: number;
    if (input.manualPlantAmounts[p] !== undefined) {
      dosePerUnit = input.manualPlantAmounts[p] as number;
    } else {
      // Cálculo base moderado para evitar inflar precios
      const base = BASE_RATES[p] || 0;
      const healthMultiplier = input.healthStatus === 'deficiente' ? 1.3 : (input.healthStatus === 'regular' ? 1.15 : 1);
      const ageFactor = activeTab === 'grass_pro' ? 1 : Math.min(2.5, 1 + (input.treeAge - 1) * 0.1);
      dosePerUnit = base * healthMultiplier * ageFactor;
    }

    const price = input.productPrices[p] || 0;
    const totalQuantity = dosePerUnit * totalUnits;
    const subtotal = totalQuantity * price;

    return {
      product: p,
      amount: parseFloat(totalQuantity.toFixed(2)),
      unit: input.selectedUnits[p] || PRODUCT_UNITS[p] || 'u',
      costPerUnit: price,
      totalCost: Math.round(subtotal),
      dosePerUnit: parseFloat(dosePerUnit.toFixed(2))
    };
  }, [input, activeTab]);

  const updateResults = useCallback(() => {
    const products = input.selectedProducts.map(p => calculateProductRow(p));
    const subtotalProject = products.reduce((acc, curr) => acc + curr.totalCost, 0);

    setResult({ 
      products, 
      totalCostPerUnit: subtotalProject / (input.numTrees || 1), 
      totalProjectCost: subtotalProject, 
      frequency: `Cada ${input.cycleFrequencyValue} ${input.cycleFrequencyUnit}` 
    });
  }, [input.selectedProducts, calculateProductRow, input.numTrees, input.cycleFrequencyValue, input.cycleFrequencyUnit]);

  useEffect(() => { updateResults(); }, [updateResults]);

  // Cálculos del porcentaje adicional
  const additionalValue = (result?.totalProjectCost || 0) * (additionalPercent / 100);
  const grandTotal = (result?.totalProjectCost || 0) + additionalValue;

  const handleExportPDF = () => {
    if (!result) return;
    const doc = new jsPDF();
    doc.setFillColor(6, 78, 59);
    doc.rect(0, 0, 210, 40, 'F');
    doc.setFontSize(22);
    doc.setTextColor(255, 255, 255);
    doc.text('BIO-GENESIS PRO', 14, 25);
    doc.setFontSize(9);
    doc.text('REPORTE TÉCNICO Y PRESUPUESTO AGRÍCOLA', 14, 32);

    doc.setTextColor(50);
    doc.setFontSize(10);
    doc.text(`Productor: ${clientData.firstName} ${clientData.lastName}`, 14, 50);
    doc.text(`Cultivo: ${activeTab === 'grass_pro' ? 'Grama ' + input.grassVariety : input.treeType}`, 14, 56);
    doc.text(`Cant. Unidades: ${input.numTrees}`, 130, 50);
    doc.text(`Fecha: ${new Date().toLocaleDateString()}`, 130, 56);

    autoTable(doc, {
      startY: 65,
      head: [['Insumo', 'Unidad de Medida', 'Cantidad Total', 'Precio Unitario', 'Subtotal (COP)']],
      body: result.products.map(p => [
        p.product,
        p.unit,
        p.amount.toLocaleString(),
        `$${p.costPerUnit.toLocaleString()}`,
        `$${p.totalCost.toLocaleString()}`
      ]),
      foot: [
        ['', '', '', 'SUBTOTAL INSUMOS', `$${result.totalProjectCost.toLocaleString()}`],
        ['', '', '', `ADICIONAL / UTILIDAD (${additionalPercent}%)`, `$${additionalValue.toLocaleString()}`],
        ['', '', '', 'TOTAL GENERAL', `$${grandTotal.toLocaleString()}`]
      ],
      theme: 'grid',
      headStyles: { fillColor: [6, 78, 59] },
      footStyles: { fillColor: [240, 240, 240], textColor: [0, 0, 0], fontStyle: 'bold' }
    });

    doc.save(`BioGenesis_Presupuesto_${clientData.lastName || 'Reporte'}.pdf`);
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 pb-20">
      <header className="bg-[#064e3b] p-6 sticky top-0 z-50 shadow-xl no-print">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
          <BioGenesisLogo />
          <nav className="flex bg-white/10 p-1 rounded-2xl backdrop-blur-md">
            {[
              { id: 'calculator', label: 'CULTIVOS' },
              { id: 'grass_pro', label: 'CÉSPED' },
              { id: 'vision', label: 'VISION IA' },
              { id: 'history', label: 'HISTORIAL' }
            ].map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === tab.id ? 'bg-white text-[#064e3b] shadow-lg' : 'text-white/70 hover:text-white'}`}>
                {tab.label}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        {(activeTab === 'calculator' || activeTab === 'grass_pro') && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            {/* PANEL DE CONFIGURACIÓN */}
            <aside className="lg:col-span-4 space-y-6 no-print">
              <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200">
                <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-6">1. Configuración del Cultivo</h3>
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase">Seleccione Cultivo</label>
                    <select 
                      value={input.treeType} 
                      onChange={e => setInput({...input, treeType: e.target.value as any})}
                      className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-emerald-500"
                    >
                      {Object.values(TreeType).map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <input type="text" placeholder="Nombre Productor" value={clientData.firstName} onChange={e => setClientData({...clientData, firstName: e.target.value})} className="p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" />
                    <input type="text" placeholder="Apellido" value={clientData.lastName} onChange={e => setClientData({...clientData, lastName: e.target.value})} className="p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" />
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-500 uppercase">Edad Árbol</label>
                      <input type="number" value={input.treeAge} onChange={e => setInput({...input, treeAge: parseInt(e.target.value) || 1})} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-500 uppercase">N° Plantas</label>
                      <input type="number" value={input.numTrees} onChange={e => setInput({...input, numTrees: parseInt(e.target.value) || 1})} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200">
                <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-6">2. Catálogo de Insumos</h3>
                <div className="max-h-[400px] overflow-y-auto space-y-3 pr-2 custom-scrollbar">
                  {Object.values(OrganicProduct).map(p => {
                    const isSelected = input.selectedProducts.includes(p);
                    return (
                      <div key={p} className={`p-4 rounded-2xl border-2 transition-all cursor-pointer ${isSelected ? 'bg-emerald-50 border-emerald-500 ring-4 ring-emerald-500/10' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                        <label className="flex items-center gap-3 cursor-pointer">
                          <input 
                            type="checkbox" 
                            checked={isSelected} 
                            onChange={() => setInput(prev => ({ 
                              ...prev, 
                              selectedProducts: isSelected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p] 
                            }))} 
                            className="w-5 h-5 accent-emerald-600 rounded"
                          />
                          <span className="text-xs font-black text-slate-800 uppercase leading-none">{p}</span>
                        </label>
                        {isSelected && (
                          <div className="grid grid-cols-3 gap-2 mt-4 animate-in slide-in-from-top-2">
                             <div className="space-y-1">
                               <span className="text-[8px] font-black text-slate-400 uppercase">Unidad</span>
                               <select 
                                 value={input.selectedUnits[p] || PRODUCT_UNITS[p]} 
                                 onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p]: e.target.value as any}})}
                                 className="w-full p-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-bold"
                               >
                                 {['g','kg','ml','cc','L','galon'].map(u => <option key={u} value={u}>{u}</option>)}
                               </select>
                             </div>
                             <div className="space-y-1">
                               <span className="text-[8px] font-black text-slate-400 uppercase">Dosis/Pla</span>
                               <input 
                                 type="number" 
                                 value={input.manualPlantAmounts[p] ?? calculateProductRow(p).dosePerUnit} 
                                 onChange={e => setInput({...input, manualPlantAmounts: {...input.manualPlantAmounts, [p]: parseFloat(e.target.value) || 0}})}
                                 className="w-full p-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-bold" 
                               />
                             </div>
                             <div className="space-y-1">
                               <span className="text-[8px] font-black text-slate-400 uppercase">Precio Unid.</span>
                               <input 
                                 type="number" 
                                 value={input.productPrices[p]} 
                                 onChange={e => setInput({...input, productPrices: {...input.productPrices, [p]: parseFloat(e.target.value) || 0}})}
                                 className="w-full p-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-bold" 
                               />
                             </div>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            </aside>

            {/* ÁREA DE REPORTE Y RESULTADOS */}
            <section className="lg:col-span-8 space-y-6">
              <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-slate-200">
                <div className="flex justify-between items-center mb-8 pb-4 border-b">
                  <div className="flex items-center gap-4">
                    <div className="w-16 h-16 bg-emerald-100 rounded-3xl flex items-center justify-center text-3xl">
                      {TREE_TYPE_ICONS[input.treeType] || <i className="fas fa-seedling text-emerald-600"></i>}
                    </div>
                    <div>
                      <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase leading-none">{input.treeType}</h2>
                      <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">Presupuesto de Inversión Agrícola</p>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={handleExportPDF} className="bg-[#064e3b] text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase shadow-lg hover:bg-black transition-all">PDF Reporte</button>
                    <button onClick={() => window.print()} className="bg-slate-100 text-slate-600 px-6 py-3 rounded-2xl text-[10px] font-black uppercase border hover:bg-slate-200 transition-all">Imprimir</button>
                  </div>
                </div>

                {result && result.products.length > 0 ? (
                  <div className="space-y-10">
                    <div className="overflow-hidden rounded-[2.5rem] border border-slate-200 bg-slate-50/50">
                      <table className="w-full text-left">
                        <thead className="bg-slate-100 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                          <tr>
                            <th className="p-6">Insumo Seleccionado</th>
                            <th className="p-6">U. Medida</th>
                            <th className="p-6">Cantidad Total</th>
                            <th className="p-6">Precio Unitario</th>
                            <th className="p-6 text-right">Subtotal (COP)</th>
                          </tr>
                        </thead>
                        <tbody className="text-sm font-bold text-slate-700">
                          {result.products.map((p, idx) => (
                            <tr key={idx} className="border-t hover:bg-emerald-50/30 transition-colors">
                              <td className="p-6 uppercase font-black text-slate-900">{p.product}</td>
                              <td className="p-6 uppercase text-[10px]">{p.unit}</td>
                              <td className="p-6">{p.amount.toLocaleString()}</td>
                              <td className="p-6 text-slate-500">${p.costPerUnit.toLocaleString()}</td>
                              <td className="p-6 text-right font-black text-emerald-700">${p.totalCost.toLocaleString()}</td>
                            </tr>
                          ))}
                        </tbody>
                        <tfoot className="bg-slate-100/80 border-t-2 border-slate-200">
                           <tr className="border-b">
                             <td colSpan={4} className="p-4 text-right font-bold text-slate-400 text-[11px] uppercase tracking-widest">Subtotal Neto de Insumos</td>
                             <td className="p-4 text-right font-black text-slate-900 text-xl">${result.totalProjectCost.toLocaleString()}</td>
                           </tr>
                           <tr className="border-b">
                             <td colSpan={4} className="p-4 text-right font-bold text-slate-400 text-[11px] uppercase tracking-widest">
                               Factor Adicional / Margen de Utilidad (%)
                               <input 
                                 type="number" 
                                 value={additionalPercent} 
                                 onChange={(e) => setAdditionalPercent(parseFloat(e.target.value) || 0)}
                                 className="ml-4 w-24 p-2 bg-white border border-emerald-300 rounded-xl text-center text-xs font-black text-emerald-700 outline-none focus:ring-2 focus:ring-emerald-500 shadow-sm"
                               />
                             </td>
                             <td className="p-4 text-right font-black text-blue-600">
                               +${Math.round(additionalValue).toLocaleString()}
                             </td>
                           </tr>
                           <tr className="bg-[#064e3b] text-white">
                             <td colSpan={4} className="p-10 text-right font-black uppercase text-xl tracking-tighter">Inversión Total Recomendada</td>
                             <td className="p-10 text-right font-black text-4xl text-emerald-400 tracking-tighter">
                               ${Math.round(grandTotal).toLocaleString()}
                             </td>
                           </tr>
                        </tfoot>
                      </table>
                    </div>

                    {/* MÓDULO IA */}
                    <div className="bg-emerald-50 p-8 rounded-[3.5rem] border-2 border-dashed border-emerald-200 relative overflow-hidden">
                       <div className="absolute top-0 right-0 p-4 opacity-5">
                         <i className="fas fa-robot text-9xl"></i>
                       </div>
                       <h4 className="text-xl font-black text-[#064e3b] uppercase mb-6 flex items-center gap-3">
                         <i className="fas fa-wand-sparkles text-emerald-600"></i> Plan de Manejo IA Especializado
                       </h4>
                       {!aiAdvice ? (
                         <button 
                           onClick={async () => {
                             setLoading(true);
                             const advice = await getAgriculturalAdvice(input);
                             setAiAdvice(advice);
                             setLoading(false);
                           }} 
                           disabled={loading} 
                           className="w-full bg-white text-emerald-900 p-8 rounded-[2rem] border-2 border-emerald-300 font-black uppercase shadow-xl hover:bg-emerald-50 transition-all flex items-center justify-center gap-4 group"
                         >
                           {loading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-brain group-hover:scale-125 transition-transform"></i>}
                           {loading ? 'Consultando Expertos...' : 'Obtener Recomendaciones ICA / AGROSAVIA con IA'}
                         </button>
                       ) : (
                         <div className="grid md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-5">
                            <div className="space-y-4">
                              <h5 className="text-[11px] font-black text-emerald-900 uppercase tracking-widest border-b border-emerald-200 pb-2">Nutrición de Suelos (Radicular)</h5>
                              {aiAdvice.radicularPlan.map((s, idx) => (
                                <div key={idx} className="p-4 bg-white rounded-2xl shadow-sm border border-emerald-100 group hover:border-emerald-500 transition-all">
                                  <p className="text-xs font-black text-slate-900 uppercase">{s.item}</p>
                                  <p className="text-[10px] font-bold text-emerald-600 uppercase mt-1">Dosis IA: {s.dosage}</p>
                                  <p className="text-[10px] text-slate-500 mt-2 italic">"{s.purpose}"</p>
                                </div>
                              ))}
                            </div>
                            <div className="space-y-4">
                              <h5 className="text-[11px] font-black text-teal-900 uppercase tracking-widest border-b border-teal-200 pb-2">Manejo Foliar (Plagas/Nutrición)</h5>
                              {aiAdvice.foliarPlan.map((s, idx) => (
                                <div key={idx} className="p-4 bg-white rounded-2xl shadow-sm border border-teal-50 group hover:border-teal-500 transition-all">
                                  <p className="text-xs font-black text-slate-900 uppercase">{s.item}</p>
                                  <p className="text-[10px] font-bold text-teal-600 uppercase mt-1">Dosis IA: {s.dosage}</p>
                                  <p className="text-[10px] text-slate-500 mt-2 italic">"{s.purpose}"</p>
                                </div>
                              ))}
                            </div>
                         </div>
                       )}
                    </div>
                  </div>
                ) : (
                  <div className="text-center py-24 bg-slate-50 rounded-[4rem] border-4 border-dashed border-slate-100 text-slate-300 font-black uppercase text-sm tracking-widest">
                    <i className="fas fa-calculator text-5xl mb-6 opacity-10"></i><br/>
                    Seleccione insumos del catálogo lateral para generar el presupuesto
                  </div>
                )}
              </div>
            </section>
          </div>
        )}

        {/* MÓDULO VISION IA */}
        {activeTab === 'vision' && (
          <div className="max-w-4xl mx-auto space-y-12">
            <div className="bg-white p-14 rounded-[4rem] shadow-2xl text-center border-4 border-emerald-50">
              <h2 className="text-5xl font-black text-[#064e3b] mb-4 tracking-tighter uppercase">BioGenesis Vision IA</h2>
              <p className="text-slate-500 font-medium mb-12 max-w-lg mx-auto">Nuestro modelo neuronal detecta plagas, hongos y deficiencias con una sola fotografía de la hoja.</p>

              <div className="relative group border-4 border-dashed border-slate-200 rounded-[3.5rem] p-10 bg-slate-50 transition-all hover:bg-slate-100 hover:border-emerald-300">
                {visionImage ? (
                  <img src={visionImage} className="aspect-video rounded-[3rem] object-cover mx-auto shadow-2xl border-8 border-white" />
                ) : (
                  <label className="cursor-pointer flex flex-col items-center py-16">
                    <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                      <i className="fas fa-camera text-4xl text-emerald-600"></i>
                    </div>
                    <span className="text-sm font-black uppercase text-slate-500 tracking-widest">Subir Imagen del Cultivo</span>
                    <input type="file" accept="image/*" onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (file) {
                        const reader = new FileReader();
                        reader.onloadend = () => setVisionImage(reader.result as string);
                        reader.readAsDataURL(file);
                      }
                    }} className="hidden" />
                  </label>
                )}
              </div>

              {visionImage && (
                <div className="flex justify-center gap-4 mt-10">
                  <button onClick={() => { setVisionImage(null); setVisionReport(null); }} className="px-10 py-5 bg-slate-200 text-slate-700 rounded-2xl font-black uppercase hover:bg-slate-300 transition-all">Eliminar</button>
                  <button 
                    onClick={async () => {
                      setLoading(true);
                      const report = await getIndependentVisionDiagnosis(visionImage, input.treeType);
                      setVisionReport(report);
                      setLoading(false);
                    }} 
                    disabled={loading} 
                    className="px-16 py-5 bg-[#064e3b] text-white rounded-2xl font-black uppercase shadow-2xl hover:bg-black transition-all flex items-center gap-3"
                  >
                    {loading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-bolt"></i>}
                    {loading ? 'Procesando Muestra...' : 'Iniciar Bio-Diagnóstico'}
                  </button>
                </div>
              )}
            </div>

            {visionReport && (
              <div className="bg-white p-12 rounded-[4rem] shadow-2xl border border-emerald-100 animate-in zoom-in-95 duration-500">
                <h4 className="text-3xl font-black text-slate-900 uppercase mb-10 tracking-tighter border-b pb-6">Informe de Patología Vegetal</h4>
                <div className="grid md:grid-cols-2 gap-12">
                  <div className="space-y-8">
                    <div>
                      <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-2">Hallazgo Identificado</p>
                      <p className="text-3xl font-black text-slate-900 leading-none">{visionReport.pestAnalysis.identifiedPest}</p>
                      <p className="text-sm text-slate-400 italic font-bold mt-2">{visionReport.pestAnalysis.scientificName}</p>
                    </div>
                    <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Síntomas Visuales</p>
                      <p className="text-sm font-medium text-slate-600 italic leading-relaxed">"{visionReport.pestAnalysis.symptoms}"</p>
                    </div>
                  </div>
                  <div className="bg-emerald-900 text-white p-10 rounded-[3.5rem] shadow-2xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-6 opacity-10">
                      <i className="fas fa-vial text-7xl"></i>
                    </div>
                    <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-8">Solución Biológica BioGenesis</p>
                    <ul className="space-y-4 mb-8">
                      {visionReport.biologicalRemedy.ingredients.map((ing, idx) => (
                        <li key={idx} className="flex items-center gap-3 text-sm font-bold">
                          <i className="fas fa-check-circle text-emerald-400"></i> {ing}
                        </li>
                      ))}
                    </ul>
                    <div className="pt-8 border-t border-white/10">
                      <p className="text-[11px] font-black text-emerald-400 uppercase mb-3">Protocolo de Aplicación</p>
                      <p className="text-xs font-medium text-emerald-50/80 leading-relaxed">{visionReport.biologicalRemedy.application}</p>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, GrassMeasureMode, GrassVariety, ClimateType, VisionReport, ApplicationMode, Department, ClientData, HistoryRecord } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, COLOMBIAN_MARKET_PRICES, TREE_TYPE_ICONS } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const BioGenesisLogo = () => (
  <div className="flex items-center gap-3">
    <div className="h-12 w-12 bg-white rounded-2xl flex items-center justify-center shadow-xl">
      <i className="fas fa-leaf text-emerald-600 text-2xl"></i>
    </div>
    <div className="flex flex-col">
      <h1 className="text-2xl font-black text-white leading-none tracking-tighter">BioGenesis <span className="text-emerald-400">PRO</span></h1>
      <p className="text-[9px] font-bold text-emerald-200 uppercase tracking-[0.3em] mt-1">Ingeniería Agronómica</p>
    </div>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'grass_pro' | 'vision' | 'history'>('calculator');
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);
  const [visionImage, setVisionImage] = useState<string | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [history, setHistory] = useState<HistoryRecord[]>([]);

  const [additionalPercent, setAdditionalPercent] = useState<number>(0);

  const [clientData, setClientData] = useState<ClientData>({
    firstName: '', lastName: '', location: '', contact: '', email: ''
  });

  // Estado extendido para capturar ediciones directas en la tabla de resultados
  const [input, setInput] = useState<CalculationInput & { 
    manualTotalAmounts: Record<string, number | undefined>,
    manualUnitPrices: Record<string, number | undefined>
  }>({
    treeType: TreeType.CITRUS, department: Department.ANTIOQUIA, applicationMode: ApplicationMode.MAINTENANCE,
    soilType: SoilType.FRANCO, climate: ClimateType.MODERATE, treeAge: 1, numTrees: 1, 
    grassVariety: GrassVariety.KIKUYO, grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: { ...COLOMBIAN_MARKET_PRICES }, manualPlantAmounts: {}, selectedUnits: {},
    cycleFrequencyValue: 3, cycleFrequencyUnit: 'meses', healthStatus: 'bueno',
    manualAmounts: {},
    manualTotalAmounts: {}, // Nuevo: Edición directa de la cantidad total en la tabla
    manualUnitPrices: {}    // Nuevo: Edición directa del precio en la tabla
  });

  const [result, setResult] = useState<CalculationResult | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('biogenesis_history_v8');
    if (saved) setHistory(JSON.parse(saved));
  }, []);

  // Lógica de cálculo que respeta la edición directa
  const calculateProductRow = useCallback((p: OrganicProduct) => {
    const totalUnits = Math.max(1, input.numTrees || 1);

    // 1. Determinar Cantidad Total
    let totalAmount: number;
    if (input.manualTotalAmounts[p] !== undefined) {
      totalAmount = input.manualTotalAmounts[p] as number;
    } else {
      // Cálculo sugerido inicial
      let dosePerPlant: number;
      if (input.manualPlantAmounts[p] !== undefined) {
        dosePerPlant = input.manualPlantAmounts[p] as number;
      } else {
        const base = BASE_RATES[p] || 0;
        const healthMultiplier = input.healthStatus === 'deficiente' ? 1.3 : (input.healthStatus === 'regular' ? 1.15 : 1);
        const ageFactor = activeTab === 'grass_pro' ? 1 : Math.min(2.5, 1 + (input.treeAge - 1) * 0.1);
        dosePerPlant = base * healthMultiplier * ageFactor;
      }
      totalAmount = dosePerPlant * totalUnits;
    }

    // 2. Determinar Precio
    const price = input.manualUnitPrices[p] !== undefined ? (input.manualUnitPrices[p] as number) : (input.productPrices[p] || 0);

    // 3. Subtotal
    const subtotal = totalAmount * price;

    return {
      product: p,
      amount: parseFloat(totalAmount.toFixed(2)),
      unit: input.selectedUnits[p] || PRODUCT_UNITS[p] || 'u',
      costPerUnit: price,
      totalCost: Math.round(subtotal)
    };
  }, [input, activeTab]);

  const updateResults = useCallback(() => {
    const products = input.selectedProducts.map(p => calculateProductRow(p));
    const subtotalProject = products.reduce((acc, curr) => acc + curr.totalCost, 0);

    setResult({ 
      products, 
      totalCostPerUnit: subtotalProject / (input.numTrees || 1), 
      totalProjectCost: subtotalProject, 
      frequency: `Cada ${input.cycleFrequencyValue} ${input.cycleFrequencyUnit}` 
    });
  }, [input.selectedProducts, calculateProductRow, input.numTrees, input.cycleFrequencyValue, input.cycleFrequencyUnit]);

  useEffect(() => { updateResults(); }, [updateResults]);

  const additionalValue = (result?.totalProjectCost || 0) * (additionalPercent / 100);
  const grandTotal = (result?.totalProjectCost || 0) + additionalValue;

  const handleExportPDF = () => {
    if (!result) return;
    const doc = new jsPDF();
    doc.setFillColor(6, 78, 59);
    doc.rect(0, 0, 210, 40, 'F');
    doc.setFontSize(22);
    doc.setTextColor(255, 255, 255);
    doc.text('BIO-GENESIS PRO', 14, 25);
    doc.setFontSize(9);
    doc.text('REPORTE TÉCNICO DE INSUMOS Y COSTOS', 14, 32);

    autoTable(doc, {
      startY: 55,
      head: [['Insumo', 'Unidad', 'Cantidad Total', 'V. Unitario', 'Subtotal (COP)']],
      body: result.products.map(p => [
        p.product,
        p.unit,
        p.amount.toLocaleString(),
        `$${p.costPerUnit.toLocaleString()}`,
        `$${p.totalCost.toLocaleString()}`
      ]),
      foot: [
        ['', '', '', 'SUBTOTAL', `$${result.totalProjectCost.toLocaleString()}`],
        ['', '', '', `UTILIDAD (${additionalPercent}%)`, `$${additionalValue.toLocaleString()}`],
        ['', '', '', 'TOTAL PROYECTO', `$${grandTotal.toLocaleString()}`]
      ],
      theme: 'grid',
      headStyles: { fillColor: [6, 78, 59] },
      footStyles: { fillColor: [240, 240, 240], textColor: [0, 0, 0], fontStyle: 'bold' }
    });
    doc.save(`Presupuesto_Agro_${clientData.lastName || 'BioGenesis'}.pdf`);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-20">
      <header className="bg-[#064e3b] p-6 sticky top-0 z-50 shadow-xl no-print">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
          <BioGenesisLogo />
          <nav className="flex bg-white/10 p-1 rounded-2xl backdrop-blur-md">
            {['calculator', 'vision', 'history'].map(tab => (
              <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === tab ? 'bg-white text-[#064e3b] shadow-lg' : 'text-white/70 hover:text-white'}`}>
                {tab === 'calculator' ? 'CÁLCULOS' : tab === 'vision' ? 'VISION IA' : 'HISTORIAL'}
              </button>
            ))}
          </nav>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        {activeTab === 'calculator' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <aside className="lg:col-span-4 space-y-6 no-print">
              <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200">
                <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-6">Configuración de Base</h3>
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase">Cultivo / Planta</label>
                    <select value={input.treeType} onChange={e => setInput({...input, treeType: e.target.value as any})} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold">
                      {Object.values(TreeType).map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-500 uppercase">Edad (Años)</label>
                      <input type="number" value={input.treeAge} onChange={e => setInput({...input, treeAge: parseInt(e.target.value) || 1})} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-500 uppercase">Cantidad Plantas</label>
                      <input type="number" value={input.numTrees} onChange={e => setInput({...input, numTrees: parseInt(e.target.value) || 1})} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200">
                <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-6">Catálogo de Insumos</h3>
                <div className="max-h-[500px] overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                  {Object.values(OrganicProduct).map(p => {
                    const isSelected = input.selectedProducts.includes(p);
                    return (
                      <div key={p} className={`p-4 rounded-xl border-2 transition-all cursor-pointer ${isSelected ? 'bg-emerald-50 border-emerald-500 ring-2 ring-emerald-500/10' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                        <label className="flex items-center gap-3 cursor-pointer">
                          <input 
                            type="checkbox" 
                            checked={isSelected} 
                            onChange={() => setInput(prev => ({ 
                              ...prev, 
                              selectedProducts: isSelected ? prev.selectedProducts.filter(x => x !== p) : [...prev.selectedProducts, p] 
                            }))} 
                            className="w-5 h-5 accent-emerald-600 rounded"
                          />
                          <span className="text-[11px] font-black text-slate-800 uppercase leading-none">{p}</span>
                        </label>
                      </div>
                    );
                  })}
                </div>
              </div>
            </aside>

            <section className="lg:col-span-8 space-y-6">
              <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-slate-200">
                <div className="flex justify-between items-center mb-8 pb-4 border-b">
                  <div>
                    <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase leading-none">Reporte de Insumos</h2>
                    <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">Edición directa habilitada</p>
                  </div>
                  <button onClick={handleExportPDF} className="bg-[#064e3b] text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase shadow-lg">Descargar PDF</button>
                </div>

                {result && result.products.length > 0 ? (
                  <div className="space-y-10">
                    <div className="overflow-hidden rounded-[2rem] border border-slate-200 bg-slate-50/50">
                      <table className="w-full text-left">
                        <thead className="bg-slate-100 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                          <tr>
                            <th className="p-5">Insumo</th>
                            <th className="p-5 w-24">U. Medida</th>
                            <th className="p-5 w-32 text-center">Cantidad Total</th>
                            <th className="p-5 w-32 text-center">V. Unitario</th>
                            <th className="p-5 text-right">Subtotal</th>
                          </tr>
                        </thead>
                        <tbody className="text-sm font-bold text-slate-700">
                          {result.products.map((p, idx) => (
                            <tr key={idx} className="border-t hover:bg-emerald-50/30 transition-colors">
                              <td className="p-5 uppercase font-black text-slate-900 text-xs">{p.product}</td>
                              <td className="p-3">
                                <select 
                                  value={input.selectedUnits[p.product] || PRODUCT_UNITS[p.product]} 
                                  onChange={e => setInput({...input, selectedUnits: {...input.selectedUnits, [p.product]: e.target.value as any}})}
                                  className="w-full p-2 bg-white border border-slate-200 rounded-lg text-[10px] font-black outline-none shadow-sm"
                                >
                                  {['g','kg','ml','cc','L','galon','u'].map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                              </td>
                              <td className="p-3">
                                <input 
                                  type="number" 
                                  value={input.manualTotalAmounts[p.product] ?? p.amount} 
                                  onChange={e => setInput({...input, manualTotalAmounts: {...input.manualTotalAmounts, [p.product]: parseFloat(e.target.value) || 0}})}
                                  className="w-full p-2 bg-white border border-slate-200 rounded-lg text-center text-xs font-black outline-none shadow-sm text-emerald-700 focus:ring-2 focus:ring-emerald-500" 
                                />
                              </td>
                              <td className="p-3">
                                <input 
                                  type="number" 
                                  value={input.manualUnitPrices[p.product] ?? p.costPerUnit} 
                                  onChange={e => setInput({...input, manualUnitPrices: {...input.manualUnitPrices, [p.product]: parseFloat(e.target.value) || 0}})}
                                  className="w-full p-2 bg-white border border-slate-200 rounded-lg text-center text-xs font-black outline-none shadow-sm text-slate-600 focus:ring-2 focus:ring-emerald-500" 
                                />
                              </td>
                              <td className="p-5 text-right font-black text-emerald-800 text-xs">${p.totalCost.toLocaleString()}</td>
                            </tr>
                          ))}
                        </tbody>
                        <tfoot className="bg-slate-100/80 border-t-2 border-slate-200">
                           <tr className="border-b">
                             <td colSpan={4} className="p-4 text-right font-black text-slate-400 text-[10px] uppercase">Subtotal Neto</td>
                             <td className="p-4 text-right font-black text-slate-900 text-lg">${result.totalProjectCost.toLocaleString()}</td>
                           </tr>
                           <tr className="border-b">
                             <td colSpan={4} className="p-4 text-right font-black text-slate-400 text-[10px] uppercase flex items-center justify-end gap-3">
                               <span>% Porcentaje Adicional (Utilidad / Gestión)</span>
                               <input 
                                 type="number" 
                                 value={additionalPercent} 
                                 onChange={(e) => setAdditionalPercent(parseFloat(e.target.value) || 0)}
                                 className="w-20 p-2 bg-white border border-emerald-300 rounded-xl text-center text-xs font-black text-emerald-700 outline-none shadow-sm focus:ring-2 focus:ring-emerald-500"
                               />
                             </td>
                             <td className="p-4 text-right font-black text-blue-600">
                               +${Math.round(additionalValue).toLocaleString()}
                             </td>
                           </tr>
                           <tr className="bg-[#064e3b] text-white">
                             <td colSpan={4} className="p-8 text-right font-black uppercase text-sm tracking-widest text-emerald-200">Total Gran Inversión</td>
                             <td className="p-8 text-right font-black text-3xl text-emerald-400 tracking-tighter">
                               ${Math.round(grandTotal).toLocaleString()}
                             </td>
                           </tr>
                        </tfoot>
                      </table>
                    </div>

                    <div className="bg-emerald-50 p-8 rounded-[3rem] border-2 border-dashed border-emerald-200">
                       <h4 className="text-xl font-black text-[#064e3b] uppercase mb-6 flex items-center gap-3">
                         <i className="fas fa-robot text-emerald-600"></i> Plan Maestro IA
                       </h4>
                       {!aiAdvice ? (
                         <button 
                           onClick={async () => {
                             setLoading(true);
                             const advice = await getAgriculturalAdvice(input);
                             setAiAdvice(advice);
                             setLoading(false);
                           }} 
                           disabled={loading} 
                           className="w-full bg-white text-emerald-900 p-8 rounded-2xl border-2 border-emerald-300 font-black uppercase shadow-md hover:bg-emerald-50 transition-all flex items-center justify-center gap-4"
                         >
                           {loading ? 'Consultando IA...' : 'Obtener Sugerencias Técnicas con IA'}
                         </button>
                       ) : (
                         <div className="grid md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-5">
                            <div className="space-y-3">
                              <h5 className="text-[10px] font-black text-emerald-900 uppercase border-b pb-2">Radicular</h5>
                              {aiAdvice.radicularPlan.map((s, idx) => (
                                <div key={idx} className="p-3 bg-white rounded-xl shadow-sm border border-emerald-100">
                                  <p className="text-[11px] font-black text-slate-900 uppercase">{s.item}</p>
                                  <p className="text-[9px] font-bold text-emerald-600 uppercase">Dosis IA: {s.dosage}</p>
                                </div>
                              ))}
                            </div>
                            <div className="space-y-3">
                              <h5 className="text-[10px] font-black text-teal-900 uppercase border-b pb-2">Foliar</h5>
                              {aiAdvice.foliarPlan.map((s, idx) => (
                                <div key={idx} className="p-3 bg-white rounded-xl shadow-sm border border-teal-50">
                                  <p className="text-[11px] font-black text-slate-900 uppercase">{s.item}</p>
                                  <p className="text-[9px] font-bold text-teal-600 uppercase">Dosis IA: {s.dosage}</p>
                                </div>
                              ))}
                            </div>
                         </div>
                       )}
                    </div>
                  </div>
                ) : (
                  <div className="text-center py-20 bg-slate-50 rounded-[3rem] border-4 border-dashed border-slate-100 text-slate-300 font-black uppercase text-sm tracking-widest">
                    Seleccione productos para generar el desglose
                  </div>
                )}
              </div>
            </section>
          </div>
        )}

        {/* MODULO VISION IA */}
        {activeTab === 'vision' && (
          <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in duration-500">
            <div className="bg-white p-14 rounded-[4rem] shadow-2xl text-center border-4 border-emerald-50">
              <h2 className="text-5xl font-black text-[#064e3b] mb-4 tracking-tighter uppercase">Diagnóstico Bio-Vision</h2>
              <p className="text-slate-500 font-medium mb-12">Sube una foto para identificar deficiencias y plagas automáticamente.</p>

              <div className="relative group border-4 border-dashed border-slate-200 rounded-[3rem] p-10 bg-slate-50 transition-all hover:bg-slate-100">
                {visionImage ? (
                  <img src={visionImage} className="aspect-video rounded-[2rem] object-cover mx-auto shadow-2xl" />
                ) : (
                  <label className="cursor-pointer flex flex-col items-center py-16">
                    <i className="fas fa-camera text-5xl text-emerald-500 mb-6"></i>
                    <span className="text-xs font-black uppercase text-slate-500 tracking-widest">Capturar Imagen</span>
                    <input type="file" accept="image/*" onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (file) {
                        const reader = new FileReader();
                        reader.onloadend = () => setVisionImage(reader.result as string);
                        reader.readAsDataURL(file);
                      }
                    }} className="hidden" />
                  </label>
                )}
              </div>

              {visionImage && (
                <div className="flex justify-center gap-4 mt-10">
                  <button onClick={() => { setVisionImage(null); setVisionReport(null); }} className="px-10 py-4 bg-slate-200 text-slate-700 rounded-xl font-black uppercase">Limpiar</button>
                  <button 
                    onClick={async () => {
                      setLoading(true);
                      const report = await getIndependentVisionDiagnosis(visionImage, input.treeType);
                      setVisionReport(report);
                      setLoading(false);
                    }} 
                    disabled={loading} 
                    className="px-16 py-4 bg-[#064e3b] text-white rounded-xl font-black uppercase shadow-xl"
                  >
                    {loading ? 'Analizando...' : 'Diagnosticar'}
                  </button>
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { TreeType, SoilType, OrganicProduct, CalculationInput, CalculationResult, AIAdvice, ProductResult, UnitType, GrassMeasureMode, GrassVariety, ClimateType, VisionReport, ApplicationMode, Department, ClientData, HistoryRecord } from './types.ts';
import { BASE_RATES, PRODUCT_UNITS, COLOMBIAN_MARKET_PRICES, TREE_TYPE_ICONS, PRODUCT_DETAILS } from './constants.tsx';
import { getAgriculturalAdvice, getIndependentVisionDiagnosis } from './services/geminiService.ts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

const BioGenesisLogo = () => (
  <div className="flex items-center gap-3">
    <div className="h-12 w-12 bg-white rounded-2xl flex items-center justify-center shadow-xl">
      <i className="fas fa-leaf text-emerald-600 text-2xl"></i>
    </div>
    <div className="flex flex-col">
      <h1 className="text-2xl font-black text-white leading-none tracking-tighter">BioGenesis <span className="text-emerald-400">PRO</span></h1>
      <p className="text-[9px] font-bold text-emerald-200 uppercase tracking-[0.3em] mt-1">Ingeniería Agronómica</p>
    </div>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'calculator' | 'vision' | 'history'>('calculator');
  const [aiAdvice, setAiAdvice] = useState<AIAdvice | null>(null);
  const [loading, setLoading] = useState(false);
  const [visionImage, setVisionImage] = useState<string | null>(null);
  const [visionReport, setVisionReport] = useState<VisionReport | null>(null);
  const [history, setHistory] = useState<HistoryRecord[]>([]);

  // Estado para el modal de detalles del producto
  const [selectedProductForDetail, setSelectedProductForDetail] = useState<OrganicProduct | null>(null);

  const [additionalPercent, setAdditionalPercent] = useState<number>(0);

  const [clientData, setClientData] = useState<ClientData>({
    firstName: '', lastName: '', location: '', contact: '', email: ''
  });

  const [input, setInput] = useState<CalculationInput & { 
    manualTotalAmounts: Record<string, number | undefined>,
    manualUnitPrices: Record<string, number | undefined>
  }>({
    treeType: TreeType.CITRUS, department: Department.ANTIOQUIA, applicationMode: ApplicationMode.MAINTENANCE,
    soilType: SoilType.FRANCO, climate: ClimateType.MODERATE, treeAge: 1, numTrees: 1, 
    grassVariety: GrassVariety.KIKUYO, grassMode: GrassMeasureMode.AREA,
    selectedProducts: [OrganicProduct.COMPOST_TERRABONO, OrganicProduct.LIQUID_HUMUS],
    productPrices: { ...COLOMBIAN_MARKET_PRICES }, manualPlantAmounts: {}, selectedUnits: {},
    cycleFrequencyValue: 3, cycleFrequencyUnit: 'meses', healthStatus: 'bueno',
    manualAmounts: {},
    manualTotalAmounts: {},
    manualUnitPrices: {}
  });

  const [result, setResult] = useState<CalculationResult | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('biogenesis_history_v8');
    if (saved) setHistory(JSON.parse(saved));
  }, []);

  const calculateProductRow = useCallback((p: OrganicProduct) => {
    const totalUnits = Math.max(1, input.numTrees || 1);

    let totalAmount: number;
    if (input.manualTotalAmounts[p] !== undefined) {
      totalAmount = input.manualTotalAmounts[p] as number;
    } else {
      let dosePerPlant: number;
      if (input.manualPlantAmounts[p] !== undefined) {
        dosePerPlant = input.manualPlantAmounts[p] as number;
      } else {
        const base = BASE_RATES[p] || 0;
        const healthMultiplier = input.healthStatus === 'deficiente' ? 1.3 : (input.healthStatus === 'regular' ? 1.15 : 1);
        const ageFactor = input.treeType === TreeType.GRASS ? 1 : Math.min(2.5, 1 + (input.treeAge - 1) * 0.1);
        dosePerPlant = base * healthMultiplier * ageFactor;
      }
      totalAmount = dosePerPlant * totalUnits;
    }

    const price = input.manualUnitPrices[p] !== undefined ? (input.manualUnitPrices[p] as number) : (input.productPrices[p] || 0);
    const subtotal = totalAmount * price;

    return {
      product: p,
