                  >
                    {loading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-microscope"></i>}
                    {loading ? 'Analizando muestra...' : 'Iniciar Bio-Diagnóstico'}
                  </button>
                </div>
              )}
            </div>

            {visionReport && (
              <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-emerald-100 animate-in slide-in-from-bottom-10">
                <h3 className="text-2xl font-black uppercase border-b pb-4 mb-6">Resultado del Análisis IA</h3>
                <div className="grid md:grid-cols-2 gap-8">
                  <div className="space-y-4">
                    <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Diagnóstico</p>
                    <p className="text-2xl font-black text-slate-900">{visionReport.pestAnalysis.identifiedPest}</p>
                    <p className="text-sm text-slate-500 italic leading-relaxed">{visionReport.pestAnalysis.symptoms}</p>
                  </div>
                  <div className="bg-emerald-900 text-white p-8 rounded-3xl">
                    <p className="text-[10px] font-black text-emerald-400 uppercase mb-4">Solución Recomendada</p>
                    <ul className="space-y-2">
                      {visionReport.biologicalRemedy.ingredients.map((ing, i) => (
                        <li key={i} className="text-sm font-bold flex items-center gap-2"><i className="fas fa-check text-emerald-400 text-[10px]"></i> {ing}</li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="max-w-4xl mx-auto bg-white p-10 rounded-[3rem] shadow-xl text-center">
             <i className="fas fa-folder-open text-6xl text-slate-200 mb-6"></i>
             <h2 className="text-2xl font-black uppercase text-slate-900">Historial de Reportes</h2>
             <p className="text-slate-500 mt-2">Próximamente: Almacenamiento local de sus cálculos y diagnósticos.</p>
          </div>
        )}
      </main>

      {/* MODAL DE FICHA TÉCNICA */}
      {selectedProductForDetail && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-[#064e3b] p-8 text-white flex justify-between items-start">
              <div>
                <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">BioGenesis Engineering</span>
                <h2 className="text-3xl font-black uppercase tracking-tighter mt-1">{selectedProductForDetail}</h2>
