              <button onClick={() => setSelectedProductForDetail(null)} className="h-10 w-10 bg-white/10 hover:bg-white/20 rounded-full flex items-center justify-center transition-all">
                <i className="fas fa-times text-xl"></i>
              </button>
            </div>

            <div className="p-10 space-y-8 overflow-y-auto max-h-[70vh] custom-scrollbar">
              <div className="space-y-3">
                <h4 className="flex items-center gap-2 text-[11px] font-black text-emerald-600 uppercase tracking-widest">
                  <i className="fas fa-flask-vial"></i> Composición y Propiedades
                </h4>
                <p className="text-slate-600 text-sm font-medium leading-relaxed bg-slate-50 p-5 rounded-2xl border border-slate-100">
                  {PRODUCT_DETAILS[selectedProductForDetail]?.properties}
                </p>
              </div>

              <div className="space-y-3">
                <h4 className="flex items-center gap-2 text-[11px] font-black text-emerald-600 uppercase tracking-widest">
                  <i className="fas fa-check-double"></i> Beneficios Clave
                </h4>
                <p className="text-slate-600 text-sm font-medium leading-relaxed">
                  {PRODUCT_DETAILS[selectedProductForDetail]?.benefits}
                </p>
              </div>

              <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100 flex gap-4">
                <div className="text-amber-500 mt-1"><i className="fas fa-triangle-exclamation text-xl"></i></div>
                <div className="space-y-1">
                  <h4 className="text-[11px] font-black text-amber-700 uppercase tracking-widest">Precauciones</h4>
                  <p className="text-amber-800 text-xs font-bold leading-relaxed">
                    {PRODUCT_DETAILS[selectedProductForDetail]?.precautions}
