                      <div key={p} className={`p-4 rounded-xl border-2 transition-all flex items-center justify-between group ${isSelected ? 'bg-emerald-50 border-emerald-500 ring-2 ring-emerald-500/10' : 'bg-slate-50 border-slate-100'}`}>
