                       )}
                    </div>
                  </div>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center opacity-30 text-slate-400 py-20 uppercase font-black tracking-widest">
                    <i className="fas fa-calculator text-6xl mb-4"></i>
