    // INFORMACIÓN TÉCNICA
    doc.text('2. ESPECIFICACIONES TÉCNICAS', 14, (doc as any).lastAutoTable.finalY + 15);
    autoTable(doc, {
      startY: (doc as any).lastAutoTable.finalY + 20,
