                          <button onClick={() => setInput({...input, grassMode: GrassMeasureMode.LINEAR})} className={`p-2 rounded-xl text-[10px] font-black uppercase border transition-all ${input.grassMode === GrassMeasureMode.LINEAR ? 'bg-emerald-600 text-white border-emerald-600 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>m Lineal</button>
