    const prompt = `Actúa como un Patólogo Vegetal experto en cultivos colombianos. Analiza esta imagen de una muestra de ${targetType}.
    Identifica detalladamente:
    1. Lectura general de la planta (color, turgencia, vigor).
    2. Identificación precisa de la plaga o deficiencia nutricional (nombre común y científico).
    3. Síntomas observados (manchas, deformaciones, necrosis) y nivel de severidad (Leve, Moderada, Crítica).
    4. Un remedio biológico/orgánico CASERO Y TÉCNICO para el control.
    5. Recomendaciones culturales preventivas.

    IMPORTANTE: Asegúrate de que los campos del análisis de plaga incluyan 'identifiedPest', 'scientificName', 'symptoms', 'severity', 'prevention', 'organicTreatment', 'controlCycle' y 'lifeCycleInfo'.

    Responde estrictamente en formato JSON válido.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { text: prompt },
          { inlineData: { mimeType: 'image/jpeg', data: imageBase64.split(',')[1] } }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            plantReading: { type: Type.STRING },
            pestAnalysis: {
              type: Type.OBJECT,
              properties: {
                identifiedPest: { type: Type.STRING },
                scientificName: { type: Type.STRING },
                symptoms: { type: Type.STRING },
                severity: { type: Type.STRING },
                prevention: { type: Type.STRING },
                organicTreatment: { type: Type.STRING },
                controlCycle: { type: Type.STRING },
                lifeCycleInfo: { type: Type.STRING }
              },
              required: ["identifiedPest", "scientificName", "symptoms", "severity", "prevention", "organicTreatment", "controlCycle", "lifeCycleInfo"]
            },
            biologicalRemedy: {
              type: Type.OBJECT,
              properties: {
                ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                preparation: { type: Type.STRING },
                application: { type: Type.STRING }
              },
              required: ["ingredients", "preparation", "application"]
            },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["plantReading", "pestAnalysis", "biologicalRemedy", "recommendations"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Respuesta vacía de IA Vision");
    const json = extractJson(text);
    if (!json) throw new Error("No se pudo parsear el JSON de la visión");
    return json;
  } catch (error) {
    console.error("Error en IA Vision:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback } from 'react';
